INSERT INTO `inhe_customer_data` VALUES ('23', '60', 'INHE-0255', '2015-12-31 00:00:17', null, 'Alyaqeen Engineering Co. LLC.', 'W00065', 'Alyaqeen Engineering Co. LLC.', 'OM', '亚洲', '阿曼苏丹国', 'http://www.yaqeeneng.com/alyaqeen/', 'Al Nadha Tower 2 | 7th Floor | Office No 4 |Behind Ghala Oxy Building |\n |Opposite Zubair | Near Man Truck Showroom| Ghala |\n |Muscat | Sultanate of Oman|', 'Al Yaqeen Engineering是阿曼Al Yaqeen Group旗下的一家公司，专门从事电力工程和水务工程建设的专业公司，业务范围覆盖整个阿曼。', '黄纯杰', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('24', '60', 'INHE-0015', '2015-12-31 00:00:18', null, 'Makgaji Printing and Projects T/A Makgaji Projects and Consulting Close Corporation', 'W00129', 'Makgaji Printing and Projects T/A Makgaji Projects and Consulting Close Corporation', 'MPAP', '非洲', '南非共和国', '', 'Unit 102(s)a, Menlyn Square Office Park, Cnr Lois Avenue & Gobie, Menlyn, 0181', '该公司主要为市政府电力公司提供能源保护方案，提高政府收入，是一家小型创业型公司，总经理Mmatholo女士之前是兰吉尔公司的销售经理。', '王维', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('25', '60', 'INHE-0308', '2015-12-31 00:00:19', null, 'Bongani Energia Lda', 'W00083', 'Bongani Energia Lda', 'AG', '非洲', '安哥拉', 'N/A', 'N/A', '1.客户在安哥拉有两个公司，分别涉及能源产业和投资项目，总部均在首都卢旺达\n2.在所在国有很好的政府关系，政府中一个部长是其大股东\n3.客户对订单很强势（即不用投标），直接从我司采购产品\n4.此项目有中介人，中介人跟客户关系很好，他希望从中抽取5美金/台的佣金', '赵刚', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('26', '60', 'INHE-0308', '2015-12-31 00:00:20', null, '东石国际工程有限责任公司', 'W00084', '东石国际工程有限责任公司', '石头', '非洲', '安哥拉', 'N/A', 'N/A', '1.东石国际于2009年成立，是一家以送变电、土建施工为主，集设计、加工及电力贸易设备及相关服务于一身的综合性技术企业。\n2.总部位于安哥拉首都罗安达cacuaco工业园区，占地面积20000多平米，拥有各类大型车辆、机械三十余辆（台），固定资产500万美元。\n3.在安哥拉现有中国员工120余人，其中高级技术工人20余人，是一支拥有电力安装、系统调试、工民建筑、大件运输、起重吊装和电力工程设计等实力强劲的专业队伍\n4.主营业务为220千伏及以下电压等级送变电工程施工', '赵刚', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('27', '60', 'INHE-0091', '2015-12-31 00:00:21', null, 'Harnessing Environmental Technologies Ltd.', 'W00048', 'Harnessing Environmental Technologies Ltd.', 'HET', '非洲', '毛里求斯', 'N/A', 'N/A', '该客户是以下知名品牌在印度洋地区的代理：SIEMENS，DAIKIN，DINEL，K-FLEX，TEEO.主要提供节能方案和产品，包括供暖，通风，空调等产品。', '林丽璇', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('28', '60', 'INHE-0051', '2015-12-31 00:00:22', null, 'Kabelek Engineering Ltd', 'W00123', 'Kabelek Engineering Ltd', 'KEL', '非洲', '毛里求斯', 'www.kabelek-ltd.com', '', '成立于2007年在毛里求斯注册提供一系列全套的电力和机械工程服务。电线安装测试，工业建筑电力安装，管道安装，民用和商用的自动化建设，再生性能源系统建设。', '盛燕', '国际业务二部', null, null, 'E', 'INHE');
