INSERT INTO `inhe_customer_data` VALUES ('30', '60', 'INHE-0246', '2015-12-31 00:00:24', null, 'B.N.S.R Sela Projects Limited', 'W00036', 'B.N.S.R Sela Projects Limited', 'BNSR', '非洲', '尼日利亚', 'N/A', '63 hailanot street,Zoran,Israel', '贸易公司，此前有做尼日利亚市场，后因尼日利亚总统换届，项目暂停。目前小批量订单是做的以色列市场。有一定的潜力。', '樊晓琴', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('31', '60', 'INHE-0246', '2015-12-31 00:00:25', null, 'Tripplesea Limited', 'W00054', 'Tripplesea Limited', 'TG', '非洲', '尼日利亚', 'www.trippleseagroup.com', '4 Bashiru Oweh Street, Ikeja\nLagos State, Nigeria', 'TG集团下设3家子公司，包含食品制药，电力设备，办公用品等。公司有实力，同时具有专业背景和经验。此前已在银河执行过4万台订单。', '樊晓琴', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('32', '60', 'INHE-0246', '2015-12-31 00:00:26', null, 'Integrated Resources Limited', 'W00067', 'Integrated Resources Limited', 'IRL', '非洲', '尼日利亚', 'N/A', '22a Adeleke Adedoyin Street \nVictoria Island, Lagos', '尼日利亚能源公司，在电力能源行业有10年的经验，其主要的服务项目包括设计和建设输电/配电网络，供应和安装电力设备，项目风险评估和管理', '樊晓琴', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('33', '60', 'INHE-0246', '2015-12-31 00:00:27', null, 'Electricity Meter Company Nigeria Plc', 'W00074', 'Electricity Meter Company Nigeria Plc', 'EMCON', '非洲', '尼日利亚', 'N/A', 'Plot 30-32, Light Industrial Estate, P.M.B. 1105, \nZaria, Kaduna State, Nigeria, \n', 'EMCON是尼日利亚本地做机电一体式电表的一家老牌表厂，因无法生产市场需要的电子表而导致工厂停止运营，近年来主要是向Conlog,兰吉尔，海兴等购买电表并安装。其电表市场主要集中在尼日利亚北方，KANO是其大本营。EMCON隶属尼日利亚北部的一个家族财团Dantata Group,Dantata Group的总经理为EMCON的董事长.2013年11月1日，EMCON所在的集团顺利的收购并接手KANO电力公司。EMCON表示其已与该集团达成内部供货协议，EMCON将是KANO电力公司唯一的电表供应商。', '樊晓琴', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('34', '60', 'INHE-0036', '2015-12-31 00:00:28', null, 'Nayo Tropical Technology Limited', 'W00122', 'Nayo Tropical Technology Limited', 'NTTL', '非洲', '尼日利亚', 'N/A', 'Nigeria', '私人贸易公司。公司主营太阳能产品。目前只是试水电表产品。', '郭涛', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('35', '60', 'INHE-0036', '2015-12-31 00:00:29', null, 'GVE Projects Limited', 'W00134', 'GVE Projects Limited', 'GVE', '非洲', '尼日利亚', 'www.gve-group.com', 'o. 9 Chief Ejims Street,\nRumuomasi,\nPort-Harcourt,\nRivers State – Nigeria.', 'GVE Projects Ltd于2005年注册于尼日利亚，是一家新能源服务解决方案供应商，主营太阳能及风能解决方案及系统的设计、销售及维护。主要客户有小区及终端用户，商场，国内大型公司工厂等。目前正在通过其创立的GVP基金与国际非营利性组织、国内政府及企业机构合作集资，为尼日利亚国家电网无法送达的偏远地区提供风能及太阳能系统，以解决用电问题。目前GVP基金已收到约10万美金捐款。', '郭涛', '国际业务二部', null, null, 'E', 'INHE');
