INSERT INTO `inhe_customer_data` VALUES ('65', '55', 'lhz', '2015-12-31 00:00:59', null, 'DREI ASOCIADOS S.R.L.', 'khxx2015123119', 'DREI ASOCIADOS S.R.L.', '', '南美洲', '巴拉圭', 'www.drei.com.py', 'Boggiani 5889\n1863 Asuncion-Paraguay', '当地一家公司，70%业务为政府招标项目，3家子公司下面分四个项目事业部，涉及农畜业，政府招标等不同项目领域，负责人属于政府招标项目部负责人', '', '', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('66', '55', 'lhz', '2015-12-31 00:01:00', null, 'Omega Integrated Systems', 'khxx2015123120', 'Omega Integrated Systems', '', '非洲', '埃及', 'www.omegaegypt.com ', '5 Messaha SQ., Dokki, Giza, CAIRO, EGYPT', '该公司于1995成立，从成立起初便和埃及电力公司合作，有销售过电能表测试架，CT/PT三相表给电力公司的案例，从2000开始，成为EDMI的代理。业务范围主要有：不同工程领域的测量设备，测试设备，标定设备。有功/无功电能表，AMR系统，电表测试设备，绿色能源(太阳能/风能)等。就埃及300万台智能电表招标项目，于2015年8月和我们签署合作协议，但暂未有合同履行', '', '', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('67', '55', 'lhz', '2015-12-31 00:01:01', null, 'Process * Plant Automation Ltd', 'khxx2015123121', 'Process * Plant Automation Ltd', '', '非洲', '加纳', 'www.automationghana.com', 'No. 3 Becca Villa \nSpintex Road, Behind Cal Bank, Accra, Ghana\n', 'PPA是一家致力于系统集成的公司，将高性能模块和产品结合。为工业，建筑建设提供方案。同时也涉及石油天然气，废水资源，电力能源行业。于2015年11月拜访我司，有意向从我司采购电表', '', '', null, null, 'E', 'INHE');
