INSERT INTO `inhe_customer_data` VALUES ('80', '60', 'INHE-0036', '2015-12-31 00:01:14', null, 'AmelioEner GmbH', 'W00135', 'AmelioEner GmbH', 'AG', '欧洲', '瑞士', 'www.amelioener.com', 'Zollweid 8 \n6331 Huenenberg\nSwitzerland\n', '客户是瑞士的能源解决方案供应商，目前有十万块旧表需要被替换。首次采购在一千台左右。但是AmelioEner表示如果我们的产品质量和价格都很优秀的话，接下来几年每年都有数千台的需求，除了直通表之外，后期还需要大量不同规格的CT表.', '郭涛', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('81', '60', 'INHE-0036', '2015-12-31 00:01:15', null, 'Lee Jong Electrical * Engineering Sdn Bhd', 'W00105', 'Lee Jong Electrical * Engineering Sdn Bhd', 'LJE', '亚洲', '文莱', '', 'No. 23, Wisma Lee Jong, Spg. 99-10, Jln. Bengkurong Masin, Kg. Bengkurong BF 1920,\nNegara Brunei Darussalam\n', '客户公司在文莱，想合作文莱市场的项目，但是我司在文莱已有合作伙伴，客户计划在马来西亚电力公司做试点，并做进入马来的许可证明。目前客户购买了66台可跟换模块表做试点之用。现在获得认证，这几家电力公司有资格进入。我们需提供技术支持客户安装系统和表计。', '郭涛', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('82', '60', 'INHE-0036', '2015-12-31 00:01:16', null, 'LETECH TECHONOLOGIES SDN BHD', 'W00140', 'LETECH TECHONOLOGIES SDN BHD', 'LETECH TECHONOLOGIES', '亚洲', '马来西亚', '', 'Lot 7892, Sublot 71, 1st Floor, Queen\'s Court,Block B, Jalan Wan Alwi,93350 Kuching, Sarawak, Malaysia', '客户计划在电力公司做试点，并做进入马来的许可证明。目前客户购买了66台可更换模块表做试点之用，已投标SESCO一个。现在获得DDZ1513和DTZ1513的技术认证，客户和马来西亚的几家电力公司建立较好的合作关系。我们需提供技术支持客户安装系统和表计，目前客户已将业务扩张到了菲律宾市场。', '郭涛', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('83', '60', 'INHE-0255', '2015-12-31 00:01:17', null, 'Genius Electronic Meter Co.,Ltd', 'W00018', 'Genius Electronic Meter Co.,Ltd', 'Genius', '亚洲', '泰国', '', '228/1 Phaholyothin Road, Samsennai, Phayathai, Bangkok, Thailand 10400', '客户想与我们在MEA和PEA项目中合作。但是在先提供样机和先支付研发保证金上一直未达成一致意见，已提供报价给客户。', '黄纯杰', '国际业务二部', null, null, 'E', 'INHE');
