INSERT INTO `inhe_customer_data` VALUES ('90', '55', 'lhz', '2015-12-31 00:01:24', null, 'VRP Holding Limited', 'khxx2015123128', 'VRP Holding Limited', '', '亚洲', '泰国', '', '', '有6个子公司。主要从事：电力系统设备的生产销售，油气产业，物流行业，汽车行业等。同PEA，MEA在机械表，避雷器，变压器等有业务往来。', '', '', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('91', '55', 'lhz', '2015-12-31 00:01:25', null, 'Porn Prom Metal Public Company Limited', 'khxx2015123129', 'Porn Prom Metal Public Company Limited', '', '亚洲', '泰国', '', '', '泰国一家上市公司，业务范围广泛，销售线缆，绝缘材料，铜等等。在电力公司人脉较广。近3年来一直致力于PEA智能表项目。', '', '', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('92', '55', 'lhz', '2015-12-31 00:01:26', null, 'Forth Meter Co.,Ltd.', 'khxx2015123130', 'Forth Meter Co.,Ltd.', '', '亚洲', '泰国', '', '', 'Forth Meter Co.,Ltd.,1989年成立，2005年上市。自去年开始联系我们。旗下的GEM公司有自己的电表厂，主营产品是电表。即之前的海龟项目的代理，客户目前掌握很详细的泰国市场信息。', '', '', null, null, 'E', 'INHE');
