INSERT INTO `inhe_customer_data` VALUES ('94', '55', 'lhz', '2015-12-31 00:01:28', null, 'HELLENIC ELECTRICITY DISTRIBUTION NETWORK OPERATOR S.A.', 'khxx2015123132', 'HELLENIC ELECTRICITY DISTRIBUTION NETWORK OPERATOR S.A.', '', '欧洲', '希腊', '', '', '希腊配电网络运营公司HEDNO是希腊公共电力公司（希腊最大的电力公司，为政府所有）的分公司，负责希腊配电网络的运营、维护及发展。', '', '', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('95', '55', 'lhz', '2015-12-31 00:01:29', null, 'ENERTA S.A.', 'khxx2015123133', 'ENERTA S.A.', '', '欧洲', '希腊', 'www.enerta.gr', '64 Louizis Riencourt St.\nApollon Tower\nAthens GR 115 23, Greece', 'ENERTA SA是希腊一家实力较强的全球性服务机构，其业务主要是帮助希腊境内和境外的公司开拓希腊的市场，其业务范围涵盖了电力，石油，天然气，风能，太阳能，建筑和其他行业。ENERTA SA和希腊政府部门、电力公司合作的项目较多，成功的案列较多。', '', '', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('96', '55', 'lhz', '2015-12-31 00:01:30', null, 'STALCO S.A.', 'khxx2015123134', 'STALCO S.A.', '', '欧洲', '希腊', 'www.stalco.gr', 'Ippokratous 1 & Fleming str\nMarousi - Attica', 'STALCO SA是希腊一家实力较强的电网配电设备生产企业，其业务主要是给希腊的电力公司PPC提供中压和低压的输电设备，STALCO SA和希腊电力公司PPC有40多年的业务来往，经常参加电力公司的招投标项目，和希腊电力公司PPC的建立很好的关系。', '', '', null, null, 'E', 'INHE');
