INSERT INTO `inhe_customer_data` VALUES ('123', '60', 'INHE-0051', '2015-12-31 00:01:57', null, 'The Kenya Power * Lighting Company Limited', 'W00009', 'The Kenya Power * Lighting Company Limited', 'KPLC', '非洲', '肯尼亚', '', '', '1.KPLC是肯尼亚唯一的国家配电与照明公司，由政府控股。2.KPLC自2017年至今动荡较大：管理层频繁变更、利润下降，自2019年起控制采购，削减成本，改善利润。3.目前电力公司受政治（商务）影响较大，电表技术部门影响力减弱。4.KPLC计划今年总计采购100万台电表，但目前受疫情影响，外来融资项目（世行、AFDB等）进度缓慢。5.预付费电表需求有所下降，等中兴部署MDMS及集抄系统（PZ03）后，预计智能电表需求将逐步上升。', '盛燕', '国际业务二部', null, null, 'E', 'INHE');
