INSERT INTO `inhe_customer_data` VALUES ('138', '61', 'INHE-0091', '2016-01-12 15:43:51', '2016-01-12 15:58:38', 'khxx2016011235/International Energy Technik (U) Ltd.  \r\n', 'khxx2016011235', 'International Energy Technik (U) Ltd.', 'IET', '非洲', '乌干达', ' http://www.iet.co.ke\r\r\r\n', 'P.O. Box 23881 | Plot 21, Lumumba Avenue | Kampala, Uganda \r\n', '1、从1990年开始一直代理西门子中低压产品及方案，公司资金实力雄厚，给电力公司UETCL，UEDCL，Umeme供过电器开关和变压器。\r\n2、2012年与我们合作投标过IET600项目，我们供应600台单相DIN双绞线电表及售电系统。', '林丽璇', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('139', '61', 'INHE-0392', '2016-01-13 09:52:37', '2016-01-13 09:57:49', 'khxx2016011336/TECNO STAFF S.A', 'khxx2016011336', 'TECNO STAFF S.A', 'TSI', '南美洲', '阿根廷', 'www.tsi-sa.com.ar\r\n', 'Pirán 6034 | C.A.B.A | C1431AMN | Argentina\r\n', '此客户之前是海兴的代理，后与海兴产生矛盾，在寻找新的合作厂家。当前该公司正积极开拓阿根廷的区域性市场，准备与当地其他4家电子公司（其他主要是电脑公司）共同形成一个集团，推行自主研发的AMI方案和架构，在该区域市场形成垄断产业，提供所需的所有电表类型、集中器和AMI软件。\r\n', '彭孜孜', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('140', '60', 'JXINHE-1277', '2016-01-15 09:01:26', '2016-01-15 09:29:28', 'khxx2016011538/KD Group', 'khxx2016011538', 'KD Group', 'KD ', '亚洲', '吉尔吉斯斯坦', '', '吉尔吉斯斯坦比什凯克玛纳斯大街基辅路 328号', '该客户是吉尔吉斯斯坦的一个贸易公司，主要会参加该国国内的一些投标，比如电线、电缆等产品，主要合作单位有：电信公司、电力公司、水泥厂、飞机场、一些私人公司等。客户与吉尔吉斯斯坦高层的关系相对比较好，实力相对比较强。', '李婉君', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('141', '53', 'JXINHE-2559', '2016-01-18 09:32:50', '2016-01-18 10:16:10', 'khxx2016011840/Abu Resala', 'khxx2016011840', 'Abu Resala', 'Abu', '亚洲', '阿富汗', '暂无', 'Kabul mandawee . Saraye badam. Second floor.  Room No : 2. Kabul Afghanistan\r\n', '阿富汗贸易公司（Sayem Rawof trading company），在浙江义乌有一家贸易公司(义乌市戴文在贸易商行)，员工人数12人左右。先前主要做服装类贸易，现进行多种经营，有承接电力部的一个小工程，年营业额5000万美金，销售能力较强，与国家国防部关系良好，提供了国防部支付其207000000阿富汗币（折合人人民币2900万左右的）的银行账单。了解电力市场，知道之前思达为该国市场电表主要供应商，该国在不久的将来9个省通电，会有大量合作机会。', '淦永妍', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('142', '61', 'INHE-0091', '2016-01-18 14:07:48', '2016-01-18 14:40:45', 'khxx2016011841/Millennium Challenge Account - Malawi\r\n', 'khxx2016011841', 'Millennium Challenge Account - Malawi', 'MCA', '非洲', '马拉维', 'http://www.mca-m.gov.mw\r\n', 'Attention: MCA-Malawi Procurement Agent\r\nStreet Address: Kang’ombe House, City Center\r\nFloor/Room number: 1st Floor, West Wing\r\nCity: Lilongwe', 'MCA是执行Millennium Challenge Corporation（MCC）公司（属美国政府）与马拉维政府签订的MILLENNIUM CHALLENGE COMPACT，由美国政府提供资金，援助在马拉维开展的项目，包括基础设施建设，电力改造，环境和自然资源管理。', '林丽璇', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('143', '60', 'INHE-0462', '2016-01-18 15:22:01', '2016-01-18 15:40:33', 'khxx2016011842/DELTAPRIMA METERING SDN BHDtest', 'khxx2016011842', 'DELTAPRIMA METERING SDN BHDtest', 'F', '亚洲', '马来西亚', 'www.deltaprima.com.my', 'No.22, Jalan SS26/6, Taman Mayang Jaya, 47301 Petaling Jaya, Selangor, Malaysia', '马来西亚共14个洲，该公司位于马来西亚沙阿兰，成立于2012.12.27，经营后付费电表销售。其80%股权由经营马国内水资源处理 / 化学制剂 / 油气开发的Damini Corporation SdnBhd持有，资金状况良好，水表方面与宁波三星合作，占市场份额50%，另一家是英国Jorshoamp。目前与该国内三大电力公司，含TENAGA NASIONAL / Sarawak energy / Sabah Electricity有合作关系。 该公司销售量在该国业内排名次于MIM / SMT / MISA / EDMI，排行第五。近期从ITRON采购三相表用于机场项目。该公司2015年9月建成电表生产车间，包括超声焊室，包装线，从盛迪购买的48表位修调校验台，设计产能300,000台/年，实验室已取得ISO17025证书，当地生产许可证书，暂未启动生产，约有5个工程师。当地进口关税6%，该公司为生产商，无贸易公司许可，如进口整表，每个批次需缴税2000美元，如进口散件，则无此笔费用。客户是当地表厂Smart Meter Technology（SMT）出身，其工程师曾是科陆技术支持，在科陆软件部总经理离职思达后离职，对国内深开发、思达、科陆、威胜等行业竞争对手较了解。', '曹亮', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('144', '53', 'JXINHE-2559', '2016-01-21 11:28:54', '2016-01-21 11:42:30', 'khxx2016012144/Suvas Shrestha', 'khxx2016012144', 'Suvas Shrestha', '', '亚洲', '尼泊尔', '暂无', 'Next to United Nation Head Quarter (UN House), Harihar Bhawan, Lalitpur, Nepal', '客户是一家专门做国际招投标的承包商，行业内经验超过25年，与尼泊尔国家电力部和NEA董事会关系良好，主要是给NEA(尼泊尔电力部)做配电设备，输电线路或工程师今年承接了两个大的项目，金额达到5亿美金。', '淦永妍', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('145', '53', 'JXINHE-2559', '2016-01-21 11:43:23', '2016-01-21 13:42:07', 'khxx2016012145/Nabin Pokhrel', 'khxx2016012145', 'Nabin Pokhrel', '', '亚洲', '尼泊尔', '暂无', '', '公司名称 IMS Consultancy，公司年营业额超过2亿美金，占据市场份额40%，与NEA尼泊尔电力公司合作超过15年且关系密切。之前是做输电线路，变电站，大坝等。集团人数200人，部门人数17人。通过NEA推荐与我们取得联系。', '淦永妍', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('146', '60', 'INHE-0391', '2016-01-22 15:12:39', '2016-01-22 15:57:53', 'khxx2016012247/Al Yaqeen Group', 'khxx2016012247', 'Al Yaqeen Group', '', '亚洲', '阿曼', 'www.yaqeeneng.com', 'Ghala-Al Nahda Towers II-704 P.O.Box:2902 Muscat-Sultane of Oman', '该集团旗下的Al Yaqeen Engineering Co.LLC 公司是一家专门从事电力工程和水务工程建设的专业公司，从2013年起与银河就建立合作，在MEDC以及Majan两个电力公司推行银河电表，建立小规模试点。', '桂弯弯', '国际业务一部', null, null, 'E', 'INHE');
