INSERT INTO `inhe_customer_data` VALUES ('151', '53', 'JXINHE-2559', '2016-02-16 09:38:15', '2016-02-16 09:48:16', 'khxx2016021656/Naresh Agrawal', 'khxx2016021656', 'HIGHTENSION SWITCHGEARES PVT. LTD., KATHMANDU, NEPAL', '', '亚洲', '尼泊尔', '', 'A.T .COMPLEX, NEW PLAZA, KATHMANDU, NEPAL\r\r\n', '客户是由尼泊尔一家电力公司bpc推荐的代理,是当地一家主要做电力材料和工程的贸易公司。主要产品为输电，变电站设备，开关，控制面板，代理知名品牌产品参加当地的招投标项目。与该客户合作过当地4000台单相电表的投标，合作态度积极，对当地电表市场及价格较为熟悉。', '淦永妍', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('152', '61', 'INHE-0434', '2016-02-16 11:27:25', '2016-02-16 11:48:48', 'khxx2016021658/Danat Trading and Services Plc\r\n', 'khxx2016021658', 'Danat Trading and Services Plc', '', '非洲', '埃塞俄比亚', '', '', '1. 该公司于2015年成立。主要从事不同产品(礼品，促销品，免费样品)分销，打印服务，平面设计以及作为咨询公司提供服务。\r\n2. 该公司除了以上业务，还涉及能源领域，铁路，农业，以及制造业。\r\n3. 因其涉足以上领域，其合作伙伴有：TBEA SunOasis Co. Ltd Of China, 中国农机院(CAAMS), 四川电力送变电建设有限公司，中国机械设备工程股份有限公司，韩国WOOAM, Inc公司，波兰ILF Consulting Engineers公司，西班牙ABEINSA/ABEINGOA公司。\r\n4. 因我司提出拜访EEU电力公司，其帮忙向电力公司递交了我司合作意向函，并落实了与电力公司的会议/宣讲/演示等安排。\r\n', '钟云林(Andy)', '国际业务二部', null, null, 'E', 'INHE');
