INSERT INTO `inhe_customer_data` VALUES ('156', '61', 'INHE-0490', '2016-02-18 09:06:56', '2016-02-18 10:10:27', 'khxx2016021862/Cashpower Sudamericana S.A.', 'khxx2016021862', 'Cashpower Sudamericana S.A.', 'CSA', '南美洲', '阿根廷', 'www.cashpower.com.ar', '阿根廷布宜诺斯艾利斯', '该公司由4个主要股东于2000年在阿根廷注册成立，其中联系人占股份63%，主要业务是STS预付费系统，咨询与培训，电表维修和校准。之前是兰吉尔在南美洲的代理，现已结束与兰吉尔的合作关系。该公司是阿根廷唯一的预付费系统供应商，在阿根廷安装了超过13万台电表。此外该公司在美洲各国都不错的联系人，在电力行业具有较强影响力。', '范辉英', '市场二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('157', '60', 'INHE-0424', '2016-02-18 16:26:03', '2016-02-18 16:49:39', 'khxx2016021865/JIRAMA', 'khxx2016021865', 'JIRO SY RANO MAlAGASY', 'JIRAMA', '非洲', '马达加斯加', 'http://www.jirama.mg/\r\n	\r\n', 'Lot II C 15 Faravohitra Rue Rainandriamampandry Antananarivo 101', 'JIRAMA是由马达加斯加国家全资拥有的有限责任公司，成立于1975年10月17日，其注册资本175.3亿Ariary（约593万美金）。它由国家财政部监管财务，由国家技术部负责能源和水资源的技术监督。该公司负责生产、运输和配发马达加斯加电力，以保证全国水电供应。						\r\n', '代莎', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('158', '53', 'JXINHE-2433', '2016-02-19 11:44:40', '2016-02-22 09:28:31', 'khxx2016021966/MINT/CZ ELECTRONICS MANUFACTURING (PTY) LTD.', 'khxx2016021966', 'MINT/CZ ELECTRONICS MANUFACTURING (PTY) LTD.', 'MINT/CZ Electronics', '非洲', '南非', 'www.czelectronics.co.za.', 'Unit 81, Van Dyk Secure Business Park, Cnr Brakpan and Van Dyk Roads, Boksburg Industrial East, Boksburg 1514, South Africa', 'MINT/CZ Electronics 是南非四大表厂之一，是黑人控股公司，在南非市场占有很大的优势。有雄厚的经济实力和强大的关系网：MINT/CZ Electronics的CEO Mr. Oupa Magashula,曾是南非国税局负责人，负责征收所有的税（进口税，关税，增值税等等），为政府和国家的运作提供资金，为南非执政党ANC筹过款，与ANC的关系非常好，ANC是国会的多数党，负责各省份和市政厅重要职位的干部分配，所以政府和市政厅投标合同的授予更多的取决于和ANC的关系。', '黄倩', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('159', '66', 'INHE-0512', '2016-02-24 13:43:25', '2016-02-24 14:53:53', 'khxx2016022468/INDEGOLA', 'khxx2016022468', 'INDEGOLA', 'INDEGOLA', '非洲', '安哥拉', 'www.bragalux.pt', 'Empreendimento Mix Center, 1o Andar', 'INGEGOLA\r是葡萄牙公司Bragalux-Montagens Eléctricas SA在安哥拉的分公司。该公司主营电力设备，产品涵盖电缆线，配电，电信设备，电路板，发电机等。该公司相关电力公司客户有Powergol,Ambergol,telectrinf。\r\r\n', '杨振', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('161', '60', 'INHE-0419', '2016-02-25 16:37:31', '2016-02-26 14:09:11', 'khxx2016022570/Ho Chi Minh City Power Corporation\r\n', 'khxx2016022570', 'Ho Chi Minh City Power Corporation', 'HCMPC', '亚洲', '越南', 'www.hcmpc.com.vn', 'Green Power Bld., 35 Ton Duc Thang Street, Dist. 1, Ho Chi Minh City, Vietnam', '胡志明电力公司，为越南5大电力公司之一。同时为越南智能电表新技术引进标杆公司。该公司业务范围覆盖胡志明市9个郡、5各县。预计2016-2020年5年间，胡志明电力公司将会又2百万台电表采购计划。', '曾波', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('162', '66', 'INHE-0512', '2016-02-26 15:17:15', '2016-02-26 15:35:00', 'khxx2016022671/Bragalux-Montagens Eléctricas SA\r\n', 'khxx2016022671', 'Bragalux-Montagens Eléctricas SA', 'Bragalux\r\r\n', '欧洲', '葡萄牙', 'www.bragalux.pt', 'Parque Industrial de Pitancinhos, no 67\r\n4700-706 Braga PORTUGAL\r\n', 'Bragalux是一家葡萄牙公司。公司主营电力设备，产品线涵盖电缆线、电信设备、电路板、发电机、配电等。该公司旗下分公司Indergola主要参与安哥拉的项目竞标。客户目前需要寻找一位可靠的电表生产商作为他们的合作伙伴一起参与安哥拉当地的投标项目。\r\r\n', '杨振', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('163', '61', 'INHE-0509', '2016-03-01 09:45:28', '2016-03-01 10:03:19', 'khxx2016030172/SANA Meter Co.ltd', 'khxx2016030172', 'SANA Meter Co.ltd', 'SANA', '亚洲', '伊朗', 'http://www.iranmeter.com/\r\n', 'Unit B. 12nd floor. KAJ Bldg. KAJ Sq. SAADATABAD . Tehran. Iran\r\r\n', '伊朗当地电表厂，成立于1999年，是伊朗最早做AMI系统的公司之一，有自主研发的CT智能表。2011年到公司参观过，对中国电表厂商很熟悉', '陈怀枝', '国际市场二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('164', '61', 'INHE-0432', '2016-03-01 11:12:18', '2016-03-01 17:23:13', 'khxx2016030173/Klartek Nigeria Limited', 'khxx2016030173', 'Klartek Nigeria Limited', 'Klartek', '非洲', '尼日利亚', 'N/A', 'Plot9, Elsie Femi Pearce Street, Lagos State, Nigeria', '性质：私营 主营业务：电子类产品贸易进口。电表行业经验：曾与印度公司Genus合作过2年，但认为对方公司产品价格过高，且无法获得足够的售后支持等，因而寻求新的供应商。CEO背景：曾任美国Oceanbank北京办事处首席代表，目前兼任当地一家投资公司市场总监Alpha Mutual Company. 2016年计划采购1万台电表供给当地5个电力公司。目前期望我司提供相关文件重新申请进口认证，其中一项是需要从我司购买样机至尼日利亚电力监管局做产品测试认证。认证通过方能申请进口许可，进而购买电表。', '谭东羊(Timon)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('165', '61', 'INHE-0432', '2016-03-01 15:05:39', '2016-03-01 15:48:09', 'khxx2016030174/Jaysquar Power', 'khxx2016030174', 'Jaysquar Power Services Limited', 'Jaysquar', '非洲', '尼日利亚', 'N/A', 'Off Biodun Ogunsanwo Street, Off Nnobi Street, Surulere,Lagos, Nigeria', '性质：私营 主营业务：高压表计量箱设备采购及安装 行业经验：Jaysquar的董事长是另一家公司First Choice Global的总经理，且是PHCN旗下配电公司的前任CEO。First Choice Global主营业务为：提供电力工程安装解决方案并实施现场安装，采购电力行业产品如电线电缆，变压器等。Jaysquar则只做高压表计量箱设备业务，其团队经验非常丰富，为PHCN，及后来的Enugu,Abuja,Ikeja等多个电力公司执行过很多个高压表计量箱项目。', '谭东羊(Timon)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('166', '61', 'INHE-0431', '2016-03-01 16:08:32', '2016-03-01 16:13:18', 'khxx2016030175/BRILLIANCE TECHNOLOGIES CO., LIMITED\r\n', 'khxx2016030175', 'BRILLIANCE TECHNOLOGIES CO., LIMITED', 'Brilliance', '亚洲', '香港', 'guojia@brilliance-led.com\r\n', 'FLAT/RM B 8/F CHONG MING BUILDING 72 CHEUNG SHA WAN ROAD KL, HONGKONG\r\r\r\n', '他是I4 Power Technology合作超过十年的本地伙伴,有时代I4公司下单,付款', '刘佩(Ted)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('167', '61', 'INHE-0432', '2016-03-02 14:32:16', '2016-03-02 14:49:46', 'khxx2016030277/Musty Digital*Security Systems Ltd', 'khxx2016030277', 'Musty Digital*Security Systems Ltd', 'Musty', '非洲', '尼日利亚', 'http://www.mustydigital.com\r\n', 'Metro Plaza Suite AF 08, Annex A, Plot 991,992 Zakariya Maimalari Street, Central Area, P.O Box 6049 Garki, Abuja, Nigeria', '性质：私营 主营业务：进口电子消费类产品如照相机，手机等，和中国青岛的一家电子产品公司合作关系很好。CEO个人背景：尼日利亚前商务部部长，参与组建尼日利亚驻中国上海外贸办公室，多次率尼日利亚代表团参加WTO,联合国会议，世界达沃斯经济论坛等国际性会议。成立了中小企业发展基金组织，现任尼日利亚投资发展委员会执行秘书长。', '谭东羊(Timon)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('168', '53', 'JXINHE-2559', '2016-03-03 08:38:03', '2016-03-03 09:10:34', 'khxx2016030379/Nikola Donovski\r\n', 'khxx2016030379', 'ENGINEERING DASS，OHRID', 'Nikola ', '欧洲', '马其顿', 'www.dass.com.mk', 'P.O.Box 143, 6000 Ohrid / MACEDONIA', '公司成立于1993年，从其官网上www.dass.com.mk的介绍来看，是一家主要从事于电力工程的公司如中低压配面板的设计和生产，变压器和配电开关的设计，生产和组装，配电线路的设计和安装等.公司2009年营业额达到7百万欧元。业务牵涉四个地区贝尔格莱德(塞尔维亚首都)，波德戈里察(南斯拉夫一个城市)，普里什蒂纳(塞尔维亚一个省会城市)，地拉那(阿尔巴尼亚的首都)。', '淦永妍', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('169', '60', 'INHE-0514', '2016-03-03 11:40:08', '2016-03-03 15:53:02', 'khxx2016030381/SCAN Electromechanical Contracting Co LLC\r\n', 'khxx2016030381', 'SCAN Electromechanical Contracting Co LLC', 'SEC', '亚洲', '阿联酋', 'www.scanelectromechanical.com', 'P. O. Box 31599, Sharjah, UAE', '该公司位于阿联酋沙迦地区，是一家主要从事与变压器，光缆相关的生产以及施工相关的公司，属于承包商性质。在过去，主要承包的工程主要涉及变电站的相关施工工程，光缆及配件的铺设与安装，配电网络系统的施工等等，项目地点，主要集中在沙迦地区，也涉及迪拜，富查伊拉以及其他酋长国地区，整体来讲，实力还是不错的。							\r\n					\r\n', '李成兵', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('170', '61', 'INHE-0509', '2016-03-10 13:25:58', '2016-03-10 13:45:16', 'khxx2016031084/TES-TOP Engineering Suppliers', 'khxx2016031084', 'TES-TOP Engineering Suppliers', 'TES-TOP', '非洲', '莫桑比克', '', 'TES-TOP, AV. KARL MARX NO. 1877. MAPUTO. MOZAMBIQUE', 'ABB经销商，兰吉尔独家代理，涉及贸易，工程施工，加气站等方面。公司总人数有400多人\r\r\r\r\n', '陈怀枝', '国际市场二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('171', '53', 'JXINHE-2288', '2016-03-10 16:18:56', '2016-03-10 17:21:07', 'khxx2016031086/Manolo Véliz', 'khxx2016031086', 'Manolo Véliz', '', '北美洲', '危地马拉', '', '', '客户为危地马拉第二大城市Quetzaltenango的一电力设备贸易商，所经营的区域有6万个电表用户，他了解到当地电表都比较陈旧，电力公司打算更换成先进的智能表，看到我们网站上的ANSI表比较符合当地需求，故联系我们了解我们各种ANSI表之间的区别，希望我们能提供样表，报价和智能表演示视频以便他去当地电力公司推广我们的产品。', '张正宜', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('173', '60', 'INHE-0514', '2016-03-11 14:45:34', '2016-03-14 12:39:45', 'khxx2016031188/Microhit Technologies LLC', 'khxx2016031188', 'Microhit Technologies LLC', '', '亚洲', '阿联', 'http://microhit.com\r\n', 'Suite No. 401 Dubai Insurance Bldg. Al Rigga St.\r\nP.O. Box 32596 - Deira Dubai, UAE\r\n			\r\n', 'Microhit Technologies LLC是一家从事通信，无线以及安防系统的公司，在中东地区有超过30年的历史和经验，是摩托罗拉，海能达，宝利通等在迪拜的代理，实力以及信誉都不错。', '李成兵', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('174', '61', 'INHE-0431', '2016-03-11 22:57:59', '2016-03-14 15:43:29', 'khxx2016031189/Feleo Investment CC\r\n', 'khxx2016031189', 'Feleo Investment CC', 'Feleo', '非洲', '纳米比亚', '无', 'P.O. Box 26579, Windhoek\r\r\n', '代理Windhoek市政的项目，应该是市政工作人员，有一个GOV的邮箱', '刘佩(Ted)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('175', '66', 'INHE-0515', '2016-03-14 10:50:20', '2016-03-14 12:36:23', 'khxx2016031490/INNOVATECH GE S.L\r\n', 'khxx2016031490', 'INNOVATECH GE S.L', 'ITG', '非洲', '赤道几内亚', 'www.innovatechge.com', '暂无', 'INNOVATECH GE S.L  是赤道几内亚的一个提供电信解决方案的系统集成商，为赤道几内亚的电力公司服务，寻求完整的AMI解决方案，此次希望在首都马拉博进行400个用户的试点计划，再逐步扩大到所有用户。公司对于赤道几内亚市场尚未开发，其有可观的电表需求潜力。\r\r\r\n						\r\r\r\n						\r\r\r\n', '陈鑫', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('176', '61', 'INHE-0509', '2016-03-14 13:35:18', '2016-03-14 13:48:47', 'khxx2016031491/JEDIG GROUP', 'khxx2016031491', 'JEDIG GROUP', 'JEDIG', '非洲', '莫桑比克', '', '2nd floor Dean Street Arcade\r\n2 Dean Street\r\nNewlands 7700\r\n', '董事长JOSE与施耐德合作起家，从事电表业务多年，公司JEDIG GROUP在南非，在安哥拉有一公司JTDL Holding。\r\rJOSE与莫三比克EDM及安哥拉ENDE高层有一定关系\r\r\r\r\r\n', '陈怀枝', '国际市场二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('177', '61', 'INHE-0440', '2016-03-15 16:03:37', '2016-03-15 18:23:12', 'khxx2016031593/B.K.K.(1985) PUBLIC COMPANY LIMITED', 'khxx2016031593', 'B.K.K.(1985) PUBLIC COMPANY LIMITED', 'BKK', '亚洲', '泰国', 'www.bkk.co.th', '201 Soi Kubon 13 Yak 2, Ramintra, Khannayao, Bangkok, Thailand 10230', 'B.K.K. (1985) Public Company Limited 成立于1985年，目前是泰国主要的建筑、施工企业之一，1996年成为上市公司，启动资金4.9亿泰铢，公司已施工了几十亿泰铢的建筑和基础设施建设项目。BKK的业务范围包括建设商住综合楼，宾馆，医院，工业厂房等，基础设施建设包括，天然气管道，防洪大坝，污水处理厂，路桥建设等。BKK旗下有两家全资子公司, B.K.K. Infrastructure Company Limited 和Mechanical Engineering Works Company Limited，其中B.K.K. Infrastructure Company Limited 成立于1986年，启动资金1亿泰铢，主要致力于公共事业的建设项目和基础设施建设项目，公司是泰国政府认可的政府项目承建商，例如路桥项目，污水处理系统，灌溉系统，土建工程等。Mechanical Engineering Works Company Limited 成立于1991年，启动资金6千万泰铢，主要致力于贸易和租赁建筑设备，例如工作台，乘客、物料起重机，振动系统，锯床等。                                                                    ', '汤伟(Will)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('178', '61', 'INHE-0432', '2016-03-15 18:06:36', '2016-03-15 18:18:52', 'khxx2016031594/Arnergy Solar Ltd. ', 'khxx2016031594', 'Arnergy Solar Ltd.', 'Arnergy', '非洲', '尼日利亚', 'http://www.arnergy.com', '7A, Akinola Cole Crescent, Off Adeniyi Jones Avenue, Ikeja, Lagos, Nigeria', '性质：私营 人数：50人以下。主营业务：提供太阳能照明产品及解决方案。目前太阳能发电项目在尼很受政府支持。在尼日前经济下滑，贷款极度紧张的情况下，Arnergy和GVE一起拿到了Bank of Industry贷款，做太阳能发电项目，并从我司购买电表供给偏远村庄用户。', '谭东羊(Timon)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('179', '61', 'INHE-0432', '2016-03-16 20:17:11', '2016-03-17 09:22:05', 'khxx2016031695/RIEX Limited', 'khxx2016031695', 'RIEX Limited', 'RIEX', '非洲', '卢旺达', 'http://www.riexrwanda.com', '卢旺达基加利', '性质：私营 人数：20人以下 主营业务：电力行业。其老板旗下两家公司：RIEX注册为贸易公司，做招投标项目，同时代理电子产品，如电表等。另外一家为REPRO Limited，专门做发电厂项目，在卢旺达已建立了一座小型发电厂，目前正和中国正泰合作电厂项目。 电表及招投标经验：此前与CONLOG有合作过，后关系破裂。近几年有参与电表行业招投标项目，EW10开标时其有代表在开标现场。与电力公司人员有较好关系。', '谭东羊(Timon)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('180', '53', 'JXINHE-2559', '2016-03-21 14:44:53', '2016-03-21 15:03:54', 'khxx2016032196/Simcontrol Solutions Ltd', 'khxx2016032196', 'Simcontrol Solutions Ltd', '', '欧洲', '罗马尼亚', 'www.simcontrol-solutions.com', 'RAMS Business Park, 42 Dudesti Pantelimon street\r\r\nZip code 033094,  3th district, Bucharest, Romania\r\r\n', '罗马尼亚当地的电力材料分销商，系统集成商，面板安装公司，公司下设多个子公司，去年就面板安装项目营业额达到2百万欧元，公司营业范围有罗马尼亚，捷克，白俄罗斯，迪拜等。', '淦永妍', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('181', '61', 'INHE-0374', '2016-03-22 09:13:07', '2016-03-22 10:45:50', 'khxx2016032297/ Amadou Baiba KOUMA', 'khxx2016032297', 'Amadou Baiba KOUMA', 'Amadou', '非洲', '马里', '', '马里巴马科', '原为海兴马里代理，引进海兴产品后与海兴产生矛盾后终止合作，目前在寻找新的合作伙伴。', '王子强', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('182', '53', 'JXINHE-2288', '2016-03-31 10:20:10', '2016-03-31 10:45:55', 'khxx20160331101/ReV2G Inc', 'khxx20160331101', 'ReV2G Inc', 'ReV2G', '北美洲', '美国', 'www.rev2g.com ', '', 'ReV2G公司于2008年在美国加利福利亚州成立，专注于可再生能源领域，为构建大型风能，太阳能等可再生能源的公用事业单位提供工程咨询服务，经营过超过10000MW的电能项目。他们在巴勒斯坦有一家名为MMNCO的兄弟公司，为ReV2G公司老板的哥哥所创立，经营能源和电力工程，在当地有45年的历史，目前正在运作一个月销量12000台的导轨分体式单相键盘预付费智能表和BS分体式三相键盘预付费智能表项目。', '张正宜', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('183', '61', 'INHE-0432', '2016-03-31 14:50:34', '2016-03-31 15:04:39', 'khxx20160331103/GMA Global Resources Limited\r\n', 'khxx20160331103', 'GMA Global Resources Limited', 'GMA', '非洲', '尼日利亚', '', 'NO 7 KEN UBA STR OFF AGUNGI ROAD LE\r\r\nKKI LAGOS 234 Nigeria\r\r\n', 'GMA是一家私人贸易公司，从事进口小宗商品。很早已与银河有接触。此前从NR05客户那里买了小批量电表做试点。', '谭东羊(Timon)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('184', '66', 'INHE-0515', '2016-04-01 11:33:09', '2016-04-01 16:40:46', 'khxx20160401104/LA SOCIETE NATIONALE D\'ELECTRICITE', 'khxx20160401104', 'LA SOCIETE NATIONALE D`ELECTRICITE', 'SNEL', '非洲', '刚果（金）', 'http://www.snel.cd', '2831, Avenue de la JusticeB.P. 500 Kinshasa/Gombe\r\r\n', '刚果（金）国家电力公司，银河表计曾于2013年为其供应过少量电表；于2015年4月，我方曾出差拜访，寻求代理，并为其融资建立表厂的计划发送过融资方案。目前该国人口众多，电表市场潜力广阔，且存在30万台电表的潜在需求。', '陈鑫', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('185', '61', 'INHE-0091', '2016-04-01 11:36:27', '2016-04-01 13:36:47', 'khxx20160401105/Quality Extended Enterprise Limited\r\n', 'khxx20160401105', 'Quality Extended Enterprise Limited', 'QEEL', '非洲', '坦桑尼亚', 'http://qualitygroup.com/portfolio_page/quality-extended-enterprise-limited/\r\n', 'Quality Plaza, 2nd Floor, Nyerere Road, P.O.Box 235, Dar es Salaam, Tanzania', 'Quality Extended Enterprises Ltd (QExE) manages the extended business operations of the Group in Tanzania and East Africa, its home turf. QExE oversees one of the largest and fastest growing business operations in the region.\r\n \r\nQExE is the prime-mover of Group’s operations wherein it renders overall strategic direction to the subsidiaries/SBU, plays the pivotal role of business integration, and leadership. Each core business is independently pursued by a subsidiary company/Strategic Business Unit (SBU) of QExE.\r\n \r\nQExE derives synergy out of operations of different operating companies/divisions by ensuring that such entities function in a coordinated manner, complementing each other. Such operational synergies result in reduced costs, quality deliverance to customers, enhanced profits, besides other benefits of collective participation.', '林丽璇', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('186', '60', 'INHE-0514', '2016-04-01 15:45:09', '2016-04-01 16:01:25', 'khxx20160401106/Ramzi Khudair Company Electric Tools  ', 'khxx20160401106', 'Ramzi Khudair Company Electric Tools', '', '亚洲', '巴勒斯坦', 'https://www.facebook.com/ramzy.kh.co', 'Palestine, Gaza     ', 'Ramzy  Khudair company, working in the field of sales of electric tools, in Gaza, since 2011, we import electrical tools from abroad (such as China, Turkey), We have an excellent experience in the field of installation and maintenance, we have a dedicated team in the electricity, where our mandate by the Electricity Distribution Company, the Gaza Strip, for the supply of pre-paid counters System', '李成兵', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('187', '60', 'INHE-0424', '2016-04-01 16:03:32', '2016-04-01 16:56:57', 'khxx20160401107/ENERGIE DU MALI.SA', 'khxx20160401107', 'ENERGIE DU MALI.SA', 'EDM', '非洲', '马里', 'www.edm-sa.com.ml', 'SQUARE PATRICE LUMUMBA, BP 69\r\r\r\nBamako\r\r\r\nMali\r\r\r\n', 'EDM是一家工业和商业有限责任公司，于1960年10月14日由马里政府成立，2011年分为水电两部分，目前马里政府控股66%，政府每年定向拨款补助。 EDM刚发布了招标通知，预采购新型低压电表（每年7万台），并且逐步替代现有的40万台电表，要求先去当地演示方案，通过后再试点。试点1000台，2016年6月开始执行，试点通过后进行批量采购。', '代莎', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('188', '53', 'JXINHE-2559', '2016-04-05 14:13:53', '2016-04-05 14:24:22', 'khxx20160405109/Pivotal Infotech Sdn Bhd ', 'khxx20160405109', 'Pivotal Infotech Sdn Bhd', '', '亚洲', '马来西亚', 'www.pivotal.com.my', 'A2-30-1 SOHO Suites @ KLCC, No 20 Jalan Perak, 50450 Kuala Lumpur, Malaysia.', '公司从事医疗IT系统12年，客户个人对于电脑和通讯软件硬件非常熟悉。国家电力公司关系非常好并正在在做太阳能产品，作为TNB(国家电力公司)的附属公司参加此次项目。行业经验2年，之前未做过电能业务和电表生意但做过价值350万马来西亚币(折合人民币543万)的软件生意 目前IT医院合同有36名员工，预计员工人数将会达到150人左右。', '淦永妍', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('189', '60', 'INHE-0088', '2016-04-05 13:45:32', '2016-04-05 16:08:29', 'khxx20160405108/DELTAPRIMA METERING SDN BHD', 'khxx20160405108', 'DELTAPRIMA METERING SDN BHD', 'DPM', '亚洲', '马来西亚', 'www.deltaprima.com.my', 'No 8, JalanBiolaSatu33/1A, Elite Industrial Estate,\r\nSeksyen33, 40400 Shah AlamSelangor\r\n', '该公司位于马来西亚沙阿兰，成立于2012.12.27，经营后付费电表销售。其80%股权由经营马国内水资源处理 / 化学制剂 / 油气开发的Damini Corporation SdnBhd持有，资金状况良好，水表方面与宁波三星合作，占市场份额50%，另一家是英国Jorshoamp。目前与该国内三大电力公司，含TENAGA NASIONAL / Sarawak energy / Sabah Electricity有合作关系。 该公司销售量在该国业内排名次于MIM / SMT / MISA / EDMI，排行第五。近期从ITRON采购三相表用于机场项目。该公司2015年9月建成电表生产车间，包括超声焊室，包装线，从盛迪购买的48表位修调校验台，设计产能300,000台/年，实验室已取得ISO17025证书，当地生产许可证书，暂未启动生产，约有5个工程师。当地进口关税6%，该公司为生产商，无贸易公司许可，如进口整表，每个批次需缴税2000美元，如进口散件，则无此笔费用。客户是当地表厂Smart Meter Technology（SMT）出身，其工程师曾是科陆技术支持,对国内深开发、思达、科陆、威胜等行业竞争对手较了解。2016年3月28号考察过该公司，客户带领与电力公司TNB项目经理见面并安排后续技术演示事宜。', '余冬纯', '国际业务一部', null, null, 'E', 'INHE');
