INSERT INTO `inhe_customer_data` VALUES ('195', '61', 'INHE-0497', '2016-04-18 09:41:47', '2016-04-25 10:58:09', 'khxx20160418117/Lumicorp', 'khxx20160418117', 'Lumicorp', 'Lumi', '南美洲', '巴拉圭', 'www.lumicorp.com.py\r\n', 'Avda. Artigas 988 c/ Cusmanish\r\r\r\nAsunción, Paraguay\r\r\r\r\n', 'Lumicorp属于Grupo Luminotecnia集团旗下公司，在全国有10家分公司。业务范围涉及电力设备，电力线材，照明，电力施工等，与国家电力公司ANDE及认证机构INTN有着紧密的往来，每年国家电力公司从该公司采购的产品金额约1000万美金。代理有一定的电力公司和认证机构的人脉关系。', '曹荃', '国际业务2部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('196', '61', 'INHE-0518', '2016-04-19 17:37:21', '2016-04-19 17:49:31', 'khxx20160419119/THE GENERAL COMPANY FOR INTERNATIONAL TRADING', 'khxx20160419119', 'THE GENERAL COMPANY FOR INTERNATIONAL TRADING', 'GCIT', '非洲', '突尼斯', 'www.gcit-tunisia.com', 'Avenue Habib Bourguiba.Immeuble Venezia App403.BP7000.Bizerte.Tunisie', '一家国际贸易公司，在非洲阿尔及利亚、喀麦隆、塞内加尔等国从事商业活动。该客户目前有电表及表箱需求', '熊璟', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('197', '53', 'JXINHE-2288', '2016-04-22 03:39:16', '2016-04-22 08:40:12', 'khxx20160422120/PROCAL', 'khxx20160422120', 'Proyectos y Calculos S.A.C', '', '南美洲', '秘鲁', 'www.procal.pe', 'Leonidas Yerovi 104 Of. 202', '该客户是秘鲁一家从事电力，自动化，机械等领域里的工程设计公司，目前其电表用户是一家建筑公司正在建造2000套别墅，需要757台二相PLC智能表和142台三相PLC智能表，9台集中器，通过GPRS网络将数据传给电力公司管理中心。目前秘鲁还是采用老式人工一家一户地抄表，智能表对当地还是新生事物，客户准备将我们的AMI智能表和系统通过建筑公司这一试点项目引入到秘鲁，逐步扩大市场范围。', '张正宜', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('198', '60', 'INHE-0406', '2016-04-22 13:54:07', '2016-04-22 15:00:54', 'khxx20160422121/The Cabinet of Ministers of the Republic of Uzbekistan', 'khxx20160422121', 'The Cabinet of Ministers of the Republic of Uzbekistan', 'CMRU', '亚洲', '乌兹别克斯坦', '', 'Tashkent', '乌国部长办公室负责乌兹别克斯坦智能电网项目第二次招标，大概是9月份进行，其最终用户是Uzbekenergo,这次招标负责Fergana, Namangan, Andijan 和 Kashkadarya四地的智能电网项目，约300万只表。', '王毅', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('199', '60', 'INHE-0424', '2016-04-26 16:08:44', '2016-04-26 16:08:44', 'khxx20160426123/Liberian Agricultural Company ', 'khxx20160426123', 'Liberian Agricultural Company', 'LAC', '非洲', '利比里亚', '', '20th street SINKOR Liberia, West Africa\r\r\n', '利比里亚农场项目，客户为控制用电量，计划在其负责的范围内推广预付费电表。之前已经通过其代理购买我们的电表。现在想扩大试点项目，准备购买BS安装预付费代码表。该国家没有国网，基本上是私人发电厂和私人公司购买安装电表。 \r\r\n', '代莎', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('200', '60', 'INHE-0088', '2016-04-27 13:46:00', '2016-04-27 14:15:15', 'khxx20160427124/JES Instrumentation * Controls', 'khxx20160427124', 'JES Instrumentation*Controls', 'JES', '亚洲', '巴基斯坦', 'www.jamali.org', '302 EUROPA CENTER, HASRAT MOHANI ROAD OFF, L.L.CHUNDRIGHAR ROAD, KARACHI, 302 EUROPA CENTER, HASRAT MOHANI ROAD OFF, L.L.CHUNDRIGHAR ROAD, KARACHI, 74200，PARKISTAN ', '\r\r\r\r\r\r\r\r\r\r\nJES Instrumentation & Controls\r\r\r\r\r\r\r\r\r自2011年与我司合作，作为我司在巴基斯坦私人项目代理商，该公司业务主要为\r工业自动控制系统，承包私人电力安装项目。\r\r\r\r\n', '余冬纯', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('201', '53', 'JXINHE-2559', '2016-04-28 16:13:46', '2016-04-29 11:03:06', 'khxx20160428125/Inaris Asia Pacific Sdn Bhd\r\n', 'khxx20160428125', 'Inaris Asia Pacific Sdn Bhd', 'FA', '亚洲', '', 'www.flywaveasia.com', '11-2,Jalan Mahkota Residence 1,Bandar Mahkota Cheras,\r\r\r\n43200 Kajang,Selangor,Malaysia.', '马来西亚当地规模较大的广播公司，是华为通信产品的合作伙伴，汽油开采平台工程的授权合作方，现在开始开拓电力业务。与马来西亚当地较大的通讯公司CELCOM合作，参加沙巴洲电表项目。', '淦永妍', '工业园国际业务部', null, null, 'E', 'INHE');
