INSERT INTO `inhe_customer_data` VALUES ('203', '61', 'INHE-0440', '2016-05-09 13:36:42', '2016-05-09 14:33:50', 'LEE JONG ELECTRICAL & ENGINEERING SDN BHD (MALAYSIA)', '', 'LEE JONG ELECTRICAL & ENGINEERING SDN BHD (MALAYSIA)', 'LEE JONG ', '亚洲', '马来西亚', 'www.leejong.com.my', 'Sublot 71, 1st Floor, Lot 7892\r\nQueen’s Court, Block B,\r\nJalan Wan Alwi,\r\n93300 Kuching,\r\nSarawak, Malaysia ', '客户公司成立于1997年，业务涉及马来西亚和文莱的住宅、商业和工业项目的电力相关服务、安装、电表以及相关售电系统。其是STS成员，有多年项目运作经验，在当地电力公司有有效的人脉关系。', '汤伟(Will)', '国际业务二部', null, null, 'E', 'INHE');
