INSERT INTO `inhe_customer_data` VALUES ('205', '61', 'INHE-0440', '2016-05-09 14:44:07', '2016-05-09 14:50:51', 'khxx20160509128/LEE JONG ELECTRICAL CO. SDN BHD ', 'khxx20160509128', 'LEE JONG ELECTRICAL CO. SDN BHD', 'LEE JONG ', '亚洲', '马来西亚', 'www.leejong.com.my', 'Sublot 71, 1st Floor, Lot 7892\r\r\nQueen’s Court, Block B,\r\r\nJalan Wan Alwi,\r\r\n93300 Kuching,\r\r\nSarawak, Malaysia ', '客户公司成立于1997年，业务涉及马来西亚和文莱的住宅、商业和工业项目的电力相关服务、安装、电表以及相关售电系统。其是STS成员，有多年项目运作经验，在当地电力公司有有效的人脉关系。', '汤伟(Will)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('206', '61', 'INHE-0434', '2016-05-16 09:04:05', '2016-05-16 09:32:06', 'khxx20160516129/AOI Electronics Factory\r\n', 'khxx20160516129', 'AOI Electronics Factory', 'AOI', '非洲', '埃及', 'www.aoi.com.eg', '4.5 Km Suez Road, 3rd gate from Sakr Factory, Heliopolis, Cairo, Egypt.', '客户公司于1979年成立，公司位于埃及开罗。是一家埃及本土公司主要经营高科技电子设备的生产以及系统的研发。其经营的产品涵盖：电视机，平板电脑，LED灯，接收器，个人电脑，笔记本电脑，医疗设备，家用电器，电子电能表，开关设备，太阳能控制器/充电器，LED显示屏。客户有自己的产房，产房面积57,000平方米，2016年1月统计员工660名，其中国合作伙伴有康佳, 长虹，ZTE，三星，KTC等，2014年有联系我们一起做电表生意，后续联系停止，于2016年重启合作谈判，合作产品：单相/三相IC卡表和系统，合作方式：联合投标/SKD或CKD散件供货。\r\r\n', '钟云林(Andy)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('207', '60', 'INHE-0419', '2016-05-17 11:38:39', '2016-05-17 11:46:35', 'khxx20160517131/Northern Power Corporation', 'khxx20160517131', 'Northern Power Corporation', 'EVN NPC', '亚洲', '越南', 'www.npc.com.vn', 'No.20 Tran Nguyen Han Street, Hoan Kiem District, Hanoi', 'EVN旗下5大电力公司之一，管辖北部20多个省电力公司所有配电业务。', '曾波', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('208', '53', 'JXINHE-2288', '2016-05-17 11:59:27', '2016-05-17 13:50:58', 'khxx20160517132/Meezah Trading Co.', 'khxx20160517132', 'Meezah Trading Co.', '', '亚洲', '约旦', '', 'P.O.Box 138 Amman 11118, Jordan ', '代理公司是一家贸易公司，成立于2000年，员工数5-10人，做过转换器，电线，开关柜，绝缘子和断路器等产品经销。代理公司各种产品的年销售量为800-1000万美金。代理的祖父是JEPCO电力公司的奠基人，是董事会的成员，代理的哥哥也在JEPCO公司工作，代理本人与当地电力公司有着较好的关系，熟悉其内部运作。', '张正宜', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('209', '53', 'JXINHE-2288', '2016-05-18 14:20:13', '2016-05-18 15:01:53', 'khxx20160518135/Alnitak Global (Pvt) Ltd.', 'khxx20160518135', 'Alnitak Global (Pvt) Ltd.', '', '亚洲', '斯里兰卡', '', '30/1, Capt. Kalum Rajapakse Mw,Wattala，Sri Lanka', '该客户是斯里兰卡一家贸易公司，主要业务和经营目标是通过新技术来开发智能城市，解决城市环境问题，污染问题等，首先专注于能源和电力领域。公司主要由市场营销专家和电气工程师组成，有10年以上承接政府部门，尤其是斯里兰卡国家电力公司CEB投标项目方面的经验，曾通过银行贷款承接过当地三个重要的电力工程项目，与CEB有着良好的关系。目前他们的业务中所涉及到的电力和基础设施建设项目越来越多，了解到CEB对可编程电表有着很大的需求并获得了一些电表招标信息，故联系我们打算合作开发当地电表市场。', '张正宜', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('210', '0', 'INHE-0391', '2016-05-19 10:12:54', '2018-08-01 08:58:14', 'khxx20160519137/Edge Line Engineering (Pty) Ltd\r\n', 'khxx20160519137', 'Edge Line Engineering (Pty) Ltd', '', '非洲', '南非', '', 'Engineering House,7 Port Road, Robertsham, Johannesburg 2091', 'Edge Line Engineering (Pty) Ltd 成立于2010年，是南非一家2级BEE公司，主要从事于电气和机械工程领域，包括发电机，电缆管理以及电力低压产品（如表箱，PVB板）等等。之前是兰吉尔在ESKOM的代理，该公司负责提供表箱，兰吉尔提供电表，但现在兰吉尔准备直接投标，因此该客户找到银河。', '桂弯弯', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('211', '60', 'INHE-0514', '2016-05-20 09:41:02', '2016-05-20 11:20:31', 'Net Solutions and Applications Limited', '', 'Net Solutions and Applications Limited', 'Net', '亚洲', '阿联', 'http://www.net-ltd.net/\r\n', 'Masdar City, Abu Dhabi, UAE\r\n', 'Net是位于阿联酋阿布扎比马斯达尔的一家专业从事系统整合，解决方案，大数据等相关工作的科技公司，成立于2014年，至今时间不长，曾经完成过阿布扎比40万台来自不同供应商的电表的AMR系统的项目。对于电表以及AMR,AMI系统比较熟悉了解。', '李成兵', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('212', '61', 'INHE-0432', '2016-05-24 10:31:11', '2016-05-24 10:50:06', 'khxx20160524139/Build Africa Corporation', 'khxx20160524139', 'Build Africa Corporation', 'ABC', '非洲', '南非', 'www.build-africa.org', 'Cape Town,South Africa', '1)Build Africa是一家慈善组织，旨在帮助非洲儿童改善生活及教育水平。目前该组织有15万名志愿者，计划2018年共计帮助100万名儿童。该组织在美国，英国，南非，肯尼亚，乌干达均有分支机构。2）南非部CEO Mr.Miles同时是南非一家电力服务公司Power Up的CEO，该公司与Build Africa合作，提供电力方面的产品和服务。', '谭东羊(Timon)', '国际业务二部', null, null, 'E', 'INHE');
