INSERT INTO `inhe_customer_data` VALUES ('216', '60', 'INHE-0424', '2016-05-31 17:50:03', '2016-05-31 18:22:00', 'khxx20160531156/Office National de l’Electricité et de l’Eau Potable-Branche Electricité\r\n', 'khxx20160531156', 'Office National de l’Electricité et de l’Eau Potable-Branche Electricité', 'ONEE-BE', '非洲', '摩洛哥', 'http://www.one.org.ma/\r\n', ' Avenue Mohamed\r\r\nBelhassan El Ouazzani, Rabat', '摩洛哥国家水电公司电力局，实力雄厚，我司在该市场已经铺垫了快4年，未来前景巨大。该公司除了总管摩洛哥全国水电，也参与非洲多个国家的水电业务，对整个非洲电力行业颇具影响力。 电力公司2014年之前处于亏损状态，从2014年起开始改善电力状况，包括提倡风能太阳能发电，推广预付费电表等等。 ', '代莎', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('217', '61', 'INHE-0431', '2016-06-02 10:08:23', '2016-06-02 10:25:34', 'khxx20160602157/Kayz Consortium Ltd\r\n', 'khxx20160602157', 'Kayz Consortium Ltd', 'KAY', '非洲', '尼日利亚', '\r\r\n', 'Plot 2 Julius Nyerere Crescent\r\r\r\r\r\r\r\nAsokoro - Abuja\r\r\r\r\r\r\r\r\n', '客户是做旅游观光，能源电力等行业的，其中能源电力是新进取得NERC认证的VENDORS，原来是和三星合作，但是因为三星在项目安排上的冲突转而与我们谈判，现在据称有一个10万台的订单在进行中', '刘佩(Ted)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('218', '61', 'INHE-0518', '2016-06-02 16:23:39', '2016-06-02 16:51:18', 'khxx20160602158/Standard Sharing Software', 'khxx20160602158', 'Standard Sharing Software', '3S', '非洲', '突尼斯', 'www.3s.com.tn', '1073 Montplasir-Tunis-Tunisia', '成立于1988年，从事IT行业，与电力公司有合作，给电力公司供IT产品，与电力公司关系良好，年营业额600万-2000万美金。子公司：Globanet。', '熊璟', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('219', '61', 'INHE-0518', '2016-06-02 17:44:35', '2016-06-02 17:44:35', 'khxx20160602159/Gotoleds', 'khxx20160602159', 'Gotoleds', 'Gtl', '亚洲', '中华民国', 'www.gotoleds.com', '深圳市福田区华强北路现代之窗大厦A座16A2', '主要从事LED行业，客户在中国深圳的办公室主要负责采购，在突尼斯、摩洛哥、迪拜、香港有商铺，去年利润300万美金。', '熊璟', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('221', '61', 'INHE-0091', '2016-06-06 16:48:55', '2016-06-06 17:04:49', 'khxx20160606160/Winch Energy Group\r\n', 'khxx20160606160', 'Winch Energy Group', 'WEG', '欧洲', '英国', 'www.winchenergy.com\r\n', '71 London Road\r\nSevenoaks, Kent, TN13 1AX\r\nUnited Kingdom\r\nOffice:+44 (0) 1732 228110\r\n', '客户本部在英国，在意大利及法国均有办事处，自有测试中心在意大利。\r\r\r\r\r\n\r主要发展可更新能源及提倡能源效率，重点在太阳能发电。\r据说在欧洲取得较大成功；从2011年起开始将业务范围扩展到非洲，拉丁美洲和亚洲。\r\r\n目前在非洲有离网项目（off-grid),需要电表。', '林丽璇', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('222', '61', 'INHE-0222', '2016-06-14 15:12:55', '2016-06-14 15:26:35', 'khxx20160614162/Engineering Smart S.A.S', 'khxx20160614162', 'Engineering Smart S.A.S', 'ES', '南美洲', '哥伦比亚', '', 'Calle 63 No. 75-35 Bogotá Colombia\r\n', '电力方案及产品供应商，公司规模较小，代理本人在电力公司有较好的人脉关系，对我司产品功能非常熟，也是PSA4-PSA6项目合作方公司一员，主要负责项目技术支持，商务沟通及联络。', '张红丽', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('223', '53', 'JXINHE-2288', '2016-06-14 15:58:01', '2016-06-14 16:57:24', 'khxx20160614163/Karam Group Inc.', 'khxx20160614163', 'Karam Group Inc.', '', '亚洲', '伊拉克', '', 'Mamoul Complex，Camp Baghdada, IRAQ', '伊拉克机电设备供应商，主要经营电力设备，配电项目，发电机，水泵，太阳能设备，电动工具，照明设备等，现有1500台至3000台单相和三相预付费键盘表居民小区直接采购项目', '张正宜', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('224', '61', 'INHE-0222', '2016-06-15 10:34:14', '2016-06-15 10:44:20', 'khxx20160615164/MESSEN S.A.S.', 'khxx20160615164', 'MESSEN S.A.S.', '', '南美洲', '哥伦比亚', '', 'Calle 63 No. 75-35 Bogotá Colombia\r\n', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系,同时时PSA1-PSA9项目合作伙伴公司的工程师，主要负责给电力公司技术支持，市场推广，以及同我司商务技术等沟通。', '张红丽', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('225', '53', 'JXINHE-2288', '2016-06-15 16:37:48', '2016-06-15 16:53:36', 'khxx20160615165/DREXEL INTERNATIONAL LTD', 'khxx20160615165', 'DREXEL INTERNATIONAL LTD', '', '亚洲', '阿联', '', 'WORLD TRADE CENTER OFFICE 1602 DUBAI UAE', '阿联酋电气设备贸易公司，主要经营非洲电力项目，现获得刚果金建筑公司100台BS型三相四线分体式预付费代码表的直接采购机会，向我们询价，如果价格合适可直接下单采购。', '张正宜', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('226', '61', 'INHE-0500', '2016-06-19 17:50:35', '2016-06-20 13:09:55', 'khxx20160619166/FactorFast (PTY) Ltd ', 'khxx20160619166', 'FACTORFAST METERING(PTY) LTD', 'FFL', '非洲', '博茨瓦纳', 'N/A', 'Gaborone, Botswana', '1.成立于2012年，在电表和售电系统比较专业，PowerCom Metering Africa在博茨瓦纳的独家智能电表代理，目前有和BPC有智能电表试点项目的合作，也和Botswana Post在智能售电系统和APP上有项目合作经验.\r\r\n2.2016年6月16日询盘我司关于一个BPC智能多功能CT/PT 三相表限制性招标项目，目前正在跟进项目详细进展和信息。\r\r\r\n', '李忠鹏(Evans)', '国际业务2部东南非1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('227', '61', 'INHE-0500', '2016-06-19 18:23:05', '2016-06-20 13:09:43', 'khxx20160619167/Scales Group\r\n', 'khxx20160619167', 'Scales Group', 'SGP', '非洲', '博茨瓦纳', 'www.scalesgroup.net\r\r\n', 'PO Box 401907\r\r\nGaborone\r\r\nBotswana\r\r\n', '1.成立于1994年，专业电力工程施工商和承包商，总部为博茨瓦纳，在津巴布韦有分支，BPC是其重要客户，电力行业经验丰富；\r\r\r\n2.\r\r2016年6月18日询盘我司关于一个单相表+三相表的试点项目（限制性招标），现在在跟进此项目进展。\r\r\n\r\r\r\r\n', '李忠鹏(Evans)', '国际业务2部东南非1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('228', '60', 'INHE-0551', '2016-06-20 08:35:32', '2016-06-20 13:43:36', 'khxx20160620168/摩洛哥电力公司非斯办公室（RADEEF）', 'khxx20160620168', '摩洛哥电力公司非斯办公室（RADEEF）', 'RADEEF', '非洲', '摩洛哥', 'www.radeef.ma', '摩洛哥非斯', '客户为摩洛哥电力公司在非斯城的一个分支机构（简称RADEEF）。', '涂淑婉', '国际一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('229', '53', 'JXINHE-2288', '2016-06-21 09:47:49', '2016-06-21 10:23:46', 'khxx20160621171/Al Rasikh Company', 'khxx20160621171', 'Al Rasikh Company', '', '亚洲', '伊拉克', 'www.alrasikh.com', 'M615, St.17, Building .13, Baghdad – Iraq.', '伊拉克电力设备贸易公司，1996年成立，在行业内有20多年历史，主要从事配电设备供应， 安装和电力工程项目，如：变电站，开关柜，智能电表等，代理和经营过ABB，韩国三星等公司的配电产品。现手头握有伊拉克一家大超市的单相和三相AMR智能表直接采购项目。', '张正宜', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('230', '61', 'INHE-0497', '2016-06-22 15:15:54', '2016-06-22 16:23:26', 'khxx20160622172/Centrifugados Mexicanos S.A. de C.V.\r\n', 'khxx20160622172', 'Centrifugados Mexicanos S.A. de C.V.', 'Cenmex', '北美洲', '墨西哥', 'cenmex.com\r\r\n', 'Km. 8 Carretera Zapopan - Tesistán.\r\nC.P. 45200, Col. Estrada \r\nZapopan, Jalisco, México.', 'CENMEX:\r\r\r\r\r\n公司全称Centrifugados Mexicanos S.A. de C.V.\r\r\r\n建立于1977年，做水泥电线杆起家，目前主要从事电力工程和土木工程项目。拥有12个工厂，生产水泥电线杆，装表和变压器的水泥墩子矮墙等，工厂遍及整个墨西哥，旗下有多家公司，厂房面积共约10万平方米，一个公司的年营业额约5000万美金，自称是墨西哥水泥电线杆供应商第一家。主要客户是墨西哥国家电力公司CFE，及其他电力产品承包商。CENMEX老板与CFE高层有着良好的关系，在商务方面具有很大优势。\r\r\r\r\r\nCENMEX还有一个合作伙伴公司专门生产电表，CMS系统（我司STA项目，即我们当前为PSA市场设计的表箱内装12只DIN表/模块的系统），自主研发设计和生产， 电表为插拔式，表和分体单元为ZIGBEE通讯，表和集中器通讯使用RF，表和集中器距离最远10公里 。\r\r\r\r\r\n\r\r\r\r\r\nMeximports:\r\r\r\r\r\nCENMEX的合作伙伴，负责CENMEX在中国其他产品，如线缆，绝缘子，变压器等，电表等电力产品的采购，供应商审核，价格洽谈等。\r\r\r\r\r\n', '曹荃', '国际业务2部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('231', '61', 'INHE-0497', '2016-06-22 17:02:27', '2016-06-22 17:57:15', 'khxx20160622173/IT&P Soluciones S.A.C.', 'khxx20160622173', 'IT and P Soluciones S.A.C.', 'ITP', '南美洲', '秘鲁', 'www.itpsoluciones.com.pe', 'Río de Janeiro 343\r\nLima 11\r\nPERU\r\n', '秘鲁客户，全称 IT and P Soluciones S.A.C.主要经营业务涉及能源、通信与网络、自动化及石油和天然气等。在电力公司有一定人脉关系。\r\r\n', '曹荃', '国际业务2部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('232', '61', 'INHE-0091', '2016-06-24 16:22:17', '2016-06-24 16:48:31', 'khxx20160624176/National Contracting Co. Ltd.\r\n', 'khxx20160624176', 'National Contracting Co. Ltd.', 'NCC', '亚洲', '印度', 'http://www.nccprojects.com/company/\r\n', 'GRR Business Center, New No. 36, Old No. 21, Vaidhya Raman Street,\r\nT. Nagar, Chennai - 600 017, India\r\n', 'NCC成立于沙特阿拉伯，在电力、石油化工产品、石油和天然气及提炼行业拥有超过30年的运营和技术经验。NCC在工程、采购及建造方面从事大型一揽子交钥匙工程。主要分4个部门：\r\r\n\r\r\r\nPower Projects Division (PPD)\r电力项目部\r\r\nTransmission & Distribution (T&D)\r输电和配电部\r\r\nConstruction Division (CD)\r建造部\r\r\nWater and Wastewater Division (WWD)\r供水和污水部\r\r\n', '林丽璇', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('233', '60', 'INHE-0088', '2016-06-24 17:40:03', '2016-06-24 17:40:03', 'khxx20160624177/Khawja Group', 'khxx20160624177', 'Khawja Group', 'KG', '亚洲', '孟加拉国', '', '128/A, Jubilee Road, Kader Tower(Level-4), Chittagong, Bangladesh', '该公司是个集团，2011年开始合作，下单基本稳定，所采购的一般普通三相表和，单相掉零线双回路计量表。产品以半散件的形式发货。\r\n客户的付款方式一般是由T/T和LC, 孟加拉国家进口付款限制，只能为L/C,客户为了避税，采用了部分T/T, 注意发货的时候要收到所有的T/T款和通知行发来的信用证。一般是收到预付款后45天发货。', '余冬纯', '国际业务一部', null, null, 'E', 'INHE');
