INSERT INTO `inhe_customer_data` VALUES ('239', '61', 'INHE-0374', '2016-07-07 10:18:34', '2016-07-07 10:18:34', 'khxx20160707183/SKY senegal', 'khxx20160707183', 'SKY senegal', 'sky', '非洲', '塞内加尔', '', '塞内加尔首都达喀尔', '母公司为中国广州某地产公司背景，2015年营业额2亿人民币，2015年在塞内加尔注册，主要针对塞内加尔，尼日尔两国光伏招投标项目，至今中标塞内加尔SENELEC电力公司金属电力杆项目550万美金，农村输变电工程250万美金，尼日尔能源部太阳能路灯和发电系统四个标总金额450万美金。Sky 在赛的负责人为肖锋与黄叶，均为福建人。', '王子强', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('240', '53', 'JXINHE-2288', '2016-07-13 08:45:44', '2016-07-13 12:31:32', 'khxx20160713184/山东科瑞节能电气有限公司', 'khxx20160713184', '山东科瑞节能电气有限公司', '', '亚洲', '中国', '', '山东科瑞节能电气有限公司', '中国电力设备制造商，主要产品为双电源自动调压变压器、三相高效永磁同步电动机等，在许多国家设有分公司，现获得拉美地区2万台预付费智能表及表箱项目招标信息，想与我们公司合作来投此标', '张正宜', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('241', '61', 'INHE-0509', '2016-07-13 09:43:32', '2016-07-13 09:43:32', 'khxx20160713185/晶詠科技股份有限公司', 'khxx20160713185', '晶詠科技股份有限公司', '晶詠科技', '亚洲', '中华民国', 'www.rms-jtec.tw', '台北市11578南港区南港路二段95号6楼', '晶詠科技股份有限公司是台湾一家工程建设公司，主要业务包括弱电工程、LED工程、建筑工程、电厂工程等。该公司以前在印尼有用过我司售电系统、刮刮卡系统及简单BS代码表，对公司的系统和电表都非常满意。该公司老板称与印尼总理关系很好，在印尼Maluku区签下一个30万台的智能水表改良工程合同，决定扔用我司的SmartVend、Smart Agent和Smart Messenger系统到水表领域。', '陈怀枝', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('242', '60', 'INHE-0343', '2016-07-21 11:02:32', '2016-07-21 11:41:42', 'khxx20160721186/Syed Azfar ', 'khxx20160721186', 'Syed Azfar', 'SA', '亚洲', '孟加拉国', '', '', '客户是孟加拉当地一家代理商，半年前有和我们联系过，询问过电表方案，现在客户获得孟加拉供电局季度5万台需求的招标项目，求购单相简表，预计季度5万台量', '马坚', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('243', '61', 'INHE-0381', '2016-07-21 10:49:19', '2016-07-21 11:41:19', 'khxx20160721187/Groupe Kadji', 'khxx20160721187', 'Groupe Kadji', 'Kadji', '非洲', '喀麦隆', 'www.kadjigroup.com', '', 'Kadji集团属于中非市场较大集团之一，在当地人脉关系很广泛且影响力较大。该集团约有1500个员工，旗下有各种不同分公司（运动类、保险类、啤酒类、塑料聚酯类、食物类等）。\r\r\r\r\n与银河合作的Kadji Odette女士主要经营当地的石油公司，CAMEROON MARKETING INTERNATIONAL OIL  SA (CMI OIL)，该石油公司的资金资本为7亿法郎。公司业务有包含往邻国出口石油，石油产品国际贸易，港口航海船只供油等。该女士还经营一家进出口贸易公司。\r\r\r\n\r\r\r\n', '张柳芳(Alexie)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('244', '53', 'JXINHE-2288', '2016-07-22 16:24:13', '2016-07-22 16:43:11', 'khxx20160722188/MAT Co., Ltd', 'khxx20160722188', 'MAT Co., Ltd', '', '亚洲', '韩国', 'www.iplug.com , www.luxmatic.co.kr', '16 Beolmal-ro 118 Beon-gil, Dongan-gu Anyang-si, Gyeonggi-do, Korea 431-060', '韩国MAT Co., Ltd. 公司是一家从事计量，节能，灯光控制，汽车充电和电力线载波模块设计的韩国技术公司，有20年以上从业经验，最近正致力于开发AMI通讯领域，主要从事智能表模块和软件系统开发，曾向日本电表企业批量提供过PLC智能表模块，现获得海外预付费表需求，希望通过OEM方式与我们合作，先向我们购买少量样表用于测试，通过后再向我们逐步批量进货，直接下订单。', '张正宜', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('245', '61', 'INHE-0550', '2016-07-25 09:36:03', '2016-07-25 09:57:14', 'khxx20160725189/INENSUS GmbH\r\n', 'khxx20160725189', 'INENSUS GmbH', 'INENSUS', '欧洲', '德国', 'www.inensus.com', 'Am Stollen 19 38640 Goslar', '该客户是前期搜索德国投标合作伙伴时取得联系的。公司主营风能和off-grid业务，是世界风能协会和非洲风能协会成员，在非洲许多国家都有项目。', '陈帅', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('246', '61', 'INHE-0588', '2016-07-27 13:58:58', '2016-07-27 16:12:29', 'khxx20160727192/Yola Electricity Distribution Company', 'khxx20160727192', 'Yola Electricity Distribution Company', 'YEDC', '非洲', '尼日利亚', 'http://www.yedc.com.ng/', '2, Atiku Abubakar Road, Jimeta-Yola,\r\r\n\r\r\nAdamawa State,Nigeria', 'YEDC是尼日利亚11个配电公司之一，主要负责尼日利亚东北部Adamawa,Taraba,Borno和Yobe州的配电业务。YEDC公司共有13个营业部，现为共计30万用户提供配电服务。现YEDC向全球招标30万台智能电表，我司准备与尼日利亚代理商IRL联合投标，现已从代理处获得标书，准备立项。', '胡林', '国际业务二部', null, null, 'E', 'INHE');
