INSERT INTO `inhe_customer_data` VALUES ('248', '61', 'INHE-0091', '2016-08-06 14:17:11', '2016-08-06 14:26:09', 'khxx20160806194/WoodGate Trademark Company Limited\r\n', 'khxx20160806194', 'WoodGate Trademark Company Limited', 'WTC', '非洲', '坦桑尼亚', 'http://www.woodgatetm.com/index.html\r\n', '369 Toure Drive\r\nGround Floor Kilwa House, Oysterbay\r\nDar Es Salaam Tanzania\r\nP.O.Box 23197\r\n', '客户公司为港口、电力公司、水利行业项目实施管理提供咨询服务，客户导向，偏贸易，主要客户是TANESCO和港口。\r\r\n据客户讲，2008年他们把威胜引进坦桑尼亚，因为和威胜的不信任所以在2013年结束了合作。', '林丽璇', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('249', '61', 'INHE-0432', '2016-08-10 03:59:56', '2016-08-10 08:38:05', 'khxx20160810196/Dassy Enterprises Ltd\r\n', 'khxx20160810196', 'Dassy Enterprises Ltd', 'DE', '非洲', '卢旺达', 'http://dassy-entreprise.com\r\n', 'Kigali, Rwanda', '1,性质：私营，10人左右。MD年龄在40左右。                                                                               2，经营范围：卢旺达太阳能产品及解决方案供应商。同时拥有两座小型水力发电厂，给卢旺达偏远地区的村庄部落供电。                                        3，该公司与多个欧洲公司、联合国有合作项目。曾获联合国驻卢旺达地区代表颁发的可持续发展企业家奖项。（http://www.newtimes.co.rw/section/Printer/2011-03-18/29390/）                                              4，与卢旺达能源公司REG（主管水、电）、世界银行等有项目合作经验。                                                       5，电表行业是第一次进入。与REG下属的EDCL,EUCL有些人脉关系：如电表部老大,EDCL-EARP项目经理，EDCL副总，EUCL副总等。                                                  6，对竞争、评标有一定的了解，和相关评标委员会主席有一定的关系，但具体需要考察，及银河的策略指导，配合。                    7，目前倾向于银河投标，他获取佣金。细节还未谈妥。\r\r\r\r\r\r\r\r\n', '谭东羊(Timon)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('251', '53', 'JXINHE-2559', '2016-08-11 14:50:46', '2016-08-11 15:22:24', 'khxx20160811198/Al-Asr Trading and consultancy', 'khxx20160811198', 'Al-Asr Trading and consultancy', 'Al-Asr', '亚洲', '巴基斯坦', '', 'Suit no 369, Street 34, F-11/2, Islamabad, Pakistan', '中型家族企业，成立于1974年。在尼泊尔、阿联酋和阿富汗有分部。主营业务:专业为海外公司承接项目和合同\r\r\n   实施项目:在巴基斯坦与TGOOD MENA合作风力项目，CR20(巴基斯坦)集团合作各种基础设施建设，土耳其MITAS输电项目，西班牙Isolex合作输电项目，中国铁路第一集团合作各种基础设施建议，华为合作一些工程。\r\r\n', '淦永妍', '工业园国际业务部', null, null, 'E', 'INHE');
