INSERT INTO `inhe_customer_data` VALUES ('253', '61', 'INHE-0440', '2016-08-23 11:06:10', '2016-08-23 15:36:41', 'khxx20160823200/Saturn Pyro', 'khxx20160823200', 'Saturn Pyro', 'Jothie', '亚洲', '马来西亚', 'http://www.saturnpyro.com/', 'No. 9-01, Jalan Austin Perdana 2/25,\r\r\r\nTaman Austin Perdana,\r\r\r\n81100 Johor Bahru, Johor, Malaysia', 'Saturn Pyro 是马来西亚领先的绿色技术解决方案供应商，目前在马来西亚吉隆坡、新山以及新加坡都有分公司。主要的产品包括1. 能源管理系统解决方案，2.GBI认证 3M 解决方案 (计量, 监控 & 管理)，3.电力基础设施Scada 系统监控。4. SCADA通讯和协议跨平台整合和无缝切换翻译解决方案。', '汤伟(Will)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('254', '53', 'JXINHE-2288', '2016-08-29 11:49:03', '2016-08-29 13:59:00', 'khxx20160829201/CEE Technologies Pte Ltd', 'khxx20160829201', 'CEE Technologies Pte Ltd', '', '亚洲', '新加坡', 'www.ceelect.com.sg', '62 Ubi Road 1, #08-10，Oxley Bizhub 2（S）408734', 'CEE技术公司于2003年成立，是新加坡一家从事自动化，电气，电子元器件和电子设备供应的贸易公司，也向客户提供相应设备的备品配件，提供可靠的售后服务和安全保障，主要市场在新加坡，马来西亚和印度尼西亚，代理的品牌主要有ABB，三菱等，代理的产品包括：以PLC为基础的控制系统，传感器，滑轮部件，打印系统解决方案等。最近CEE公司从新加坡电力公司那里获得1万台单相两线插拔式RF模块多功能智能表的招标信息，故联系我们想参加此项投标', '张正宜', '工业园国际业务部', null, null, 'E', 'INHE');
