INSERT INTO `inhe_customer_data` VALUES ('256', '61', 'INHE-0431', '2016-09-14 14:52:18', '2016-09-14 15:09:02', 'khxx20160914205/Genesis Energy\r\n', 'khxx20160914205', 'Genesis Energy', 'GES', '非洲', '尼日利亚', 'www.genesisenergygroup.net\r\r\r\n', 'Consectetur adipiscing elit vest\r\r\r\r\r\nbulum scelerisque vehicula\r\r\r\r\r\ntincidunt tempor ante dolor\r\r\r\r\r\n.. GGeenneessiiss 22001166 || 0000\r\r\r\r\r\n\r\nPHYSICAL & POSTAL ADDRESS:\r\r\r\r\r\n3-4 Devonshire Street ,\r\r\r\r\r\nLondon, W1W 5DT\r\r\r\r\r\nUnited Kingdom\r\r\r		\r\n', '1.总部位于英国的公司，主营业务为油，气，能源等\r\r\n2.在加纳，尼日利亚做为IPP提供电力，总共近700MW\r\r\n3.与我们联系的是他们位于尼日利亚的分公司 WFC Utilities Limited，主营精力是电表和水表以及相关系统方案，还未取得NERC的认证，计划申请中', '刘佩(Ted)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('257', '60', 'INHE-0406', '2016-09-14 16:12:23', '2016-09-14 16:33:41', 'khxx20160914206/ACER-TORG', 'khxx20160914206', 'ACER-TORG', '', '亚洲', '吉尔吉斯斯坦', '', '', '“ACER-TORG”公司从1998年就开始在吉尔吉斯斯坦从事工程建设，学校，锅炉房，电力等。客户同北方电力公司高层具有联系，也了解我们公司、海兴、三星等参与北电以前的招标。\r\r\n', '王毅', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('258', '60', 'INHE-0560', '2016-09-19 08:36:00', '2016-09-19 10:24:58', 'khxx20160919207/Юрий Козельский', 'khxx20160919207', 'Юрий Козельский', 'Юрий ', '亚洲', '哈萨克斯坦', 'www.nikenergy.asia', 'Бизнес центр \"Нурлы-Тау\" 5А, оф.126', ' ТОО \"НИК-КАЗАХСТАН\"- 东欧国家电工仪器计量仪表的最大制造商之一。总部设在乌克兰首都基辅。该公司经营范围广泛，涉及热力，煤炭，焦炭冶金等领域。项于2011年开始生产智能电表及电力能源计量系统。目前已通过 ISO 9001:2008 和ISO 14001:2004认证。Юрий Козельский 为该公司的股东代表，负责该公司对外采购及项目落实事务。', '李美娇', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('259', '61', 'INHE-0381', '2016-09-20 09:23:49', '2016-09-20 10:04:53', 'khxx20160920210/SOCIETE NATIONALE D\"ELECTRICITE', 'khxx20160920210', 'SOCIETE NATIONALE D\"ELECTRICITE', 'SNEL S.A', '非洲', '刚果（金）', '', '2831,Avenue de la Justice B.P.500 KINSHASH/GOMBE', '刚果金电力公司', '张柳芳(Alexie)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('260', '61', 'INHE-0575', '2016-09-21 16:00:22', '2016-09-21 16:21:40', 'khxx20160921212/Acclinks Communication(深圳市立华信技术有限公司)', 'khxx20160921212', 'Acclinks Communication(深圳市立华信技术有限公司)', 'Acclinks', '亚洲', '中国', 'http://www.acclinks.com/', '深圳市南山区创业路现代城华庭2栋26E', '    Acclinks 之前是一家主营转换插头的公司，现主要业务是与各大电信、通讯、数字电视以及电力公司合作，为太平洋国家的目标客户提供各种电力系统以及通讯解决方案。', '丁梦情', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('261', '61', 'INHE-0434', '2016-09-22 09:56:37', '2016-09-22 10:17:31', 'khxx20160922213/Grupo Engco', 'khxx20160922213', 'Grupo Engco', 'Engco', '非洲', '莫桑比克', 'www.engco.co.mz\r\r\n网站在维护', 'Av. FPLM, No322, Maputo', '1. 客户是莫桑比克本地公司，当前有4家子公司从事不同领域，大部分是和能源电力设施相关。\r\r\n\r\n2. 有自己的灯具组装车间，2016年7月拜访时，有讨论建厂(电表组装厂)合作。\r\n\r\n3. 和电力公司的业务主要在路灯这一块儿，电表的业务成效不佳。\r\n\r\n4. 资金方面有待进一步考察', '钟云林(Andy)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('262', '53', 'JXINHE-2559', '2016-09-22 10:31:37', '2016-09-22 10:47:32', 'khxx20160922215/VBC Limitada', 'khxx20160922215', 'VBC Limitada', 'VBC', '非洲', '莫桑比克', 'www.vbc.co.mz\r\n', 'Av. Julius Nyerere N. 1597, Maputo-Mo?ambique\r\n', 'VBC是一家100%的莫桑比克本土公司，产品涉及电信通讯，移动设备，生物和能源技术。获得IGSQ奖项及20\r\n11全非奥运会官方供应商。\r\n', '淦永妍', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('263', '53', 'JXINHE-2288', '2016-09-23 14:55:52', '2016-09-23 17:03:35', 'khxx20160923216/Taha Electric company', 'khxx20160923216', 'Taha Electric company', '', '亚洲', '巴勒斯坦', '', 'Palestine - Gaza - Gaza strip- Alwehda street', '该公司是巴勒斯坦基础建设承包商和电力设备供应商，专注于电网，输电材料和设备，太阳能系统等领域，1982年成立，有34年电力行业经验，与电力公司有着较好的关系。该公司现有员工250名，有专业工程师组成的技术团队承接各种电力行业项目。', '张正宜', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('264', '61', 'INHE-0500', '2016-09-27 09:51:02', '2016-09-27 10:04:55', 'Namibia Power Corporation (Proprietary) Limited\r\n', '', 'Namibia Power Corporation (Proprietary) Limited', 'NamPower', '非洲', '纳米比亚', 'www.nampower.com.na\r\n', 'NamPower Center 15 Luther Street, Windhoek\r\r\nPO Box 2864, Windhoek, Namibia\r\r\n', '纳米比亚国有电力公司，也是纳米比亚唯一的发电和输电公司，主要负责发电和输电，不负责配电和售电，目前全国电力用于约25万；', '李忠鹏(Evans)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('265', '53', 'JXINHE-2288', '2016-10-08 16:16:24', '2016-10-08 16:28:13', 'khxx20161008217/FABURAMA KANTEH', 'khxx20161008217', 'FABURAMA KANTEH', '', '非洲', '冈比亚', '', 'Tambana Village, Jokadou District, North Bank Region,The Gambia.', '客户由资深的进出口，市场营销专家，顾问和有干劲的年轻销售人员组成，主要经营电力设备的销售，除冈比亚之外，在塞拉利昂，马里，几内亚比绍，毛里求斯和加纳等国都有一定程度的业务联系。客户曾多次联系冈比亚当地电力公司取得了智能表，预付费表和三相CT表的详细技术要求资料和需求信息，工作颇有进展，他们办事努力，认真，已与我们签订代理协议。', '张正宜', '工业园国际业务部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('266', '61', 'INHE-0440', '2016-10-10 13:48:55', '2016-10-10 14:28:49', 'khxx20161010219/VRP ENGINEERING&TRADING CO.,LTD.', 'khxx20161010219', 'VRP ENGINEERING AND TRADING CO.,LTD.', '', '亚洲', '泰国', 'www.vrp-engineering.co.th', '85/4 Bangkruai-Sainoi Rd., Bang Rak Yai, Bangbua thong, Nonthaburi. 11110', 'VRP Holding Limited 成立于2004年，注册资金1亿泰铢，由来自各个领域的专业工程师和专家团队建立，目前有6个子公司，业务范围覆盖工程，能源，物流，石油&天然气和电力等领域，VRP 集团公司和泰国一些实力很强的伙伴合作、运营，这些合作伙伴包含了泰国石油管理局（PTT), 丰田总代理（泰国），泰国省级电力公司（PEA), 泰国城市电力公司（MEA), 泰国能源部和泰国内政部，VRP集团公司一直在扩展业务，目前给他们所有的客户提供质量和安全保险。', '汤伟(Will)', '二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('267', '61', 'INHE-0497', '2016-10-11 14:31:05', '2016-10-11 14:41:35', 'khxx20161011221/AICO - ING CARLOS CELLERI', 'khxx20161011221', 'AICO - ING CARLOS CELLERI', 'AICO', '南美洲', '厄瓜多尔', 'http://www.aico.com.ec', 'Av. América N35-58 y Manosca - Quito \r\r\r\nPlanta Industrial: Pasaje OE9 N47-11 y Fernando Montalvo, Sector Cochapamba Alto - Quito\r\r\r\n', '经营中低压电力设备，主要为中低压开关柜，电机控制中心，配电板，电能质量分析仪等，是施耐德的代工厂和经销商。该客户对电表行业比较了解，熟悉投标规则，采购模式，认证要求等，与电力公司有着不错的关系。', '曹荃', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('268', '61', 'INHE-0598', '2016-10-14 09:24:00', '2016-10-14 13:33:15', 'khxx20161014222/MESSEN S.A.S', 'khxx20161014222', 'MESSEN S.A.S', '', '南美洲', '哥伦比亚', '', 'Calle 63 No.75-35 Bogotá Colombia', '电力方案及产品供应商，公司规模较小，代理本人十分熟悉我们的产品，在电力公司有良好人脉和关系，同时是PSA1-PSA10项目合作伙伴公司，主要负责电表市场推广，给电力公司技术支持，以及同我司商务技术等沟通。', '韦汉莹', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('269', '61', 'INHE-0587', '2016-10-14 14:59:00', '2016-10-14 17:31:49', 'khxx20161014223/Celdon Group', 'khxx20161014223', 'Celdon Group', 'CGP', '非洲', '尼日利亚', 'www.celdongroup.com', '16 Adetokunbo Ademola Crescent (Behind Transcorp Hilton) Wuse II, Abuja, Nigeria', '该客户在银行工作时积攒了很好的金融人脉，2012年与西班牙人成立了Celdon Consulting Limited提供金融咨询，之后成立Celdon Ltd.(Engineering`Consulting)、Celdon Restaurant`Hotels Ltd.和Celdon Health`Medical Supplier Ltd.。上述公司一起则组成了Celdon Group。2015年3月，客户投资20万美元，拿到了PAKTIM20%的股份并成为其在尼日利亚的CEO。当时PAKTIM接到17，000台单相电表和8,000台三相电表的订单（此订单已执行一部分，剩下的由HOLLEY执行），客户想追加20%PAKTIM的股份，遭拒后于2016年6月底决定成立Celdon Technologied Ltd.来做电表业务，预计2016年底脱离PAKTIM,不再持有其股份。PKATIM与HOLLEY于2013年开始合作，此次客户与HOLLEY的CEO郭俊峰会面，签署了意向合作协议，未涉及订单信息。客户愿意与银河合作，只要银河的报价和付款方式有竞争力（HOLLEY提供的付款方式是12-18个月的延期信用证）。但HOLLEY没有自生产表箱，所以这点上客户倾向于跟银河合作。客户认为与银河合作可以从Enugu开始，Enugu对于银河的技术应答很满意，后续如客户与Enugu进展良好，我方需提供样机进行测试。客户设想在当地建立工厂，近期计划是组建小型SKD组装厂，单相测试台20-24表位，三相测试台16表位。第一年可能以成品订单的10%来采购SKD，比例逐年上升。客户希望我司提供以下产品一个20GP的报价：单相BS分体PLC(含表箱和双极断路器)、单相BS分体M-BUS(含表箱和双极断路器)、单相DIN分体PLC(含表箱和双极断路器)、单相DIN分体M-BUS(含表箱和双极断路器)、三相BS分体PLC(含表箱和断路器)、三相BS分体PLC(含表箱和断路器)。', '陆飞雨', 'guoji', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('270', '61', 'INHE-0497', '2016-10-18 10:17:27', '2016-10-18 11:33:03', 'khxx20161018225/SUMINISTROS INDUSTRIALES, S.A.', 'khxx20161018225', 'SUMINISTROS INDUSTRIALES, S.A.', 'SISA', '北美洲', '巴拿马', 'http://www.sisapanama.net', '68th street, San Francisco, Panama, Rep, of Panamá', '2015年为海兴代理，并成功中标ENSA的招标项目，供海兴的两相三线导轨表、预付费系统和线损控制系统，总金额6百万美金。去年海兴在秘鲁设立的办事处欲摆脱代理独立投标，现已与该代理脱离关系。\r\n该代理的联系人Eric曾是电力公司Gas Natural Fenosa的采购部老大，任职多年，跟Fenosa的关系非常好，有很丰富的人脉资源。SISA拥有45年的中压、低压电力设备供货经验，公司是巴拿马籍华裔Erdulfo Chang先生成立，目前其女儿Anabella Díaz任总经理。去年的营业额是750万美金.\r\n', '曹荃', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('271', '60', 'INHE-0514', '2016-10-20 17:29:41', '2016-10-24 10:52:44', 'khxx20161020226/Bahwan Projects & Telecoms  LLC', 'khxx20161020226', 'Bahwan Projects & Telecoms  LLC', 'BPT', '亚洲', '阿曼', 'www.suhailbahwangroup.com\r\n ', 'Al Rawaq Building, Qurum, Muscat\r\r\nSultanate of Oman.', 'Bahwan Projects & Telecoms  LLC为阿曼四大家族企业SBGH集团下属的一家子公司，主要从事通信与工程项目承包，在中东区域都设有子公司，实力较好；\r\r\n', '李成兵', '国际业务一部', null, null, 'E', 'INHE');
