INSERT INTO `inhe_customer_data` VALUES ('275', '61', 'INHE-0587', '2016-10-28 16:29:44', '2016-10-28 17:44:44', 'khxx20161028230/Electricity Company of Ghana', 'khxx20161028230', 'Electricity Company of Ghana', 'ECG', '非洲', '加纳', 'www.ecgonline.info', 'Electro/Volta House, 28th February Road, Accra, Ghana', 'ECG负责加纳国南部六省的配电以及售电，南部六省分别为：Ashanti, Western, Central, Eastern, Great Accra和Volta。联系人George是加纳总统办公室的工作人员，此前积极地代银河与电力公司进行联系，目前为我们向电力公司提交了介绍信，并正在沟通样机事宜。客户表示先要进行样机测试，样机测试通过后会进行后续购买。', '陆飞雨', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('276', '61', 'INHE-0500', '2016-11-22 15:50:05', '2016-11-22 16:05:10', 'khxx20161122235/The Central Electricity Board (CEB)\r\n', 'khxx20161122235', 'The Central Electricity Board (CEB)', 'CEB', '非洲', '毛里求斯', 'www.ceb.intnet.mu\r\r\n', 'The Chairman Tender Committee \r\r\r\r\nCentral Electricity Board, \r\r\r\r\nCurepipe,\r\r\r\r\nRep of Mauritius\r\r\r\r\nFacsimile number: \r\r\r\nElectronic mail address: ctc@ceb.intnet.mu\r\r\r\r\n', '1、毛里求斯国家电力公司，负责配售电业务；毛里求斯国家总人口：2013年数据约130万，总电力用户（居民、普通商用、LPU用户）：45万（13年数据）；当前电表供应商：EDMI，Elster，Iskraemeco，Landis*Gyr，Actaris（Itron）\r\r ；AMR软件供应商：EDMI Multidrive，Hexing AMI software。                                                                                                  2、此次招标2万台单相模块智能表，表箱，AMI集抄系统以及相关配置的服务器和配件。                                                                            ', '李忠鹏(Evans)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('277', '61', 'INHE-0431', '2016-11-23 16:43:30', '2016-11-23 16:50:36', 'khxx20161123237/National Contracting Company\r\n', 'khxx20161123237', 'National Contracting Company', '', '亚洲', '沙特阿拉伯', 'http://www.nccprojects.com/company/info/about/\r\n', 'P.O. Box 90\r\nAddress: Al-Khobar 31952', 'Extra high voltage substations of up to 400 kV, in both conventional outdoor and GIS versions\r\r\nTransmission lines up to 500 kV AC & DC, designed to international standards\r\r\nSub-transmission and distribution systems\r\r\nIndustrial electrical projects\r\r\nFiber optic projects\r\r\n', '刘佩(Ted)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('278', '60', 'INHE-0535', '2016-11-24 16:31:52', '2016-11-24 17:31:56', 'khxx20161124240/Tim Ryder Electrical cc', 'khxx20161124240', 'Tim Ryder Electrical cc', 'TRE', '非洲', '南非', 'www.timryder.co.za', '15 Lomac Park，Richards Drive，Halfway House', '该客户专注领域包括电表安装；街灯的安装和维修；故障查找；高、低压线缆焊接；线缆铺设和端接；变压器和开关装置的维修；抄表和审核，44KV线路建设等。项目包括对ESKOM的线路建设，线缆安装，抄表，电表断连和重连，变压器和开关装置维修；对city power的街灯维修；对城市公园园艺设计等。', '左亚楠', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('279', '61', 'INHE-0593', '2016-11-25 14:50:01', '2016-11-25 18:36:40', 'khxx20161125241/Energie du Mali –SA ', 'khxx20161125241', 'Energie du Mali –SA', 'EDM-SA', '非洲', '马里', 'https://www.edm-sa.com.ml/', 'SQUARE PATRICE LUMUMBA, BP 69\r\r\nBamako\r\r\nMali\r\r\n', '马里能源公司是一家工商业性质股份有限公司。于1960年10月14日由马里政府创办。\r\r\r\r\r\r\n创立初期马里能源公司涉及两个业务领域，第一是生产和配送可饮用水，第二部分是在马里共和国全境内发电生产、输电、供电。\r\r\r\n2011年1月1日生产和配送可应用水功能分离，从此马里能源公司仅负责电力部门的管理。马里政府持有马里能源公司66%股份，剩下的34%由IPS WA持有，马里能源公司服务402 000个客户，其中2000个高压用户，另外400 000个低压客户分布于全国各地。', '胡蝶', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('280', '60', 'INHE-0535', '2016-11-28 13:46:26', '2016-11-28 13:56:50', 'khxx20161128242/Hayleys Industrial Solutions (Pvt) Ltd\r\n', 'khxx20161128242', 'Hayleys Industrial Solutions (Pvt) Ltd', 'HIS', '亚洲', '斯里兰卡', 'www.hayleysaventura.com', 'Hayleys Industrial Solutions (PVT) LTD,No 25, Foster Lane, Colombo 10, Sri Lanka', 'Hayleys是一个总部设在首都科伦坡的大型跨国集团，旗下经营纺织、化工、建材、物流、能源电力、旅游度假等各项产品与服务，业务基本涉及各个领域及行业，在斯里兰卡国内拥有广泛的资源与雄厚的财力。就电力与能源这一部门，Hayleys在CEB有很强的关系，合作经验丰富。\r\r\n', '左亚楠', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('281', '60', 'INHE-0399', '2016-11-29 19:31:31', '2016-11-30 08:34:25', 'khxx20161129244/PT. Alusbae Cipta Solusi (ACiS ) ', 'khxx20161129244', 'PT. Alusbae Cipta Solusi (ACiS )', 'ACIS', '亚洲', '印尼', ' http://www.alusbae.com/', ' Menara Karya, 28th floor\r\nJl. HR. Rasuna Said, Blok X-5, Kav. 1-2\r\nJakarta 12950, Indonesia\r\n', 'ACIS是做通信行业，包括网络优化提速，无线电设备，Machine to Machine 等业务，与电信运营商的业务比较多。\r\n', '左三维', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('283', '61', 'INHE-0602', '2016-12-01 17:46:19', '2016-12-02 16:31:25', 'khxx20161201245/Eandis\r\n', 'khxx20161201245', 'Eandis', '', '欧洲', '比利时', 'www.eandis.be\r\n', 'Electriciteitstraat 70, BE-2800 Mechelen\r\n', '电力，天然气，供热，公共照明解决方案提供商\r\nDIN-ABC对功能不清楚\r\r\nBox-300通断电感兴趣11月16日\r\r\n已发送相关资料，未联系上whatsapp,已成为领英好友。对方目前尚未回复。', '牛童', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('284', '61', 'INHE-0602', '2016-12-01 17:50:22', '2016-12-02 16:31:18', 'khxx20161201246/Orange', 'khxx20161201246', 'Orange', '', '欧洲', '法国', 'www.orange.com', '140 avenue de la Rébuplique 92320 Chatillon France', '电信运营商\r\n1.想非洲合作\r\n2.他们做HES，我们做表，对GPRS通信感兴趣\r\n3.想要样机\r\n11月16日已发送相关资料，已建立whatsapp联系。表示这周比较忙，希望下周可以详聊\r\n11月22日回复，表示希望在我们的表对接。具体要求还需详细聊。\r\r\n\r\n\r\n\r\n', '牛童', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('285', '61', 'INHE-0602', '2016-12-01 17:53:48', '2016-12-02 16:31:09', 'khxx20161201247/Liquix', 'khxx20161201247', 'Liquix', '', '欧洲', '荷兰', 'www.liaquix.eu', 'Spacelab SI 3824MR Amersfoort The Neitherlands', '欧洲领先的线上支付平台，涉足预付费，移动支付等领域\r\n预付费、解决方案、电表、DIN、单三相模块表\r\n11月16日已发送相关资料，未联系上whatsapp,已成为领英好友，表示下周可以聊聊。\r\n11月25日已回复，表示希望和我们在孟加拉合作投一个标，我们做电表硬件，他们搞系统。', '牛童', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('286', '61', 'INHE-0602', '2016-12-01 17:56:00', '2016-12-02 16:31:01', 'khxx20161201248/Inepro Metering BV\r\n', 'khxx20161201248', 'Inepro Metering BV', '', '欧洲', '荷兰', 'www.ineprometering.com', 'Pondweg7 2153 PK Nieuw-Vennep The Netherlands', '对手的合作伙伴\r\r\n\r\n11月18日已发邮件联系，尚未收到回复，争取在whatsapp和领英上加一下。', '牛童', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('287', '61', 'INHE-0602', '2016-12-01 17:58:41', '2016-12-02 16:30:53', 'khxx20161201249/NXP Semiconductors', 'khxx20161201249', 'NXP Semiconductors', '', '欧洲', '法国', 'www.nxp.com', '2 esplanade Anton Philips,Campus EffiScience,Colombelles BP 20000,14906 Caen Cedex 9,France', '半导体\r\r\nNXP （恩智浦半导体）是一家新近独立的半导体公司，由飞利浦公司创立，已拥有五十年的悠久历史，主要提供工程师与设计人员各种半导体产品与软件，为移动通信、消费类电子、安全应用、非接触式付费与连线，以及车内娱乐与网络等产品带来更优质的感知体验。\r\r\n2015年2月，飞思卡尔与 NXP达成合并协议，合并后整体市值 400 亿美金。收购在2015年下半年彻底完成。为纳斯达克上市公司，在全球20多个国家拥有3.7万名员工\r\n上海有分公司，常来深圳\r\n感兴趣第三方售电', '牛童', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('288', '60', 'INHE-0560', '2016-12-02 10:44:47', '2016-12-02 10:44:47', 'khxx20161202250/Indulis Viksne', 'khxx20161202250', 'Indulis Viksne', ' Viksne', '欧洲', '拉脱维亚', 'http://www.sadalestikls.lv/rus', 'Ventspils iela 58, Rīga, Latvija\r\r\r\n', 'AS \"Sadales tīkls\"--拉脱维亚当地著名电力公司，主要从事电力产品供应，拥有庞大的经营及分销网络，电力产品服务对象超过100万，覆盖拉脱维亚全境的99%，每年都有稳定的产品需求量。此次招标项目需求量大，且合作前景广阔，是我司产品大规模进入欧洲表计市场的重要契机。', '李美娇', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('289', '61', 'INHE-0091', '2016-12-06 10:18:05', '2016-12-06 10:38:15', 'khxx20161206251/Angelique International Limited\r\n', 'khxx20161206251', 'Angelique International Limited', 'Angelique', '亚洲', '印度', 'http://www.angelique-india.com\r\n', 'H.O - Plot no 12  Sec 125, Noida -201301 UP\r\n', '1996年成立，EPC公司，在电力、水利、农业行业及工业工程项目专做交钥匙项目，业务遍布非洲、中东、南亚和东南亚。\r\n客户在坦桑尼亚市场曾中过农电REA的标，执行工程承包项目。', '林丽璇', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('290', '61', 'INHE-0580', '2016-12-12 10:40:40', '2016-12-12 15:30:58', 'khxx20161212252/ADREM', 'khxx20161212252', 'ADREM', '', '欧洲', '罗马尼亚', 'www.adrem.ro', 'Mihail Kogalniceanu 13,bloc C2, Brasov', '罗马尼亚ADREM公司规模较大，旗下三个公司ADREM INVEST, ADREM ENGINEERING 和ADREM LINK，分别致力于能源产业的产品，解决方案和服务。ADREM INVEST为电网提供服务，如抄表、电能计量组管理、电力基础设施维护和配电网运行；从复杂的工程总承包到家庭设备，ADREM ENGINEERING开发和实施全面的能源基础设施解决方案；ADREM LINK为提高能源效率、可视信息、操作优化和自动化控制提供解决方案。但是ADREM公司没有自己的产品，电表产品由供应商提供。\r\n\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n它是罗马尼亚电力公司CEZ的合作伙伴，负责该公司电表计量。\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n\rADREM ENGINEERING部门 Business Unit Smart Grid负责采购电表产品。\r\n\r\n', '刘前', '国际2部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('291', '61', 'INHE-0497', '2016-12-19 10:09:25', '2016-12-19 10:25:08', 'khxx20161219253/ALTA TENSIóN ALTATEN S.A.\r\n', 'khxx20161219253', 'ALTA TENSIóN ALTATEN S.A.', 'ALTATENSA', '南美洲', '厄瓜多尔', 'www.altatensa.com.ec\r\n', 'Avenida 10 de Agosto N55-52 y Psj. Pedro Barrios,Quito,Ecuador', '代理ALTATENSA是一家电力设备进口商，拥有丰富的电表投标经验，供货经验，和运作经验，实力不错。', '曹荃', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('292', '60', 'INHE-0557', '2016-12-19 10:33:09', '2016-12-19 10:49:16', 'khxx20161219254/ЧПТУП \"Солтика\"\r\n', 'khxx20161219254', 'ЧПТУП \"Солтика\"', 'SOLTIKA', '欧洲', '白俄罗斯', 'http://soltika.by/', 'Belarus, Minsk, st. Majakouskaha, 11 postal code 220000', '客户生产贸易型企业，公司主要产品电表，数据采集器，集中器，AMR系统，软件。\r\r\n', '程芸', '国际业务一部 ', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('293', '61', 'INHE-0587', '2017-01-03 15:43:54', '2017-01-03 18:18:21', 'khxx20170103257/WFC Utilities', 'khxx20170103257', 'WFC Utilities', '', '非洲', '尼日利亚', 'wfcutilities.com/http://genesisenergygroup.net/contact-us/', '3680 Erie Crescent Off Nile Street\r\r\nMaitama Abuja, Nigeria/+234-9291945', 'WFC Utilities是英国能源公司Genesis Energy旗下的子公司。Genesis Energy是一家英国公司，致力于非洲能源事业（电力，水力，天然气等）。而WFC主营的是水力和电表相关产品。', '陆飞雨', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('294', '61', 'INHE-0500', '2017-01-05 15:16:53', '2017-01-05 15:22:29', 'khxx20170105259/Rousant International Limited', 'khxx20170105259', 'Rousant International Limited', 'Rousant', '非洲', '南非', 'www.rousant.co.za\r\n', '84 Beyers Naude Drive, Roosevelt Park, Johannesburg, 2195\r\r\r\nP. O. Box 4316, Cresta, 2118\r\r\r\n', '1、成立于1993，总部位于南非，专业的电力电气设备设施经销商、贸易商和工程承包商，行业经验丰富，其客户群体主要电力公司为主，在Kenya, Uganda, Tanzania, Ghana, Namibia, South Africa, Ethiopia, Zambia, Mauritius都有项目，有多次参与CEB变压器、电缆线、电线杆招投标经验，中过CEB导线标\r\n', '李忠鹏(Evans)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('295', '60', 'INHE-0406', '2017-01-06 13:54:51', '2017-01-06 14:08:10', 'khxx20170106260/PESTECH ENGINEERING TECHNOLOGY (CHINA) CO.LTD.\r\n', 'khxx20170106260', 'PESTECH ENGINEERING TECHNOLOGY (CHINA) CO.LTD.', 'PESTECH', '亚洲', '马来西亚', 'http://www.pestech-international.com/\r\n', 'No.A312 Air City Plaza, Nanfaxin Town, Shunyi District, Beijing, 101300, P.R. CHINA\r\r\n', 'PESTECH设计、生产、承建中高压变电站，公司现在是变电站领域的大型总承包商。主要业务地点在亚洲非洲国家，如文莱，斯里兰卡，柬埔寨，马来西亚，吉尔吉斯斯坦，塔桑尼亚，加纳，马里等18个国家和地区。\r\n', '王毅', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('296', '60', 'INHE-0514', '2017-01-14 15:40:50', '2017-01-16 09:08:37', 'khxx20170114261/Munir Sukhtian Group Trading\r\nSukhtian for Power, Water & Environment\r\n', 'khxx20170114261', 'Munir Sukhtian Group TradingSukhtian for Power, Water and Environment', 'MSG', '亚洲', '约旦', 'www.sukhtian.com\r\n', 'P.O. Box 1027Amman 11118 – Jordan\r\n', 'Munir Sukhtian Group Trading- Sukhtian for Power, Water and Environment是MSG集团下属子公司，成立于1990年（MSG成立于1933），主要从事环境保护水处理的业务，是GE Water “General Electric”, Hach Lange, Dow “Rohm And Haas”, BASF,\r\r\nOxychem and Ohaus等国际品牌在约旦的代理，在约旦主要承担约旦水务局的工程项目，目前准积极准备进入energy领域。', '李成兵', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('297', '60', 'INHE-0549', '2017-02-15 13:32:35', '2017-02-15 14:07:54', 'khxx20170215262/毛里塔尼亚国家电力公司', 'khxx20170215262', 'Société Mauritanienne d`électricité', 'SOMELEC', '非洲', '毛里塔尼亚', 'http://www.somelec.mr/', '47, Avenue de l`Indépendance BP 355 Nouakchott, MAURITANIE', 'SOMELEC (毛里塔尼亚电力公司)成立于2001，是从1975年成立的毛里塔尼亚水电公司分离出来的。它负责整个毛里塔尼亚境内城市及其周边的发电，输电，配电和用电.', '王秀明', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('298', '60', 'INHE-0549', '2017-02-20 11:12:56', '2017-02-20 11:33:16', 'khxx20170220263/Office National de l’électricité et de l’Eau Potable - Branche électricité', 'khxx20170220263', 'Office National de l`électricité et de l`Eau Potable - Branche électricité', 'ONEE-Branche Electricité', '非洲', '摩洛哥', 'http://www.one.org.ma/', '65, Rue OTHMAN BEN AFFAN 20 000 CASABLANCA MAROC', '摩洛哥水电局电力部，对改善摩洛哥公民的生活和国家的经济竞争力起着很重要的作用。', '王秀明', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('299', '60', 'INHE-0399', '2017-02-20 15:39:06', '2017-02-20 15:56:22', 'khxx20170220264/Radiant Energy & Power Inc. ', 'khxx20170220264', 'Radiant Energy and Power Inc.', 'REP', '亚洲', '孟加拉国', 'N/A', 'Suit-502, Level-5, Block-C BGMEA Complex, 23/1 Panthapath Link Road, Kawran Bazaar, Dhaka-1215\r\r\n', '该公司主营IT公司，是谷歌和Facebook当地主要合作伙伴。副业，船运，拥有3艘船提供船运业务给海军。投标业务，包括和Power China合作的太阳能发电，CMEC合作的项目以及炼油项目的投标。', '左三维', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('301', '61', 'INHE-0587', '2017-02-27 08:59:59', '2017-02-28 08:42:29', 'khxx20170227265/Langai Merchants Ltd.', 'khxx20170227265', 'Langai Merchants Ltd.', '', '非洲', '尼日利亚', '', 'NO 1 Dogon Juction Bauchi Rd, Plateau State, Nigeria', '客户主要是做贸易业务的，有3家公司：轮胎贸易、加油站和包装材料生产。目前来看，规模都不是很大。客户之前没有接触过电表业务，来之前，他称手上有JED的15,000台订单。此次他的目的是希望我司提供单三相样机，他拿去JED演示，演示成功即下达订单。', '陆飞雨', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('302', '61', 'INHE-0091', '2017-03-03 09:34:59', '2017-03-03 13:59:05', 'khxx20170303266/Global Merge Synergy Sdn Bhd\r\n', 'khxx20170303266', 'Global Merge Synergy Sdn Bhd', 'GMS', '亚洲', '马来西亚', '', 'No 15, Jalan Plumbum 7/101 D, Seksyen 7, Selangir, Shah Alam, Selangor, Malaysia\r\r\n', '2006年5月成立，提供电气和电子产品的供货、安装、检修及服务。主要做LED灯和代码表。2000年至2012年期间，给TNB和SESB供过单/三相单子表。\r\r\n', '林丽璇', '国际业务二部', null, null, 'E', 'INHE');
