INSERT INTO `inhe_customer_data` VALUES ('304', '61', 'INHE-0374', '2017-03-13 14:13:38', '2017-03-13 15:03:37', 'khxx20170313268/Afrique mines et Industries', 'khxx20170313268', 'Afrique mines et Industries', 'SENELEC', '非洲', '塞内加尔', 'www.amisa.sn', 'sodida dakar senegal', '此客户是塞内加尔\r\r矿产设备供应商，是电力公司测试设备的供应商，招投标经验丰富，人脉较多，做事效率较高，与电力公司关系很好。\r\r\r\n', '王子强', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('305', '60', 'INHE-0535', '2017-03-13 16:18:30', '2017-03-13 16:54:58', 'khxx20170313269/Khanyi Ngco Solutions (Pty) Ltd', 'khxx20170313269', 'Khanyi Ngco Solutions (Pty) Ltd', 'KNS ', '非洲', '南非', '无', '33 Adonis Road, Edleen, Kempton Park, Gauteng, 1619', '该公司由Matlhare Bodibe所有，100%黑人所有性质公司。Matlhare Bodibe以前是Eskom的工程师，同时是ZAR01项目中合作客户Makgaji的技术经理。该公司主要服务包括：电费收入保护，LPU和SPU电表安装，CT和VT验证，LPU和SPU电表和基础建设审计，费率分析与制定，电能管理，AMR/AMI/Vending兼容方案，水表检测和管理系统，电表和水表培训等。主要参与Eskom及一些地方市政府的电表项目，由于Matlhare Bodibe的个人工作背景，与ESKOM及周边省市的政府等相关工程师有一定关系。也在经常留意可与我司合作的电表项目机会。					\r\n						\r\n\r\n						\r\n					\r\r\n						\r\r\n\r\r\n', '左亚楠', '国际业务一部', null, null, 'E', 'INHE');
