INSERT INTO `inhe_customer_data` VALUES ('307', '66', 'JXINHE-2559', '2017-03-20 08:08:04', '2017-03-20 08:40:10', 'khxx20170320272/ConnectPlus Technology Sdn Bhd ( HQ )', 'khxx20170320272', 'ConnectPlus Technology Sdn Bhd ( HQ )', 'Protechnology', '亚洲', '马来西亚', 'www.protechnology.com.my', '43, Jalan PJS 11/22,Bandar Sunway, 47500 Subang jaya, Selangor, Malaysia', 'TNB线缆、开关、连接器的供应商之一，有给TNB供过软件分析和服务类产品，业务涵盖石油、天然气、运输、电力，机械等。', '淦永妍', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('308', '61', 'INHE-0578', '2017-03-24 15:28:35', '2017-03-24 16:16:31', 'khxx20170324273/Serumula Business Solutions (PTY) LTD', 'khxx20170324273', 'Serumula Business Solutions (PTY) LTD', 'Serumula Solutions', '非洲', '莱索托', '', 'Starlion Group Building,Second Floor,Maseru,Lesotho', '1. 公司于2012年成立，总公司在莱索托，分公司在南非豪登省；主营电能行业软件相关，工程项目咨询等，规模中等；                  2. 联系人哥哥公司有 SUCCESS INTERNATIONAL (Pty) Ltd，主要做工程施工，目前正在与莱索托电力局合作做相关电表项目安装工作；与电力局具有较好的合作关系。                                                                                             3. 因此表示此次莱索托电力局招标具有较强把握。该客户合作态度也较好。', '覃湘君(June)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('309', '61', 'INHE-0587', '2017-03-27 16:45:58', '2017-03-27 16:54:08', 'khxx20170327274/L R Group', 'khxx20170327274', 'L R Group', '', '非洲', '尼日利亚', 'http://lr-group.com', '41 Euphrates Street, Maitama,Abuja, Nigeria', 'L R Group是一家以色列集团，经营范围包括农业（专注将新科技运用于非洲和亚洲国家，如尼日利亚、安哥拉、斯里兰卡、巴布亚新几内亚、科特迪瓦等等）、健康、通信、能源（电力太阳能等）、建筑和水利。\r\n', '陆飞雨', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('310', '61', 'INHE-0500', '2017-04-06 13:42:50', '2017-04-06 13:59:04', 'khxx20170406277/Koxmac Zambia Limited\r\n', 'khxx20170406277', 'Koxmac Zambia Limited', 'KOX', '非洲', '赞比亚', 'N/A', 'Plot No.383,Salama Park,Salama Raod,Lusaka,Lusak Province,Zambia', '1.成立于2007，经销商和贸易商为主，年销售额300万美元左右，主要客户群体集中在市政单位、市政供水和电力公司等，和ZESCO合作过部分机械设备和劳保用品等；\r\r\r\r\r\n2.代理的主要客户关系在总统府和\r电力公司采购部两个层次，\r对于市政和电力公司的招标流程较为熟悉；\r\r\n3.银河在赞比亚市场通过直接投标、由代理协助客户关系运作的模式进行合作。', '李忠鹏(Evans)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('311', '60', 'INHE-0549', '2017-04-06 13:38:28', '2017-04-06 14:35:56', 'SOCIETE NIGERIENNE\r\nD`ELECTRICITE\r\n', '', 'SOCIETE NIGERIENNED`ELECTRICITE', 'NIGELEC\r\r\r\r\n', '非洲', '尼日尔', 'http://www.nigelec.ne/\r\n', 'n°201, Avenue du Général de G aulle (PL\r\n30) Niamey, Niger', '尼日尔电力公司,是尼日尔的极地发电输电配电公用事业。在特许经营制度下实现尼日尔电力公共服务的使命，以期实现生产，购买，进口，运输和分配电能的目的。创建时间：1968年9月1日,尼日利亚政府有多数股权，其管理由矿业和能源部监督，经营四座发电厂。资本约33.56亿非郎（合610万美元），总部位于尼日尔的首都及最大城市尼亚美\r\r。\r\r\n', '王秀明', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('312', '61', 'INHE-0612', '2017-04-11 14:39:08', '2017-04-11 15:02:11', 'khxx20170411278/Sistindacema TMX \r\n', 'khxx20170411278', 'Sistindacema TMX', 'ST', '北美洲', '墨西哥', 'http://www.sistindacematmx.com/\r\n', 'Calle 8 N°205 x 35 y 37 Col. Leandro valle, Mérida, Yucatán. México \r\r\r\n', 'SISTINDACEMATMX 成立于2006年，主要从事中压低压电力设备（变压器）销售、安装、维护，工程、建筑设计规划等。主要客户有CFE(墨西哥国家电力公司)、PEMEX（墨西哥最大石油公司）。与电力公司有着非常不错的关系。\r\r\n', '陈晨', '国际二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('313', '60', 'INHE-0560', '2017-04-14 10:34:06', '2017-04-14 11:23:12', 'khxx20170414279/Больков Виталий', 'khxx20170414279', 'Больков Виталий', 'Больков', '亚洲', '', 'http://www.add-energy.com/', '03179, г. Киев, Брест-Литовское шоссе 8А, ООО \"АДД-Энергия\"', '乌克兰add-energy公司是乌克兰境内的一家专业从事表计产品销售业务的公司，该公司为ADD-Grup公司在乌克兰的唯一经销商，成立于1999年，主要为乌克兰境内用户供应电力及提供能源计量解决方案，拥有ADDAX（ADDAX IMS）计量系统.add-energy公司在乌克兰的客户主要为电力公司，且拥有自己的服务中心，用以支持其产品及设备。现与我司正在商讨合作事宜，方向为在乌克兰大力推进预付费系统项目。', '李美娇', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('314', '61', 'INHE-0228', '2017-04-17 16:52:11', '2017-04-17 17:02:53', 'khxx20170417280/VR Enbekon eG\r\n', 'khxx20170417280', 'VR Enbekon eG', 'VRE\r\r\r\r\n', '欧洲', '德国', 'www.vr-enbekon.de\r\n', 'Lilienthalstr. 3\r\n82178 Puchheim\r\nDeutschland\r\n(Germany)\r\n', '询盘客户，客户公司是做新能源，例如光伏太阳能发电、充电桩，等。', '谭雯', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('315', '61', 'INHE-0091', '2017-04-21 17:58:26', '2017-04-21 18:13:11', 'khxx20170421281/IOTSEG Pte Ltd\r\n', 'khxx20170421281', 'IOTSEG Pte Ltd', 'IOTSEG\r\r\n\r\r\r\n', '亚洲', '新加坡', 'http://iotseg.com/\r\n', '#01-01, 10 Tannery Lane, Singapore 347773\r\n', '\r\r\n\r\nIOTSEG为配电公司、公共事业部门，系统运营部门及政府代理机构在智能电网领域提供研究与发展服务，尤其致力于发展APP，分析工具，基于物联网的家庭和建筑自动化系统，以及智能控制平台。', '林丽璇', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('316', '61', 'INHE-0497', '2017-04-27 08:40:30', '2017-04-27 09:05:48', 'khxx20170427282/CCP S.A.', 'khxx20170427282', 'CIA. COMERCIAL DEL PARAGUAY S.A.', 'CCP S.A.', '南美洲', '巴拉圭', 'www.ccp.com.py', 'Chile 877 c/ Piribebuy - Asunción\r\r\n', 'CCP S.A.成立于1933年，拥有83年的电力行业经验，专注于进口、销售电力设备配件、材料、照明设备等。\r\n', '曹荃', '国际业务2部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('317', '61', 'INHE-0431', '2017-04-27 15:16:36', '2017-04-27 15:39:36', 'khxx20170427283/EDCL', 'khxx20170427283', 'EDCL', 'LRW', '非洲', '卢旺达', 'edcl.reg.rw', '', '客户是卢旺达国家电力公司,负责卢国的配电工作,一直有从世行和非洲发展银行等取得资金并用于建设当地的配电网络(包括提供电表)', '刘佩(Ted)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('318', '61', 'INHE-0431', '2017-04-27 15:51:17', '2017-04-27 15:56:56', 'khxx20170427284/  Energy Development Corporation Limited  ', 'khxx20170427284', 'Energy Development Corporation Limited', 'EDCL', '非洲', '卢旺达', 'www.edcl.reg.rw', 'Electricity Access Roll out Program(EARP)KN2 ST 3, Nyarugenge District, Kigali City, Kigali, Rwanda.Kigali City Tower 10th FloorCity: KIGALIZIP Code: NACountry: RWANDA\r\n', '客户是卢旺达国家电力公司,负责卢国的配电工作,一直有从世行和非洲发展银行等取得资金用于建议当地的配电网络(包括提供电表)\r\n', '刘佩(Ted)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('319', '60', 'INHE-0535', '2017-04-28 15:21:55', '2017-04-28 17:43:02', 'khxx20170428285/SRC  Electricals\r\n', 'khxx20170428285', 'SRC  Electricals', 'SRC', '亚洲', '斯里兰卡', '无', 'No: 470/1C,   High Level Road\r\r\r\nMakumbura\r\r\r\nPannipitiya   10230\r\r\r\nSri Lanka.', 'SRC是当地一家电力产品供应商，客户包括电力公司和一些私人商业和工业用户。对私人用户的产品供应包括太阳能设备（太阳能板，变流器等），电表 ；对电力公司主要通过招投标供应HV设备。电力公司的电表招标对技术和商务要求非常严格。尽管私人电表市场较小，但是他们也在做。早期在2000年，他们一直供应Iskraemeco电表，现在 Iskraemeco电表在斯里兰卡早已不活跃。后来他们找过Itron	和Elster,	他们也不感兴趣。				\r\r\n因近期对电表产品的需求，通过KEMA网站查找得知我司电表产品通过KEMA认证，进而找到我司。						\r\r\r\n', '左亚楠', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('320', '60', 'INHE-0560', '2017-05-02 09:45:01', '2017-05-02 10:20:44', 'khxx20170502286/Santral electric', 'khxx20170502286', 'Santral electric', '', '亚洲', '阿塞拜疆', 'www.santral.az', 'AZ1029, Azerbaijan,  Baku, 11/2071 Z.Bunyadov', '阿塞拜疆电力改革后，全国所有的电表将由之前的巴库电力公司接管，重新组建了新的电力公司Azerishiq，负责配电、售电等。\r\r\r\nSantral Electric是一家集团公司，旗下有销售电力配件、工具、灯具商城，还经营几个工厂，业务有承接电力工程，加工电缆线、表箱等。Santral官方上和Azerishiq没有关系，但是Azerishiq的高层在Santral有股份，Azerishiq所有的电表只会通过Santral来购买。\r\r\r\n', '李美娇', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('321', '66', 'JXINHE-2559', '2017-05-03 14:25:42', '2017-05-03 16:11:45', 'khxx20170503287/Wande InternationalTeku – 12, Kathmandu,Nepal', 'khxx20170503287', 'Wande International', 'Wanda', '亚洲', '尼泊尔', '         ', 'BRAMHA TOLE, WANDE NARAYANSTHAN, TEKU-12 ,KATHMANDU ,\r\r\nNEPAL\r\r\n', '公司成立于1992年，主营进口各类办公设备，参加政府类投标，曾与中国水电，天津CCECC，法国Sogreah等合作参加NEA发电站业务。', '淦永妍', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('322', '60', 'INHE-0514', '2017-05-10 09:34:53', '2017-05-10 09:50:07', 'khxx20170510288/Fury Trade Co.', 'khxx20170510288', 'Fury Trade Co.', '', '亚洲', '巴勒斯坦', '', 'albakri bldg., Rafeedia st., Nablus, Palestine', '客户位于巴勒斯坦西岸地区（巴沙客户位于加沙地带，西岸和加沙分别由哈马斯以及法塔赫管理，共同归巴勒斯坦民族解放机构管制，加沙和西岸）北部地区，主要负责西岸的水表和电表的市场，巴沙地区也有涉及；该客户之前是南非Conlog的代理，但由于Conlog没有PLC ，没有CT表，不再适合当地市场竞争，所以该客户决定重新寻找供应商；', '李成兵', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('323', '61', 'INHE-0228', '2017-05-12 16:19:40', '2017-05-15 09:52:22', 'khxx20170512289/Swissfinance SA\r\n', 'khxx20170512289', 'Swissfinance SA', 'Swissfinance SA\r\r\n\r\r\n', '欧洲', '瑞士', 'http://swissfinance-sa.ch/en/\r\n', 'Avenue Viollier 3, Nyon, Vaud, 1260', '瑞士一家金融服务公司，此前和利比亚电力公司做过项目，但是不电表类的。', '谭雯', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('324', '61', 'INHE-0228', '2017-05-16 15:02:16', '2017-05-19 15:10:52', 'khxx20170516290/INTEMO', 'khxx20170516290', 'INTEMO', '', '欧洲', '荷兰', 'http://www.intemo.com/en/home-2/\r\n', 'Marshallstraat 24,5705 CN Helmond,the Netherlands', 'Innovative Technology in Motion, this is what Intemo and its mindset are all about. Like the words suggest: with Intemo innovation comes first. In embedded computers, sensors, components, and product design in the area of industrial computers. \r\n', '谭雯', '业务2部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('325', '60', 'INHE-0399', '2017-05-18 11:25:34', '2017-05-18 13:54:22', 'khxx20170518291/Metro Teleworks Inc.', 'khxx20170518291', 'Metro Convergence Inc.', 'MCI', '亚洲', '菲律宾', 'www.metroconvergence.com.ph', 'Unit 2207, Antel Global Corporate Centre, Julia Vargas Avenue, Ortigas Center, Pasig City', '菲律宾当地网络服务公司成立于1997年，前身为METROSERV COMMUNICATIONS INC. 主要业务为经销电信产品，例如光纤跳线，光纤头，以及电信类的交钥匙项目。由于今年该业务利润降低，竞争激烈，该公司在寻找新的业务增长点。', '左三维', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('327', '60', 'INHE-0535', '2017-05-18 16:33:50', '2017-05-18 17:29:51', 'khxx20170518292/ecoprise\r\n', 'khxx20170518292', 'ecoprise', 'EP', '亚洲', '尼泊尔', 'www.meroecoprise.org\r\n	\r\n', 'Do Cha Marga , PaniPokhari, Maharajgunj \r\nKathmandu \r\n			\r\n', 'EP是尼泊尔一家专注于家用太阳能系统，太阳能发电，可持续产品制造等的盈利性企业；设计、制造、供应清洁能源解决方案。同时履行公共职责和发展商业市场活动，重点发展可持续产品和服务，以产生经济，环境和社会效益。至今，已完成1000+个太阳能安装项目，2000+清洁能源解决方案等的销售.						\r\r\n该公司成立于2010年，与政府，私营部门和国际机构在多个不同种类的太阳能项目中有过丰富的合作经验。', '左亚楠', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('328', '66', 'JXINHE-2559', '2017-05-19 16:52:27', '2017-05-19 17:19:55', 'khxx20170519293/Siddiqsons Limited', 'khxx20170519293', 'Siddiqsons Limited', 'Siddiqsons', '亚洲', '巴基斯坦', 'http://www.thesiddiqsonsgroup.com/', '26th Floor - Ocean Mall & Tower\r\r\nPlot # G-3 Block 9 Clifton Road，Karachi, Pakistan', '集团公司，成立于1953年，旗下四家子公司，分别从事能源(煤电，太阳能)，纺织服装，钢铁(镀锌板)，畜牧(奶制品)行业，同时拥有地产经营多家商场。', '淦永妍', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('330', '61', 'INHE-0593', '2017-05-22 17:37:54', '2017-05-22 17:50:51', 'khxx20170522295/ENTREPRISE MALIENNE DE TRAVAUX ET D’INGENIERIE\r\n', 'khxx20170522295', 'ENTREPRISE MALIENNE DE TRAVAUX ET D’INGENIERIE', 'EMTI', '非洲', '马里', 'http://www.emti-mali.com', 'BP E 2827 – Kalabancoro – Bamako		\r\n', '公司已有客户，2012年曾出货马里电力公司。', '胡蝶', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('331', '60', 'INHE-0399', '2017-05-24 15:59:45', '2017-05-24 16:07:36', 'khxx20170524296/CSL Projects Limited', 'khxx20170524296', 'CSL Projects Limited', 'CSL', '亚洲', '孟加拉国', 'www.clsprojectsbd.com', 'House No.15 (2nd Floor), Road No.24, Gulshan, Dhaka-1212, Bangladesh.', '母公司为Consolidated Services Limited (CSL)， CSL Projects Limited 成立专门为孟加拉寻找优质国外厂商实现该国Millennium Development Goals (MDG)千禧年发展目标。该公司与新成立的电力公司NWPDCL有较好的关系。', '左三维', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('332', '61', 'INHE-0587', '2017-05-25 09:37:43', '2017-05-25 10:31:15', 'khxx20170525297/B.N.S.R. Sela', 'khxx20170525297', 'B.N.S.R. Sela Projects Ltd.', '', '非洲', '尼日利亚', 'comet-me.org', '', 'B.N.S.R Sela projects L.T.D是一家经营水/电表以及电表配件的公司。\r\nQuadlogic Controls Corporation和EMS是以色列两家表计产品进口商，而BNSR\r\n是2007年从EMS分离出来的，目前除了和中国的相关厂商有合作之外，还和荷兰\r\n的INEPRO有合作。BNSR目前集中在预付费产品这一块，曾经参与过以色列、博\r\n茨瓦拉、纳米比亚、尼日利亚等地的IC卡水表或者电表项目。', '陆飞雨', '国际业务二部', null, null, 'E', 'INHE');
