INSERT INTO `inhe_customer_data` VALUES ('336', '61', 'INHE-0091', '2017-05-27 09:29:32', '2017-05-27 10:57:19', 'khxx20170527301/Danish Private Limited', 'khxx20170527301', 'Danish Private Limited', 'Danish', '亚洲', '印度', 'www.danish.co.in\r\n', 'F-679-680, G-694, Sitapura Industrial Area, Jaipur (Raj.)-302022 India \r\n', '电力设备生产厂家，生产油式配电变压器、干式变压器、电源变压器、控制继电器面板、变电站自动化。产品销往阿富汗、孟加拉、塞内加尔、尼日利亚、几内亚、南非、莫桑比克、乌干达、坦桑尼亚、肯尼亚等非洲国家及中东国家，也在印度本地供货，并销售给施耐德、ABB、西门子。\r\n', '林丽璇', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('337', '60', 'INHE-0399', '2017-06-02 10:31:37', '2017-06-02 10:49:34', 'khxx20170602302/TBS Industrial Services, Inc.', 'khxx20170602302', 'TBS Industrial Services, Inc.', 'TBS', '亚洲', '菲律宾', 'tbsindustrial.com.ph', '# 6 Rosal St., Saint Dominic 3, Mindanao Ave., Banlat, Quezon City\r\r\r\n', '该公司主营业务为灭火设备和方案。是日本火灾设备公司的合作伙伴，在该行业有17年经验。随着公司发展以及菲律宾对清洁能源，可持续能源的需求增加，逐渐进入到能源行业。', '左三维', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('338', '61', 'INHE-0636', '2017-06-02 21:36:34', '2017-06-03 15:53:05', 'khxx20170602303/Kenya Electricity Transmission Company Ltd', 'khxx20170602303', 'Kenya Electricity Transmission Company Ltd', 'KETRACO', '非洲', '肯尼亚', 'http://www.ketraco.co.ke/', 'Kawi Complex, Block B,5th Floor, Popo Lane, Off Red Cross Road, South C, P.O. Box 34942-00100, Nairobi', 'Kenya Electricity Transmission Company Ltd (肯尼亚输电有限公司)，位于肯尼亚内罗毕，属于国有企业，主营国内输电、区域邻国间输电', '倪明杰', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('339', '66', 'JXINHE-2559', '2017-06-06 08:09:35', '2017-06-06 08:38:22', 'khxx20170606305/Power System Engineering Consultants', 'khxx20170606305', 'Power System Engineering Consultants', 'PSEC', '亚洲', '巴基斯坦', 'www.pseconsultant.com', '31/2-B,Abu Bakar Block, Raja Market,New Garden Town, Lahore-Pakistan', '公司成立于2013年8月23日，由该国NTDC(National Transmission and Dispatch Company国家输配电发展公司)/DISCO(Distribution Companies各省配电公司)/WAPDA(The Water and Power Development Authority国家水电开发署)一些高级官员成立的能源顾问公司。公司CEO是NTDC的总经理，LESCO的前CEO,能源部主管是NTDC前能源计划部总经理，为亚开行的高级顾问。公司业务涉及，能源，输电，配电等。主要项目有，评估LESCO(拉合尔电力局)和IESCO(伊斯兰堡电力局)的输电和配电损耗，亚开行投资的NTDC-500KV输电项目，NTDC项目-500KV双回路输电项目(约130KM)。', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('340', '61', 'INHE-0500', '2017-06-13 02:36:37', '2017-06-13 08:42:29', 'khxx20170613307/Elektro Hinsch (Contracting) ( Pty) Ltd', 'khxx20170613307', 'Elektro Hinsch (Contracting) ( Pty) Ltd', 'EHC', '非洲', '纳米比亚', '无网站', '9-11 Hosea Kutako Drive，Windhoek, Namibia', '成立于2009年，纳米比亚当地电力工程承包商，电力行业工程经验丰富，主要的客户为Nampower，REDS和LAs（纳米比亚国家电力公司，各级市电和省电），主要工程范围涉及中低压线路传输改造工程、农村电力改造工程等。', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('341', '61', 'INHE-0500', '2017-06-13 23:33:39', '2017-06-14 13:26:38', 'khxx20170613308/Baltazar Fernandes & Moreira,lda\r\n\r\n', 'khxx20170613308', 'Baltazar Fernandes and Moreira,lda', 'BFM', '欧洲', '葡萄牙', 'www.bfm-brg.pt\r\r\n', 'Rua Do Arinho lt1 B Sequeira\r\r\n4705-629 Braga\r\r\n', '1.成立于2001年，葡萄牙电力设备经销商和贸易商，主要的业务范围在安哥拉等葡语国家，电力设备经验丰富，在葡语国家由其是安哥拉有丰富的供货记录和经验；', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('342', '61', 'INHE-0580', '2017-06-20 09:08:38', '2017-06-20 10:18:31', 'khxx20170620309/myDompet ', 'khxx20170620309', 'myDompet', '', '亚洲', '新加坡', 'https://mydompet.com\r\n', 'JTC Launchpad, Singapore\r\r\r\n', '客户主要业务是电子化付款平台，旨在改变现金付款和银行账户付款的方式。终端用户通过持有客户开发的扫码平台，或划账平台，直接进行付款。业务涉及食品商店，机场，书店，学校，智能用电等领域。', '刘前', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('343', '60', 'INHE-0549', '2017-06-23 07:08:14', '2017-06-23 08:33:58', 'khxx20170623311/Agence Malienne pour le Développement de l`Energie Domestique et l`Electrification Rurale\r\n', 'khxx20170623311', 'Agence Malienne pour le Développement de l`Energie Domestique et l`Electrification Rurale', 'AMADER', '非洲', '马里', 'wwww.amadermali.net', 'Colline de Badalabougou,Immeuble n°2 de l\'ex-CRES, Bamako, Mali', '马里家庭能源和农村电气化发展机构，成立于2013年5月。该机构的主要任务是家庭能源消耗的控制和农村和郊区通电发展。', '王秀明', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('344', '61', 'INHE-0642', '2017-06-29 10:45:26', '2017-06-30 08:40:14', 'khxx20170629313/MOJAB For Technilogy * Engineering ', 'khxx20170629313', 'MOJAB For TECHNOLOGY * ENGINEERING', '', '亚洲', '约旦', 'http://www.mojab.net', 'Zeyad Dabbas Biulding # 19, Office # 107\r\nAbdulla Ibn Rawaha Street,\r\nAl Rabieh\r\nAmman-Jordan\r\n', '约旦首都安曼的一家当地公司，主要经营的是一些和电力行业相关的二次设备（仪表），自动化系统，马达，驱动和中低压配电设备（开关柜，断路器，避雷器和变压器），产品非常杂，应该是主要作为来自伊拉克首都巴格达和叙利亚首都大马士革的两家公司的代理商，并且和其他国际公司也有过代理业务。 此公司在约旦叙利亚伊拉克都有客户，并且和约旦发电公司（CEGCO, SEPGCO）和输配电公司（NEPCO ,JEPCO ,EDCO, IDECO）有过多次合作关系。', '潘正豪(James)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('345', '61', 'INHE-0432', '2017-07-04 01:21:58', '2017-07-04 08:49:47', 'khxx20170704315/Mr.Alfred', 'khxx20170704315', 'Mr.Alfred', 'AK', '非洲', '肯尼亚', 'N/A', 'Nairobi,Kenya', '客户为肯尼亚电力公司KPLC的员工。现希望个人直接从银河采购部分产品。', '谭东羊(Timon)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('346', '61', 'INHE-0374', '2017-07-04 05:22:18', '2017-07-04 15:02:36', 'khxx20170704316/GEEC', 'khxx20170704316', 'GLOBAL ENGINEERING ENERGY and CONSTRUCTION', 'GEEC', '非洲', '突尼斯', 'www.geec.tn', 'Passage du lac Maracaibo \r\nBalbina, Résidence les Dauphins\r\nBloc B1 les berges du Lac', '突尼斯智能能源智能家居公司，主要代理欧洲意大利比利时智能用电管理系统（针对公司等大客户），智能家居（针对家庭），总部在突尼斯，在北非阿尔及利亚、利比亚、摩洛哥、西非科特迪瓦有分公司。在电力公司以及能源部有不错关系基础，有建厂合作意愿。', '王子强', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('347', '61', 'INHE-0636', '2017-07-04 15:20:17', '2017-07-04 15:33:31', 'khxx20170704317/Alfred Mwangi', 'khxx20170704317', 'Alfred Mwangi', 'AK', '非洲', '肯尼亚', '', 'Nairobi, Kenya', 'Alfred Mwangi为KPLC员工，职位为实验室LPU测试工程师，在肯尼亚与乌干达都有比较广的人脉，与银河业务以及银河在肯尼亚的代理都建立了比较深厚的友谊。本次采购为\rAlfred Mwangi个人采购，所以无法提供公司名称。\r\n\r\r\n', '倪明杰', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('348', '60', 'INHE-0560', '2017-07-05 10:37:30', '2017-07-05 10:46:18', 'khxx20170705318/\"ADD-Energy\" LLC', 'khxx20170705318', '\"ADD-Energy\" LLC', '\"ADD-Energy\" ', '欧洲', '乌克兰', 'http://www.add-energy.com/', '03179, г. Киев, Брест-Литовское шоссе 8А, ООО \"АДД-Энергия\"			\r\n', '乌克兰add-energy公司是乌克兰境内的一家专业从事表计产品销售业务的公司，该公司为ADD-Grup公司在乌克兰的唯一经销商，成立于1999年，主要为乌克兰境内用户供应电力及提供能源计量解决方案，拥有ADDAX（ADDAX IMS）计量系统.add-energy公司在乌克兰的客户主要为电力公司，且拥有自己的服务中心，用以支持其产品及设备。现与我司正在商讨合作事宜，方向为在乌克兰大力推进预付费系统项目。\r\r\n', '李美娇', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
