INSERT INTO `inhe_customer_data` VALUES ('352', '60', 'INHE-0601', '2017-07-19 11:02:36', '2017-07-19 11:17:36', 'khxx20170719325/Intelligent Metering Systems (Pvt) Ltd\r\n', 'khxx20170719325', 'Intelligent Metering Systems (Pvt) Ltd', 'Intelligent Metering', '亚洲', '巴基斯坦', '', '\r\r24-Km Multan Road, Mohlanwal, Lahore\r\r\n\r\n', 'Intelligent Metering Systems是巴基斯坦拉合尔一家实力雄厚的智能电表制造商，拥有自有的电表工厂。\r\n\r\r\nIntelligent Metering Systems (Pvt) Ltd是WAPDA和LESCO等巴基斯坦电力主管部门和电力公司的认证电表供应商，有长期的供货记录和良好的客户关系。', '常一琳', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('353', '61', 'INHE-0500', '2017-07-21 08:42:07', '2017-07-21 08:51:33', 'khxx20170721326/Meter Mate Prepaid Electric Meters cc', 'khxx20170721326', 'Meter Mate Prepaid Electric Meters cc', 'MMP', '非洲', '南非', 'www.metermate.co.za\r\n', '133 Jan Smuts Avenue，Parkwood，Johannesburg，2193，Gauteng，South Africa', '1.南非Submeter业务供应商，其主要的客户为当地分表业务私人主体，如房东，私人公司，写字楼和其他商业机构，成立时间较早，目前年均分表业务在1.5万台左右；\r\r\n2.2012年至2013年有直接从业务2部林丽旋处购买过单相BS代码表1000台左右，现在重新联系上谈分表业务的合作；\r\r\n', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('354', '61', 'INHE-0091', '2017-07-25 17:30:26', '2017-07-25 17:50:40', 'khxx20170725327/Enrochem Pte Ltd\r\n', 'khxx20170725327', 'Enrochem Pte Ltd', 'EPL', '亚洲', '新加坡', '', 'Reg Add: 10 Anson Road #22-02 International Plaza Singapore 079903\r\nBilling Add: UE BizHub Central, 12 Ang mo Kio Street 64, Block A, #03-04, Singapore 569088', 'IOT项目客户新注册公司，专门做智能计量和电能管理服务。之后使用新公司与银河交易。', '林丽璇', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
