INSERT INTO `inhe_customer_data` VALUES ('357', '61', 'INHE-0625', '2017-08-02 09:51:16', '2017-08-02 10:13:18', 'khxx20170802333/Green World Solutions', 'khxx20170802333', 'Green World Solutions', 'Green World Solutions', '欧洲', '英国', 'http://www.greenworldsolutions.co.uk/\r\n', 'Green World Solutions Ltd 12 Forest Road, Southport, PR8 6ST	\r\r\n', 'Green World Solutions 是一家位于英国的能源监控系统方案公司，也做EPC工程,隶属于Bryden capital Group集团；\r\r\r\r\r\r\r\nGreen World Solutions 与英国能源公司和电力公司有合作，涉及电，水，气，热，对电表有需求；                                \r\r该公司最近的项目需要四表合一的Wireless M-Bus 单相及三相CT接入电表,客户对我们的Wireless M-Bus单相模块表（MID），三相CT接入Wireless M-Bus模块表(MID)，以及我们的split-core CT都很感兴趣，称赞我们的产品很好，客户最近项目的需求量单相表大约1000（MID），150/5，CT 大约1000个。', '古丽', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('358', '60', 'INHE-0549', '2017-08-07 21:44:11', '2017-08-08 08:36:41', 'khxx20170808335/Comptoir Commercial de Bamako SARL', 'khxx20170808335', 'Comptoir Commercial de Bamako SARL', 'CCB Sarl', '非洲', '马里', '', 'Niamakoro Cité Unicef face à c?té de la station Total qui fait face au Lycée Tigana Daliba(Mali)\r\r\n', 'Comptoir Commercial de Bamako是一家有限责任公司(S.A.RL.)，有一百万西非法郎资本。\r\r\r\r\r\r\r\r\n该公司建立于2019年11月15日，的注册号为: MaBko2010 B.5096。该公司营业范围涉及各个领域，是一家提供一般性贸易服务（例如信息材料和办公材料供货，机械零部件，IT服务，食品的供应，汽车销售，房产，代理，培训，土建，咨询，进出口等）的公司。Comptoir Commercial Bamako提供高质量产品和服务,具有满足客户的所有内部和国际资源。他和以上各个领域的公司（比如BRAMALI，FITINA SA，CONSEIL PATRONAT，SOMAGEP，EDM等）保持着商业联系。', '王秀明', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
