INSERT INTO `inhe_customer_data` VALUES ('360', '66', 'INHE-0635', '2017-08-18 09:22:10', '2017-08-18 09:54:58', 'khxx20170818338/KMA COMPANY LIBYAN', 'khxx20170818338', 'Intertouch Systems Computer Ltd', 'Intertouch', '非洲', '利比亚', 'http://www.intertouch.ae/', 'Zayed the first St, Khalidiah, Abu Dhabi \r\n P.O.Box 129804 \r\n', 'Intertouch为迪拜当地一家提供电脑等电子产品及交互系统的公司，利比亚当地合作伙伴KMA company,主要为利比亚和叙利亚的石油和电力公司提供电子产品和系统', '李明芳', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('361', '61', 'INHE-0434', '2017-08-21 09:44:55', '2017-08-21 10:04:21', 'khxx20170821339/LIBANGO HOLDINGS, INC.\r\n', 'khxx20170821339', 'LIBANGO HOLDINGS, INC.', 'LIBANGO', '非洲', '利比里亚', '', '11th Street, Payne Ave. Sinkor, Monrovia, Liberia\r\r\n', '1. LIBANGO HOLDINGS, INC.为本地公司，公司CEO为Mr. Joseph Crayton\r\r\r\r\r\n2. 该公司是本地合资公司，其中AZA市场的Jose在LIBANGO控股\r\r\r\r\r\n3. 该公司的成立主要经营和当地电力公司LEC(Liberia Electricity Corporation)的生意\r\r\r\r\r\n4. 该公司CEO和电力公司二把手Thomas Zailee Gonkerwon关系不错，能多次安排一起去其见面\r\r\r\r\r\n5. 据悉该公司CEO和美国千禧年组织在当地的分支机构(MCA-L)的CEO是发小\r\r\r\r\r\n6. 该公司CEO和另一股东Alexander Kashif Garley在本地还有一个生产螺钉的工厂，且有计划在本地搭建一个钢铁厂', '钟云林(Andy)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('362', '61', 'INHE-0518', '2017-08-30 15:08:13', '2017-08-30 15:32:37', 'khxx20170830340/中机国能电力工程有限公司杭州分公司', 'khxx20170830340', '中机国能电力工程有限公司杭州分公司', 'CSEEC', '亚洲', '中国', 'www.cseec.cn', '中国浙江省杭州市滨盛路1786号12楼', '中机国能电力工程有限公司杭州分公司隶属于国际集团，在刚果布进行多年电力项目承包，并在刚布建有水泥电线杆厂，与电力公司及能源部合作密切。目前该公司有与我司合作的想法，有意愿做我司在刚的代理。并现该公司获得刚果布一个PEC配网项目，其中有5000台电表的需求，希望我司', '熊璟', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('363', '60', 'INHE-0535', '2017-08-30 15:36:58', '2017-08-30 16:36:33', 'khxx20170830341/DSL Engineering', 'khxx20170830341', 'Tsogatec (Pty) Ltd.', 'DSL', '非洲', '南非', '无', '210 Amarand Avenue,\r\r\nDSL Engineering,\r\r\nMenlyn Maine-Regus Business Centre,\r\r\nWaterkloof Glen Ext 2\r\r\nPretoria, 0180\r\r\n', '客户为ZAR项目前负责人，是一家B-BBEE性质的服务供应商，主要参与电力公司及一些地方市政府的电表项目和机会挖掘，服务包括：电费收入保护，电能管理，电表安装和培训等。', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('364', '66', 'INHE-0635', '2017-09-01 09:54:13', '2017-09-01 10:07:51', 'ARALCA, S.A', '', 'ARALCA, S.A', 'ARALCA', '北美洲', '多米尼加', 'http://aralca.com.do/contacto.html', 'C/Nicolás de Bari No. 6, La Esperilla, ', '1990年成立的多米尼加工程和建筑公司。在多米尼加执行了诸多电力工程类项目，有丰富的电力工程项目招投标项目经验，熟悉电力公司流程，与本国三家电力公司合作经验丰富。', '李明芳', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('365', '60', 'INHE-0535', '2017-09-07 16:00:02', '2017-09-07 16:25:07', 'khxx20170907343/Capital Power Systems Ltd.\r\n', 'khxx20170907343', 'Capital Power Systems Ltd.', 'CP', '亚洲', '印度', 'capitalpowers.com \r\n', 'B-40,sector-4,Noida,Uttar Pradesh -201301, India\r\r\n', 'Capital为印度本地一家行业内制造商，产品包括电表，水表和气表，致力于预付费计量方案，交钥匙计量方案，端到端AMI方案。从单纯的制造到开发智能仪表，量身定制的端到端AMI解决方案，交钥匙工程和OEM，为其不断扩大客户群。拥有ISO9001，ISO14001,ISO27001，OHAS18001,印度BIS证书，CMMI LEVEL III 认证，NABL认证实验室，自动化注塑厂，高速全自动SMT生产线，内部工具室和3D打印，传送带装配，校准，测试和包装线。客户涵盖印度本地各大大小小电力公司，房地产开发商，公营事业和turnkey总承包商。', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('366', '60', 'INHE-0535', '2017-09-07 17:18:04', '2017-09-07 17:41:35', 'khxx20170907344/Cosmos International Ltd.\r\n', 'khxx20170907344', 'Cosmos International Ltd.', 'CG', '亚洲', '印度', 'www.cosmosintl.com\r\n', 'B- 313 - 315, Somdutt Chamber-I，Bhikaji Cama Place.，New Delhi - (India)\r\r\n', 'Cosmos集团是印度领先的商业机构，业务范围包括进出口，国际招投标，金融和配电等。不同的专业部门由有资格和经验丰富的专业人员来管理。部门包括农业机械设备，配电和输电，太阳能和可再生能源，建筑设备，港口装卸设备，医疗保健诊断系统。该客户目前在Uttar Pradesh (U.P.)与Discoms 合作建立AMI智能电表项目以减少他们的损失、提高其效率和收入。\r\r\n', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('367', '61', 'INHE-0587', '2017-09-12 14:44:41', '2017-09-12 16:22:08', 'khxx20170912345/VBC Corporation', 'khxx20170912345', 'VBC Corporation', '非洲', '非洲', '莫桑比克', 'www.vbc.co.mz\r\n', 'Av. Julius Nyerere N. 1597, Maputo-Mozambique\r\r\r\n', 'VBC集团是一个莫桑比克公司，业务范围包括：通讯，电信，生物医疗和能源。\r该公司在当地承包过较多EPC工程\r，也承接过莫桑比克电力公司EDM的一些项目，与EDM关系良好。\r\r\n', '陆飞雨', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('368', '61', 'INHE-0228', '2017-09-12 16:27:49', '2017-09-12 16:41:18', 'khxx20170912346/metrima\r\n', 'khxx20170912346', 'Metrima AB', 'metrima', '欧洲', '瑞典', 'http://www.metrima.com/en/\r\n', 'Westmansgatan 37, SE-582 16 Link?ping\r\n', '瑞典的AMR系统供应商，在瑞典有批量供货。\r\nMetrima is a complete AMR (Automatic Meter Reading#FE54` smart metering) supplier with solid experience and know-how reflected in the company as a whole.\r\n\r\nWe offer one of the best systems on the market with solutions for communication and collection of measured data.\r\n\r\nOur central system MActor gives the customer the opportunity to use the most optimal means of communication. With MActor you as a customer get a reliable and cost efficient AMR concept - with the possibility to choose meter manufacturer.', '谭雯', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('369', '60', 'INHE-0535', '2017-09-14 08:27:22', '2017-09-14 08:42:50', 'khxx20170914348/Rasa Rayan Co., Ltd.', 'khxx20170914348', 'Rasa Rayan Co., Ltd.', 'RASA', '亚洲', '伊朗', 'http://www.rasarayan.co\r\n', '3rd Fl., No.6,10th Str., Val-fajr town,south Sheikh Bahaiee Ave.,Tehran-Iran\r\n', 'RASA是一家活跃于EPCF（工程，采购，建设和金融）和基础建设发展投资的知识型公司，专注于电信，电力和能源，石油天然气和石油化工、房地产与酒店，铁路和公路，矿业和工业，贸易和金融领域。Rasa之前是EDMI的代理，Rasa正考虑并准备放弃EDMI选择新的合作伙伴，原因是Rasa对于EDMI管理层频换以及管理层决策，市场策略的混乱导致其在以往投标过程中遇到了相当多的问题以及麻烦，Rasa对此表示很不满；其在过去做EDMI的代理期间，积累了大量的客户资源，和银河合作，可以利用其现有的资源直接进行销售和投标.\r\r\n', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('370', '66', 'JXINHE-2559', '2017-09-16 04:11:37', '2017-09-18 08:42:43', 'khxx20170916349/NARENDRA NIRMAN SEWA (P.) LTD', 'khxx20170916349', 'NARENDRA NIRMAN SEWA (P.) LTD', 'NARENDRA', '亚洲', '尼泊尔', '', 'Kalanki Kathmandu,Nepal', '公司主营变压器和EPC项目', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('371', '61', 'INHE-0500', '2017-09-18 08:30:38', '2017-09-18 08:43:01', 'khxx20170918350/GSA Ltd\r\n', 'khxx20170918350', 'GSA Ltd', 'GSA', '欧洲', '阿尔巴尼亚', 'www.gsa.al\r\n', 'Rr. Ibrahim Rugova, Pallati 64/1,Tirana,Albania\r\r\n', '1、公司成立历史悠久，较专业的工程总包公司，当地规模较大，主要行业为：\r\r\r\r\r\n1) The trade of energy & electric/electronic equipment电力、电力设备的经销贸易为主；\r\r\r\r\r\n2) Engineering in the Project Implementation (Power projects, Metering and Process Control Systems) and in the application of new technologies.电力工程和自动化工程总包商；\r\r\r\r\r\n3）2016年开始和中国公司在首都地拉那合作开办氯化冶金工厂。\r\r\r\n2、据其网站信息：阿尔巴尼亚40%的电表由其提供\r\r\r，当前电表合作厂商为EDMI，只要集中在CT表。\r\r\n', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('372', '66', 'INHE-0635', '2017-09-19 10:04:00', '2017-09-19 10:23:32', 'khxx20170919351/CAM Servicios del Peru S.A.', 'khxx20170919351', 'CAM Servicios del Peru S.A.', 'CAM PERU ', '南美洲', '秘鲁', 'http://www.cam-la.com/quienes-somos/nuestra-empresa', 'Av. Maquinarias Nro 2977 - Lima', '电力工程服务和通讯工程服务提供商，拉美跨国大型公司，在秘鲁，智利，哥伦比亚都有分公司。 1998年开始在秘鲁位各个电力公司提供工程实施，安装，维护等服务。目前秘鲁智能电表安装计划已经写入法律，CAM peru 有意参与智能电表类项目运作。Cam peru 主要客户为秘鲁20个电力公司种比较大的6个有Edenor, Enel , Luz de sur, Hidrandina,Enose, Electro Oriente, Eletro Norte。 ', '李明芳', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('373', '61', 'INHE-0662', '2017-09-27 15:27:33', '2017-09-27 16:12:48', 'khxx20170927352/INTRACOM TELECOM', 'khxx20170927352', 'INTRACOM TELECOM', 'INTRACOM', '欧洲', '希腊', 'www.intracom-telecom.com', 'Building A1, 1st Floor\r\nBuilding A1, 1st Floor 19.7 km Markopoulou Ave.\r\n19002 Peania, Athens, Greece', '希腊最大的电信设备和方案服务提供商，希腊智能电网市场的主要玩家之一。服务市场涉及欧洲，中东和非洲等，在南非和摩洛哥均有子公司。', '陈丽', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('374', '61', 'INHE-0662', '2017-09-28 16:22:44', '2017-09-29 13:31:24', 'khxx20170928353/Saturn Pyro Sdn Bhd', 'khxx20170928353', 'Saturn Pyro Sdn Bhd', '', '亚洲', '马来西亚', 'www.saturnpyro.com', '44 & 44A, Jalan Palma Rafis 1, Taman Dato Chellam, 81800 Ulu Tiram, Johor, Malaysia\r\r\n', 'Saturn Pyro是马来西亚绿色技术解决方案的提供商，产品和方案包括电能表，气表和水表，EnMS解决方案，Scada电气基础设施监控系统等，在新加坡，印度均有办事处。西班牙著名表厂Circutor是其供应商，已经合作了六年。', '陈丽', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('375', '61', 'INHE-0642', '2017-09-29 14:52:48', '2017-09-29 16:38:03', 'khxx20170929354/AISAINFO INTERNATIONAL', 'khxx20170929354', 'AISAINFO INTERNATIONAL', '', '亚洲', '中国', 'http://www.asiainfo.com.cn/index.html', '北京市海淀区中关村软件园二期西北旺东路10号院亚信总部研发中心大厦 　100193', '客户公司名称为亚信国际，是亚信科技旗下的一家海外业务子公司。从客户官网上可以看出，客户公司主营产业互联网包括软件产品以及定制化服务，并且业务扩展到金融，政府，医疗，电力等多个行业, 且其公司除中国市场外，还为丹麦，匈牙利，印度等多个国家提供专业化软件与服务。据客户告知，之前在尼泊尔没有做过电表类的项目，但是有客户关系(据客户告知，客户公司的关系可以直通电力公司顶层人员)。', '潘正豪(James)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('376', '66', 'INHE-0635', '2017-09-29 17:15:42', '2017-09-29 17:23:02', 'khxx20170929355/AL MEHWAR AL THABIT', 'khxx20170929355', 'AL MEHWAR AL THABIT', '', '非洲', '利比亚', '', 'Soug Giuma, Ashat Road, Tripoli, Libya', '利比亚电力公司Gecol下属子公司', '李明芳', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('377', '61', 'INHE-0374', '2017-10-05 03:48:20', '2017-10-09 16:46:30', 'khxx20171005356/Inter Global Technology Services', 'khxx20171005356', 'Inter Global Technology Services', 'IGTS', '非洲', '塞内加尔', '', '', '电信代理公司，与SN电力公司总经理关系不错。', '王子强', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('378', '60', 'INHE-0601', '2017-10-09 10:40:11', '2017-10-09 10:57:46', 'khxx20171009357/INTERLINK COMMUNICATION PUBLIC COMPANY LIMITED\r\n', 'khxx20171009357', 'INTERLINK COMMUNICATION PUBLIC COMPANY LIMITED', 'Interlink', '亚洲', '泰国', 'http://www.interlink.co.th/index.php\r\n', '48 Interlink Building, soi Rung-Reung, Ratchadaphisek Rd.,Samsennok, HuayKhwang , Bangkok 10310, Kingdom of Thailand \r\r\n', 'Interlink成立于1995年3月9日，主要从事布线系统业务，并且是美国AMP品牌和仓储的授权经销商。公司的业务主要集中在布线和电信业务上，以获得更多的市场份额，并实现快速增长。 Interlink Communication PLC是泰国第一家引入LAN电缆技术的公司，目前在泰国是非常受欢迎和知名度最高的公司。本公司经营信息通信技术产业（ICT），其主要业务涉及电脑及电讯布线，目前Interlink是包括品牌LINK和COMMSCOPE在内的海外电缆和设备制造商指定的泰国授权经销商。\r\r\r\r\r\r\r\r\r\r\r\r\r\n', '常一琳', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('379', '60', 'INHE-0549', '2017-10-10 16:33:25', '2017-10-11 08:34:42', 'khxx20171010358/OCP Group S.A.', 'khxx20171010358', 'OCP Group S.A.', 'OCP', '非洲', '摩洛哥', 'http://www.ocpgroup.ma/', '2-4, Rue Al Abtal - Hay Erraha - 20200 Casablanca Morocco\r\r\r\r\n', '作为磷酸盐和磷酸盐衍生物市场的全球领导者，OCP自1920年成立以来一直是国际市场的重要参与者。OCP整合在整个磷酸盐价值链中，提取和销售磷酸盐及其衍生物，磷酸和肥料，是世界上最大的磷酸盐岩和磷酸盐出口国，也是世界上最大的化肥生产国之一。', '王秀明', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('380', '61', 'INHE-0662', '2017-10-11 09:46:06', '2017-10-11 10:06:29', 'khxx20171011359/ingtech GmbH', 'khxx20171011359', 'ingtech GmbH', '', '欧洲', '德国', 'www.tecing.de', ' Frankfurt am Main\r\r\nHandelsregister Frankfurt am Main, HRB 98904\r\r\nGesch?ftsführer. Dr. Heithem Matti\r\r\n', '德国公司，IT起家，目前公司提供业务包括咨询，工程管理，金融服务，运输支持以及当地的法律服务等,为行业提供解决方案，特别是在项目困难阶段需要寻找非常规解决方案时。', '陈丽', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('381', '61', 'INHE-0228', '2017-10-12 16:09:01', '2017-10-12 17:34:44', 'khxx20171012361/OCEA Smart Building', 'khxx20171012361', 'OCEA Smart Building', 'OCEA', '欧洲', '法国', 'www.ocea-smart-building.fr\r\n', '1 Place Victor Hugo\r\r\r\n92400 COURBEVOIE\rF，France\r\r\n\r\r\n', 'Ocea Smart Building is proposing a unique solution to building manager and renter in collective habitat.Target is to warranty a better control of the energy expense, globally as well as individually, and thus a water and energy consumption reduction.\r\nThe easy to use Ocea Smart Building solution allowes traceability via smart meters, individual invoicing and data analysis. \r\nThe increasing demand leads Ocea Smart Building to adapt its technical solution to use more and more Remote metering readings.\r\nThis document will present the functional specifications required to the future Remote metering reading solution from Ocea Smart Building.\r\n', '谭雯', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('382', '66', 'INHE-0635', '2017-10-13 14:49:22', '2017-10-13 15:00:40', 'khxx20171013362/SILVATECH S.A', 'khxx20171013362', 'SILVATECH S.A', 'Silvatech', '南美洲', '厄瓜多尔', 'http://www.silvatech.com.ec/soluciones-de-medicioacuten-elster.html', 'Av. José Vicente Trujillo 413 y Bogota,Guayaguil ', '当地重要的电表和电力计量方案供应商，多年间多次中标当地国家电力公司电表招标项目。目前代理Elster和ABB产品。', '李明芳', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
