INSERT INTO `inhe_customer_data` VALUES ('385', '60', 'INHE-0560', '2017-10-23 11:36:17', '2017-10-23 11:50:49', 'khxx20171023366/ГП “Новатор”', 'khxx20171023366', 'ГП “Новатор”', 'ГП “Новатор”', '欧洲', '乌克兰', 'http://www.novator-tm.com/', '29018, Украина, г. Хмельницкий, ул. Тернопольская, 17\r\r\nГП “Новатор”', 'ГП “Новатор”是乌克兰的一家现代国有企业，其旗下拥有ГП “Новатор”赫梅利尼茨基无线电工程厂，成立于1966年，是苏联无线电工业部的结构，是航空航天工业生产无线电电子，雷达，无线电导航和其他设备的企业之一。自身也生产电表水表及燃气表，以及集抄系统，在乌克兰市场上拥有一定的市场份额，未来两年该公司欲大力发展表计行业，该公司将在乌克兰大量进口电表产品。', '李美娇', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
