INSERT INTO `inhe_customer_data` VALUES ('389', '61', 'INHE-0642', '2017-11-16 20:29:42', '2017-11-17 10:05:23', 'khxx20171116371/深圳市华力特电气有限公司', 'khxx20171116371', '深圳市华力特电气有限公司', '', '非洲', '加纳', 'http://www.chinafarad.com/cn/index.aspx', '广东省深圳市光明新区.光明高新技术产业园子塘片区。同观路转二号路。华力特大厦', '深圳市华力特电气有限公司成立于1994年，注册资金4.8亿元人民币，是深圳市首批国家级高新技术企业，软件企业，民营骨干领军企业以及自主创新行业龙头企业。华力特电气业务主要包括城市轨道交通，机场，港口，金属冶炼，大型建筑，海外电力等领域。目前华力特已经和加纳国家电力公司，安哥拉国家电网公司有过业务来往，并且有不少EPC项目经验。', '潘正豪(James)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('390', '60', 'INHE-0535', '2017-11-17 10:09:33', '2017-11-17 10:16:43', 'khxx20171117372/Larsen & Toubro Limited\r\n', 'khxx20171117372', 'Larsen & Toubro Limited', 'L&T', '亚洲', '印度', '\r\nwww.larsentoubro.com	\r\n', 'L&T House, Narottam Morarjee Marg, ballard Estate, Mumbai 400 001, Maharashtra, India\r\r\n', 'Larsen & Toubro是一个从事技术、工程、建筑、制造业和金融服务等全球业务的大集团。帮助解决全球范围内30多个国家的客户对关键领域的关键需求——碳氢化合物、基础设施、电力、加工工业和国防。\r\nL&T涉及经济的核心、高影响力部门，综合能力跨越了“设计交付”的整个范围。70多年的发展强大，以客户为中心的方法和不断追求世界级的质量，拥有丰富的专业技术，工程，建筑，基础设施项目和制造业经验，并在主要业务领域保持前列。\r\n', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
