INSERT INTO `inhe_customer_data` VALUES ('392', '61', 'INHE-0642', '2017-11-20 09:22:02', '2017-11-20 13:29:52', 'khxx20171120374/Dovetail Energy,Inc', 'khxx20171120374', 'Dovetail Energy,Inc', '', '非洲', '利比里亚', '', '11th Street, Payne Ave. Sinkor, Monrovia, Liberia', '1. Dovetail Energy, Inc.是 Joseph Crayton 为了摆脱安哥拉客户Jose 而设立的另外一家公司，该公司主要由Joseph Crayton 以及 Alexander Kashif Garlety 掌控。2.Dovetail Energy,Inc.将会代替 LIBANGO HOLDINGS, INC.在AZL市场与我司进行商业来往 3. 该公司的成立主要经营和当地电力公司LEC(Liberia Electricity Corporation)的生意 4. 该公司CEO和电力公司二把手Thomas Zailee Gonkerwon关系不错，能多次安排一起去其见面 5. 据悉该公司CEO和美国千禧年组织在当地的分支机构(MCA-L)的CEO是发小 6. 该公司CEO和另一股东Alexander Kashif Garley在本地还有一个生产螺钉的工厂，且准备分包一部分利比里亚大型钢铁厂的建设工作。								\r\n														\r\n', '潘正豪(James)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
