INSERT INTO `inhe_customer_data` VALUES ('395', '61', 'INHE-0434', '2017-12-01 01:27:08', '2017-12-01 08:33:44', 'khxx20171201378/MOL CON A ENGINEERING PLC', 'khxx20171201378', 'MOL CON A ENGINEERING PLC', 'MOL CON', '非洲', '埃塞俄比亚', '', 'Bole, Addis Ababa, Ethiopia', '1. 此公司总经理是一名女士也是EEP工程师，和EEU的配电老大关系好，之前一起共事过；\r\r\r\n2. 此公司是新成立的公司，之前此人在其丈夫公司上班，其丈夫公司MAG Engineering and Business PLC；\r\r\r\n3. 该客户通过在EEU了解到的信息，得知后续智能表采购会上量，前提是智能表本地生产；\r\r\r\n4. 该客户有意投资本地建厂', '钟云林(Andy)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('396', '61', 'INHE-0228', '2017-12-04 10:54:51', '2017-12-04 11:12:21', 'khxx20171204379/Jacek Kozbial\r\n', 'khxx20171204379', 'Jacek Kozbial', 'Jacek Kozbial\r', '欧洲', '波兰', '无', '波兰', '客户在波兰从1990年开始，为电力公司设计和实施AMI/AMR/智能电网项目，对各类集抄方案都比较熟悉。询盘客户。', '谭雯', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('397', '61', 'INHE-0434', '2017-12-10 22:45:43', '2017-12-11 08:57:16', 'khxx20171210380/RAYMAN PLC', 'khxx20171210380', 'RAYMAN PLC', 'RAYMAN', '非洲', '埃塞俄比亚', '', 'Global Insurance  ldg., rm No8, Addis Ababa, Ethiopia', '1） R 公司是一家有店铺的电气经销商，主要经营断路器，简单的 DIN 分表，目测产品全部是自 己品牌。此公司有两家门店，做批发和零售，也做投标和代理。该公司据说有一支 5 人 的技术团队；有一个 800 平的仓库（据说原先计划组装手机卖）。 2） 拜访的是 R 公司的老板 F 和业\r\r\n务经理 A。沟通来看，F 清楚本地的税费（关税=高达 100%， 增值税=15%，所得税=高达 35%）。从开车，吃饭和家庭成员数量来看，F 估计有钱：开车是 奔驰，谈吐淡定，思路清晰。业务经理 A 是电气专业， 沟通来看熟悉配电业务（对银河 BOX300，LPU，DTMS，DA 和变电站方案感觉很兴奋，直接 表示自己可以拿到标书草稿，可以运作银河技术点进标书；有朋友，有办法）。另外，很有 意思的 F 和 R 去过深圳创银，说某项目代理创银（有 2016 年去创银的照片），一切都弄好， 创银最后一刻不开保函放弃了；导致他们对创银印象不好。 3） F 和我方洽谈，对我方要求投资 25 万美元建厂设备，表现的比较淡定。只是提到，一旦拿 单供货，需要银河做些支持。 4） 对于我方安排的任务，R 公司算是比较快，一天之后基本确定 ZEP 不可能限定为：制造商才 能投标；但 EEP 实际只会选择厂商中标。对于要求必须在截标前提交样机，表示内线人员需 要征求高层领导意见。就 ZEP 而言，知道 EEP 第一次做智能电网业务，没经验，很谨慎，会 设立专门委员会评标（2 个技术+2 个董事会成员+采购+其它）。ZEP 标书说是西班牙和意大 利公司写的规格。对于参与投标的人，说目前为止大概 15 个公司，已经拿到名单，会发给 我们。同时，会发给我们 EEP 和 EEU 的组织架构图。ZEP 而言，清楚负责的部门是工程技术 部（隶属项目部）。 5） R 公司业务经理对电力业务脑子转的很快。在了解我方 SRM06 待执行的时候，已经想法比较 多，考虑商业楼宇分表业务和服务（他们目前经销简单 DIN 表）。 \r\r\r\r\n \r\r\r\r\n总结：R 公司是电气行业企业，有一定经济基础（可以出资 25 万美元，有厂房），团队上心（业务经理 懂输配电，知道技术运作），判断有一定客户关系。从言谈气质判断，老板有一定实力，比较清和；业 务经理狡猾，但懂产品方案和业务运作。客户关系和合作条件待判断沟通，验证（ZEP 说是要 4%的佣金， 算是合理）', '钟云林(Andy)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
