INSERT INTO `inhe_customer_data` VALUES ('399', '66', 'INHE-0634', '2017-12-20 14:07:34', '2017-12-20 14:13:41', 'khxx20171220382/Alpha Power Engineering CO., ltd', 'khxx20171220382', 'Alpha Power Engineering CO., ltd', 'ALPHA', '亚洲', '缅甸', 'http://alphapowerengineering.com/			\r\n', 'No. 16, Yoedayar Street, Ward 5, 9th Mile, Mayangone Township, Yangon, Myanmar', '阿尔法电力工程有限公司是缅甸仰光一家EPC公司，成立于2010年，有多次参与电力公司投标经验，当地关系网络相对成熟。是LS（智能能源）, CEWE（电力监测仪器和传感器和电力管理系统）, Secure,（电力监控） Commax（智能家居）等品牌分销商。产品：供应245kV的分站设备（气体断路器，断路开关，电流互感器，电压互感器，避雷器和电力变压器）；245kV ACSR，AAC，HDBC，和相关配件等。供应控制面板，电池组和充电器、电力线载波（PLCC设备）、电源线和电缆附件（400V至66kV）XLPE，SWA，AWA，Cu，PVC端接套件和接头，保护继电器和电表。官网：http://alphapowerengineering.com/								\r\n', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
