INSERT INTO `inhe_customer_data` VALUES ('401', '60', 'INHE-0560', '2018-01-04 09:48:25', '2018-01-04 10:07:53', 'khxx20180104385/OOO \"Shinavanda-Savdo\" ', 'khxx20180104385', 'OOO \"Shinavanda-Savdo\"', 'OOO \"Shinavanda-Savdo\" \r\r\n', '亚洲', '乌兹别克斯坦', 'www.schetchik.Uz', ' Узбекистан, г. Ташкент, улица Мухтара Ашрафи, 34, 100074\r\n', 'OOO \"Shinavanda-Savdo\"公司是一家主要从事电力设备供应及销售的企业#FE54`\r经营产品包括电能表，水表，气表，电缆，电流互感器等。在乌兹别克斯坦拥有强大的分销渠道及经营门店，用户种类多涉及终端用户，工业用户，商业用户及电力公司，且需求稳定。该公司现在其国内大力推广宣传其产品，发展其实力。\r\r\r\r\n\r\r\r\r\n', '李美娇', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('402', '66', 'JXINHE-2559', '2018-01-04 15:17:33', '2018-01-04 15:34:55', 'khxx20180104386/RELIANCE CORPORATION (PVT) LTD', 'khxx20180104386', 'RELIANCE CORPORATION (PVT) LTD', 'RELIANCE', '亚洲', '巴基斯坦', 'http://www.reliancecorp.pk/', 'HOUSE NO.54, MIAN MAGRALLA ROAD, F7/2, ISLAMABAD', '专业国际项目承包商，提供项目投标，管理和运作服务，拥有一定的政治资源。', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('403', '60', 'INHE-0560', '2018-01-08 15:41:38', '2018-01-08 16:34:03', 'khxx20180108387/Iskraemeco d.d.', 'khxx20180108387', 'Iskraemeco d.d.', 'Iskra', '欧洲', '斯洛文尼亚', 'www.iskraemeco.si', 'Savska loka 4\r\r\n4000 Kranj, Slovenia', 'Iskraemeco 成立于1945年，主要从事先进表计计量产品的设计与生产并拥有强大的研发实力，现已经在全球范围内安装了7500万台电表，其产品种类齐全，包括表计产品，软件系统等，通信方案，其在欧洲表计市场上占有一定的市场份额，综合实力较强。2007年，Iskraemeco与Elsewedy Electric联手，进一步增强了其在欧洲表计市场上的实力。', '李美娇', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('404', '61', 'INHE-0578', '2018-01-10 11:33:18', '2018-01-10 13:39:46', 'khxx20180110389/MeterX Proprietary Limited\r\n', 'khxx20180110389', 'MeterX Proprietary Limited', 'Meter X', '非洲', '南非', 'http://www.meterx.co.za \r\r\r\r\n\r\r\r\n', 'Albion Spring Building, 183 Main Road, Rondebosch, Cape Town, South Africa', 'Meter X 主要业务为电表及抄表系统业务，为Solar Xgen （太阳能EPC工程公司）下属公司；主要配合Xgen公司业务进行电表业务。Xgen 及Meter X公司具有BBBEE资质，主要负责人为黑人，团队其他人员白人居多；均具有一定的电力行业从业经历。\r根据联系了解，Meter X公司具有较完备的生意模式，付款方式、结算条件较优；且在南非太阳能行业具有一定的口碑和能力，可以为后期其他业务（配电等）开拓储备一定的客户资源。', '覃湘君(June)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('405', '60', 'INHE-0680', '2018-01-16 10:44:55', '2018-01-16 10:54:07', 'khxx20180116390/MAV Trade Plus', 'khxx20180116390', 'MAV Trade Plus', 'MAV \r\r\n', '亚洲', '吉尔吉斯斯坦', '', 'Kulatov street 1a, Bishkek city,Republic of Kyrgyzstan\r\r\r\n', 'MAV是一家专业从事电缆，稳压器，开关，断路器，简单电表，表箱等贸易的快速增长企业。目前是俄罗斯‘’伊尔库茨克电缆”当地代理商，“托木斯克电缆”当地代理商，“电缆出口”当地代理商，中国“德力西电器有限公司”当地代理商。\r\n', '陈嘉豪', '国际业务1部', null, null, 'E', 'INHE');
