INSERT INTO `inhe_customer_data` VALUES ('407', '60', 'INHE-0680', '2018-01-19 11:42:48', '2018-01-19 11:46:55', 'khxx20180119392/ASMAN SERVIS\r\n', 'khxx20180119392', 'ASMAN SERVIS', 'ASMAN \r\r\n\r\n', '亚洲', '吉尔吉斯斯坦', '', 'Республика Кыргызстан, Жалад-Абад область, город Жалалабад, ул. Н.Айтматова 8\r\r\r\n', '此客户为我司在吉国南部两个电力公司即贾拉拉巴德电力公司和奥什电力公司的代理， 执行BY项目\r\r\n', '陈嘉豪', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('408', '60', 'INHE-0680', '2018-01-19 11:47:06', '2018-01-19 11:51:32', 'khxx20180119393/贾拉拉巴德电力\r\n', 'khxx20180119393', '贾拉拉巴德电力', '贾拉拉巴德电力\r\n', '亚洲', '吉尔吉斯斯坦', 'http://www.jae.kg/\r\n', '', '贾拉拉巴德电力总用户约20万，目前已经安装了3500台左右智能电表，对于我们关闭其AMI系统不满意，公司没有资金单独购买AMI系统；\r\n', '陈嘉豪', '国际业务1部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('409', '61', 'INHE-0440', '2018-01-21 05:07:44', '2018-01-22 08:07:08', 'khxx20180121394/INHEMETER (T) LIMITED ', 'khxx20180121394', 'INHEMETER (T) LIMITED', 'ITL', '非洲', '坦桑尼亚', 'www.inhemetertz.com', '  P.O.BOX 5998,DAR ES SALAAM,Tanzania', 'Africarriers Limited 和 INHEMETER (T) LIMITED 的实际控制人都是Mr. Fidahussein N. Rashid 98% 和Abraham Rajakil 2%。Africarriers投资ITL，银河参照双方的建厂合作协议，有条件授权ITL使用INHEMETER的商标和支持本地工厂建设。ITL是坦桑尼亚已知的第一家电表组装厂，主要业务是电表生产和销售，主要客户为TANESCO,REA,ZECO等。', '汤伟(Will)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('410', '61', 'INHE-0440', '2018-01-21 05:45:50', '2018-01-22 08:06:49', 'khxx20180121395/TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'khxx20180121395', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TANESCO', '非洲', '坦桑尼亚', 'http://www.tanesco.co.tz/', '\r\nUmeme Park, Morogoro Road - Ubungo,P.O. Box 9024, Dar Es Salaam, Tanzania.', '\r\nTANESCO是坦桑能源和矿产部下的半国营机构。公司涵盖了坦桑大陆的发电，输电，配电和售电，以及批量售电到桑给巴尔（ZECO）。TANESCO拥有坦桑境内大部分的发电，输电和配电设施。TANESCO目前用户数量约160万，每年采购约25万-30万台（包含单相智能预付费表，三相AMR预/后付费电表），预算金额约为2000万美元（DDP）价格条款。 \r\n', '汤伟(Will)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('411', '61', 'INHE-0500', '2018-01-29 08:45:24', '2018-01-29 09:08:05', 'khxx20180129396/Pre-Paid Mobile Vending Solutions cc\r\n', 'khxx20180129396', 'Pre-Paid Mobile Vending Solutions cc', 'PPM', '非洲', '纳米比亚', 'N/A', 'P.O.BOX 1482 Otjiwarongo,Windhoek,Namibia\r\r\r\n', '1.成立于2009年，纳米比亚本地中小型私营公司，主营业务为：纳米比亚第三方通讯服务和售电服务提供商，有ICT技术背景，之前和南非一家ICT公司Expertron合作过Airtime第三方通讯服务业务；\r\r\n2.BEE等级：公司所有权100%纳米比亚黑人，管理层100%纳米比亚黑人，等级较高（纳米比亚本地招标对BEE资质是强制性要求）；', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('412', '61', 'INHE-0500', '2018-01-29 09:20:59', '2018-01-29 09:43:26', 'khxx20180129397/Erongo Regional Electricity Distributor Company (Pty) Ltd\r\n', 'khxx20180129397', 'Erongo Regional Electricity Distributor Company (Pty) Ltd', 'ERONGO', '非洲', '纳米比亚', 'www.erongored.com\r\n', '91，Hage Geingob Street, Eromgo RED Head Office, Walvis Bay, Namibia', '1.Namibia市场 6个主要售电公司之一，属于半国营企业，公司主要股东为NamPower（纳米比亚唯一国有发电和输电公司）和地区区域政府，售电管理区域主要为Walvis Bay,Swakopmund,Henties Bay,Arandis,Karibib,Usakos和Omaruru,总电力用户数量为45400个，其中商业用表数量为3500个，LPU用表数量为400个；\r\r\r\n2.Erongo当前电表一半比例为兰吉尔和Itron的Cashpower分体式代码表，另外一半仍是机械式电表和插座式代码表，售电系统为南非公司Syntell提供，功能陈旧；\r\r\n3.Erongo本地招标对BEE资质有强制性要求，投标者必须要满足纳米比亚BEE资质（本地黑人一定所有权和管理权等，等级越高评分越高）。', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
