INSERT INTO `inhe_customer_data` VALUES ('416', '66', 'JXINHE-2559', '2018-02-24 09:37:28', '2018-02-24 10:01:02', 'khxx20180224402/Eletricidadede Mo ambique', 'khxx20180224402', 'Eletricidadede Mo ambique', 'EDM', '非洲', '莫桑比克', 'www.edm.co.mz', 'Av. Agostinho Neto, No. 70, First Floor', '1995年莫桑比克国家电力公司（EDM）成立，管理全国用户数量（2011年数据）101万户，员工人数3402人，营业收入2.8亿美元。国家面临着电力基础设施投资落后于经济发展速度的现状,与其他非洲国家相比,莫桑比克具有相对稳定的政治环境,经济持续恢复性增长,投资法律环境较为健全,电力行业急需外部资金和技术进入,以加快电力基础设施项目建设,满足其经济发展的需要。', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
