INSERT INTO `inhe_customer_data` VALUES ('418', '60', 'INHE-0680', '2018-02-24 15:22:19', '2018-02-24 16:38:22', 'khxx20180224404/北方电力', 'khxx20180224404', '北方电力severelectro', 'severelectro', '亚洲', '吉尔吉斯斯坦', 'http://severelectro.kg/\r\n', '722160, Чуйская обл.,Аламудунский район, с.Лебединовка, ул. Чкалова, 3\r\n', '吉尔吉斯斯坦的首都北方电力公司（ОАО \"Северэлектро\" www.severelectro.kg）约60万用户，的招投标项目，招标产品主要为三相表直通表和三相CT表。产品在测试的过程中出现了一些不符点，比如对继电器的设置、停电显示并且将最后的显示数据上传至系统等需要修改电表的程序，而且需要的时间相对比较长。\r\r\n后续该电力公司的产品招标项目会继续按照这个技术规格来完成，需要根据相应的技术规格来修改电表的程序，以满足电力公司的需求。\r\r\n', '陈嘉豪', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
