INSERT INTO `inhe_customer_data` VALUES ('421', '66', 'INHE-0579', '2018-03-05 17:11:10', '2018-03-05 17:42:13', 'khxx20180305408/E24 Middle East & Africa', 'khxx20180305408', 'E24 Middle East * Africa', 'E24', '亚洲', '黎巴嫩', 'www.e24solutions.com/', 'Sharp Minds SAL, May Tabet Building, 1st Floor, Emile Edde Street, Salloume Hayek Roundabout, Sin el Fil, Lebanon.\r\r\n', 'E24是一家提供能源解决方案公司，主要致力于太阳能可再生能源和储存能源项目设计和执行。业务涉及智能家居，智能电网（为工厂，村庄，建筑楼，通讯公司等提供电力储备方案）等。在北美，欧亚，欧洲，中东，非洲均有分公司。我们的客户是中东&非洲区的子公司。', '孙娜', '国际业务三部', null, null, 'E', 'INHE');
