INSERT INTO `inhe_customer_data` VALUES ('423', '61', 'INHE-0642', '2018-03-13 01:01:35', '2018-03-16 08:22:48', 'khxx20180313410/Process & Plant Automation Limited', 'khxx20180313410', 'Process * Plant Automation Limited', 'PPA', '非洲', '加纳', 'www.automationghana.com', '', '以前在加纳有过合作项目，属于老客户范畴。现在PPA打算和我司在加纳MCA项目中合作', '潘正豪(James)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('424', '61', 'INHE-0642', '2018-03-13 16:07:37', '2018-03-16 08:22:11', 'khxx20180313411/Millennium Challenge Account\r\n', 'khxx20180313411', 'Millennium Development Authority', 'MiDA', '非洲', '加纳', 'www.mida.gov.gh', '', 'MiDA以The Government of Ghana Millennium Challenge Account 名义实施项目， Millennium Challenge Account 实属美国千禧年公司旗下，用以资金援建非洲地区的机构。该机构由Millennium Development Authority (MiDA)监督、管理和实施项目。2014年，MCC和加纳政府达成援助协议，援助金额为US$ 498,200,000，用以帮助加纳经济增长以及消除贫困。						\r\n					\r\r\n', '潘正豪(James)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('425', '60', 'INHE-0535', '2018-03-14 13:40:42', '2018-03-14 14:01:32', 'khxx20180314412/JP MINDA GROUP', 'khxx20180314412', 'JP MINDA GROUP', 'JPM', '亚洲', '印度', 'www.jpmgroup.co.in', 'GP-14, HSIIDC,Sector 18, Gurugram, Haryana-122001(INDIA)', '\r\r\r\r\r\r\r\r\r\r\r\nJP MINDA GROUP集团，旗下多个子公司包括JNS Instruments，JPM工具，JPM汽车， JAY钢铁，JNJ电子等14个子公司。JPM的汽车业务过去5年是印度第一。旗下JNS Instruments主业是给汽车和摩托车生产速度表，与日本Nippon Seiki Co.,Ltd有合资工厂，当地市场占有率超过40%。电表这块属于JNS Instruments的业务范围。主要给韩国客户OEM，产品供货韩国电力公司（KEPCO）。工厂生产制造管理较规范，电表生产具备SMT生产和注塑生产能力，但电表研发能力不强。有足够的财力自行开立保函和为项目进行融资。\r\r\n					\r\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\n', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('426', '60', 'INHE-0535', '2018-03-14 15:49:11', '2018-03-14 15:58:54', 'khxx20180314413/Energy Efficiency Services Limited', 'khxx20180314413', 'Energy Efficiency Services Limited', 'EESL', '亚洲', '印度', 'https://eesl.eproc.in', 'Energy Efficiency Services Limited, C/o Projects & Development India Ltd., PDIL Bhawan, 1st Floor, A-14, Sector-1,\r\r\nNOIDA-201 301, Distt. Gautam Budh Nagar, U.P.\r\r\n', 'EESL(Energy Efficiency Services Limited), 是NTPC Limited, Power Finance Corporation, Rural Electrification Corporation 和 Powergrid共同组成的JV，设立于电力部下以推动能源效率项目的执行。【EESL的目标】：\r\n1.	为需求侧措施方面包括市政功能，农业，公共建筑，照明灯等提供能源效率项目准备；\r\n2.	执行中央或邦政府或其代理机构的计划，项目和政策；\r\n3.	与私有ESCOs和其他公司合作促进能源效率；\r\n4.	在能源效率，CDM项目和其他有关领域提供咨询服务；\r\n5.	传授培训，培养股东能力。\r\n\r\r\n', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('427', '60', 'INHE-0514', '2018-03-16 15:11:55', '2018-03-16 15:47:51', 'khxx20180316414/Majan Electricity Conpany', 'khxx20180316414', 'Majan Electricity Conpany', '', '亚洲', '阿曼', 'http://majanco.co.om\r\n', 'P.O. Box 286, Sohar, Postal Code 311\r\r\nSultanate of Oman\r\r\n', 'Majan电力公司是阿曼三大配电公司之一（MEDC, Majan，Mazoon），负责阿曼北部地区的供电，包括Albatinah区域，Al-Dhahirah区域以及Buraimi省，成立于2005年。', '李成兵', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('428', '66', 'JXINHE-2559', '2018-03-16 16:45:11', '2018-03-16 17:10:39', 'khxx20180316415/Season Malaysia Manufacturing Sdn Bhd', 'khxx20180316415', 'Season Malaysia Manufacturing Sdn Bhd', 'SEASON', '亚洲', '马来西亚', 'www.seasongroup.com', 'No. 2636, Lorong Perusahaan 8A, Prai Insuatrial Estate, 13600 Prai Penang. Malaysia.', 'SEASON GROUP集团下属的生产企业，主要从事于定制化生产和机械服务，在美国，加拿大，墨西哥，英国，中国和马来西亚有分厂，员工人数1800人，占地约80万平方英尺。', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('429', '66', 'INHE-0634', '2018-03-19 14:16:38', '2018-03-19 14:29:59', 'khxx20180319416/Electricity Supply Enterprise', 'khxx20180319416', 'Electricity Supply Enterprise', 'ESE', '亚洲', '缅甸', 'http://www.moep.gov.mm/electricity-supply-enterprise-overview\r\n', '缅甸内比都', '缅甸内比都电力局。内比都是缅甸首都，人口约115.8万。', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('430', '61', 'INHE-0695', '2018-03-20 10:06:40', '2018-03-20 10:54:21', 'khxx20180320417/TRANSTECH, A.S.', 'khxx20180320417', 'TRANSTECH, A.S.', 'Transtech SK', '欧洲', '斯洛伐克', 'http://www.transtech-sk.eu\r\n', '\r\r\nJilemnického 4,080 01 Presov Slovak republic', '斯洛伐克经销商，为摩尔多瓦电表厂ADD GRUP在斯洛伐克的代理，曾在2015年帮助其拿下电力公司VSD Slovakia的招标（14000台智能电表）。\r\r\n2015年公司收入为220万欧元，雇员为7人。\r\r\n参与过两个欧盟资助的调研项目，也被斯洛伐克本地媒体有所报道过。', '卿于蓝', '国际二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('431', '88', 'INHE-0091', '2018-03-21 08:35:08', '2018-03-21 09:52:02', 'khxx20180321418/Rural Electrification Authority\r\n', 'khxx20180321418', 'Rural Electrification Authority', 'REA', '非洲', '肯尼亚', 'www.rea.co.ke', 'Kawi House, South C,\r\nP.O. Box 34585, 00100\r\nNairobi, Kenya\r\r\n', 'REA负责肯尼亚农村地区的电力建设：\r\r\r\n●管理农村/电气化计划基金\r\r\r\n●制定和更新农村电气化总体规划\r\r\r\nREA负责肯尼亚农村地区的电力建设：\r\r\n●管理农村/电气化计划基金\r\r\nREA负责肯尼亚农村地区的电力建设：\r\r\n●管理农村/电气化计划基金\r\r\n●制定和更新农村电气化总体规划\r\r\n●考虑到某些地区的具体需求，包括使用电力进行灌溉和支持农场外收入的可能性，促进使用可再生能源，包括小水电，风能，太阳能，生物质能，地热能，混合系统和燃油组件活动。\r\r\n●实施农村电气化项目和寻找额外资金\r\r\n●管理农村电气化牌照和许可，招标和合同授予						\r\n\r\r\n考虑到某些地区的具体需求，包括使用电力进行灌溉和支持农场外收入的可能性，促进使用可再生能源，包括小水电，风能，太阳能，生物质能，地热能，混合系统和燃油组件活动。\r\r\n实施农村电气化项目和寻找额外资金\r\r\n管理农村电气化牌照和许可，招标和合同授予						', '林丽璇', '智能配电事业部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('432', '61', 'INHE-0432', '2018-03-22 20:08:57', '2018-03-23 12:32:05', 'khxx20180322419/Safaricom Public Limited Company', 'khxx20180322419', 'Safaricom Public Limited Company', 'Safaricom', '非洲', '肯尼亚', 'https://www.safaricom.co.ke\r\n', '肯尼亚内罗毕', '1.肯尼亚最大的通讯运营商                                                                                                       2.目前移动用户数量约为2800万，占肯尼亚总人口数（约4000万）的70%。                                                              3.股东结构：英国沃达丰集团占股40%、肯尼亚政府占股35%、社会投资占股25%。                                                        4.2007年推出电子钱包支付M-PESA（类似于中国的支付宝、微信），目前注册用户约2700万，全国有13万多个代售点。2017年M-PESA交易额达到约690亿美元。                                                                                                                  5.2017年光线用户数量约83000户（肯尼亚工厂及租房目前使用光线网络）。                                                            6.2017年净收入约4.4亿美元。                                                                                                    7.Safaricom目前与华为合作紧密。在其实验室展示了其正在与华为合作的NB-IOT智能水表测试样机。						\r\r\r\r\r\r\r\r\r\n', '谭东羊(Timon)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('433', '60', 'INHE-0535', '2018-03-28 10:36:10', '2018-03-28 10:47:16', 'khxx20180328421/JPM Industries Limited', 'khxx20180328421', 'JPM Industries Limited', 'JPM', '亚洲', '印度', 'www.jpmgroup.co.in', ' Khasra No. 39/14,15/1,17/1, VPO-Mohammadpur Jharsa, Old Khandsa Road, Gurgaon (Haryana)', '属于JP MINDA GROUP集团旗下14个子公司之一。目前和多年来一直通过各种公司在印度和国外从事汽车和其他非汽车零部件(能源仪表等)的组装、制造和销售业务。电表业务主要给韩国客户OEM，供货韩国电力公司（KEPCO）。工厂生产制造管理较规范，具备电表SMT和注塑能力，但电表研发能力不强。有足够的财力自行开立保函和为项目进行融资。', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('434', '61', 'INHE-0695', '2018-03-28 17:38:25', '2018-03-28 17:54:56', 'khxx20180328422/Elgama sistemos, UAB.', 'khxx20180328422', 'Elgama sistemos, UAB.', 'Elgsis', '欧洲', '立陶宛', 'http://navitus.lt\r\n', 'Visoriu str. 2, LT-08300 Vilnius Lithuania\r\r\r\n', '立陶宛当地的一个能源管理系统方案提供商，主要做AMI/AMR软件方面。\r\r\n成立于1994年，在2002年的时候联同当地伙伴公司推出了立陶宛第一个电表抄读系统，有超过3000个计量点接入，通信方式主要为GSM/GPRS，辅助为PSTN及以太网\r\r\n主要业务地区为波罗的海三国，部分欧洲国家（白俄罗斯,波兰，希腊，西班牙）以及南美国家（哥伦比亚，玻利维亚，巴拉圭）\r\r\n公司只无生产电表的 能力，因此也在寻找合适的电表厂商一起合作。对合作表现出了较强烈的愿望，对我们具有DLMS以及MID认证比较看重。\r\r\n公司整体体量及规模不算太大，但可作为银河在欧洲市场的一个切入点。', '卿于蓝', '国际二部', null, null, 'E', 'INHE');
