INSERT INTO `inhe_customer_data` VALUES ('447', '61', 'INHE-0725', '2018-04-18 08:40:43', '2018-04-18 09:22:06', 'khxx20180418439/BTS Power Limited', 'khxx20180418439', 'BTS Power Limited', 'BTS', '非洲', '尼日利亚', 'www.btspowerafrica.com', 'Nurses House, 43 Afribank Street, Victoria Island, Lagos', 'BTS电力有限公司是一家专业从事电网、离网和嵌入式发电厂的开发、运营和维护的机构，主要市场为西非地区。其目标和核心业务主要是:为电力基础设施的部署、运营和维护提供一站式解决方案，同时降低客户的运营成本，为西非服务不足的社区和用户提供可靠电力。该公司和尼日利亚的EKEDC公司和IKEJA公司都有良好的关系，对当地的市场也比较熟悉。', '赵政洁(Oscar)', '国际业务部二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('448', '66', 'INHE-0634', '2018-04-18 14:50:46', '2018-04-18 15:28:15', 'khxx20180418440/Parami Energy Service Co.,Ltd\r\n', 'khxx20180418440', 'Parami Energy Service Co.,Ltd', 'PES', '亚洲', '缅甸', 'http://parami.com/', '#14-02, #15-07 Sakura Tower, Sule Pagoda Rd, Yangon\r\n', 'Parami Energy Service Co.,Ltd成立于2004年，是缅甸一家中型规模企业，业务范围涉及石油、天然气、建筑以及电力IPP和EPC工程，拥有200名员工，与Honeywell有合作关系。\r\n', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('449', '66', 'INHE-0634', '2018-04-18 14:55:15', '2018-04-18 15:28:28', 'khxx20180418441/Danayarzar Co., Ltd.\r\n', 'khxx20180418441', 'Danayarzar Co., Ltd.', 'DYZ', '亚洲', '缅甸', 'http://www.danayarzar.com/\r\n', 'No (33/C), Pyay Road, 7mile, Mayangone Township, Yangon.', 'Danayarzar Co., Ltd.是缅甸一家大型配电公司，拥有全国10%、仰光25%的配电项目。有18万用户数量，电力容量约 250-300MW。主要业务包括变压器、11KV和400V的SAC线、变电站等。在APE-ESE投标中与许继合作投标未中，在其官网发现该公司与正泰有过合作。\r\n', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('450', '61', 'INHE-0500', '2018-04-20 02:33:34', '2018-04-20 08:26:52', 'khxx20180420442/City of Windhoek\r\n', 'khxx20180420442', 'City of Windhoek', 'COW', '非洲', '纳米比亚', 'www.windhoekcc.org.na\r\r\n', 'Patterson Street, Southern Industrial Area, WINDHOEK, NAMIBIA\r\r\n', '1.Namibia市场 6个主要售电主体单位中最大的，属于市政公司性质，和其他5个售电主体公司主要股东为NamPower（纳米比亚唯一国有发电和输电公司）和地区区域政府、并且只从事配电和售电业务不一样，COW属于首都市政府全权管理，配电业务只是其中的一个部门业务，配电和售电管理区域主要为Townhouse, Katutura Customer Care Centre, Khomasdal, Wanaheda, and Soweto。总电力用户数量为5万个，其中商业用表数量为5000个，LPU用表数量为1000个，其余为普通居民用户；                                                      2.COW当前电表绝大部分比例为兰吉尔和Itron的Cashpower分体式代码表，另外一小半仍是机械式电表和插座式代码表，售电系统为南非公司提供，功能陈旧；                                                                                                      3.COW本地招标对BEE资质有强制性要求，投标者必须要满足纳米比亚BEE资质（本地黑人一定所有权和管理权等，等级越高评分越高）。', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
