INSERT INTO `inhe_customer_data` VALUES ('456', '61', 'INHE-0695', '2018-05-08 19:36:10', '2018-05-09 09:11:15', 'khxx20180508467/L&G Metering Ltd.', 'khxx20180508467', 'L*G Metering Ltd.', 'LG METERING', '欧洲', '乌克兰', 'http://www.lgmetering.kiev.ua\r\n', '02160, г. Киев, ул. Березнева, 10, оф. 1112\r\r\r\n', '客户为乌克兰本地的AMR系统商，也在代理兰吉尔的热表以及其他厂商的数据集中器以及其他电器设备及检验设备（EVM,Гран-Система-С,GOSSEN METRAWATT）。 客户在乌克兰本地有22年的AMR经验，在同客户沟通的过程中，客户展现出了对电表及通信相关知识的一定素养。', '卿于蓝', '国际二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('457', '60', 'INHE-0514', '2018-05-10 17:22:46', '2018-05-10 17:35:38', 'khxx20180510468/Al-Tareq For Engineering Technology Co.\r\n', 'khxx20180510468', 'Al-Tareq For Engineering Technology Co.', '', '亚洲', '约旦', 'www.tateco-eng.com\r\n \r\n', 'Khalda - Amr Bin Malek Street.\r\nAl Assaf Bulding 69 - Floor. 2\r\nAmman - Jordan.\r\nP.O.Box 2249 Amman 11821 Jordan\r\n', 'TATECO成立于2004年1月，是一家获授权的约旦民营公司，并在安曼商会挂牌上市。其主营业务是为客户提供最先进的电气设备和一流的行业解决方案。该公司之前是海兴在约旦的代理，利用其在电力公司的关系，帮海兴中过几次标，现在由于海兴的AMI系统在约旦电力公司Jepco出现了问题，所以在寻求新的合作伙伴。', '李成兵', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
