INSERT INTO `inhe_customer_data` VALUES ('462', '61', 'INHE-0440', '2018-05-24 02:23:06', '2018-05-24 08:33:48', 'khxx20180524476/Rural Energy Agency ', 'khxx20180524476', 'Rural Energy Agency', 'REA', '非洲', '坦桑尼亚', 'http://rea.go.tz/\r\n', 'Rural Energy Agency - REA\r\r\nMawasiliano Towers, 2nd Floor\r\r\nSam Nujoma Road\r\r\nP. O. Box 7990\r\r\nDar es Salaam, Tanzania\r\r\n', '为了实现坦桑尼亚全国的发展目标，促进农村经济发展和加快农村电力化进程，2007年，坦桑尼亚政府在能源部下成立了自治机构Rural Energy Agency (REA) 。REA响应坦桑尼亚政府在农村发展和执行现代能源的新政策，目标是满足坦桑尼亚农村地区85%以上的人口对现代能源的需求。', '汤伟(Will)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
