INSERT INTO `inhe_customer_data` VALUES ('471', '61', 'INHE-0440', '2018-06-06 06:39:28', '2018-06-06 08:33:00', 'khxx20180606493/ZANZIBAR ELECTRICITY CORPORATION', 'khxx20180606493', 'ZANZIBAR ELECTRICITY CORPORATION', 'ZECO', '非洲', '坦桑尼亚', 'http://www.zeco.co.tz', 'ZECO Headquarters, Gulioni Street\r\nZanzibar\r\nP.O.BOX 235\r\nZanzibar-Tanzania\r\n', '桑给巴尔电力公司ZANZIBAR ELECTRICITY CORPORATION (ZECO)，100%属于桑岛政府，归属能源部管辖。ZECO主要从TANESCO购电，然后供岛上居民使用，每年新增约3-5万新用户,是坦桑除国电（TANESCO)、农村电力公司（REA）后的第三个电力公司。 ', '汤伟(Will)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('473', '61', 'INHE-0431', '2018-06-07 09:19:08', '2018-06-07 10:36:35', 'khxx20180607495/Meter&Control d.o.o.\r\n', 'khxx20180607495', 'Meter*Control d.o.o.', 'M*C', '欧洲', '塞尔维亚', 'www.meterandcontrol.com\r\r\n', 'Tr??anska 21\r\r\r\r\r\n11080 Zemun\r\r\r\r\r\nSerbia\r', '\r\r\r\r\r\r\n塞尔维亚表，公司成立于2008，公司创始人有PLC研发的经验。公司有一定规模并取得以下证书：ISO 9001 Quality management/ ISO 14001 Environmental management/ OHSAS 18001 Occupational health and safety/ ISO/IEC 27001 Information security。公司有一定的技术和研发实力，据称自己的产品和方案符合： ISO/IEC 17020 Inspection body type C/ MID-D certificate on production quality system/ EC-type examination certificate and Certificate of Conformity/ DLMS/COSEM/ IDIS/ IEC 62052-11/ IEC 62053-21/ EN 50470-1/ EN 50470-3/ IEC 62055-31', '刘佩(Ted)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('474', '61', 'INHE-0722', '2018-06-13 09:11:39', '2018-06-13 10:35:48', 'khxx20180613497/SIREMCO S.A.DE C.V', 'khxx20180613497', 'SIREMCO S.A.DE C.V', 'SMEI', '北美洲', '墨西哥', '', 'ALBERTA 2288 P.B.L.A.,LOS COLOMOS,GUADALAJARA,44660,JALISCO,MEXICO', 'SIREMCO S.A.DE.C.V，简称SMEI，是由墨西哥CENMEX投资控股的一家致力于精准计量电力的公司。拥有完整的电表硬件、程序、通讯和系统设计能力以及安装和集抄实施经验，目前已经向CFE供应和管理着17万只电表，主要是DIN箱式方案表。SMEI的方案可以实现预付费和集抄。SMEI清楚墨西哥当地电力行业规则，懂电表业务，有业务基础，技术、服务能力和经济实力。其公司的管理层清楚墨西哥电表业务的机遇和挑战，有切实可行的竞争策略。', '冯婷', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('475', '93', 'INHE-0726', '2018-06-13 10:32:38', '2018-06-13 11:08:07', 'khxx20180613498/BURNED STONE CO., LIMITED', 'khxx20180613498', 'BURNED STONE CO., LIMITED', 'BURNED STONE', '亚洲', '中国', '', 'RM1502,EASEY COMMERCIAL BUILDING 253-261 HENNESSY ROAD,WANCHAI,HONGKONG', 'BURNED STONE CO.,LIMITED, 中文名为博德世通有限公司，私人股份有限公司，成立于2013年，在香港注册，谭剑锋为法人兼总经理，谭剑锋在江苏还有一家公司，江苏湖岸星光信息技术有限公司，成立于2017年，业务涉及国际 电信设备、服务和国际专线，是贸易商。', '李卓涵', '智能配电事业部业务', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('476', '61', 'INHE-0432', '2018-06-15 16:09:03', '2018-06-15 16:53:38', 'khxx20180615499/PowerGen Renewable Energy\r\n', 'khxx20180615499', 'PowerGen Renewable Energy', 'Powergen Renew', '非洲', '肯尼亚', 'http://www.powergen-renewable-energy.com/\r\n', '肯尼亚 内罗毕', '1.公司主营业务：太阳能微网总包项目，现为东非最大的太阳能微网服务供应商，已在肯尼亚、坦桑尼亚、赞比亚等国家建立了数百个太阳能微网发电站。2.公司历史：于2011年在肯尼亚内罗毕成立总部。创始人及董事长等均为美国人且毕业于美国哈佛商学院。公司曾受到TED等媒体专门报道，也收到来自于美国国际发展组织（USAID）的资金赞助。目前总部团成员约50人。', '谭东羊(Timon)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('477', '61', 'INHE-0642', '2018-06-18 23:46:27', '2018-06-19 08:31:35', 'khxx20180618500/Electricity Generation Company(Malawi) Ltd', 'khxx20180618500', 'Electricity Generation Company(Malawi) Ltd', 'Egenco', '非洲', '马拉维', 'http://www.egenco.mw/', 'Electricity Generation Company （Malawi）Limited (EGENCO)#FE54` No. 7 Victoria Avenue, Chayamba Building#FE54` P.O. Box 1567#FE54` Blantyre, Malawi', '马拉维发电公司，2016年9月9号从ESCOM（Electricity Supply Corporation of Malawi Limited）独立出去，主要负责发电工作，目前掌管350.8MW的水力发电站以及22.57MW的柴油发电站。', '潘正豪(James)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('478', '60', 'INHE-0727', '2018-06-20 14:43:09', '2018-06-20 14:51:45', 'khxx20180620501/Electric Vine Industries', 'khxx20180620501', 'Electric Vine Industries', 'EVI', '亚洲', '印尼', 'www.electric-vine.com\r\n', 'Electric Vine Industries, Trio Building, JI.Mampang Prapatan Raya No 17 E-F, Suite 302,Jakarta Selatan, 12790, Indonesia', '该客户是一家微电力公司，主营微电网，利用太阳能为印度尼西亚没有通电的地区（如偏远地区，农村等）提供电能。当地有工程安装队，负责项目的整体图纸设计，独立采购硬件（太阳能电板、逆变器、蓄电池等）。', '何素贞', '国际业务一部', null, null, 'E', 'INHE');
