INSERT INTO `inhe_customer_data` VALUES ('484', '61', 'INHE-0695', '2018-07-02 15:43:36', '2018-07-02 16:40:25', 'khxx20180702508/DALI - MN, sro\r\n', 'khxx20180702508', 'D.A.L.I. - M.N., s.r.o.', 'DALI MN', '欧洲', '斯洛伐克', 'http://dali-mn.sk', 'Turen 385, 903 01, Turen Slovak Republic\r\r\n', 'ISKRAMECO在斯洛伐克及捷克的代理。\r\n公司主要代理产品包括：电池，电表，变压器，高压开关，以及电力监测系统。\r\n代理较为靠谱，在斯洛伐克本地，该代理同电力公司关系较好，同该市场三家电力公司均有业务往来，对当地的电表市场较为熟悉。\r\n同时，该公司在邻国捷克有有相应的代理业务。待关系建立成熟后，可同期将业务扩展至捷克。\r\n', '卿于蓝', '国际二部', null, null, 'E', 'INHE');
