INSERT INTO `inhe_customer_data` VALUES ('486', '60', 'INHE-0714', '2018-07-03 17:01:43', '2018-07-03 17:13:51', 'khxx20180703510/厦门弘基永业投资有限公司', 'khxx20180703510', '厦门弘基永业投资有限公司', 'MRC', '亚洲', '菲律宾', '无', '厦门市湖里区岐山北路223号五楼', '厦门弘基永业投资有限公司，公司总部在菲律宾，大股东在菲律宾印刷业和垃圾处理业在业界很有名气。公司没有建网站，主要是开展菲律宾业务，因为客户在菲律宾关系网比较强大。公司主要有三大板块，移动支付/建设工程/配电设备的代理。现菲律宾SM微信支付已上线，这是客户与当地的BDO银行合作的业务。所以今后中国游客去菲律宾SM消费都可以用微信支付，现在业务还在拓展更大商铺。', '杨叶', '国际业务一部', null, null, 'E', 'INHE');
