INSERT INTO `inhe_customer_data` VALUES ('497', '60', 'INHE-0729', '2018-07-31 11:08:45', '2018-07-31 11:13:20', 'khxx20180731532/Confidence Group\r\n', 'khxx20180731532', 'Confidence Group', 'Confidence', '亚洲', '孟加拉国', '', '', '与孟加拉军方企业以及电力公司有关系，以往业务均为向上述企业直接供货。公司合伙人之一是一个华人，在孟加拉生活30多年，熟知当地的业务。有意向向我司直接采购预付费表零配件，在孟加拉组装，通过国有企业GEMCO向REB等电力公司供货。直接采购（简称直采）在孟加拉规定只有政府性质的公司之间才可以开展直接采购。REB还有约2400万只表的需求，其中一部分需求将直采。\r\n', '吴成博', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
