INSERT INTO `inhe_customer_data` VALUES ('500', '60', 'INHE-0514', '2018-08-01 12:34:57', '2018-08-01 13:25:25', 'khxx20180801535/Pars Tableau', 'khxx20180801535', 'Pars Tableau', '', '亚洲', '伊朗', 'http://parstableau.com/en/products-en/', 'No.11, Naqdi St. North Mofatteh St. Shahid Beheshti Ave. Tehran, Iran 1576646119\r\r\r\n', 'Pars Tableau是伊朗的EPC承包商，主要从事变电站，配电，转换开关等工程的施工建设，业务范围包括伊朗，中亚，中东，欧洲等区域，且在该区域已经积累了大量的工程建设经验以及市场资源。', '李成兵', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('501', '61', 'INHE-0722', '2018-08-02 14:46:35', '2018-08-02 16:08:05', 'khxx20180802536/Proveedora e Importadora Valan S.A. de C.V.', 'khxx20180802536', 'Proveedora e Importadora Valan S.A. de C.V.', 'Valan', '北美洲', '墨西哥', 'http://pivalan.com', 'Manuel Z. Cubillas No. 135 Colonia Fuentes del Centenario C.P. 83250, Hermosillo, Sonora', 'Proveedora e Importadora Valan S.A.de C.V.建立于2002年，主营业务为输电、配电等工程类项目、进口和生产电气设备和电子材料以及提供能源解决方案。拥有自己的品牌Medithor，目前在电表行业管理着超过4000台电表。', '冯婷', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('502', '61', 'INHE-0719', '2018-08-07 09:38:54', '2018-08-07 10:04:40', 'khxx20180807538/TECH INDUSTRIAS GLOBALES S.R.L', 'khxx20180807538', 'TECH INDUSTRIAS GLOBALES S.R.L', 'Teching', '南美洲', '秘鲁', 'www.teching.com.pe\r\n\r\n', 'Calle H, Mz: G1, Lt: 02, Bocanegra – Callao\r\n\r\n', '该公司于2015年成立，主营为工商业水电气测量方面的业务。通过智能计量为住宅，商业和工业部门提供解决方案，综合服务，能源，水，气体监测。还销售用于仪表和通信相关的智能设备。主要客户有： ENEL, LUZ DEL SUR, ELECTRO ORIENTE, ENSA, ENOSA, HIDRANDINA, ELECTROCENTRO, ELECTROPUNO, ELECTRO UCAYALI, ELECTROSUR, SEAL, STATKRAFT, EDEGEL, ENGIE, 在2015年开始与国电ELECTRO ORIENTE合作并开始供货。 \r\r\n\r\r\r\n\r\r\r\r\n\r\r\r\r\n', '林丽君', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('503', '60', 'INHE-0514', '2018-08-07 10:42:32', '2018-08-07 10:55:56', 'khxx20180807539/Public Establishment for Transmission of Electricity', 'khxx20180807539', 'Public Establishment for Transmission of Electricity', 'PETE', '亚洲', '叙利亚', 'http://pete.gov.sy/', '17th Nissan Street– in front of  Carlton Hotel-Mezzeh –Damascus\r\n', 'PETE是于2011年由叙利亚总统巴沙尔亲自颁发号令成立，借此于电力系统发电和配电单独开来。PETE主要负责叙利亚输电网络的运营，维护以及开发，同时还负责接入该网络的用户的售电。', '李成兵', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('504', '60', 'INHE-0066', '2018-08-09 14:42:23', '2018-08-09 16:00:14', 'khxx20180809540/JSC NPK ROTEK', 'khxx20180809540', 'JSC NPK ROTEK', 'ROTEC', '欧洲', '俄罗斯', 'http://www.rotek.ru', '117452, Москва,  ул. Азовская д.35, корп. 3., подъезд 2, этаж 1, офис 8 ', '该客户为当地领先的电信、广播设备研发、制造商及系统集成商，成立于1991年，主要业务方向为：通信/广播设备研发生产；网络集成。主要客户群体为：国家组织，政府部门机构，电信运行商，银行、金融公司，大型企业和中小企业，业务模式为定制和实施项目。随着市场需求的发展，客户需增加自己的智能电表方向的业务。', '邱洁', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('505', '60', 'INHE-0088', '2018-08-14 14:46:15', '2018-08-14 15:12:31', 'khxx20180814542/SINGTEL GROUP', 'khxx20180814542', 'SINGTEL GROUP', 'SG', '亚洲', '新加坡', 'https://www.singtel.com/\r\n', 'Singtel\r\n31 Exeter Road, Comcentre\r\nSingapore 239732, Republic of Singapore\r\nTel: +65 6838 3388\r\nFax: +65 6732 8428\r\nWebsite: www.singtel.com/globalservices\r\n', 'Singtel IoT <g-iotmktg@singtel.com>', '余冬纯', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('506', '60', 'INHE-0088', '2018-08-14 15:10:35', '2018-08-14 15:18:36', 'khxx20180814543/ZH Technologies International Pte Ltd\r\n', 'khxx20180814543', 'ZH Technologies International Pte Ltd', 'ZHT', '亚洲', '新加坡', '\r www.zhtechintl.com\r', '100 Peck Seah Street\r\n#09-14, PS100\r\nSingapore 079333', 'ZH国际70%新加坡股东 30%福建智恒科技，智恒2003年成立 60%营收为水表相关业务。目前与SSN进行兼容工作。水电气中智恒无电表相关经验。目前是三家入选新加坡电力运行水电气 NB 集抄的公司之一，唯一一家与国内公司有联系。\r\n', '余冬纯', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('507', '60', 'INHE-0088', '2018-08-14 16:57:23', '2018-08-14 17:16:59', 'khxx20180814544/Energy Market Authority', 'khxx20180814544', 'Energy Market Authority', 'EMA', '亚洲', '新加坡', 'https://www.ema.gov.sg/about_us.aspx', '991G Alexandra Road #01-29\r\r\r\n Singapore 119975', '						\r\r\n能源市场管理局（EMA）是新加坡贸易和工业部下属的法定委员会。主要工作氛围是确保可靠和安全的能源供应，促进能源市场的有效竞争，并在新加坡发展充满活力的能源部门。EMA是能源市场监督及制度制定部门。', '余冬纯', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('508', '60', 'INHE-0088', '2018-08-16 16:43:55', '2018-08-16 16:54:37', 'khxx20180816546/State Electric Company Limited', 'khxx20180816546', 'State Electric Company Limited', 'STE', '亚洲', '马尔代夫', 'www.stelco.com.mv', 'Ameenee Magu, Male\'20349, Republic of Maldives', 'STELCO电力公司从1949年开始发展，装机容量仅为14千瓦，并为马累的住宅提供电力。过去五十年来，公司以“电力部”和“马尔代夫电力局”等不同名称作为政府部门运作。 1997年，“国家电力公司”“State Electric Company” STELCO成立。最初的客户数量在马累约有50个房屋。今天，不同岛屿的客户总数已增至37,660人，其他岛屿的客户数量增至14,462人（截至2016年6月）。每年约增长8%用户，目前总装机容量达到70MW。\r\n', '余冬纯', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('509', '61', 'INHE-0431', '2018-08-21 09:26:45', '2018-08-21 09:53:15', 'khxx20180821548/Central Electricity Board', 'khxx20180821548', 'Central Electricity Board', 'CEB', '非洲', '毛里求斯', 'www.ceb.intnet.mu', 'Central Electricity Board,\r\r\r\nRue du Savoir,\r\r\r\nCyber City,\r\r\r\nEbene\r\r\r\nRep of Mauritius\r\r\r\n', '该客户是毛里求斯电力公司，始建于1953年，归属毛里求斯政府所有，直接向能源部汇报。负责全国近40%的发电（其余由IPP提供），输电和配电。全国有近47万用户。', '刘佩(Ted)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('510', '61', 'INHE-0431', '2018-08-21 09:30:59', '2018-08-21 09:42:57', 'khxx20180821549/Pascal Computer Services Ltd \r\n					\r\n', 'khxx20180821549', 'Pascal Computer Services Ltd', 'PCS\r\r\n', '非洲', '毛里求斯', 'www.pascalcomputer.net\r', '40/42 St Georges Street Port Louis\r\r\r', '客户是毛里求斯有三十年历史，做IT行业的。是联想，\rDell,HP在当地的经销商。 有给电力公司CEB供过IT设备。\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\n', '刘佩(Ted)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('511', '60', 'INHE-0560', '2018-08-21 16:03:36', '2018-08-21 18:01:21', 'khxx20180821550/ООО \"ЕМН Украина\"', 'khxx20180821550', 'ООО \"ЕМН Украина\"', 'ООО \"ЕМН Украина\"\r\r\r\n', '欧洲', '乌克兰', 'http://www.emh.com.ua/', '03142, г. Киев, ул. Академика Кржижановского, 4 (вход в офис со стороны ул. Зализняка)', '“EMN UKRAINE”公司于2008年与世界知名的德国公司“EMHElektrizit?tsz?hlerGmbH＆Co KG”一起（自2010年起成立“EMN Metering GmbH＆Co KG”）成立。销售由EMN Concern Metering GmbH＆Co KG生产的电力计量设备，与仪表配合使用的技术支持和培训#FE54`为自动计量系统（数据收集和传输设备，软件）提供设备，并计量其他能源资源#FE54`为电力，水，热力，天然气，污水和其他资源创建自动数据采集中心（商业，技术会计，流程管理）的服务。现已与该公司高层取得联系，获取其具体技术规格及探讨合作方式阶段。', '李美娇', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('512', '61', 'INHE-0662', '2018-08-27 09:35:53', '2018-08-27 10:38:38', 'khxx20180827551/ELMU Hálózati Kft', 'khxx20180827551', 'ELMU Hálózati Kft', 'ELMU', '欧洲', '匈牙利', 'www.elmu.hu', 'éMáSZ Hálózati Kft.\r\r\nEKRSZ_40147473\r\r\nDózsa Gy?rgy út 13.\r\r\nMiskolc\r\r\n3525\r\r\nMagyarország\r\r\n', 'ELMU是匈牙利最大的公司之一，2017年营业额为HUF236.74B，约合8.3亿美金，净收入为HUF15.49B，约合5420万美金。子公司包括ELM? Hálózati Kft，ELM?-éMáSZ Hálózati Szolgáltató Kft. éMáSZ ügyfélszolgálati Kft，ELM?-éMáSZ 负责电力业务。该公司原母公司为RWE，今年年初被EON接管。2017年EON采购了简单表和预付费表，付款及时。\r\n', '陈丽', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('513', '60', 'INHE-0760', '2018-08-28 15:01:53', '2018-08-28 15:20:17', 'khxx20180828555/kommunar corporation ', 'khxx20180828555', 'kommunar corporation', '乌克兰KC公司', '欧洲', '乌克兰', 'www.tvset.com.ua', '乌克兰哈尔科夫市卢金卡街8号', '客户为乌克兰首屈一指的国防军工企业集团公司下属的计量表计分公司，该公司成立于2003年，有成熟的销售渠道，主要销往乌克兰的东部和中部地区，和较好的政府资源，经常与国企合作进行电表改造项目。在占据乌克兰电表20%左右的市场份额，是一位非常有潜力的合作伙伴。', '郝健颖', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('514', '61', 'INHE-0695', '2018-08-30 10:24:23', '2018-08-30 10:31:55', 'khxx20180830557/Vallin SIA', 'khxx20180830557', 'Vallin SIA', 'Vallin', '欧洲', '拉脱维亚', 'http://vallin.lv', 'Maskavas iela 322, Rīga, LV-1063, Latvija', 'VALLIN公司自1994年以来一直从事电能，安装，仪表和会计，电信和工作安全领域的材料营销和营销。\r\n该公司业务范围包括拉脱维亚和立陶宛，办公室和仓库位于里加（拉脱维亚），销售办事处位于维尔纽斯（立陶宛）。\r\n该公司之前在代理 Actaris（现Itron）的产品，现因价格因素，寻求新的合作伙伴。\r\n', '卿于蓝', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('515', '61', 'INHE-0695', '2018-08-30 10:37:19', '2018-08-30 10:42:10', 'khxx20180830558/Energijos Skirstymo Operatorius AB', 'khxx20180830558', 'Energijos Skirstymo Operatorius AB', 'ESO', '欧洲', '立陶宛', 'http://www.eso.lt\r\n', 'Aguonu str. 24, LT-03212 Vilnius, Lithuania\r\n', 'Energijos Skirstymo Operatorius AB成立于2016年1月1日，合并LESTO AB和一家股份公司Lietuvos dujos。ESO由国有能源公司【Lietuvos Energija】控制，该公司是波罗的海国家最大的能源公司之一。\r\n\r\nESO的主要活动：电力供应和分配，天然气分配，??电力和天然气供应保障，电力和天然气的引入，电力和燃气配电网络的维护和发展，能源分配保证的安全性和可靠性。\r\n\r\nESO为立陶宛的160万客户提供服务。公司服务面积平方公里达到65.3万。平方公里。', '卿于蓝', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('516', '61', 'INHE-0744', '2018-09-03 09:17:05', '2018-09-03 09:43:58', 'khxx20180903559/突尼斯国家电力与燃气有限公司', 'khxx20180903559', '突尼斯国家电力与燃气有限公司', 'STEG', '非洲', '突尼斯', 'http://www.steg.com.tn\r\n', ' 38 rue Kamel Ataturk 1080 Tunis\r\r\n', '突尼斯国家电力与燃气有限公司是突尼斯大型国有公司，负责电力和燃气在整个突尼斯的生产、输送和销售，目前共有近400万电力用户和80万燃气用户', '郑超波(Mike)', '配电部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('517', '60', 'INHE-0549', '2018-09-06 15:35:03', '2018-09-06 15:56:28', 'khxx20180906562/ENTREPRISE DE COMMERCE GENERAL EQUIPEMENTS ET INSTALLATIONS DIVERS\r\n', 'khxx20180906562', 'ENTREPRISE DE COMMERCE GENERAL EQUIPEMENTS ET INSTALLATIONS DIVERS', 'ECEID', '非洲', '布基纳法索', 'http://www.cci.bf/?q=en/eceid', 'Avenue de l\'Aéroport, Porte 1490\r\r\n01 BP 4790 Ouagadougou 01 \r\r\nBURKINA FASO\r\r\n', '布基纳法索首都瓦加杜古的一家贸易公司', '王秀明', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('518', '61', 'INHE-0725', '2018-09-07 09:22:05', '2018-09-07 09:46:41', 'khxx20180907563/Ibadan Electricity Distribution Company Plc', 'khxx20180907563', 'Ibadan Electricity Distribution Company Plc', 'IBEDC', '非洲', '尼日利亚', 'www.ibedc.com', 'Capital Building, 115 Moshood Abiola Way (Old Ring Rd.), Ibadan, Oyo State, Nigeria', 'Ibadan Electricity Distribution Company Plc（IBEDC)是尼日利亚十一家电力公司之一，实力强劲，于2013年11月1日成立，现主要负责Oyo, Ogun, Osun及Kwara州的输配电工作，负责并监督该区域的电表采购。IBEDC是与菲律宾最大电力公司MERALCO是合作伙伴关系，每年对电表的需求量排在尼日利亚11家电力公司前列。', '赵政洁(Oscar)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('519', '93', 'INHE-0762', '2018-09-07 17:20:55', '2018-09-07 17:35:34', 'khxx20180907564/Regideso\r\n', 'khxx20180907564', 'Regideso', 'Regideso\r\n', '非洲', '布隆迪', 'http://www.regideso.bi/', 'Burundi Bujumbura ,\r\r\nRohero \r\r\nAvenue de la Science No.3\r\r\n', '客户为布隆迪国家水电局公司，国有企业', '莫林睿', '智能配电事业部业务', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('520', '66', 'INHE-0579', '2018-09-10 15:23:21', '2018-09-10 15:35:32', 'khxx20180910565/KLK Sprl', 'khxx20180910565', 'KLK Sprl', 'KLK', '非洲', '布隆迪', '无', '10, Av du Lac Tanganyika, Q. Asiatique P.O. Box 97, Bujumbura', 'KLK SPRL成立于2012年。业务范围涉及电气产品贸易，EPC工程项目等。近5年供货线缆，低高压电力产品以及水管等产品给电力公司。雇员数量根据项目情况而定，常驻员工15人。\r\r\n', '孙娜', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('521', '66', 'INHE-0579', '2018-09-10 15:26:39', '2018-09-10 17:19:08', 'khxx20180910566/REGIDESO Burundi', 'khxx20180910566', 'REGIDESO Burundi', 'REGIDESO', '非洲', '布隆迪', 'http://www.regideso.bi/', 'Burundi Bujumbura, Rohero Avenue de la Science No.3', 'REGIDESO Burundi成立于1962年,是布隆迪唯一的电力公司。其任务是确保城市地区或农村中心的电力和饮用水的生产，运输，分配和商业化。它拥有财政自主权，并受到水、能源部和采矿部的监督。REGIDESO开发了96.5％的国家电力。目前该市场计划使用预付费电表，RE\r\rGIDESO指定当地五家公司供应电表。\r\r\r\r\r\r\r\r\r\n', '孙娜', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('522', '60', 'INHE-0549', '2018-09-18 10:52:42', '2018-09-18 11:41:44', 'khxx20180918567/Groupe Forrest International S.A.', 'khxx20180918567', 'Groupe Forrest International S.A.', '', '欧洲', '比利时', 'www.forrestgroup.com', 'Parc des Collines, Avenue Pasteur 9 | 1300 Wavre, Belgique', 'Forrest集团（也是福雷斯特集团）是一家成立于1922年的集团公司，目前活跃于中非和东非。 它由Malta Forrest创立，目前由新西兰血统的比利时企业家George Arthur Forrest持有。Forrest集团今天包括许多分公司，这些公司被分为管理、能源、工程与施工、冶金与采矿、贸易、食品、银行和社会活动八大分支，包括各种工业活动：风力发电、水力发电、采矿和冶金、水泥制造、公共工程、土木工程、生物食品、航空和弹药制造等，分布于刚果民主共和国、比利时、肯尼亚（EGMF KENYA）和南非（GFI RSA）。', '王秀明', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('523', '60', 'INHE-0549', '2018-09-18 13:59:47', '2018-09-18 16:02:12', 'khxx20180918568/Société nationale d`électricité', 'khxx20180918568', 'Société nationale d`électricité', 'SNEL', '非洲', '刚果（金）', 'http://www.snel.cd/', '2831, Avenue de la Justice B.P. 500 Kinshasa/Gombe,RDC', 'SNEL是刚果民主共和国的电力公司，负责电力生产、传输和配送。它是一家于1970年5月16日根据第70/033号法令成立的一家上市公司，根据2008年7月7日第08/007号法律第四条和2009年4月24日第09/12号法律修改，变为一家有限责任公司，刚果民主共和国为唯一股东，受有关责任公司的法律和法规管辖，受特定法律法规以及这些章程的约束。SNEL于2018年3月份正式推出预付费电表计划。', '王秀明', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('524', '60', 'INHE-0549', '2018-09-19 14:49:02', '2018-09-19 15:20:10', 'khxx20180919569/Eurafrican Power Solutions\r\n', 'khxx20180919569', 'Eurafrican Power Solutions', 'EPS\r\r\r\n', '欧洲', '比利时', 'http://www.forrestgroup.com/fr/eps.html\r\n', 'Parc des Collines, Avenue Pasteur 9 | 1300 Wavre, Belgique', '福雷斯特集团是一家成立于1922年的集团公司，目前活跃于中非和东非。该集团目前有21家分公司，这些公司被分为管理、能源、工程与施工、冶金与采矿、贸易、食品、银行和社会活动八大分支，从事各种工业活动：风力发电、水力发电、采矿和冶金、水泥制造、公共工程、土木工程、生物食品、航空和弹药制造等，分布于刚果民主共和国、比利时、肯尼亚（EGMF KENYA）和南非（GFI RSA）。                                   EPS是福雷斯特集团能源分支下的一家子公司，其目标是协调福雷斯特集团能源分支。它活跃在能源领域的集团公司的所有活动中。EPS于2014年，在巩固福雷斯特集团能源分支的框架下建立。该公司的使命是项目管理，采购，设计和工程，融资和国际发展。EPS完全由福雷斯特集团持有，总部位于比利时瓦夫尔。', '王秀明', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('525', '93', 'INHE-0762', '2018-09-25 03:12:53', '2018-09-25 10:33:10', 'khxx20180925570/Energy Development Corporation (EDCL) Ltd\r\n', 'khxx20180925570', 'Energy Development Corporation (EDCL) Ltd', 'EDCL', '非洲', '卢旺达', 'www.reg.rw', 'KN2 ST 3, Nyarugenge District, Kigali City\r\nP.O.B 3855 Kigali, Rwanda', '卢旺达国电下属分管电力生产，输送的公司。', '莫林睿', '智能配电事业部业务', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('526', '61', 'INHE-0770', '2018-09-25 08:45:04', '2018-09-25 10:06:08', 'khxx20180925571/OMNISWIFT NIGERIA LIMITED., LTD\r\n', 'khxx20180925571', 'OMNISWIFT NIGERIA LIMITED., LTD', 'ONL', '非洲', '尼日利亚', 'www.omniswift.com', '25 Durban Street, Off Adetokunbo Ademola Crescent,Wuse II, Abuja,Nigeria', '该公司位于尼日利亚首都阿布贾，2011年创立，主营业务IT战略咨询、软件服务和基础设施解决方案。主要合作伙伴为微软、惠普、戴尔、思科系统等。2016年给当地配电公司Kaduna Disco提供过软件支持服务。\r\n', '刘博', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('527', '61', 'INHE-0770', '2018-09-25 11:48:52', '2018-09-25 12:38:37', 'khxx20180925572/Kaduna Electricity Distribution Plc', 'khxx20180925572', 'Kaduna Electricity Distribution Plc', 'KNEDC\r\r\n', '非洲', '尼日利亚', 'http://kaedco.com/\r\n', '			\r\rNo 1-2 Ahmadu Bello Way, Kaduna, Kaduna State，Nigeria\r\r\n\r\n', '该配电公司是尼日利亚11家配电公司之一，负责尼日利亚的Kaduna, Kebbi, Sokoto, Zamfara地区的售电业务，客户人数约为49万（2018年），家庭用户数量排名第六，尼日利亚排名前三的电力公司之一。\r\r\r\r\r\n', '刘博', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('528', '61', 'INHE-0776', '2018-09-25 12:28:27', '2018-09-25 14:24:16', 'khxx20180925573/Power and Energy, Constructors, Suppliers and Consultants S.A.\r\n', 'khxx20180925573', 'Power and Energy, Constructors, Suppliers and Consultants S.A.', '', '北美洲', '巴拿马', '', '巴拿马', '主营高压变电站和输电线路的保护和控制的电力业务，也为电力生产商提供技术支持', '李玟', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('529', '61', 'INHE-0770', '2018-09-25 12:47:42', '2018-09-27 09:56:29', 'khxx20180925575/Millennium Challenge Account-Liberia\r\n', 'khxx20180925575', 'Millennium Challenge Account-Liberia', 'MCA-L', '非洲', '利比里亚', 'http://www.mca.gov.lr\r\n', 'F&F Building, 2nd/3rd Floor\r\r\n63 United Nations Drive\r\r\nCoconut Plantation, Mamba Point\r\r\nMonrovia, Liberia\r\r\n', 'MCA-L是利比里亚政府的一个机构，于2015年10月23日设立。它实际属于MCC旗下，用于资金援助非洲地区机构，该机构的采购实际由MCC监管和项目实施。\r\r', '刘博', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('530', '93', 'INHE-0762', '2018-09-25 14:00:16', '2018-09-25 14:23:46', 'khxx20180925576/Pascal Nsengiyumva', 'khxx20180925576', 'Pascal Nsengiyumva', 'Pascal', '非洲', '卢旺达', 'www.rousant.com', 'Plot No 710，Behind Top Tower Hotel. Kigali', '客户为个人佣金代理，其同时兼做卢旺达一家贸易公司ROUSANT的国家代表，ROUSANT主要为卢旺达国电提供电缆，电线等电网配套设备，与银河供货范围不冲突。代理每年通过ROUSANT给国电的供货金额达到600万美金上下，其与国电采购总监的关系非常好。\r\r\n', '莫林睿', '智能配电事业部业务', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('531', '60', 'INHE-0760', '2018-09-26 15:07:15', '2018-09-26 15:22:14', 'khxx20180926577/克孜奥尔达配电公司', 'khxx20180926577', '克孜奥尔达配电公司', 'KZ', '亚洲', '哈萨克斯坦', 'www.krec.kz', '哈萨克斯坦克孜奥尔达市阿依杰克大街25号\r\r\r\n', '客户为哈萨克斯坦克孜奥尔达州的州配电公司', '郝健颖', '业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('532', '60', 'INHE-0601', '2018-09-26 17:00:18', '2018-09-26 17:12:56', 'khxx20180926578/Provincial Electricity Authority\r\n', 'khxx20180926578', 'Provincial Electricity Authority', 'PEA', '亚洲', '泰国', 'https://www.pea.co.th/\r\n', '200 Ngam Wong Wan Rd. Chatuchak Bangkok 10900\r\n', 'PEA是泰国最大的电力公司，PEA的电网业务覆盖泰国99.98%的国土面积，拥有512个变电站和914个办公地点。\r\nPEA拥有2400万用户，是第二大电力公司MEA用户的3倍以上。\r\n', '常一琳', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('533', '61', 'INHE-0744', '2018-09-27 13:58:35', '2018-09-27 14:06:05', 'khxx20180927579/中国水利水电第一工程局有限公司', 'khxx20180927579', '中国水利水电第一工程局有限公司', '中水一局', '亚洲', '中国', 'www.zsyj.com', '吉林省长春市经济技术开发区东南湖大路3799号 ', '中国水利水电第一工程局有限公司(以下简称水电一局)，隶属于世界500强企业－－中国电力建设集团（股份）有限公司，是国家大中型水利水电工程建设的骨干企业之一。水电一局积极实施“走出去”战略，优先发展国际业务，在刚果（金）、刚果布、乌干达、埃塞俄比亚、印度尼西亚、越南、老挝、缅甸、蒙古、俄罗斯等十余个国别进行了水利水电、输变电、矿山、铁路等领域的施工建设，形成了成熟的国别市场，在深耕细作、优质履约国际项目的同时，水电一局注重维护央企品牌形象，积极践行社会责任，在所在各个国别均取得了良好的经济效益和社会效益。', '郑超波(Mike)', '海外部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('534', '61', 'INHE-0744', '2018-09-27 14:59:09', '2018-09-27 15:04:25', 'khxx20180927583/Societe National de Electricite de Congo', 'khxx20180927583', 'Societe National de Electricite de Congo', 'SNEL', '非洲', '刚果（金）', 'www.snel.cd', 'Avenue de la Justice Kinshasa Congo', '刚果金国家电力公司隶属于刚果金国家能源部，由刚果金政府100%控股，负责全国范围内的发电、输电及配电业务', '郑超波(Mike)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('535', '60', 'INHE-0769', '2018-09-28 15:49:41', '2018-09-28 16:14:05', 'khxx20180928584/Jordanian Electric Power Company Limited', 'khxx20180928584', 'Jordanian Electric Power Company Limited', 'JEPCO', '亚洲', '约旦', 'http://www.jepco.com', '安曼', 'JEPCO成立于1938年。约旦66%的用电都是有JEPCO提供的，每年大约都有1-2次的采购计划，感兴趣的主要是预付费电表及AMI方案。Jepco 这边AMR 从CT/CTVT部分开始，已经完成了将近60%的部分，全部由 Landis-gyr负责，采用的是GPRS（2G）方案。单三相电能表方面，正在做G3PLC和高速PLC的试点，我们的竞争对手主要有海兴，华立，科陆等。代理和电力公司对我们现场演示的AMI方案都比较满意。', '吴琼', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('536', '93', 'INHE-0091', '2018-09-29 10:27:41', '2018-09-29 10:39:26', 'khxx20180929585/IMSAQA ELECTRIC, Lda\r\n', 'khxx20180929585', 'IMSAQA ELECTRIC, Lda', 'IMSAQA', '非洲', '莫桑比克', '', 'Av. OUA No. 783\r\nCidade de Maputo - Mo?ambique \r\n', '主要做莫桑比克电力公司生意，给电力公司供产品。', '林丽璇', '智能配电事业部业务', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('537', '93', 'INHE-0789', '2018-09-29 14:18:38', '2018-09-29 14:48:06', 'khxx20180929586/Electricity Distribution and Supply Authority (EDSA) \r\n', 'khxx20180929586', 'Electricity Distribution and Supply Authority (EDSA)', 'EDSA', '非洲', '塞拉利昂', 'http://www.edsa.sl \r\n', 'Murray Town Road， Electricity Building , S iake Steven Street, Freetown， Freetown， Western Area sl  \r\r\r\n', '电力分配和供应局（EDSA）是在2014年底国家电力局（NPA）分拆后成立的.EDSA负责塞拉利昂的电力分配和供应，而其大部分业务集中在西部。EDSA努力扩展其网络以实现全国的电气化。EDSA拥有700多名员工，其组织结构正在进行全面重组，以客户满意度为中心，并以分销技术服务和商业服务为核心，对整个业务价值链有全面的了解。\r\r\r\r\r\r\n', '林凤兰', '智能配电事业部业务', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('538', '61', 'INHE-0432', '2018-10-07 16:31:37', '2018-10-08 08:48:16', 'khxx20181007587/Arab Organization for Industrialization\r\n', 'khxx20181007587', 'Arab Organization for Industrialization', 'AOI', '非洲', '埃及', 'https://www.aoi.org.eg', '埃及开罗', '阿拉伯工业化组织（AOI）是埃及，沙特阿拉伯王国，阿拉伯联合酋长国和卡塔尔国于1975年成立的埃及阿拉伯军事组织，负责监督阿拉伯国防工业的集体发展。随着AOI成员国之间关系的逐渐恶化，埃及于1993年成为AOI的唯一所有者。AOI现直属于埃及国防部管辖。', '谭东羊(Timon)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('539', '61', 'INHE-0772', '2018-10-08 15:04:44', '2018-10-08 15:40:00', 'khxx20181008588/NATIONAL WATER AND ELECTRICITY COMPANY LTD', 'khxx20181008588', 'NATIONAL WATER AND ELECTRICITY COMPANY LTD', 'NAWEC', '非洲', '冈比亚', 'www.nawec.gm', '53 Mamadi Manjang Highway KANIFING P.O. Box 609 Banjul, The Gambia', '冈比亚国家电力公司，全资国有，直属能源部，主管所有水和电项目，去年采购了10000台单相预付费智能表和AMI系统，近一年客户获得世行资金1800万美金，用于电力相关的项目采购。2018年第四季度将采购31000台相预付费智能表。2019将进一步采购三相电表和建设实验室', '张子琦(Miranda)', '国际二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('540', '60', 'INHE-0769', '2018-10-08 15:48:34', '2018-10-08 16:09:43', 'khxx20181008590/NEW MACHINERY CO.', 'khxx20181008590', 'NEW MACHINERY CO.', 'NEW MACHINERY', '亚洲', '叙利亚', 'http://nmc.amirgroup.com/\r\n', 'Damascus- Syria', '叙利亚当地服务经销商，是AL AMIR GROUP旗下的子公司。', '吴琼', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('541', '61', 'INHE-0772', '2018-10-08 15:53:42', '2018-10-08 16:39:33', 'khxx20181008591/Sana Jaiteh', 'khxx20181008591', 'SanaJaiteh CO LTD', 'SANA', '非洲', '冈比亚', '', 'Dakar，Gambia', '扶轮社冈比亚主席，菲律宾驻冈比亚使领馆领事，政治掮客；目前所知该代理有两次中国到访记录，第一次2017年随政府代表团到广州，以及本次中非论坛随代表团来北京。运作特变的输变电项目。与能源部，财政部和总统有较好关系。曾定居英国，为人健谈友善，做事谨慎', '张子琦(Miranda)', '国际二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('542', '61', 'INHE-0719', '2018-10-09 09:57:54', '2018-10-09 11:03:24', 'khxx20181009592/Electro Oriente S.A.', 'khxx20181009592', 'Electro Oriente S.A.', '暂无', '南美洲', '秘鲁', 'http://www.elor.com.pe/portal_elor/', 'Oficina central: Av. Augusto Freyre 1168', 'Electro oriente S.A是国家电力公司，集发电，输电，配电和商业售电于一体，由国家全资拥有，FONAFE(秘鲁国家商业活动融资基金）负责，具有技术，行政，经济和财务自主权。该公司的服务必须以公共事业和广大群体的社会利益优先为准则。在1983年成立，主要的影响区域有478,415,.09平方公里（占全国的37.22%),主要包括洛雷托，圣马丁，亚马逊和卡哈马卡几个区域，在2015年底该公司的股本被全部认购，总价值大约为161,73百万美元。\r\r\n', '林丽君', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('543', '60', 'INHE-0549', '2018-10-09 15:35:00', '2018-10-09 16:13:24', 'khxx20181009593/Société IYA', 'khxx20181009593', 'Société IYA', '', '非洲', '马里', '', 'Hamdallaye ACI 2000 Bamako Mali', '马里本地一家做一般贸易，服务提供，勘探采矿和分包商采矿的公司。\r\r\n', '王秀明', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('544', '60', 'INHE-0560', '2018-10-09 16:34:33', '2018-10-09 17:13:03', 'khxx20181009594/ОАО *Меридиан* им. С.П. Королёва', 'khxx20181009594', 'ОАО *Меридиан* им. С.П. Королёва', 'ОАО *Меридиан*', '欧洲', '乌克兰', 'http://merydian.kiev.ua/', '\r\r\r\nUkraine, 03124, Kyiv, 8 Boulevard Vaclav Havel', '“Meridian”n.S.P Korolov股份公司是一家现代化企业，专门从事各种用途的电子设备的开发和批量生产，制造和供应机械单元和组件，提供符合欧洲标准的广泛服务。除此之外，也涉猎无人机系统，大型注塑模具制造，3D测量设备及电镀等产业。在乌克兰已有65年的经营历史及品牌经验，拥有丰富的客户资源及人脉关系。', '李美娇', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('545', '60', 'INHE-0769', '2018-10-15 15:53:55', '2018-10-15 16:24:25', 'khxx20181015596/UNITED GULF CONSTRUCTION CO W.L.L\r\n', 'khxx20181015596', 'UNITED GULF CONSTRUCTION CO W.L.L', 'UGCC', '亚洲', '科威特', 'ugcc.com', 'Block 1, Plot 264, Behind Fire Stn. Al-Ardiya P.O. Box 23495 Safat 13095 Kuwait\r\r\n', '科威特排名前六的工程建设公司\r\r\nUGCC隶属于科威特Jeeran Holding company，owner为美籍伊朗人Aliyar Dehghani，其目前长居美国，公司目前由其子Kevin实际运营，Holding下面有四家公司，UGCC（Construction EPC承包商）占Jerran Holding 60%的股份，总资产约为20亿美元，主要业务包括道路建设，管道建设，房屋建造，区域性综合体建设等；主要客户有科威特公共事业部，公共房屋福利部，科威特石油公司，科威特国家石油公司；另外，科威特是中冶在科威特的代理，据中冶的人反映，UGCC实力还不错。', '吴琼', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('546', '61', 'INHE-0719', '2018-10-16 09:53:52', '2018-10-16 13:36:43', 'khxx20181016597/ELECTRO UCAYALI S.A.', 'khxx20181016597', 'ELECTRO UCAYALI S.A.', '暂无', '南美洲', '秘鲁', 'https://www.electroucayali.com.pe/Portal/index.aspx', 'Av. Circunvalación N° 300, Distrito de Yarinacocha, Provincia de Coronel Portillo, Departamento de Ucayali.', '1995年成立，是一家国家电力公司，由Electrocentro SA出资建立\r，又名Empresa Concesionaria de Electricidad de Ucayali S.A.\r\r\n集发电，输电，配电于一体。主要影响区域是秘鲁的ucayali大区，用户数量大概为50000，拥有在Coronel Portillo，Padre Abad和Atalaya三个省份的特许经营权，前两个地区都已经连接进秘鲁唯一的国家大电网（SEIN)里了。\r\r\r\r\r\n\r\r\r\r\r\r\n', '林丽君', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('547', '93', 'INHE-0091', '2018-10-16 14:24:24', '2018-10-16 14:33:08', 'khxx20181016598/Ministry of Energy\r\n', 'khxx20181016598', 'Ministry of Energy', 'MoE', '非洲', '加纳', 'http://www.energymin.gov.gh/\r\n', 'P. O. Box SD40, Stadium Post Office Accra, Ghana\r\n', '能源部是加纳政府负责能源政策的制定、实施、监测和评估部门，以及监督和协调能源领域机构的活动。', '林丽璇', '智能配电事业部业务', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('548', '93', 'INHE-0762', '2018-10-16 17:46:03', '2018-10-16 17:54:59', 'khxx20181016599/Energy Utility Corporation Limited', 'khxx20181016599', 'Energy Utility Corporation Limited', 'EUCL', '非洲', '卢旺达', 'http://www.reg.rw/', '', 'KN82 ST3\r\r\r\nNyarugenge District\r\r\r\nKigali City\r\r\r\nP.O. Box 537 Kigali, Rwanda\r\r\r\nTel: +(250) (0) 78 818 1224\r\r\r\nEmail: info@reg.rw\r\r\r\nWebsite: www.reg.rw\r\r\r\n', '莫林睿', '智能配电事业部业务', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('549', '60', 'INHE-0088', '2018-10-16 17:16:54', '2018-10-16 18:08:13', 'khxx20181016600/Tenaga Nasional Berhad', 'khxx20181016600', 'Tenaga Nasional Berhad', 'TNB', '亚洲', '马来西亚', 'www.tnb.com.my', 'Tenaga Nasional Berhad No 129, Jalan Bangsar 59200 Kuala Lumpur', '马来西亚 TNB电力公司（TenagaNasional Berhad），负责马来西亚半岛的发电、输电和配电工作。TNB电力公司建于1990年9月，其前身为1949年建立的中央电力局（CEB），后更名为国家电力局（NEB）。TNB实行股份制，股东有国内的也有国际的，但马来西亚政府通过财政部继续保持着过半数的股份。1992年，TNB的股票在吉隆坡股票交易所上市。1996年1月，TNB百年债券成功发行。\r\r\nTNB积极推行发电燃料多样化的政策，采用天然气、煤、石油和水电4种燃料发电，以减少对石油的依赖。利用本上天然气发展高效能的燃气发电厂是TNB的长远计划。\r\r\nTNB在马来西亚半岛上架设的输电系统，主要电压等级是275kV、132kV和66kV。整个电网由位于吉隆坡的国家负荷调度中心和若干不同的区域控制中心所控制。TNB的电力系统还与新加坡、泰国的电网相连以交换电力。目前 TNB正着手建设一条500kV输电线路，它将成大国家电网的骨干线路。\r\r\nTNB的配电系统电压等级一般为33kV或更低。对需要较高电压的用户，则由变电站直接向用户供电。马来西亚的电力供应正向独立电力生产者（IPP）方向过渡。马来西亚政府已向一些IPP颁发了许可证。这些IPP的电厂中，有些已在1995年投入生产。预计IPP的总发电容量约为 4000MW。 TNB在4家IPP中有股金。\r\r\n为了进一步增强竞争机制，TNB进行了改组。改组后形成的4个主要部门是：能源供应、商业经营、财务和劳资。发电、输电和配电业务归属于能源供应部门；商业经营部门负责非核心业务活动，包括国内外新的营业活动的建立、发展以及检查和监督子公司、合资企业的营业活动；而劳资部门则负责劳务、编制以及其它一些事务。\r\r\nTNB现在约有800万用户，概括地可分为工业、商业、生活、采矿和公共照明等类。为进一步提高用户服务水平，TNB还设立了怨天营业式帐柜，为用户在居家附近提供种种便民电力服务。\r\r\nTNB电力公司目前拥有职123，000万。尽管电力系统规模不断扩大，职工人数却始终保持相当固定。2015年8月发布2016-2021年6年智能电表安装约820万台电表。\r\r', '余冬纯', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('550', '60', 'INHE-0769', '2018-10-17 08:53:11', '2018-10-17 10:31:11', 'khxx20181017601/Ministry of Electricity and Water of State of Kuwait', 'khxx20181017601', 'Ministry of Electricity and Water of State of Kuwait', 'MEW', '亚洲', '科威特', 'https://www.mew.gov.kw/', '', '科威特水电部（MEW）客户事业部副部长Dr. Misha’a Al-Otaibi 2017年底表示，为了提高国家智能电网的发展，科威特推出了旧电表更换成智能电表的计划。该项计划在2018年上半年开始进行项目招标，智能电表的招标数量是80万台，未来可能扩展到120万台。科威特电信公司Zain赢得科威特水电部（MEW）智能计量竞标项目，在未来七年负责科威特智能表计系统项目，包括维护、管理智能电表和水表抄表系统，培训客服中心人员，开发电子付费系统等。Zain会和E&Y公司、爱立信公司合作推进该项目，前两年主要安装智能仪表，后五年主要是维护管理抄表系统。按照科威特水电部的计划，第一批智能仪表将安装在基础设施建设部门、工业和农业部门的物业，其次是住宅用户。', '吴琼', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('551', '61', 'INHE-0725', '2018-10-19 13:58:43', '2018-10-19 14:33:52', 'khxx20181019605/Ministry of Energy(Ghana)', 'khxx20181019605', 'Ministry of Energy(Ghana)', 'MOE', '非洲', '加纳', 'http://www.energymin.gov.gh/', 'Ministry of Energy P. O. Box SD40, Stadium Post Office Accra, Ghana', '加纳能源部是加纳政府部门，负责能源政策的制订、执行、监测和评估，同时负责各能源部门活动的监督和协调。该部的任务是发展和维持一个有效力，实现财政创收的能源部门，提倡竞争，为当地人民提供安全、安全和可靠的能源供应，以满足加纳的发展需要。', '赵政洁(Oscar)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('552', '61', 'INHE-0725', '2018-10-19 14:33:40', '2018-10-19 14:48:42', 'khxx20181019606/Electricity Company of Ghana Limited', 'khxx20181019606', 'Electricity Company of Ghana Limited', 'ECG', '非洲', '加纳', 'http://www.ecgonline.info/', 'Electro Volta House, P.O. Box 521, Accra, Ghana', '加纳电力公司(ECG)是加纳政府全资控股的电力公司。加纳电力公司(ECG)于1997年2月成立。它始于1947年4月1日的电力部，负责全国的配电，1967年改称为加纳电力公司。1987年北方电力公司（NED）成立，自此ECG主要负责加纳1/3的地区（南部人口密集地区）的输配电工作，现管理用户超过180万。', '赵政洁(Oscar)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('553', '61', 'INHE-0500', '2018-10-24 03:28:56', '2018-10-24 09:25:01', 'khxx20181024607/Econet Wireless Zimbabwe', 'khxx20181024607', 'Econet Wireless Zimbabwe', 'EWZ', '非洲', '津巴布韦', 'www.econet.co.zw\r\n', 'No. 2 Old Mutare Road  \r\nMsasa\r\nHarare, Zimbabwe\r\n', '1.津巴布韦最大的电信运行商，市场份额50%，也是津巴布韦最大私人集团公司，主营业务以电信通讯基础设施建设和运行、有线和无线网络运营、EFT电子转账ECOCASH运营、IPP独立发电等为主；\r\n2.客户正在计划实施智能电表战略规划，即第一阶段：通过其自营的IPP太阳能发电站建立其完善的智能计量网络，第二阶段：通过和津巴布韦电力公司ZETDC联合，将智能计量的方案推广到全国；\r\n3.当前银河是第一个给此客户做宣讲的智能表计厂商，并进行了正式宣讲，初步得到了客户的认可。', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('554', '61', 'INHE-0776', '2018-10-24 15:43:51', '2018-10-24 16:13:01', 'khxx20181024608/Sichergrid INC', 'khxx20181024608', 'Sichergrid INC', 'Sichergrid\r\r', '北美洲', '巴拿马', 'www.sichergrid.com', '\r\r\nC Street, #84 Quintas Reales, Villa Zaita - Panama', '巴拿马电力产品采购商和智能电网服务商，与中美洲大部分国家的电力公司有业务往来。', '李玟', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('555', '60', 'INHE-0781', '2018-10-29 02:59:20', '2018-10-30 14:10:41', 'khxx20181029609/Ideal Electrical Enterprise Ltd.', 'khxx20181029609', 'Ideal Electrical Enterprise Ltd.', 'IEEL', '亚洲', '孟加拉国', '', 'Zirat Chamber(2nd Floor),31,Bangabandhu Avenue,Dhaka-1000.', '超过30年的专业做电力设备投标业务的公司，与几大电力公司和能源部有良好的关系。合作了几个投标，已中标开始供货。', '李启坦', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('556', '66', 'INHE-0628', '2018-10-29 10:53:48', '2018-10-29 17:25:12', 'khxx20181029611/Vulcan Holdings Ltd', 'khxx20181029611', 'Vulcan Holdings Ltd', 'Vulcan', '非洲', '塞拉利昂', 'http://www.vulcanholdings.co.uk/about.html', '1 Wilberforce Street, Freetown, Sierra Leone', 'Vulcan旗下有多家公司，从事工业、能源、房地产、农业、进出口贸易行业。企业控制人为黎巴嫩人，黎巴嫩裔在塞拉利昂一直控制经济命脉，较有实力。能源部电表招标项目刚刚启动，目前能源部公开的只有3万台，客户没有参与过，但曾中标过同属能源部管辖的水表(含软件)项目招标，合同金额432万美元。', '刘元豪', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('557', '66', 'INHE-0628', '2018-10-29 11:19:47', '2018-10-29 17:25:00', 'khxx20181029612/ELECTRICITY DISTRIBUTION AND SUPPLY AUTHORITY', 'khxx20181029612', 'ELECTRICITY DISTRIBUTION AND SUPPLY AUTHORITY', 'EDSA', '非洲', '塞拉利昂', 'http://www.edsa.sl/', 'ELectricity House,36 House Siaka Stevens St,Freetown, Sierra Leone', '塞拉利昂电力分配和供应局（EDSA）是在2014年底国家电力局（NPA）分拆后成立的.EDSA负责塞拉利昂的电力分配和供应，而其大部分业务集中在西部 EDSA努力扩展其网络以实现全国的电气化。 ', '刘元豪', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('558', '66', 'INHE-0628', '2018-10-29 11:27:06', '2018-10-29 17:24:32', 'khxx20181029613/African Development Bank', 'khxx20181029613', 'African Development Bank', 'ADB', '非洲', '科特迪瓦', '', 'Avenue Joseph Anoma，01 BP 1387 Abidjan 01，C?te d\'Ivoire', '非洲开发银行是一个多边开发金融机构。非洲开发银行成立于1964年，由三个实体组成：非洲开发银行，非洲发展基金和尼日利亚信托基金。非洲开发银行的使命是通过促进公共和私人资本投资于可能有助于该地区经济和社会发展的项目和计划，来消除贫困和改善非洲大陆的生活条件。', '刘元豪', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('559', '61', 'INHE-0770', '2018-10-29 15:40:34', '2018-10-29 16:51:30', 'khxx20181029614/Elecnor\r\n', 'khxx20181029614', 'Elecnor', 'ECR', '欧洲', '西班牙', 'www.elecnor.com\r\n', 'Paseo de la Castellana, 81 - Planta 20 - 28046 Madrid Spain \r\r\r\r\n', 'ELECNOR是西班牙一家以基础设施和特许经营两个主要业务领域进行项目开发、建设和运营的公司，具有60年的历史，业务分部全球53个国家，公司规模超过13000人，业务主要集中于基础设施建设、可再生能源和新兴技术。近三年营收国内外占比各约45%和55%，且国外营收占比呈上升趋势，2017年营收23亿欧元，净利润7千万欧元。', '刘博', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('560', '61', 'INHE-0770', '2018-10-29 16:25:21', '2018-10-29 16:48:50', 'khxx20181029615/Lucky Group', 'khxx20181029615', 'Lucky Group', 'LG', '亚洲', '印度', 'http://www.luckygroupcompanies.net/\r\n', 'Logix Techno Park, Tower - C, Ground Floor,Plot No. 4 & 5, Sector - 127, Noida - 201 301, UP, INDIA\r\r\n', 'Lucky Group是印度一家拥有25年经验的从事交钥匙工程、采购和建筑（EPC）项目的集团公司。业务领域涉及电力、工业、农业、教育、基础设施、医疗保障等；业务范围主要在非洲、东南亚和印度；拥有ISO认证；该集团公司有丰富的执行亚洲开发银行、非洲开发银行、世界银行、国家基金和私人基金等机构在海外资助的项目的经历。', '刘博', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('561', '61', 'INHE-0770', '2018-10-29 17:30:23', '2018-10-29 19:33:09', 'khxx20181029616/Liberia Electricity Corporation', 'khxx20181029616', 'Liberia Electricity Corporation', 'LEC', '非洲', '利比里亚', 'http://lecliberia.com\r\n', 'LEC Headquarters, Waterside P.O. Box 10-165\r Monrovia, Liberia\r\r\r\r\n', '利比里亚电力公司是利比里亚共和国政府通过立法法于1973年设立的公共事业实体，其任务是向全国供应经济、可靠的电力，LEC有责任确保提供高效、可靠的电力，以此满足利比里亚日益增长的电力需求。\r\r\r\r\n', '刘博', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('562', '93', 'INHE-0789', '2018-11-01 10:10:54', '2018-11-01 10:53:50', 'khxx20181101619/Millennium Challenge\r\nAccount - Liberia\r\n', 'khxx20181101619', 'Millennium ChallengeAccount - Liberia', 'MCA-Liberia', '非洲', '利比里亚', 'www.mca.gov.lr\r\n', 'F&F Building, 2nd/3rd Floor\r\r\n63 United Nations Drive\r\r\nCoconut Plantation, Mamba Point\r\r\nMonrovia, Liberia\r\r\n', '2004年初，美国总统布什在墨西哥的蒙特雷发出“世界发展新协调”的倡议，将发达国家更多的援助与发展中国家更大的责任相结合，并为此提议建立了一种机制，既“千年挑战帐户”，或称作“利于千年发展的帐户”即MCC。在此机制下，大量的发展援助基金将提供给那些实施良政、促进人类发展及鼓励经济自由化的国家。 MCA-Liberia 是利比里亚政府于2015年10月23日根据国家立法机构法案设立的一个合法，独立和自治机构。它负责管理利比里亚政府与美利坚合众国政府之间千年账户的钱款，主要集中在解决利比里亚发展中存在的两种限制性约束，可获得和负担得起的电力以及改善道路。', '林凤兰', '智能配电事业部业务', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('563', '61', 'INHE-0772', '2018-11-01 10:19:44', '2018-11-01 15:28:51', 'khxx20181101620/E.ON Off Grid Solutions GmbH', 'khxx20181101620', 'E.ON Off Grid Solutions GmbH', 'EGOS', '欧洲', '德国', 'www.rafikipower.com\r\n', '\r\r\nV?lklinger Stra?e 4\r\nD-40219 Düsseldorf, Germany\r\n			\r\r\r\r\n		\r\n\r\r\n', '该客户是通过谭东阳的美国客户介绍，公司总部在德国，在坦桑有全资分公司EGOS，EGOS与WHI（WORLD HOPE INC）组成的联合体中标了UNOPS（联合国项目办公室）的塞拉利昂39座村庄微电网项目。', '张子琦(Miranda)', '国际二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('564', '61', 'INHE-0722', '2018-11-02 17:10:01', '2018-11-02 17:51:20', 'khxx20181102621/Empresa Energía Honduras', 'khxx20181102621', 'Empresa Energía Honduras', 'EEH', '北美洲', '洪都拉斯', 'www.eeh.hn', 'Tegucigalpa,M.D.C.,Honduras,C.A.', 'EEH为洪都拉斯目前唯一电力分销商，由哥伦比亚电力公司EPM(Empresas Públicas de Medellín E.S.P.)投资成立。洪都拉斯国电ENEE由于经营不善，以竞标方式将部分电力业务承包了EEH。EEH目前主要业务为中低压的输、配、售电，拥有自主采购权。EEH拥有180万用户，从2017年开始计划部署智能电表，截止2018年10月已经部署27万只智能电表。', '冯婷', '国际业务2部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('565', '61', 'INHE-0721', '2018-11-05 08:46:55', '2018-11-05 10:54:39', 'khxx20181105623/Anxor Ingeniería S.A', 'khxx20181105623', 'Anxor Ingeniería S.A', 'Anxor', '北美洲', '尼加拉瓜', 'www.anxor.com\r\n', 'Colonia Reissell # 83.\r\r\n\r\r\nManagua, Nicaragua, Centroamérica\r\r\n', '工业解决方案供应商，为电气行业提供工程服务，并为全球公认的电气行业制造商提供代理服务。是尼加拉瓜国有电力公司DISNORTE-DISSUR以及配电公司ENATREL的供应商之一。\r\r\r\n', '胡云义(Anita)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('566', '61', 'INHE-0725', '2018-11-06 02:28:27', '2018-11-06 08:57:28', 'khxx20181106624/Eko Electricity Distribution Plc', 'khxx20181106624', 'Eko Electricity Distribution Plc', 'EKEDP', '非洲', '尼日利亚', 'https://ekedp.com/', 'Contract Office, 2nd Floor, 24/25 Marina Road, Lagos Island, Nigeria', 'Eko Electricity Distribution Plc（EKEDP)是尼日利亚十一家电力公司之一，实力强劲，现主要负责10个区域（西部：Agbara, Ojo, Festac；中部：Ijora, Mushin, Orile, Apapa；东部：Lekki, Ibeju, Lagos南部）的输配电工作，负责并监督该区域的电表采购，每年对电表需求及采购量位居11家电力公司前列。', '赵政洁(Oscar)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('567', '61', 'INHE-0722', '2018-11-12 09:42:23', '2018-11-12 10:57:36', 'khxx20181112625/Telefónica Digital Espa?a,S.L.', 'khxx20181112625', 'Telefónica Digital Espa?a,S.L.', 'Telefónica', '欧洲', '西班牙', 'http://www.telefonica.com/', 'Distrito C Edificio Oeste 1, Planta 3, Ronda de la Comunicación s/n, 28050 Madrid, Espa?a', 'Telefónica Digital Espa?a,S.L.（西班牙电信集团）是是世界上最大的电讯公司之一，成立于1924年，业务包括固定通讯线路、移动电话、互联网、数据、有线电视等。业务范围主要集中在欧洲和拉美地区。目前在智利有个10万台的项目。', '冯婷', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('568', '61', 'INHE-0793', '2018-11-13 08:39:11', '2018-11-13 09:38:18', 'khxx20181113627/SAV ENGINEERS PRIVATE LIMITED.\r\n', 'khxx20181113627', 'SAV ENGINEERS PRIVATE LIMITED.', '  SEPL', '亚洲', '印度', 'http://www.savengineer.in/\r\n', 'A-71/2, 1st Floor, Hari Nagar, Ashram, Mathura Road, New Delhi 110014.\r\r\n', 'The company started its business activities in the year 2006 in the field of import of Bus Bar turnking system, Tap Off Box etc.  And diversify into the supply, erection and commissioning of Crystal Brand (Mfg.  by Sinhal Udyog) Dual Pre- paid Energy Meters in the year 2012 along with meter boards and since then successfully supplied and installed more than 50000 meters at different projects’ site and having more than 40000 meters orders in hand to execute. \r\n', '辛方腾(Daniel)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('569', '61', 'INHE-0772', '2018-11-19 14:50:48', '2018-11-19 15:47:58', 'khxx20181119628/BOCAI IMPORT EXPORT TRADE LIMITED', 'khxx20181119628', 'BOCAI IMPORT EXPORT TRADE LIMITED', 'BOCAI', '非洲', '塞拉利昂', '', '塞拉利昂佛里顿', '在该市场经商中国商人，有一定人脉关系。通过共同电力行业朋友联系上。表示当地人脉是总统亲戚。希望银河授权，支持其投标。不需要银河开保函。中标后，由银河供货。', '张子琦(Miranda)', '国际二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('570', '61', 'INHE-0772', '2018-11-19 16:30:39', '2018-11-19 16:53:20', 'khxx20181119629/SIERRA LEONE ELECTRICITY DISTRIBUTION AND SUPPLY AUTHORITY\r\n', 'khxx20181119629', 'SIERRA LEONE ELECTRICITY DISTRIBUTION AND SUPPLY AUTHORITY', 'EDSA', '非洲', '塞拉利昂', '', '', '该市场的国有配电公司，拿到非发行的资金用于改善入户情况，现在对5万多预付费电表，表箱，PLC电线等零配件招标。', '张子琦(Miranda)', '国际二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('571', '60', 'INHE-0088', '2018-11-20 08:41:07', '2018-11-20 09:33:18', 'khxx20181120630/Empresa Nacional de Energía Eléctrica', 'khxx20181120630', 'Empresa Nacional de Energía Eléctrica', 'ENEE', '北美洲', '洪都拉斯', 'http://www.hondutel.hn/', 'Tegucigalpa MDC Honduras, Centro América', 'ENEE是由洪都拉斯政府拥有和运营的一家电力公司。洪都拉斯国家电力能源公司拥有4500多名员工；为130万户家庭和10多万家商业，工业客户提供服务；2012年6月约占洪都拉斯电力需求的84.8％。洪都拉斯约一半的电力部门是私人拥有的，其余的发电能力由ENEE负责\r\r\n\r\r\r\nEmpresa Energía Honduras（EEH）是洪都拉斯国家电力公司，由财团组建，该财团在墨西哥，巴拿马，危地马拉，哥伦比亚和智利拥有40多年的运营经验。由于洪都拉斯能源公司（EEH）负责所有电力线路，\r布线和所有系统的维护，所产生的总能量仅分配给城市和家庭。 私营部门只负责发电。通过国际招标成为洪都拉斯国家能源分布系统的执行公司，主要负责电网分布及维修，售电，征收以及减少和控制科技和非科技损失。\r', '余冬纯', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('572', '60', 'INHE-0088', '2018-11-20 09:30:30', '2018-11-20 09:43:07', 'khxx20181120631/Electrical Dealer S. de D. L. de C.V.', 'khxx20181120631', 'Electrical Dealer S. de D. L. de C.V.', 'EDS', '北美洲', '洪都拉斯', 'www.electrical-dealer.com', 'COL. MODEMA 23 AVE 8 Y 9 CALLE #288 SAN PEDRO SULA HONDURAS', '洪都拉斯本地私人企业，在当地开展照明等低压电力工程项目，供应电力设备，工具，材料给私人项目及电力公司。2012年开始合作联系，推广PLC/GPRS圆表，2014年来访我司并采购了CT GPRS表运作试点。', '余冬纯', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('573', '61', 'INHE-0721', '2018-11-23 15:32:34', '2018-11-23 18:41:31', 'khxx20181123632/Servicios Electricos Profesionales, S.A.\r\n', 'khxx20181123632', 'Servicios Electricos Profesionales, S.A.', 'SEPSA ', '北美洲', '尼加拉瓜', 'https://gruposepsa.com/', 'Semáf La Robelo 9c al N 2c Oe 1/2c Sur\r\nManagua - Managua\r\n', '主营电力材料、光纤、电力安装服务等。尼加拉瓜三大电表经销商之一,与电力公司关系密切。\r\r\n', '胡云义(Anita)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('574', '61', 'INHE-0770', '2018-11-25 11:14:25', '2018-11-26 08:42:42', 'khxx20181125633/Pascal Computer Services Ltd (PCS)', 'khxx20181125633', 'Pascal Computer Services Ltd (PCS)', 'PCS', '非洲', '毛里求斯', 'www.pascalcomputer.net', '40/42 St Georges Street Port Louis', 'Pascal Computer Service Ltd自1990年以来一直从事IT行业。凭借20多年的经验，PCS已成为毛里求斯IT行业中的市场领先公司，致力于为毛里求斯本地和海外市场提供高端IT产品和广泛的IT解决方案。 在银行、资本市场、医疗保健、保险和制造业拥有庞大的客户群。PCS的主要产品包括电脑硬件设备和软件设备，客户有ASUS、HP、Fujitsu、DELL、LENOVO、Microsoft等。', '刘博', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('575', '61', 'INHE-0770', '2018-11-25 13:38:25', '2018-11-26 08:42:15', 'khxx20181125634/Central Electricity Board（CEB）', 'khxx20181125634', 'Central Electricity Board（CEB）', 'CEB', '非洲', '毛里求斯', 'http://ceb.intnet.mu/', 'Corporate Office\r\r P.O Box 134\r\r Rue du Savoir\r\r Ebene Cybercity\r\r Ebene 72201\r\r Mauritius \r\r\r\r\n', '中央电力委员会(CEB)是毛里求斯政府全资拥有的附属机构，向能源和公用事业部报告。行政首长协调会成立于1952年，受1964年1月25日《中央电力委员会法》的授权，CEB的业务是“制定和执行发展计划，总体目标是促进、协调和改善电力的发电、传输、分配和销售”。毛里求斯自1982以来已实现100%电气化。\rCEB通过自有的4个火力发电站和8个水电站生产满足约40%的全国总电力需求，其余60%从独立发电厂购买。目前，它是唯一负责向民众输送、分配和供应电力的组织。\r\r\r\n', '刘博', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('576', '61', 'INHE-0722', '2018-11-26 17:31:02', '2018-11-26 18:11:03', 'khxx20181126635/RMD Energy Honduras', 'khxx20181126635', 'RMD Energy Honduras', 'RMD', '北美洲', '洪都拉斯', 'http://www.rmdenergy.net', 'RMD Energy Honduras Sandy Bay Roatan, HN', 'RMD Energy,成立于2015年，主要经营太阳能等绿色能源的方案咨询，提供方案，系统安装、维护等服务。业务服务面向商业区、旅游区和居民区。在官网也见了通讯塔方面相关业务。', '冯婷', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('577', '61', 'INHE-0770', '2018-11-27 14:08:47', '2018-11-27 15:57:45', 'khxx20181127636/Botswana Power Corporation', 'khxx20181127636', 'Botswana Power Corporation', 'BPC', '非洲', '博茨瓦纳', 'https://www.bpc.bw/', 'Plot 1222 Nkrumah Road Gaborone Botswana', '博茨瓦纳电力公司（BPC）是博茨瓦纳的一家国有公司，负责发电，输电和配电。它成立于1970年，目前是该国唯一的电力供应商。Morupule电站（燃煤）供应国内发电的80％，但是该国依赖从邻国进口能源。该地区经常面临供电不足而停电的问题。', '刘博', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('578', '66', 'INHE-0634', '2018-11-29 13:42:22', '2018-11-29 14:03:36', 'khxx20181129637/Kinetic Myanmar Technology Co., Ltd', 'khxx20181129637', 'Kinetic Myanmar Technology Co., Ltd', 'Kinetic', '亚洲', '缅甸', 'https://kineticmyanmar.com/', 'No. (797/A), Room 301, MAC Tower II, Corner of Bogyoke Aung San Road & Wardan Street, Lanmadaw Township, Yangon Myanmar.', '成立于2008年，公司主营业务范围：电信、ISP、IOT，员工总人数超过600人。', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('579', '60', 'INHE-0601', '2018-12-03 16:30:32', '2018-12-03 16:38:56', 'khxx20181203639/Electricite du Laos', 'khxx20181203639', 'Electricite du Laos', 'EDL', '亚洲', '老挝', 'http://edl.com.la/', 'Lao-Thai Friendship Road, 309, Ban Thang Klang. Sisattanak district. Vientiane Capital. Lao PDR.\r\r\r\n', '老挝电力公司（Electricite du Laos，EDL）是一家老挝国有企业，它拥有并经营老挝全国的发电，输电和配电\r\r\n。公司还管理老挝国家电网的电力进口和出口。老挝电力公司在1959年创建，总部位于万象。\r\n2010年7月，国际金融公司借给1500万美元给老挝电力公司在老挝农村地区来扩建电力网络和变电站。公司还\r\r\n从亚洲开发银行获得债务融资。到2020年，老挝政府预计将为90％的老挝家庭提供电力。\r\n', '常一琳', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('580', '60', 'INHE-0601', '2018-12-04 11:31:47', '2018-12-04 11:50:31', 'khxx20181204640/BCI Company Limited\r\n', 'khxx20181204640', 'BCI Company Limited', 'BCI', '亚洲', '老挝', 'www.bcilao.com\r\n', 'SAPHANGMOR VILLAGE, SAYSETTHA DISTRICT, VIENTIANE, LAO PDR\r\n', 'BCI是老挝国家电力公司EDL的工程承包商和项目咨询公司，和EDL有长期的合作关系和商业往来。', '常一琳', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('581', '66', 'INHE-0634', '2018-12-04 17:37:38', '2018-12-04 17:55:15', 'khxx20181204641/深圳友讯达科技股份有限公司', 'khxx20181204641', '深圳友讯达科技股份有限公司', '友讯达', '亚洲', '中国', 'http://www.friendcom.com', '深圳市南山区西丽龙珠三路光前工业17栋6楼', '成立于2002年，是一家集研究、生产、开发于一体的高科技企业。公司主要生产集中器、采集器等电力计量设备，同时生产应用于各种水、电、气计量装置的无线数传模块，是专业的无线数据采集设备制造商。', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('582', '66', 'JXINHE-2559', '2018-12-06 00:35:11', '2018-12-06 08:34:06', 'khxx20181206642/Shahzad International(Pvt)limited ', 'khxx20181206642', 'Shahzad International(Pvt)limited', 'Shahzad International ', '亚洲', '巴基斯坦', 'http://www.shahzadintl.com.pk/#/home\r\n', '20, Margalla Road, F-8/3 Islamabad Pakistan', '巴基斯坦专业石油开采集团，旗下拥有石油和煤矿开采，能源，航空，保险和旅游等多家子公司，与NTDC（国家输配电公司）关系良好。', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('583', '66', 'JXINHE-2559', '2018-12-06 15:04:15', '2018-12-06 18:17:41', 'khxx20181206643/National Transmission and Despatch Company', 'khxx20181206643', 'National Transmission and Despatch Company', 'NTDC', '亚洲', '巴基斯坦', ' www.ntdc.com.pk', 'Room No. 622, WAPDA House, Shahra-e-Quaid-e-Azam, Lahore - Pakistan', '巴基斯坦国家输配电公司，管理全国范围内的电网和输配电设施。', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('584', '61', 'INHE-0432', '2018-12-11 03:05:34', '2018-12-11 08:34:14', 'khxx20181211644/安讯通科技有限公司', 'khxx20181211644', '安讯通科技有限公司', '安讯通', '亚洲', '中国', '无', '北京', '1.成立于2016年，隶属于中国公安部，负责对接中国公安部一所、二所、三所研究院在海外的国家网络与信息安全业务拓展。                  \r\n2.注册地址为香港，因其特殊身份，网上没有公开信息。                                            3.该公司为我们已立项的EIA项目合作方：埃及政府正在建设新首都并将打造为智慧城市，搭建智慧控制平台，涉及智慧交通、智慧能源、智慧控制等多方面业务，其中包含涉及国家信息与安全的业务，智能表计（三表合一）只是其中很小的一块业务。而安讯通则是中国公安部负责该项目的中国对接方，负责当地业务开发和政府关系建设、维护。                                                                            \r\n4.2018年11月业务因EIA项目出差至现场，同时安讯通引荐了当地的另外一家企业AIO（Arab International Optronics）,促成了电表本地建厂、本地生产的合作意向。', '谭东羊(Timon)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('585', '61', 'INHE-0432', '2018-12-11 03:43:29', '2018-12-11 08:33:05', 'khxx20181211645/Arab International Optronics', 'khxx20181211645', 'Arab International Optronics', 'AIO', '非洲', '埃及', 'http://aioegy.com/\r\n', '埃及开罗', '1.正式成立于1984年，埃及国防部占51%股份，法国泰利斯集团占股49%（是设计、开发和生产航空、防御及信息技术服务产品的专业电子高科技公司，同时是法国最大的防务类机械电子科技公司）。                                                                                2.AIO是埃及国防部下属的一家民用企业，生产民用电子产品、LED灯、电子显示屏、太阳能板等。                                          \r\n3.2018年11月业务出差时，与合作伙伴一起拜访了该公司，本来是要谈EIA三表合一项目合作，却意外促成了电表本地建厂、本地生产的合作意向。', '谭东羊(Timon)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
