INSERT INTO `inhe_customer_data` VALUES ('587', '93', 'INHE-0811', '2018-12-12 16:33:47', '2018-12-12 17:12:22', 'khxx20181212648/E.G.C2.I SARL', 'khxx20181212648', 'E.G.C2.I SARL', 'E.G.C2.I\r\r\n', '非洲', '塞内加尔', 'http://egc2i.weebly.com ', 'Arafat 2 villa N° 20，Dakar，Senegal\r\r\r\r\n', '该公司是塞内加尔达喀尔地区的建筑工程公司，在建筑、安装、电焊，电力施工方面有非常丰富的经验。与塞内加尔电力公司SENELEC，ICS，SOCOCIM，SONACOS等公司都有过合作', '宁桃美', '银河电网业务部', null, null, 'E', 'INHE');
