INSERT INTO `inhe_customer_data` VALUES ('590', '61', 'INHE-0695', '2018-12-17 09:20:24', '2018-12-18 08:53:12', 'khxx20181217659/Stredoslovenska distribucna, a.s.', 'khxx20181217659', 'Stredoslovenska distribucna, a.s.', 'SSD', '欧洲', '斯洛伐克', 'https://www.ssd.sk/\r\n', 'Pri Rajcianke 2927/8, 010 47  Zilina\r\r\n', '斯洛伐克当地三大配电公司之一，51%股份为国有，剩余49%股份属于E.ON。\r\n主要负责斯洛伐克中部市场(Zilina, Banska). 大约有70万客户。\r\n', '卿于蓝', '国际二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('591', '66', 'INHE-0634', '2018-12-17 09:56:02', '2018-12-18 08:53:28', 'khxx20181217660/Propel Network Sdn Bhd', 'khxx20181217660', 'Propel Network Sdn Bhd', 'Propel', '亚洲', '马来西亚', 'https://pronetwork.com.my/', '84-1 & 84-2, Jalan Sungai Burung AA32/AA,\r\r\nBukit Rimau, Seksyen32,\r\r\n40460 Shah Alam, Selangor DE, Malaysia.', 'Propel Network is a game changer solutions provider in the Information, Communication & Technology and Environmental Energy Industry with services and products that provide high quality strategy, consulting and implementation solutions to all customers. With a range of full end-to-end turnkey engineering services in the ICT and Clean Energy space, network operators, equipment manufacturers, power producers and businesses can enjoy premium Project Management, Design, Planning,Optimization, Environmental Engineering, Operations & Maintenance and other critical services that ensure the smooth running and success of any project.\r\n\r\nProviding highly skilled professionals in both an insource and outsource capacity allows for customized solutions that fit any business requirement. All this is supported with a suite of inhouse developed software tools and products from around the world that range from test & measurement equipment, 3D mapping, cutting-edge Drone technology to state-of-the-art security, asset management and business enterprise software solutions – all of which are available to our clients.\r\n\r\nEstablished in 2008 with a presence and clients in Malaysia, Philippines, Myanmar and Cambodia, Propel Network is on track to be a regional leader in the ICT as well as the Environmental sector and will continuously strive to provide the best for all clients and customers.\r\n', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('592', '66', 'INHE-0628', '2018-12-18 15:13:49', '2018-12-18 15:32:37', 'khxx20181218663/Delta International limited', 'khxx20181218663', 'Delta International limited', 'Delta', '非洲', '塞拉利昂', '', '1 wilberforce street,Freetown', 'Delta公司是银河SLE项目代理实际控制公司之一，目前在执行塞拉利昂电力部太阳能路灯项目。Delta将直接投标，银河作为供应商。', '刘元豪', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('593', '66', 'INHE-0774', '2018-12-21 09:58:05', '2018-12-21 11:05:46', 'khxx20181221665/M/S Multi Electromechanical Trading Co.', 'khxx20181221665', 'M/S Multi Electromechanical Trading Co.', 'MEMCO', '亚洲', '约旦', 'http://www.memcojo.com/\r\r\n', 'Khalda, Amer Bin Malik Street, Alzeyadat Buidling No. 65, 1st Floor\r\nP.O.Box 2087, Amman 11953', '（1）成立于2002年，在约旦主要经营机电产品，包括：电缆和通信电缆，负载开关和隔离器，柴油发电机，输电变压器，LV&MV 开关设备，测试设备，电缆接头，电表和水表，防爆材料等。服务电力公司，水和矿产资源主管部门，机电承包商和终端用户；\r\r\r\n（2）获得ISO9001:2008认证；\r\r\n（3）电表中标记录： 标号：IDECO6/2004  采购公司：IDECO，表商：ISKRAMECO 产品：3相电表 合同金额：7005 欧元\r\r\n                   标号：IDECO15/2008 采购公司：IDECO，表商：MEMF      产品：3相电表 合同金额：89000美元            						\r\r\n\r\r\n\r\r\n', '何森华', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('594', '66', 'INHE-0774', '2018-12-24 13:45:59', '2018-12-24 14:25:31', 'khxx20181224666/Irbid District Electricity Co.,Ltd', 'khxx20181224666', 'Irbid District Electricity Co.,Ltd', 'IDECO', '亚洲', '约旦', 'www.ideco.com.jo', 'Irbid, Ratib Al Batayneh Street', '成立于1957年，原名Irbid National Electricity Company,经营发电，输电和Irbid,Mafraq,Jerash,Balqa等地区的配电，1967年公司更名为Irbid Electricity Company Public Shareholding Company Limited，是也门3大电力公司之一。', '何森华', '国际业务3部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('595', '66', 'INHE-0579', '2018-12-28 09:37:21', '2018-12-28 11:15:06', 'khxx20181228669/INTERFACE ENGINEERING GROUP LTD.', 'khxx20181228669', 'INTERFACE ENGINEERING GROUP LTD.', 'IEG', '亚洲', '黎巴嫩', 'http://www.ieglb.com/\r\n', 'Banbouk Centre 5th floor\r\r\nLa Sagesse St.\r\r\nJdeidet El Metn, Lebanon\r\r\n', '\r\r\n\r\r\nIEG成立于1995年\r\r\n公司性质：系统集成商\r\r\r\r\n公司规模：固定员工15人左右。根据项目增加临时雇员。\r\r\r\r\n公司经营范围：智能电网项目提供系统服务。\r\r\n项目经验：①参加阿布扎比智能电网项目。部署基于西门子SACDA的DMS系统。\r\r\n         ②作为NDB Technologies（加拿大）代理，为沙特阿拉配电站提供并安装完整的监控系统。', '孙娜', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('596', '66', 'INHE-0774', '2019-01-02 11:20:45', '2019-01-02 11:37:20', 'khxx20190102670/EVN Macedonia AD, Skopje', 'khxx20190102670', 'EVN Macedonia AD, Skopje', 'EVN', '欧洲', '马其顿', 'http://www.evn.mk\r\n', 'Str. 11 Oktomvri No. 9\r\r\n1000 Skopje\r\r\nMacedonia', 'EVN集团是一家总部位于奥地利的电力生产商和运输商，是欧洲最大的电力生产商之一，在14个国家拥有300多万客户。该公司还经营水处理，天然气供应和废物管理业务领域。它是奥地利第二大公用事业公司。 EVN Macedonia AD, Skopje 于2006年进入马其顿，作为EVN集团的一部分，主要经营马其顿共和国的配电和供电业务。2013年售电量为5.028GW\r\n', '何森华', '国际业务3部', null, null, 'E', 'INHE');
