INSERT INTO `inhe_customer_data` VALUES ('600', '60', 'INHE-0535', '2019-01-15 16:51:03', '2019-01-15 17:35:36', 'khxx20190115674/Uttar Pradesh Power Corporation Limited\r\n', 'khxx20190115674', 'Uttar Pradesh Power Corporation Limited', 'UPPCL', '亚洲', '印度', '', 'U.P. Power Corporation Ltd\r\nR No. 514, 5th Floor, Shakti Bhavan Extn.\r\n14, Ashok Marg, Lucknow – 226001\r\n', '印度UP邦电力公司，Uttar Pradesh Power Corporation Limited（UPPCL）是根据1956/2013年公司法的规定注册的公司，是北方邦政府的全资实体。\r\n除了作为发电和输电实体的控股公司外，UPPCL还是UP邦五家区域电力公司的控股公司，即Paschimanchal Vidyut Vitaran Nigam Limited（PVVNL），Purvanchal Vidyut Vitaran Nigam Limited（PuVVNL），Madhyanchal Vidyut Vitaran Nigam Limited（MVVNL），Dakshinanchal Vidyut Vitaran Limited（DVVNL）和Kanpur电力供应公司（KESCO）。', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('601', '61', 'INHE-0431', '2019-01-17 18:03:51', '2019-01-17 18:14:21', 'khxx20190117675/El Sewedy Intelligence\r\n', 'khxx20190117675', 'El Sewedy Intelligence', 'ELS', '非洲', '埃及', 'www.elsewedyintel.com', '25 Dr. El Sobky street, Dokki, Giza, Egypt', '\r\r客户创始人是El Sewedy表厂工作过的，他说是El Sewedy集团所有者的表兄弟，目前已经从那里离职，主要提供一揽子解决方案给一些如建筑商等的用户，他们有自己的系统，现在想购买我们的电表。', '刘佩(Ted)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('602', '66', 'INHE-0774', '2019-01-18 11:16:11', '2019-01-18 11:50:51', 'khxx20190118677/Energy Code d.o.o\r\n', 'khxx20190118677', 'Energy Code d.o.o', 'Energy Code d.o.o\r\r\r\n', '欧洲', '克罗地亚', 'http://www.koncar.hr/\r\n', '克罗地亚首都阿格勒布Te?anjska 16,Zagreb		\r\n', '1997年-1998年在Koncar（Electotechnical Institute) 做变压器研究；\r\r\n1998年-2004年在OKit d.o.o.任项目经理，开发电力机构信息系统；\r\r\n2007年-2014年在Koncar-KET d.d. 任副总监，负责商业燃气调度的IT Development 项目；\r\n2014年-2016年担任Koncar（Power plant and Electric Traction Engineering Inc）BU Process information system总监；\r\n2016年-至今在施耐德做Smartgrid销售经理，同时开了自己的公司Energy Code d.o.o.做能源领域的指导、咨询业务。\r\r\n\r\r\n\r\r\n\r\r\n\r\n\r\n\r\n\r\n', '何森华', '业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('603', '66', 'INHE-0774', '2019-01-18 11:40:37', '2019-01-21 11:45:34', 'khxx20190118678/Hrvatska Elektroprivreda', 'khxx20190118678', 'Hrvatska Elektroprivreda', 'HEP', '欧洲', '克罗地亚', 'http://www.hep.hr/', 'Ulica grada Vukovara 37, 10 000  Zagreb', 'HEP集团是一个克罗地亚国有电力公司，一个多世纪以来从事发电、输电和配电业务，过去几十年开始从事供热和天然气配送。\r\nHEP集团拥有多家子公司，以控股公司的形式组建。集团母公司HEP d.d.履行集团公司管理的职能，为客户提供安全可靠的电力供应条件。\r\n\r\n', '何森华', '业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('604', '61', 'INHE-0793', '2019-01-21 16:14:07', '2019-01-21 17:13:52', 'khxx20190121680/Metsys Gazdasagi Szolgaltato Kft.', 'khxx20190121680', 'Metsys Gazdasagi Szolgaltato Kft.', 'MS', '欧洲', '匈牙利', 'www.metsys.hu', 'H-1131 Budapest-Reitter Haz Reitter Ferenc u.132.', '该客户为匈牙利公司Metsys,其主营业务为小型电网，他目前的业务目标是做大型商场，建筑等的电网建设。目前该公司想找一些电表供应商，其要求电表供应商必须通过MID和DLMS认证。', '辛方腾(Daniel)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('605', '61', 'INHE-0719', '2019-01-21 16:23:10', '2019-01-21 17:44:25', 'khxx20190121681/Electrosur s.a', 'khxx20190121681', 'Electrosur s.a', 'Esur', '南美洲', '秘鲁', 'http://www.electrosur.com.pe/', 'Calle Zela 408, Tacna,peru', '是秘鲁一家私有的配电公司，1985年成立，主管秘鲁南部的的Tacna和Moquegua大区（约16, 401.40平方米） ，一共有12个变电站，变压器有138/10 kV，66/10 kV，33 / 22.9 kV和33/10 kV，安装功率超过100 MVA\r\r，市场占比大概在3.65%左右。\r\r\n', '林丽君', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
