INSERT INTO `inhe_customer_data` VALUES ('607', '61', 'INHE-0793', '2019-01-21 17:24:48', '2019-01-21 17:44:46', 'khxx20190121683/Wattler', 'khxx20190121683', 'Wattler', '', '欧洲', '匈牙利', 'www.wattler.eu', 'H-1094 Budapest, Pava u.8', '匈牙利一家安装电表及提供配套服务的公司，目标市场为三相PLC智能表和AMI（HES)管理系统，该公司需要我司提供一些样机和系统进行测试，今年匈牙利会有新的法案，预计会有较大增长。', '辛方腾(Daniel)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
