INSERT INTO `inhe_customer_data` VALUES ('613', '61', 'INHE-0793', '2019-01-23 09:03:49', '2019-01-23 09:13:26', 'khxx20190123690/Trilliant Incorporated', 'khxx20190123690', 'Trilliant Incorporated', 'TID', '北美洲', '美国', 'https://trilliant.com/\r\n', '401 Harrison Oaks Blvd.，Suite 300 Cary，NC 27513\r\r\n', '该客户是美国著名的通讯系统软件及解决方案提供商，在全球电表系统提供商中可以排名前三，其与加拿大的Hydro One Networks，英国的British Gas和美国的Iberdrola Central Maine Power等著名能源供应商都有合作。其融资超过2.12亿美元，预计今年收入1500万美元，公司规模300人以上（数据来源于网络搜索www.owler.com）。该公司和我司在马来西亚的项目有过合作，目前业务与该公司项目经理PAR取得联系，此人工作细致，能力较强。', '辛方腾(Daniel)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('614', '61', 'INHE-0793', '2019-01-23 09:09:35', '2019-01-23 09:55:02', 'khxx20190123691/Vattenfall Eldistribution AB', 'khxx20190123691', 'Vattenfall Eldistribution AB', '', '欧洲', '瑞典', 'https://www.vattenfalleldistribution.se/\r\n', 'RU 2560 Stockholm,  169 92 Sweden\r\r\r\r\r\n', 'Vattenfall Eldistribution AB 是瑞典国家全资电力公司Vattenfall AB下辖的子公司，是瑞典最大的电力公司之一，该公司在瑞典西部，中部和北部均有电网部署，部分电网也会通过其子公司VasterbergslagensElnatAB和GotlandsElnatAB来运营。其总供电客户户数约为85万户（瑞典低压用户总数520万户以上，高压用户6500户以上）。Vattenfall Eldistribution 资金来源于瑞典政府，员工规模750人以上，在瑞典四个地点设有办事处：Jokkmokk，Lulea，Solna和Trollhattan；该公司2018年投资约40亿瑞典克朗（合30.2亿人民币）进行电网系统，电表方面的全面升级。（以上数据来源于该公司官网和互联网搜索）', '辛方腾(Daniel)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
