INSERT INTO `inhe_customer_data` VALUES ('618', '66', 'INHE-0634', '2019-02-11 09:02:35', '2019-02-11 09:14:06', 'khxx20190211697/Khin Maung Nyunt Trading Company Limited', 'khxx20190211697', 'Khin Maung Nyunt Trading Company Limited', 'KMN', '亚洲', '缅甸', 'http://www.kmngroupmm.com\r\r\n', '12/YaKaNa(Naing)061072 No.43,Shwe Tharaphy Yeikmon,Bayintnaung Street, Kamayut Township, Yangon', 'KMN是Khin Maung Nyunt Group of Companies下属最大历史最长的子公司，于1995年成立，从一家小型本地供应商发展壮大，成为缅甸电力行业最值得信赖、最可靠的产品和服务供应商之一。', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('619', '66', 'INHE-0634', '2019-02-11 11:32:32', '2019-02-11 14:19:50', 'khxx20190211699/Sipromad Group', 'khxx20190211699', 'Sipromad Group Company Limited', 'SG', '非洲', '马达加斯加', 'www.sipromad.com', 'LA TOUR\r\nRue Rainivoninahitriniarivo, Ankorondrano Antananarivo 101\r\nMADAGASCAR\r\n', '1918年成立，是马达加斯加最大的财团，业务范围主要涵盖房地产、旅游业、烟草业、科技产品零售经销、日常消费品类生产销售，药业和Orange money金融交易等。', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('620', '61', 'INHE-0431', '2019-02-14 17:54:41', '2019-02-14 18:04:39', 'khxx20190214702/SALDANHA BAY MUNICIPALITY\r\n', 'khxx20190214702', 'SALDANHA BAY MUNICIPALITY', 'SBM', '非洲', '南非', '', 'Private Bag X12\r\nVREDENBURG\r\n7380\r\n', '南非市政之一，管理19000用户，现在计划招标为期三年的售电系统。', '刘佩(Ted)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('621', '61', 'INHE-0500', '2019-02-15 09:24:06', '2019-02-15 09:37:16', 'khxx20190215704/CENTLEC (SOC) Ltd', 'khxx20190215704', 'CENTLEC (SOC) Ltd', 'CENTLEC', '非洲', '南非', 'www.centlec.co.za\r\n', '30 Rhodes Avenue，Oranjesig\r，Bloemfontein\r 9300\r\r\r\r\n', '1.位于南非自由州省，是自由州省唯一的大都市市政公司Mangaung Metropolitan Municipality 直接下属负责输配电公司，南非8大大都市市政公司之一，2016年总人口统计为约80万，家庭户数约27万户，电力用户约20万，为银河在南非市政的重要目标客户之一；\r\r\r\r\n2.2017年年度电费收入为22亿兰特，其中预付费电费收入为7亿兰特，中大型商业工业后付费电费收入为15亿兰特，年度线损10.77%，总计线损金额为1.7亿兰特。技术线损金额为1.1亿兰特，非技术线损金额为6千万兰特；\r\r\n3.当前市政公司的集抄系统供应商为AURECON Group和Jagertech（PTY）LTD，2016年授标，为三年期合同；售电系统服务提供商：海兴，2016年授标，为三年期合同。', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('622', '66', 'JXINHE-2559', '2019-02-18 11:53:34', '2019-02-18 12:47:03', 'khxx20190218710/王红', 'khxx20190218710', '王红', '王红', '亚洲', '中国', 'www.kaifametering.com  \r\n', '四川省成都市高新区（西区）合作路1218号\r\r\n', '深圳长城开发科技股份有限公司（证券简称：深科技 ）是全球领先的EMS企业，为全球客户提供技术研发、工艺设计、生产控制、采购管理、物流支持等全产业链服务。1994年在深交所上市（证券代码：000021），连续七年位列MMI全球EMS企业排名前列（2010-2016），是中国500强、深圳市工业百强企业。\r\n', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('623', '66', 'JXINHE-2559', '2019-02-18 14:03:16', '2019-02-18 14:49:47', 'khxx20190218711/Islamabad Energy Supply Company', 'khxx20190218711', 'Islamabad Energy Supply Company', 'IESCO', '亚洲', '巴基斯坦', 'http://www.iesco.com.pk', 'Street No.40, Sector G-7/4, Islamabad Pakistan', '巴基斯坦首都伊斯兰堡电力公司，管理270万用户，共计5个区，19个部门。', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('624', '66', 'JXINHE-2559', '2019-02-19 15:50:30', '2019-02-19 16:19:01', 'khxx20190219712/成都长城开发科技有限公司\r\n', 'khxx20190219712', '成都长城开发科技有限公司', '长城开发', '亚洲', '中国', 'www.kaifametering.com', '四川省成都市高新区（西区）合作路1218号\r\r\n', '成都长城开发科技有限公司（以下简称“深科技成都公司”），是深圳长城开发科技股份有限公司（以下简称 “深科技”，证券代码：000021）的下属控股子公司，前身为深科技的计量系统事业部（1995年-2016年），是集研发、生产、销售、服务为一体的智能计量产品及能源管理解决方案提供商', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('625', '61', 'INHE-0725', '2019-02-20 09:50:09', '2019-02-20 10:15:25', 'khxx20190220713/ACOB Lighting Technology Limited', 'khxx20190220713', 'ACOB Lighting Technology Limited', 'ACO', '非洲', '尼日利亚', 'www.acoblighting.com', 'Abuja, Nigeria', 'ACOB Lighting Technology Limited主要在尼日利亚和非洲地区推广可持续LED产品（LED灯）、可再生能源和通用电气化项目。目前正在借由微型电网项目推动其在尼日利亚地区的业务发展。同时ACOB是AMDA:Africa Mini-grid Developers Association (由11家盈利性主营微型电网项目的公司组成的协会组织）的一员，ACOB的President Mr Alexander同时是AMDA的两名执行秘书之一。', '赵政洁(Oscar)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('626', '61', 'INHE-0431', '2019-02-25 09:36:32', '2019-02-25 10:23:37', 'khxx20190225715/Powerline Solutions&Investments Ltd.', 'khxx20190225715', 'Powerline Solutions&Investments Ltd.', 'PSI', '非洲', '乌干达', '', 'Plot 772, Lutaaya Drive, Bukoto P.O. Box 6254 Kampala, Uganda\r\n', '客户主要从事的是配电项目相关的安装工作的公司，有过农网和UMEME项目执行经验', '刘佩(Ted)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('627', '66', 'INHE-0774', '2019-03-01 10:24:14', '2019-03-01 10:39:59', 'khxx20190301718/TIMELPROEKT DOOEL', 'khxx20190301718', 'TIMELPROEKT DOOEL', 'TIMELPROEKT\r\r\n', '欧洲', '马其顿', 'http://www.timel.com.mk', 'Misko Mihajlovski Street, 52\r\nPO Box 338\r\n1000 Skopje, Macedonia', '成立于1998年，主营输电、配电系统，变电站，工厂的设计，建设安装，维护测试，咨询等，新能源系统和能源管理系统设计和实施。他们有意向在EVN项目中和我们合作，帮我们跟EVN联系，如果我们中标可以为我们提供服务和支持。', '何森华', '业务三部', null, null, 'E', 'INHE');
