INSERT INTO `inhe_customer_data` VALUES ('631', '60', 'INHE-0781', '2019-03-14 03:23:16', '2019-03-14 09:31:41', 'khxx20190314726/Northern Electricity Supply Company Limited', 'khxx20190314726', 'Northern Electricity Supply Company Limited', 'NESCO', '亚洲', '孟加拉国', 'www.nesco.gov.bd', '', '近两年新成立电力公司，由BPDB分离出去，负责孟加拉西北地区供电，用户数约110万。', '李启坦', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('632', '66', 'INHE-0774', '2019-03-14 08:34:03', '2019-03-14 10:17:03', 'khxx20190314727/ESO AB', 'khxx20190314727', 'ESO AB', 'ESO', '欧洲', '立陶宛', 'https://www.eso.lt', 'Virsuliskes crossroads 34', 'Energy Distribution Operator AB（ESO)成立于2016年1月1日，合并LESTO AB和一家股份公司Lietuvos Dujos。 ESO由国有能源公司“Lietuvos Energija”控制，该公司是波罗的海国家最大的能源公司之一。\r\nESO的主要业务：电力供应和分配，天然气分配，电力和天然气供应保障，电力和天然气的引入，电力和燃气配电网络的维护和发展，能源分配保证的安全性和可靠性。\r\nESO为立陶宛的160万客户提供服务。\r\n', '何森华', '业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('633', '66', 'INHE-0774', '2019-03-14 10:28:42', '2019-03-14 10:35:44', 'khxx20190314729/UAB Verslo aptarnavimo centras', 'khxx20190314729', 'UAB Verslo aptarnavimo centras', 'VAC', '欧洲', '立陶宛', 'http://vac.le.lt', 'P. Luksio g. 5B, 08221 Vilnius', 'Verslo Aptarnavimo Centras UAB（VAC）隶属于国家控制的国家能源集团Lietuvos Energija（以下简称集团）。该公司成立于2014年，旨在改善支持本集团核心业务的流程并降低成本。\r\n\r\nVAC的活动旨在通过提供公共采购，会计和劳务关系管理服务来支持和服务集团公司。通过将服务功能集中在一家公司，VAC团队由上述集团公司授权的所有领域的专家组成。\r\n\r\n通过集中公共采购，会计和劳动关系管理流程，VAC正在努力使其标准化，提高透明度和效率，并确保其完成。该支持服务集中模型符合世界上应用的最佳实践。\r\n\r\n提供专业服务的公司的成立标志着实施集团公司治理模式的重要一步。它为实现2014年至2020年Lietuvos Energija的战略目标提供了大量可能性，即集团公司活动的多样化，提高运营效率，形成新的组织文化。', '何森华', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('634', '61', 'INHE-0695', '2019-03-20 14:11:57', '2019-03-20 15:48:55', 'khxx20190320732/Verslo Aptarnavimo Centras			\r\n', 'khxx20190320732', 'Verslo Aptarnavimo Centras', 'VAC', '欧洲', '立陶宛', '\rhttp://vac.le.lt\r\n\r\r\n', 'P. Luksio g. 5B, 08221 Vilnius\r\r\r\n', 'ESO母公司Lietuvos Energija (Lithuania Energy-立陶宛能源)旗下的子公司之一，专门负责为立陶宛能源集团提供公共采购，财会，人力行政管理服务。\r\n', '卿于蓝', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('635', '66', 'INHE-0579', '2019-03-26 09:30:15', '2019-03-26 09:58:59', 'khxx20190326734/The Green Pact SAL', 'khxx20190326734', 'The Green Pact SAL', 'TGP', '亚洲', '黎巴嫩', 'https://www.thegreenalliance.co.uk/', '6th floor, Sodeco 5 building, Petro Trad street, Yessouieh sector Beirut Lebanon\r\r\r\n', '1. The Green Pact 致力于可再生资源，清洁能源的项目，在黎巴嫩进行光伏产品的项目。\r\r\n2. 该公司实施EPC项目，包括光伏设备的建立，发电机设备的建立，并网工作等。\r\n3.该客户为集团公司，包括Green Future, The Green Pact, Green Arms, Rational Financial以及RNA energy。', '孙娜', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('636', '66', 'INHE-0774', '2019-03-26 10:29:08', '2019-03-26 10:51:32', 'khxx20190326735/UTE d.o.o.', 'khxx20190326735', 'UTE d.o.o.', 'UTE', '欧洲', '克罗地亚', 'http://www.ute.hr/', 'Flaciusova 1\r\nHR-52100 Pula', 'UTE是一家私人有限责任公司，从事电气设备的设计，生产和销售。1975-1997年间该公司作为Uljanik造船厂电气设备和电子设备的制造商出现在世界市场上。1997年以来，公司继续从事自己的生产活动并独立为一家私有的有限公司。\r\n目前该公司的主要领域是可再生能源、工业自动化、轮船电气系统和驻车设备&E-bIke', '何森华', '业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('637', '66', 'INHE-0774', '2019-03-26 10:34:29', '2019-03-26 10:51:20', 'khxx20190326736/AEM S.A.', 'khxx20190326736', 'AEM S.A.', 'AEM', '欧洲', '罗马尼亚', 'http://www.aem.ro/', 'Piata General Gheorghe Domasnean nr. 5, Timisoara', 'AEM成立45年以来主要生产和销售电能表和气表，也生产部分配电设备。想从我们直接采购配件和特定项目中的电表。', '何森华', '业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('638', '66', 'INHE-0774', '2019-03-26 10:38:12', '2019-03-26 10:51:01', 'khxx20190326737/POZYTON', 'khxx20190326737', 'POZYTON', 'POZYTON', '欧洲', '波兰', 'http://www.pozyton.com.pl', 'Poland, 42-202 Czestochowa, ul. Staszica 8 ', 'POZYTON是波兰电子测量设备制造商，公司总部位于Cz?stochowa。\r\r\n该公司成立于1989年，是一家致力于研究电子新技术的工程集团，专注于开发真正独特的设备，用于测量电路功率，电流和能量消耗。 该公司最初只生产简单的设备，但多年来POZYTON的单一产品线扩展为各种具有广泛测量能力的精密电子仪表。目前有一个标，但是没发满足要求机会不大，希望合作以后的项目。现在想要我们的样机了解我们产品。 ', '何森华', '业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('639', '66', 'INHE-0774', '2019-03-26 10:41:36', '2019-03-26 10:50:46', 'khxx20190326738/Elektrocentar Petek', 'khxx20190326738', 'Elektrocentar Petek', 'Elektrocentar Petek', '欧洲', '克罗地亚', 'www.ecp.hr', 'Etanska cesta 8 · HR-10310 Ivani?-Grad', 'Elektrocentar Petek 是电厂建设，低压输电和各种电力安装，照明安装，电动机和系统管理的领军企业。\r\n该公司由一家传统的私人企业，现发展为克罗地亚在电力，电信和建筑领域中提供服务和工程实施的领军企业之一。也销售电气设备，建筑材料和设备。 HR商会代表处主任介绍合作HRV项目，对方一直未联系谈合作的事情。近期发邮件说当地有个通信模块采购的标，要我们报价', '何森华', '业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('640', '61', 'INHE-0770', '2019-03-26 17:46:22', '2019-03-26 18:22:01', 'khxx20190326739/Ethiopian Electric Power,\r\n', 'khxx20190326739', 'Ethiopian Electric Power,', 'EEP', '非洲', '埃塞俄比亚', 'http://www.eep.gov.et\r\n', 'P.O.Box , Addis Ababa, Ethiopia\r\r\n', '埃塞俄比亚电力公司是埃塞俄比亚联邦民主共和国的国有电力生产商。它从事发电厂，发电和输电的开发，投资，建设，运营和管理。该公司是埃塞俄比亚能源部门的主要参与者。 埃塞俄比亚电力公司拥有并运营埃塞俄比亚国家电网，所有高压输电线路均高于66千伏，包括所有连接的变电站和几乎所有国家电网内的发电厂。\r\n', '刘博', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('641', '61', 'INHE-0770', '2019-03-26 18:03:04', '2019-03-26 18:21:43', 'khxx20190326740/ZOBIL GLOBAL BUSINESS\r\n', 'khxx20190326740', 'ZOBIL GLOBAL BUSINESS', 'ZGB', '非洲', '埃塞俄比亚', '', 'CMC, Near Michael Church, Leoul Taz Building, 4th Floor, Office No 403\r\r\r\r\nP.o.box 24465, Addis Ababa, Ethiopia\r', '该公司于2003年成立，位于埃塞俄比亚，主要和政府部门(EEPCO，后分成两部分EEPO和EEU)合作，有成功向电力公司销售过输电变压器，开关设备，保险丝的案例。注册资本11万人民币左右。\r\n', '刘博', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('642', '60', 'INHE-0434', '2019-03-27 12:27:22', '2019-03-27 12:46:02', 'khxx20190327741/HIMVEST HOLDING', 'khxx20190327741', 'HIMVEST HOLDING', 'HM', '非洲', '摩洛哥', 'http://himvestholding.com/', '5, rue Chevalier Bayard, Roches Noires, Casablanca, Maroc.', '1. 客户当前主要从事投资，有自己的矿业，同时也做汽车修理，房地产\r\r\r\r\n2. 客户在卡萨布兰卡有自己的一栋楼，在Grand Mogador酒店附近。楼高7层，1~6层出租，客户办公室在第7层。\r\r\r\r\n3. 客户帮引荐了ONEE负责特高压/高压的技术负责人Abdulhaldi先生，于发标前提供了项目标书。\r\r\r\r\n4. 客户在不同的工业园分别有一块2000平方米和2200平方米的地，有意投资建厂。\r\n5. 据了解，客户的前妻是国王的妹妹。客户有跟北方国际，中国中车合作项目。\r\n\r\n\r\r\n\r\r\n\r\n\r\r\n\r\r\r\n', '钟云林(Andy)', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
