INSERT INTO `inhe_customer_data` VALUES ('645', '61', 'INHE-0432', '2019-04-02 14:25:33', '2019-04-02 14:38:34', 'khxx20190402748/Intrasoft International SA', 'khxx20190402748', 'Intrasoft International SA', 'Intrasoft', '欧洲', '希腊', 'https://www.intrasoft-intl.com/', '希腊雅典', '欧洲领先的IT方案和服务供应商，在世界多个国家有自己的分公司，2016年汤伟和郭总监有去拜访，讨论希腊市场合作事宜。对希腊电力公司及电力市场情况很熟悉，也是电表及集抄项目的主要玩家之一。目前其主要的合作伙伴，有SAGEMCOM和EDMI。但其负责人认为SAGEMCOM和EDMI的价格太高，在找合适的替代者。Intrasfot和其兄弟公司Intracom出自同一家集团公司，也是目前市场上的主要竞争对手。而电力公司对于大型集抄项目，也是更倾向于同这两家公司合作。\r\r\n', '谭东羊(Timon)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
