INSERT INTO `inhe_customer_data` VALUES ('647', '61', 'INHE-0776', '2019-04-03 15:27:21', '2019-04-03 15:31:35', 'khxx20190403750/Tecsur S.A\r\n', 'khxx20190403750', 'Tecsur S.A', 'Tecsur', '南美洲', '秘鲁', 'http://www.tecsur.com.pe/\r\n', '', '秘鲁国家电力局LDS的电力采购和电力项目实施公司，由LDS决定技术需求，Tecs\r\nur按照要求采购和施工。', '李玟', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('648', '66', 'INHE-0774', '2019-04-03 17:35:50', '2019-04-03 17:59:58', 'khxx20190403751/SOCIETATEA DE DISTRIBUTIE A ENERGIEI ELECTRICE MUNTENIA NORD S.A.', 'khxx20190403751', 'SOCIETATEA DE DISTRIBUTIE A ENERGIEI ELECTRICE MUNTENIA NORD S.A.', 'SDEE Distributie Muntenia Nord SA', '欧洲', '罗马尼亚', 'www.mnd.distributie-energie.ro#FE54`', '44, Marasesti st, Ploiesti, county Prahova', 'SOCIETATEA DE DISTRIBUTIE A ENERGIEI ELECTRICE MUNTENIA NORD S.A.（SDEE Muntenia Nord）是Electrica集团的一部分，是为Muntenia北部提供服务的配电运营商。 该公司在Vrancea，Galati，Buzau，Braila，Prahova和Dambovita县开展业务，覆盖面积约29.000平方公里。\r\r\r\n凭借120年的传统，SDEE Muntenia Nord通过一个长度超过73,000公里的分销网络和超过2.260名员工，为约130万消费者提供服务。', '何森华', '业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('649', '61', 'INHE-0840', '2019-04-03 18:35:20', '2019-04-04 08:28:19', 'khxx20190403752/Enterprise Data Services Ltd\r\n', 'khxx20190403752', 'Enterprise Data Services Ltd', 'EDS', '非洲', '毛里求斯', 'http://www.eds.mu\r\n', '24 Dr Roux Street, Rose-Hill\r\r\nRepublic of Mauritius\r\r\n', '1999年成立，为企业和政府部门提供电力电信设备及解决方案，公司员工45人\r\n', '冯敏杰', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('650', '66', 'INHE-0634', '2019-04-04 11:50:26', '2019-04-04 14:00:58', 'khxx20190404753/Mandalay City Development Committee', 'khxx20190404753', 'Mandalay City Development Committee', 'MCDC', '亚洲', '缅甸', 'https://www.myanmarwaterportal.com/pages/136-mcdc/info.html\r\n', '', 'MCDC曼德勒市发展委员会是缅甸第二大城市曼德勒的行政机构。 MCDC负有广泛的责任，包括城市规划，土地管理，税收和城市发展。 MCDC通过税收，费用，许可证和房地产开发来增加自己的收入。 MCDC的主席担任曼德勒市市长，并担任曼德勒地区政府的市政部长。 MCDC目前由市长Ye Lwin担任主席。\r\r\n', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('651', '61', 'INHE-0431', '2019-04-08 10:25:17', '2019-04-08 10:29:59', 'khxx20190408755/cyberteq', 'khxx20190408755', 'cyberteq', 'CYB', '欧洲', '波兰', 'www.cyberteq.com', 'Przy Bramie，Grzybowska 62, 2nd floor，Warsaw 00-844\r\r\n', '该客户是做ICT设备的，在波兰和阿联酋以及新加坡和卢旺达有分公司', '刘佩(Ted)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('652', '60', 'INHE-0535', '2019-04-14 17:03:14', '2019-04-15 08:32:29', 'khxx20190414758/NICE PROJECTS LIMITED\r\n', 'khxx20190414758', 'NICE PROJECTS LIMITED', 'NICE', '亚洲', '印度', 'www.niceppl.com', '201, Aggarwal Okhla Plaza, 2nd Floor, 15, Community Center, Okhla Industrial Area, Phase-1, New Delhi-110020, India. \r\r\r\n', '该公司主要涉及工程建设项目，比如建筑，水泵，电力，重型钢制造等，Naftogaz对该公司持有25%股份。因为该公司有电力行业项目的经验，便于开立保函，因此被建议用来合作UPD项目。\r\n', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('653', '61', 'INHE-0819', '2019-04-17 06:35:21', '2019-04-17 08:26:13', 'khxx20190417761/马达加斯加电力公司', 'khxx20190417761', '马达加斯加电力公司', 'jirama', '非洲', '马达加斯加', 'www.jirama.com', '13,rue rabezavana,siag 15 bis ambodifilao,antananarivo,madagascar', 'JIRAMA成立于1975年10月17日，部位于首都塔那那利佛，直到1999年，他都是该国唯一的国有电力公司。1999年之后，JIRAMA继续垄断配电网络。2018年6月，JIRAMA正在考虑修复其配电网络。', '付为(Adam)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('654', '61', 'INHE-0805', '2019-04-17 16:57:06', '2019-04-17 17:55:59', 'khxx20190417774/Blindobarras By Cedal Cia Ltda .', 'khxx20190417774', 'Blindobarras By Cedal Cia Ltda .', 'Blindobarras', '南美洲', '厄瓜多尔', 'https://www.blindobarras.com/', 'Av. De la Prensa N51-270 y Florida, Quito, Ecuador, 170104', '厄瓜多尔市场新开发代理商。国企股东背景，资金实力比较雄厚。主要负责人Cesar曾经主持过银河产品在哥伦比亚的认证工作，对我司产品熟识度高。合作意愿强烈，预计可助我司尽快打开厄瓜多尔市场。', '翁达', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('655', '61', 'INHE-0500', '2019-04-18 12:57:39', '2019-04-18 13:26:21', 'khxx20190418775/SAP Technologies PTY LTD\r\n', 'khxx20190418775', 'SAP Technologies PTY LTD', 'SAP', '非洲', '莱索托', 'N/A', 'Metcash Room 145A,Maseru,Lesotho', '1.成立于2017年，主营业务为电器和电子类设备经销商；\r\r\n2.公司的老板Papiso Rakhoboso为莱索托电力公司LEC董事会主席的妻弟，通过内部关系取得了部分电力公司的项目；\r\n3.LES招标发布前其找到银河告知近期会有智能电表和系统的招标，询问合作机会。\r\n', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('656', '61', 'INHE-0500', '2019-04-18 13:11:18', '2019-04-18 13:25:51', 'khxx20190418776/LESOTHO ELECTRICITY COMPANY (PTY) LTD\r\n', 'khxx20190418776', 'LESOTHO ELECTRICITY COMPANY (PTY) LTD', 'LEC', '非洲', '莱索托', 'www.lec.co.ls\r\n', '53 Moshoeshoe Road, Industrial Area, Maseru, Lesotho Postal: P.O. Box 423, Maseru 100\r\r\n', '1.莱索托国家电力公司，国有企业性质，负责全国独家输售配电业，用户总数约21万，其中22万约普通居民用表，约1万个LPU用户，全国通电率约47%；\r\r\n\r\r\n2.当前电表供应商主要为兰吉尔和Conlog，以及部分Itron电表，供应商主要来自南非本地；\r\r\n3.当前售电系统供应商为兰吉尔；\r\r\n4.此市场潜在的竞争对手为：兰吉尔，Conlog，Ontect(Itron),EDMI和海兴。', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('657', '66', 'INHE-0628', '2019-04-26 09:53:20', '2019-04-26 09:53:20', 'khxx20190426779/Modern Scientific & Electronics Co., Ltd.', 'khxx20190426779', 'Modern Scientific & Electronics Co., Ltd.', 'MOSECO', '亚洲', '约旦', 'http://www.mosecogroup.com/', 'P.O. Box: 1914, Amman 11941, Jordan', 'MOSECO总部在约旦，同时在巴勒斯坦、沙特和卡塔尔设有分支机构，业务范围在中东地区，员工有1200人。目前业务主要为，通讯、石油、电力、新能源、电信。合作伙伴和客户有Vodafone、MTN、电力局等。已经向约旦电力局供货太阳能、电池和通讯等产品。', '刘元豪', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('658', '61', 'INHE-0431', '2019-04-26 20:57:40', '2019-04-28 08:45:15', 'khxx20190426780/TBEA Uganda', 'khxx20190426780', 'TBEA Uganda', 'TBEA', '非洲', '乌干达', 'www.tbea.com.cn', 'Plot 44， Solent Ave, Mbuya,Kampala, Uganda', '特变电工股份有限公司 （乌干达项目部） 特变在乌干达农网取得一个2亿美金的配网EPC工程，里面包含15万只电表', '刘佩(Ted)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('659', '60', 'INHE-0560', '2019-04-30 11:15:29', '2019-04-30 11:26:40', 'khxx20190430781/ООО \"энергопромсис\"', 'khxx20190430781', 'ООО \"энергопромсис\"', 'Энергопромсис', '欧洲', '乌克兰', 'https://youcontrol.com.ua/ru/catalog/company_details/38864924/', '01014 CITY KYIV STREET ZVIRYNETSKA BUILDING 63', 'ООО энергопромсис主要从事的贸易领域有：自动化能源商业核算系统\r\n电表EMH，Elster，ZMD，Actaris\r\n项目安装，启动和调整工作在信息系统的实施上\r\n油分析仪MTE\r\n型号计数器，校准器和校准支架MTE，Zera，Actaris\r\nShield Digital Devices Satec\r\n电能质量分析仪LEM，Fluke\r\n补偿装置Nokian电容器\r\n测量仪器\r\n信息系统\r\n计量与标准化', '李美娇', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('660', '61', 'INHE-0654', '2019-05-05 15:21:46', '2019-05-05 15:34:27', 'khxx20190505783/ADMINISTRACION NACIONAL DE ELECTRICIDAD(ANDE)', 'khxx20190505783', 'ADMINISTRACION NACIONAL DE ELECTRICIDAD(ANDE)', ' ANDE', '南美洲', '巴拉圭', 'http://www.ande.gov.py/', 'Padre Egidio Cardozo 1268, Asunción, 巴拉圭', '巴拉圭国家电力公司，主要经营输电和配电，是该国唯一一个电力公司，员工人数约为5千。', '李明(Ming)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('661', '61', 'INHE-0805', '2019-05-06 18:15:34', '2019-05-07 08:36:44', 'khxx20190506784/ELECTROHUILA S.A. E.S.P.', 'khxx20190506784', 'ELECTROHUILA S.A. E.S.P.', 'ELECTROHUILA', '南美洲', '哥伦比亚', 'http://www.electrohuila.com.co/\r\n', 'Palermo, Huila, Colombia', '我司在哥伦比亚重要的目标电力公司。20万用户规模，未来五年用于AMI投资预计达1000万美元。与我司哥伦比亚代理有着良好的客户关系！						\r\n', '翁达', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('662', '61', 'INHE-0721', '2019-05-16 13:47:43', '2019-05-16 14:24:45', 'khxx20190516786/Administración Nacional de Usinas y Trasmisiones Eléctricas\r\n', 'khxx20190516786', 'Administración Nacional de Usinas y Trasmisiones Eléctricas', 'UTE', '南美洲', '乌拉圭', 'https://portal.ute.com.uy/\r\n', 'Palacio de la Luz\r\r\nParaguay 2431 C.P. 11.800\r\r\n\r\r\nMontevideo\r\r\nRepública Oriental del Uruguay\r\r\n\r\r\n', 'UTE是乌拉圭国有公司，致力于发，输，配电和售电，提供配套服务和咨询。为了满足位于全国176,215平方公里的120万客户的需求，UTE拥有水力，风力和热力发电厂。来自萨尔托格兰德水电站（阿根廷和乌拉圭之间的两国合资企业）的能源以及来自第三方拥有的发电厂的能源补充UTE产能。\r\r\n', '胡云义(Anita)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('663', '61', 'INHE-0776', '2019-05-20 14:42:15', '2019-05-20 16:40:55', 'khxx20190520787/HIDRANDINA S.A.', 'khxx20190520787', 'HIDRANDINA S.A.', '', '南美洲', '秘鲁', 'https://www.distriluz.com.pe/hidrandina/', '	JR. SAN MARTIN NRO. 831\r\n', '秘鲁国有特许经营配电公司之一，现有87万用户，2017年财报显示其总资产为5亿美元，负债2亿美元，年营业收入2.8亿美元，年净利润3000万美元，年毛利润率为8.8%；其是秘鲁国有电力集团Distriluz的全资子公司，旗下有共四家子公司，分别为：HIDRANDINA, ELECTRONORTE, ELECTROESTE, ELECTROCENTRO四家电力公司，共有超过260万用户，客户数量占秘鲁市场的31%份额。', '李玟', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('664', '61', 'INHE-0381', '2019-05-24 16:33:43', '2019-05-24 16:46:14', 'khxx20190524788/GE Power', 'khxx20190524788', 'GE Power', 'GE', '欧洲', '法国', 'www.gegridsolutions.com/', '102 avenue de Paris | 91300 Massy, France', '通用电气公司，即美国通用电气公司（General Electric Company，简称GE，创立于1892年，是世界上最大的提供技术和服务业务的跨国公司。自从托马斯·爱迪生创建了通用电气公司以来，GE在公司多元化发展当中逐步成长为出色的跨国公司。目前，公司业务遍及世界上100多个国家，拥有员工315,000人。', '张柳芳(Alexie)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('665', '60', 'INHE-0535', '2019-05-26 19:17:41', '2019-05-27 08:56:07', 'khxx20190526789/Redington India Ltd', 'khxx20190526789', 'Redington India Ltd', 'Redington', '亚洲', '印度', 'www.redington.com', 'Kamak Towers 2nd Floor No.. 12 A,, Thiru Vi Ka Industrial Estate Guindy, Chennai, Tamil Nadu 600032\r\n', '总部位于美国,智能IoT云解决方案供应商，可提供相关硬件软件，去年全球总营收60亿美元；业务范围涵盖中东，非洲，斯里兰卡，新加坡等，过去2年内开始进军印度本地云业务，与Amazon，IBM，Microsoft开展合作，已在印度成功实施过智能水表解决方案。也有意向拓展基于云的智能计量市场。', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('666', '60', 'INHE-0535', '2019-05-26 19:21:15', '2019-05-27 08:56:19', 'khxx20190526790/Blue Ocean Systems Infotech Pvt. Ltd.', 'khxx20190526790', 'Blue Ocean Systems Infotech Pvt. Ltd.', 'Blue Ocean', '亚洲', '印度', 'www.blueoceansystems.in\r\n', '1208, 12th Floor,  Rupa Solitaire,\r\nPlot No. A-1, Sector-1,\r\nMillennium Business Park,\r\nMahape, Navi Mumbai - 400710.\r\n', '总部在美国，成立于2005年。主营兼容业务解决方案，致力于能源，连接，交通，电力公司等领域的IoT, IIoT, 智能城市解决方案，云方案，SAP等。尤其在电力公司方面，Blue Ocean有SAP数据迁移至云，资产调查，变电站监控等实施执行经验。\r\r\n', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('667', '61', 'INHE-0725', '2019-05-27 10:08:02', '2019-05-27 10:51:52', 'khxx20190527791/Energy-Lux', 'khxx20190527791', 'Energy-Lux', 'EL', '非洲', '埃及', 'www.energy-lux.com', '7 El Nozha street, Nasr city, Cairo, Egypt.', '该公司于四年前成立，主做LED灯及防火报警设备，中压配电设备及线缆等产品，在当地市场协助国外厂商拓展业务，老板Mr Hatem在El Sewedy (Ahemd一脉）以项目总监职位工作20年以上，积累了丰富的客户资源，公司实力较强，目前正与其洽谈EIA市场本地建厂合作事宜，', '赵政洁(Oscar)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('668', '61', 'INHE-0725', '2019-05-27 10:43:10', '2019-05-27 11:01:15', 'khxx20190527792/Alexander Electricity Distribution Company', 'khxx20190527792', 'Alexander Electricity Distribution Company', 'AEDC', '非洲', '埃及', 'http://aedc.gov.eg/', 'Sidi El Metwally St., El Attarin, 9 Alexander, Egypt', 'Alexander Electricity Distribution Company是埃及市场九家电力公司之一，目前管理用户260万，未来一年预计采购电表25万台，在当地九家电力公司中实力位居前列，受当地电力行业主管部门Egyptian Electricity Holding Company（EEHC）管辖，在今年9-10月份预计招收10万台预付费IC卡表', '赵政洁(Oscar)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('669', '61', 'INHE-0381', '2019-05-31 13:32:31', '2019-05-31 16:53:15', 'khxx20190531797/SIECOM', 'khxx20190531797', 'SIECOM', 'SIE', '亚洲', '缅甸', 'http://www.siecom.co.kr/', '', '韩国公司，1970年成立，主要做电力设备产品，如变压器、保险系、断路器以及一些管理系统。', '张柳芳(Alexie)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('670', '61', 'INHE-0840', '2019-06-05 00:26:05', '2019-06-12 16:56:57', 'khxx20190605799/Ceyma - Solu??es Energéticas e Manuten??o Industrial, Lda', 'khxx20190605799', 'Ceyma - Energy Solutions and Industrial Maintenance, Lda', 'CML', '非洲', '安哥拉', '', 'Zona Industrial de Viana, (Rua da Maxi), Block B\r\r\nMunicipality of Viana\r\r\nProvince of Luanda\r\r\nrepublic of Angola\r\r\n', '2015年成立的当地公司，主营承接电力公司或电力项目承包商的电表安装与连接等业务，老板R先生从有60多年经营电力项目历史的Ambergol出身，与其Ceyma的老板合作发展业务，他们在电力行业人脉广泛，并与电力公司及能源部长经营着良好的关系，寻求与我司合作向电力公司及其承包商提供电表及系统业务，目前接到承包商ANERGY的订单13000台电表，本月内先下6500台，合作成功后续会有更多的项目机会', '冯敏杰', '国际二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('671', '66', 'JXINHE-2559', '2019-06-14 11:36:32', '2019-06-14 11:40:35', 'khxx20190614801/Rotax Ltd.com\r\n', 'khxx20190614801', 'Rotax Ltd.com', 'Rotax', '亚洲', '斯里兰卡', '', 'No,332, Galle Road，Colombo 04, Sri Lanka.', '公司成立于1963年，拥有23年的投标经验，拥有200名以上的员工的家族式企业，从事于电力产业，产品包括，开关、控制面板，计量控制和保护装置，校准设备，测试设备，输变电系统的测试和维护设备，实验室设备，照明，工业马达，线缆，工业化集成，电力材料配件，中低压电容等，为西门子、SOCOMEC、TERASAKI,TECS等品牌的当地经销商。\r\r\n', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('672', '61', 'INHE-0843', '2019-06-14 13:35:25', '2019-06-14 14:02:59', 'khxx20190614802/西电国际', 'khxx20190614802', '西电国际', '西电', '南美洲', '厄瓜多尔', 'http://www.xianelectric.com.cn\r\r\n', '厄瓜多尔基多办事处', '西安西电国际工程有限责任公司（简称“西电”）创立于1986年，是中国西电集团控股的国际承包和对外贸易企业，主营输配电国际工程承包，2012年起在厄瓜多尔开设办事处，开始做输变电和配电项目，目前有7000万美元项目在执行。西电在厄瓜多尔运作多年，与当地电力局有十分密切的关系，可以帮助我司尽快打开厄瓜多尔市场。', '刘畑杏(Laura)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('673', '61', 'INHE-0843', '2019-06-14 14:06:42', '2019-06-14 14:32:29', 'khxx20190614803/基多电力局', 'khxx20190614803', 'Empresa Eléctrica Quito S.A.', 'EEQ', '南美洲', '厄瓜多尔', 'https://www.eeq.com.ec\r\n', 'Av. 10 de Agosto y Bartolomé de las Casas, Quito\r\r\n', 'EEQ（Empresa Eléctrica Quito S.A.）是厄瓜多尔四大电力公司之一，成立于1955年，隶属厄瓜多尔电力和可再生能源部。主要为厄瓜多尔首都及其附近省份生产和供应电力。EEQ运营着水电站、热电厂；拥有配电变电站40座，输电线路700公里。除其他服务外，EEQ还负责公共照明系统的保养及维修等。', '刘畑杏(Laura)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('674', '61', 'INHE-0843', '2019-06-14 14:18:59', '2019-06-14 14:27:52', 'khxx20190614804/DISGARPAR S.A.', 'khxx20190614804', 'DISGARPAR S.A.', 'DISGARPAR', '南美洲', '厄瓜多尔', '', 'Mz. 170 Dpto. C4 Dpto. C4, Condominio los Olmos Bldg. Guayaquil#FE54` Guayas\r\r\n', 'DISGARPAR成立于1996年，家族式企业，从事电力行业15年，主营中高压输变电材料及设备，与当地电力局有多年的密切关系，是厄瓜多尔四大电力局之一CENTROSUR的供应商。', '刘畑杏(Laura)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('675', '61', 'INHE-0843', '2019-06-14 15:00:02', '2019-06-14 16:44:15', 'khxx20190614805/ElecGalapagos S.A.', 'khxx20190614805', 'ElecGalapagos S.A.', 'ElecGalapagos', '南美洲', '厄瓜多尔', 'www.elecgalapagos.com.ec', 'Galapagos, Ecuador', 'ElecGalapagos是在厄瓜多尔加拉帕戈斯省的省电力局，主营电力生产、运输、分配和商业化，从事配电网项目、系统、设施、厂房的规划、建设、开发、扩建、管理、购销、租赁以及实施替代能源的各项活动；以及与电能和替代能源相关的机械设备和设施的操作和维护。', '刘畑杏(Laura)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('676', '60', 'INHE-0535', '2019-06-20 17:41:58', '2019-06-21 08:41:56', 'khxx20190620810/ Al Mostajed Technologies \r\n', 'khxx20190620810', 'Al Mostajed Technologies', 'AMT', '亚洲', '阿联', 'www.gblenergy.com\r\n', 'Unit MA4, Jebel Ali Free Zone, Dubai, United Arab Emirates', '该公司总部位于英国，在中东设有区域办事处。是发电，输电，配电，自动化，智能电网，石油化学加工，水利项目等的总解决方案供应商。提供各种EPC工程，项目管理，项目设计，兼容，测试，运维，安装，售后服务，培训等服务。', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('677', '60', 'INHE-0535', '2019-06-20 18:25:43', '2019-06-21 08:42:26', 'khxx20190620811/Lahore Electric Supply Company Limited\r\n', 'khxx20190620811', 'Lahore Electric Supply Company Limited', 'LESCO', '亚洲', '巴基斯坦', '', 'Lahore Electric Supply Company\r\nChief Engineer (Development), PMU, LESCO\r\nStreet No. 132 KV Qartaba Grid Station, Mozang, Bahawalpur Road, Lahore.\r\nPostal Code: 54600\r\nCountry: Pakistan\r\n', '巴基斯坦政府（GoP）正在启动一项在亚行资助下的巴基斯坦电力公司的大规模AMI规划。 投资计划分阶段实施，目标是在巴基斯坦的主要城市和工业活动中心实现重大的AMI覆盖。该项目的第一阶段旨在覆盖Lahore（LESCO）地区的170万消费者。LESCO电力公司覆盖以下8个配电区域：North Lahore  Circle#FE54`Central Lahore Circle#FE54`Eastern Lahore  Circle#FE54`Okara Circle#FE54`South-Eastern LHR Circle#FE54`Sheikhupura Circle#FE54`Kasur Circle#FE54`Nankana Circle\r\r\n', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('678', '60', 'INHE-0868', '2019-06-20 18:25:20', '2019-06-21 08:42:41', 'khxx20190620812/Rotax Pvt Ltd\r\n', 'khxx20190620812', 'Rotax Pvt Ltd', 'Rotax', '亚洲', '斯里兰卡', 'www.rotaxltd.com', 'No,332, Galle Road\r, Colombo 04, Sri Lanka\r\r\r\r\n', 'Rotax Pvt Ltd 公司成立于1963年，拥有23年的投标经验，拥有200名以上的员工的家族式企业，从事于电力产业，产品包括，开关、控制面板，计量控制和保护装置，校准设备，测试设备，输变电系统的测试和维护设备，实验室设备，照明，工业马达，线缆，工业化集成，电力材料配件，中低压电容等，为西门子、SOCOMEC、TERASAKI,TECS等品牌的当地经销商。\r\r\r\n', '庄钦', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('679', '66', 'JXINHE-2559', '2019-06-25 14:11:40', '2019-06-25 15:18:19', 'khxx20190625815/Hellenic Electricity Distribution Network Operator', 'khxx20190625815', 'Hellenic Electricity Distribution Network Operator', 'HEDNO', '欧洲', '希腊', 'www.deddie.gr\r\n', '20 Perraivou & 5 Kallirrois str.\r\r\n117 43 Athens', 'PPC SA的合资子公司，希腊电力配电网络运营商，负责管理营运希腊32非连接岛屿的电力系统，约占全国人口的15%和总营收的14￥。', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('680', '66', 'JXINHE-2559', '2019-06-25 14:50:22', '2019-06-25 15:18:09', 'khxx20190625816/Protasis Engineering*Consulting ', 'khxx20190625816', 'Protasis Engineering*Consulting', 'PROTASIS', '欧洲', '希腊', 'http://www.protasis.net.gr/\r\n', '59B Apostolopoulou st. 15231 Chalandri, Athens, Greece', 'Protasis 是一家电能系统工程和顾问公司，公司成立于2002年，致力于向电力公司的输配部门，发电公司，工业企业等提供能源解决方案。业务涉及发电，绿色能源，电能输送，工业包括油气，石化，钢铁，铝等。公司为电力保护，控制，自动化和计量系统行业的引导者。\r\r\n', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('681', '61', 'INHE-0642', '2019-06-26 16:10:44', '2019-06-26 16:10:44', 'khxx20190626817/Botswana power corporation', 'khxx20190626817', 'Botswana power corporation', 'BPC', '非洲', '博茨瓦纳', 'https://www.bpc.bw/', '', '博茨瓦纳电力公司', '潘正豪(James)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('682', '61', 'INHE-0642', '2019-06-26 16:19:01', '2019-06-26 16:27:34', 'khxx20190626818/Keysource (Pty)Ltd ', 'khxx20190626818', 'Keysource (Pty)Ltd', '', '非洲', '博茨瓦纳', '', '博茨瓦纳', '本地代理公司，主要业务为项目安装以及代理供货业务，次代理与BPC电力公司有过项目来往，具备一定客户关系。', '潘正豪(James)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('683', '61', 'INHE-0793', '2019-06-28 17:04:04', '2019-06-28 17:47:51', 'khxx20190628820/HOG Engineering Ghana Ltd.', 'khxx20190628820', 'HOG Engineering Ghana Ltd.', 'HOG', '非洲', '加纳', 'www.hogghana.com', 'No.7 Yoate street Adabraka,Accra-Ghana', '该客户为加纳市场新代理，经济实力方面：其有两家公司，一家药店，一家变压器经销公司，总共有14名员工；其自己有一辆宝马，公司有三辆汽车，目前和电力公司PDS有很多在执行合同，单张合同价值50万美左右，和其一起去过几次银行，判断其融资额度较高；人脉方面：其认识能源部长，电力公司总经理，采购部总监，和其一起拜访过PDS采购部总监，判断其公司电表有销路，而其也需电表厂家一起合作。个人能力方面：此人性格较急，有点脾气，但也讲道理，个人业务能力较强，和多家中国公司在变压器方面有合作，在拜访期间发现其极为繁忙，总体来说值得合作。其目前正在和宁夏隆基谈电表合作，在业余进行相关宣讲后，其对我司产品也产生较浓厚兴趣，愿意开展合作，业务已与其洽谈相应订单。', '辛方腾(Daniel)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('684', '60', 'INHE-0535', '2019-06-29 16:59:09', '2019-06-29 20:10:48', 'khxx20190629822/MAHARASHTRA STATE ELECTRICITY TRANSMISSION CO. LTD\r\n', 'khxx20190629822', 'MAHARASHTRA STATE ELECTRICITY TRANSMISSION CO. LTD', 'MSETCL', '亚洲', '中国', 'www.mahatransco.in. \r\r\n', 'Automation Communication\r\n& Innovation,\r\nOld SLDC\r\nBuilding,MSETCL,\r\nThane Belapur road,Airoli,\r\nNavi Mumbai - 400 708\r\n', '马哈拉施特邦电力传输有限公司（MSETCL）是印度最大的州立传输电力公司，拥有46217 circuit KM输电线路的输电网络和具有123846MVA变压能力的660EHV变电站。孟买国家负荷调度中心（SLDC）负责运营，监测和控制电力系统。2007年5月17日，根据Hon.MERC的2006第42号命令，基于可用性的费率和偏差处理机制，要在马哈拉施特邦实施ABT电表。SLDC要求ABT电表数据约3000个接口地点要根据MSETCL的地域进行每周DSM计费。目前，所有这些数据都是手动人工获取，在SLDC验证和处理。且调度和处理机制期限为15分钟。而根据监管机构论坛（FOR）新指南，现在需要将调度和处理周期改为15分钟。', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('685', '60', 'INHE-0781', '2019-07-09 02:07:49', '2019-07-09 08:45:46', 'khxx20190709830/Bangladesh Power Development Board', 'khxx20190709830', 'Bangladesh Power Development Board', 'BPDB', '亚洲', '孟加拉国', 'www.bpdb.gov.bd', 'WAPDA Building (9th floor),Motijheel C/A, Dhaka-1000.', ' 用户数约350万，后分离出NESCO(约110万用户)用户数为240万。受电力部直属管辖。WZPDCL, NESCO都是从BPDB分离出去的电力公司。', '李启坦', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('686', '61', 'INHE-0593', '2019-07-11 10:54:01', '2019-07-11 10:59:01', 'khxx20190711833/Agence Burkinabè d’Electrification Rurale (ABER)', 'khxx20190711833', 'Agence Burkinabè d’Electrification Rurale (ABER)', 'ABER', '非洲', '布基纳法索', 'http://www.aber.bf', 'Ouaga 2000, Avenue El Hadj Salifou CISSE', '布基纳法索农村电力局（农电）。根据2017年4月20日第014/2017号法律第11条，农电负责任务为：\r\n\r\n1. 通过以较低的成本发展农村电气化，促进国家电力领域的公平覆盖#FE54`\r\n2. 助力实施国家电气化计划#FE54`\r\n3. 促进农村人口获得电力#FE54`\r\n4. 确保在基础设施发展框架内委派项目所有权#FE54`\r\n5. 监督活跃在这些地区的其他机构开展的农村电气化和农村能源使用活动#FE54`\r\n6. 为能源部长和监管机构编写关于农村电气化活动的年度报告。', '胡蝶', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('687', '61', 'INHE-0593', '2019-07-11 17:32:05', '2019-07-11 17:49:25', 'khxx20190711836/La Société d’Installation Maintenance et d’Etude d’Equipement Electrique', 'khxx20190711836', 'La Société d’Installation Maintenance et d’Etude d’Equipement Electrique', 'SIMEEEL', '非洲', '布基纳法索', 'https://simeeel.com/presentation/', '06 BP 9346 OUAGADOUGOU 06', '1998年7月8日成立的Burkina法律下的私人公司，注册资本为1.5亿西非法郎。\r\r\r\r\r\n\r\r\r\r\r\n他们的目标是在任何需要的地方提供电力，特别是在布基纳法索的城市和乡村以及西非和中非，总要的业务范围为配电网络建设，提供防火及监控设备，太阳能相关的项目。', '胡蝶', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('688', '61', 'INHE-0877', '2019-07-12 10:08:21', '2019-07-12 11:06:52', 'khxx20190712837/江苏汇鸿外经', 'khxx20190712837', '江苏汇鸿外经', 'SRN', '非洲', '尼日利亚', 'www.skyrun.net.coom', '南京市江宁区天元路108号', '关联企业：江苏汇鸿国际集团全资子公司\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\n注册时间：2009年\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\n注册资本：\r1亿元\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\n核心业务：可可豆贸易、家电组装（有本地工厂）\r\r\r\r\r\n\r\r\r\r\r\r\n经验概述：SRN电表业务在SX的支持下，于2014年开展，采购了测试台体以及4K电表等。后SX与MJ合作，主动弱化了与其合作关系，SR转而与许继电气、林洋电气合作。\r\r\r其电表行业经验尚浅，但在尼国经营十余年，积累了一定的资源。\r\r\r\r\r\n\r\r\r\r\r\n\r\r客户评级：C类客户（合作意愿强，有一定的经销能力。但专业性、规模、市占率一般）', '张震(Fred)', '业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('689', '60', 'INHE-0560', '2019-07-12 13:31:56', '2019-07-12 13:45:33', 'khxx20190712838/HAZAARBAT LLC', 'khxx20190712838', 'HAZAARBAT LLC', 'HAZAARBAT LLC', '亚洲', '蒙古', '后续补充', 'Mongolia，Ulan-Bater，District Sukhe-Bater,4-site,5-pmirk.,28-5', 'Hazaarbat LLC 为蒙古国乌兰巴托的进出口贸易公司，在当地专门做政府投标项目和工程，主要行业有：机电产品、汽车配件、电站通信设备等。', '李美娇', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('690', '60', 'INHE-0790', '2019-07-18 10:59:26', '2019-07-18 11:26:35', 'khxx20190718840/Al-Tareq Engineering Technology Co			\r\n', 'khxx20190718840', 'Al-Tareq Engineering Technology Co', 'TATECO', '亚洲', '约旦', 'http://www.tateco-eng.com/', '', 'TATECO成立于2004年1月，是一家获授权的约旦民营公司，并在安曼商会挂牌上市。其主营业务是为客户提供最先进的电气设备和一流的行业解决方案。该公司之前是海兴在约旦的代理，利用其在电力公司的关系，帮海兴中过几次标，现在由于海兴的AMI系统在约旦电力公司Jepco出现了问题，所以在寻求新的合作伙伴。', '莫亚检', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('691', '60', 'INHE-0790', '2019-07-18 11:08:39', '2019-07-18 11:25:34', 'khxx20190718841/Irbid District Electricity Co.,Ltd. ', 'khxx20190718841', 'Irbid District Electricity Co.,Ltd.', 'IDECO', '亚洲', '约旦', 'https://www.ideco.com.jo', '伊尔比德，Ratib Al Batayneh街', 'IDECO公司成立于1957年的民用电力公司，属私营企业，负责包括伊尔比德马弗拉克杰拉什阿杰隆的拜勒加省的和行政区的发电，输电和电力的分配。1967年该公司的名称改为Irbid Electricity Company Public Shareholding Company Limite ', '莫亚检', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('692', '60', 'INHE-0868', '2019-07-19 10:39:18', '2019-07-19 10:52:19', 'khxx20190719845/Infotech Group', 'khxx20190719845', 'Infotech Group', 'Infotech', '亚洲', '巴基斯坦', 'www.infotechgroup.com', '12-N, Gulberg II, Lahore, Pakistan\r\n', '我们的总部位于新加坡，在全球各地设有办事处，从伦敦到阿克拉，是全球增长最快的信息技术集团之一。在过去20多年里，信息技术公司在世界各地的重要项目上投入了数百万美元，为企业提供了丰富的解决方案。', '庄钦', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('693', '60', 'INHE-0868', '2019-07-19 10:58:06', '2019-07-19 11:06:27', 'khxx20190719847/Tetra Tech', 'khxx20190719847', 'Tetra Tech', 'Tetra Tech\r\r\n', '北美洲', '美国', 'www.tetratech.com\r\n', '3475 East Foothill Blvd.， Pasadena， CA 91107， US', 'Tetra Tech是全球领先的咨询，工程和技术服务提供商。 我们的声誉取决于我们的员工的技术专长和奉献精神 -  20,000名员工跨学科和时区合作，为具有挑战性的项目提供智能，可持续的解决方案。 我们很自豪能够成为水，环境，基础设施，资源管理，能源和国际发展方面的领先技术专家。 Tetra Tech将全球数十亿美元的公司资源与全球450个地点的本地，以客户为中心的交付相结合。\r\r\n', '庄钦', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('694', '97', 'INHE-0549', '2019-07-19 14:50:11', '2019-07-19 15:30:27', 'khxx20190719848/Vision Madagascar', 'khxx20190719848', 'Vision Madagascar', 'VIMA', '非洲', '马达加斯加', 'www.visionmadagascar.com\r\r\n', 'Explorer Business Park - Ankorondrano - B.P 12 128 - Antananarivo 101 - MADAGASCAR', 'VISION MADAGASCAR（ViMa）由Zouzar Bouka于2000年创立，其中包括马达加斯加最具标志性的建筑，包括2007年南非大使馆和2010年塔那那利佛市政厅。\r\r\r\n房地产部门仍然在ViMa Real Estate，ViMa Business Centers和ViMa Majunga Hub中扮演着最重要的角色。通过这些子公司，ViMa是马达加斯加商业园概念的先驱，拥有着名的承租人组合：大使馆，国际机构，财富500强企业......\r\r\r\nViMa Majunga Hub拥有马达加斯加西海岸的第一个工业园区，拥有80英亩的城市土地和650,000平方英尺的租赁空间。\r\r\r\nViMa Woods等风险投资公司 - 以FSC标准运营 - 将其定位为私营企业在改善马达加斯加生活质量方面做出充分贡献的国家发展的主要贡献者。\r\r\r\nViMa与体育发起人ASO，雷格斯商业中心，Symbion Power，Teleperformance（多渠道客户体验的全球领导者），世界贸易中心和Eiffage等品牌的合作使其成为真正的全球参与者。\r\r\r\n', '王秀明', '商务组(Commerce Division)', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('695', '66', 'INHE-0774', '2019-07-22 09:54:52', '2019-07-22 10:04:38', 'khxx20190722849/SC ENERGOBIT SA', 'khxx20190722849', 'SC ENERGOBIT SA', 'ENERGOBIT ', '欧洲', '罗马尼亚', 'www.energobit.com', 'RO 400221 Cluj-Napoca, Parcul Industrial Tetarom I\r\r\nStr. Taietura Turcului nr. 47/11', '成立于25年前，约700名员工，主要做开关柜、输电变压器、低压输电设备和工业自动化设备等电气设备；提供中、高、低压输电交钥匙工程，室内外照明方案，智能计量，SCADA系统，电气维护、咨询服务等业务。', '何森华', '业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('696', '66', 'INHE-0774', '2019-07-22 10:05:07', '2019-07-22 10:29:30', 'khxx20190722850/Electromagnetica S.A.', 'khxx20190722850', 'Electromagnetica S.A.', 'Electromagnetica S.A.', '欧洲', '罗马尼亚', 'https://www.electromagnetica.ro', 'Calea Rahovei 266-268, Sector 5, Bucharest, Postal Code 050912', '1930年成立，最早做电讯设备，现有产品和服务包括：生产和供应配电/计量设备，LED照明方案；电气和电子组件；金属组件浇筑；工具和模具；汽车部件；铁路运输安全系统；还涉及绿色能源生产及能源效率提高技术。', '何森华', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('697', '66', 'INHE-0774', '2019-07-22 10:26:52', '2019-07-22 10:43:53', 'khxx20190722851/MPS', 'khxx20190722851', 'MPS', 'MPS', '欧洲', '罗马尼亚', 'http://www.mps-grup.ro/', 'CLUJ-NAPOCA, STR. ATELIERULUI, NR. 11A', '2012年成立，和华为有合作。提供通信和能源领域服务；提供光伏系统的咨询，设计，建造和维护的综合服务。也涉及智能计量业务。', '何森华', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('698', '66', 'INHE-0774', '2019-07-22 10:35:35', '2019-07-22 10:49:05', 'khxx20190722852/Eximprod Grup', 'khxx20190722852', 'Eximprod Grup', 'Eximprod ', '欧洲', '罗马尼亚', 'https://www.epg.ro/en', '	\r\n3rd Cpt. Av. Mircea T. Badulescu Street, Buz?u, Zip Code 120038 \r\n1-3 Lacul Tei Bdul., 7th floor, Bucharest', '	\r\n成立于1994年，主要专注于能源领域业务。目前拥有员工350名，营业额3900万欧元，4个生产工厂。主要产品有：中压电气产品、ACADA、软件和自动化、可再生能源、混凝土加强技术、铁路设备；高压熔断器等；', '何森华', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('699', '61', 'INHE-0431', '2019-07-22 14:25:00', '2019-07-22 14:34:37', 'khxx20190722853/Uganda Electricity Distribution Company Limited ', 'khxx20190722853', 'Uganda Electricity Distribution Company Limited', 'UEEDCL', '非洲', '乌干达', 'www.uedcl.co.ug ', 'Street Address: Plot 37,Nakasero Road 	 \r\nFloor/Room number:  	UEDCL Tower,6th Floor \r\nTown/City: Kampala 	\r\n', '乌干达国家配网公司。配网的主要业务外包给UMEME运营。但是UEDCL也部分采购小批量订单。', '刘佩(Ted)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('700', '66', 'INHE-0628', '2019-07-22 20:47:42', '2019-07-23 08:51:33', 'khxx20190722854/ZEUP POZYTON', 'khxx20190722854', 'ZEUP POZYTON', '', '欧洲', '波兰', 'www.pozyton.com.pl', 'Zak?ad Elektronicznych Urz?dzeń Pomiarowych POZYTON Sp. z o. o.\r\n\r\nul. Staszica 8, 42-202 Cz?stochowa, Poland', '波兰Pozyton 电表厂成立于1989年，目前生产多种型号的单相表、三相表和多功能CT表，且单、三相表均有四相限、复费率、带负荷曲线和无线通讯要求，全部符合欧盟MID标准，向波兰多个电力局都有供货经验。Pozyton对已经参观银河并进行了技术交流。银河也参观了Pozytond的工厂，并达成了合作意向。目前客户积极为银河翻译标书和提供当地支持，希望一起进行投标。', '刘元豪', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('701', '66', 'INHE-0774', '2019-07-23 08:47:10', '2019-07-23 09:21:05', 'khxx20190723856/Zak?ad Elektronicznych Urz?dzeń Pomiarowych POZYTON Sp. z o. o.', 'khxx20190723856', 'Zak?ad Elektronicznych Urz?dzeń Pomiarowych POZYTON Sp. z o. o.', 'POZYTON', '欧洲', '波兰', 'http://www.pozyton.com.pl/', 'ul. Staszica 8, 42-202 Czestochowa, Poland', '成立于1989年，开始做简单的电子产品，后来引进德国电表技术做电表产品。目前，主要的产品有：1.家用单三相电表；2.用于小商场、购物中心和工厂的三相变压器接入式电表；3.用于配电公司和电厂的高精度变压器接入式电表；4.远程抄表系统等。以前最大的合作客户是Enea，现在是PGE。', '何森华', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('702', '66', 'INHE-0774', '2019-07-23 09:21:33', '2019-07-23 09:56:58', 'khxx20190723857/PGE Dystrybucja SA', 'khxx20190723857', 'PGE Dystrybucja SA', 'PGE Dystrybucja ', '欧洲', '波兰', 'https://pgedystrybucja.pl/', 'ul. Garbarska 21A, 20-340 Lublin', '波兰5大电力公司之一。2010年8月31日，波兰能源监管办公室指定PGE Dystrybucja运营商Dystrybucyjnego在特许经营区域内指定的运营区域进行分配电，PGE Dystrybucja占地面积122 433平方公里（约占全国的38％）。2010年9月1日PGE Dystrybucja开始电力运营业务，该公司是由当地的8家运营商合并而成，目前8家运营商作为PGE Dystrybucja的分支。						\r\n\r\n', '何森华', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('703', '66', 'INHE-0774', '2019-07-25 08:38:18', '2019-07-25 09:13:34', 'khxx20190725858/SOCIETATEA DE DISTRIBUTIE A ENERGIEI ELECTRICE TRANSILVANIA SUD S.A.', 'khxx20190725858', 'SOCIETATEA DE DISTRIBUTIE A ENERGIEI ELECTRICE TRANSILVANIA SUD S.A.', 'SDEE Transilvania Sud SA', '欧洲', '罗马尼亚', 'www.sdeets.ro', 'Luchian Stefan, pictor, nr. 25', 'SDEE Transilvania Sud SA 是罗马尼亚八大配电公司之一，主要为管辖区域内的260万居民提供输、配电，在相关领域有超过100年的经验。它由6家分子机构组成，给Alba, Bra?ov, Covasna, Harghita, Mure? 和 Sibiu 6个县提供电力，服务覆盖面积3,4100KM2。此外，SDEE Transilvania Sud SA 负责其自有电力设施的运行、维护和升级满足安全、质量、经济和环保的要求。 公司的主管机构是股东大会，负责决定业务及其经济和商业政策。由董事会负责公司的日常管理。此机制从2007年8月份根据 HGR 675/2007开始实施。			\r\r\n', '何森华', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('704', '60', 'INHE-0868', '2019-07-25 14:11:44', '2019-07-25 14:14:11', 'khxx20190620812/Roche Projects Pvt Ltd', 'khxx20190620812', 'Roche Projects Pvt Ltd', '', '亚洲', '斯里兰卡', 'www.rotaxltd.com', 'No,332, Galle Road, Colombo 04, Sri Lanka\r\n', 'Rotax Pvt Ltd 公司成立于1963年，拥有23年的投标经验，拥有200名以上的员工的家族式企业，从事于电力产业，产品包括，开关、控制面板，计量控制和保护装置，校准设备，测试设备，输变电系统的测试和维护设备，实验室设备，照明，工业马达，线缆，工业化集成，电力材料配件，中低压电容等，为西门子、SOCOMEC、TERASAKI,TECS等品牌的当地经销商。\r\n', '庄钦', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('705', '61', 'INHE-0843', '2019-07-25 18:56:46', '2019-07-26 09:16:41', 'khxx20190725859/Guzgaltobi Electric Company C.A.\r\n', 'khxx20190725859', 'Guzgaltobi Electric Company C.A.', 'Guzgaltobi', '南美洲', '厄瓜多尔', '', 'Lomas de Urdesa, Panorama, 830, Guayaquil, Ecuador\r\r\n', 'Guzgaltobi在厄瓜多尔主要从事2S和12S圆表和圆表底座的销售和经销，拥有自己的电表品牌。与厄瓜多尔国电CNEL有密切的合作关系，是国电CNEL的供应商，同时在厄瓜多尔电力与清洁能源部有关系。\r\r\n', '刘畑杏(Laura)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('706', '61', 'INHE-0843', '2019-07-25 19:00:09', '2019-07-26 09:16:52', 'khxx20190725860/CNEL S.A.', 'khxx20190725860', 'CNEL S.A.', 'CNEL', '南美洲', '厄瓜多尔', 'https://www.cnelep.gob.ec\r\n', 'Av. Del Bombero km 6 1/2 Via la Costa Edif. Grace, Ecuador', 'CNEL是厄瓜多尔国家电力公司，2008年经由厄瓜多尔国家电力政策重组成立。目前是厄瓜多尔第四大公司，服务范围覆盖全国44%的领土，主要为西部沿海地区，为厄瓜多尔超过50%的人口提供电力服务。\r\r\n', '刘畑杏(Laura)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('707', '66', 'JXINHE-2559', '2019-07-26 22:56:59', '2019-07-29 08:46:19', 'khxx20190726871/Sislog Lda', 'khxx20190726871', 'Sislog Lda', 'Sislog', '非洲', '莫桑比克', 'www.sislog.com.mz', 'R. Francisco Matange, 196 – Maputo – MO?AMBIQUE\r\r\r\n', '公司成立于2000年莫桑比克的马普托市，致力于IT软件和应用的开发，业务涉及云服务，软件开发，USSD手机服务，文件共享，定位和VOIP系统等。公司曾为EDM（莫桑比克电力公司）提供过云服务，主要客户包括莫桑比克当地的两大通信公司，VODACOM和MCEL,国家银行，国家工业和商业部等。', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('708', '66', 'JXINHE-2559', '2019-07-29 10:04:15', '2019-07-29 10:10:37', 'khxx20190729872/Hidroeléctrica de Cahora Bassa, S.A.', 'khxx20190729872', 'Hidroeléctrica de Cahora Bassa, S.A.', 'HCB', '非洲', '莫桑比克', 'www.hcb.co.mz\r\n\r\n \r\n', 'Songo-Tete', 'HCB公司是南非最大的独立发电公司（IPP），向莫桑比克和南非发展社区提供电力供应。公司总部位于莫桑比克的TETE省的SONGO镇的CAHORA BASSA大坝，在马普托和CHIMOIO设有办公室，公司为国家占股的私营企业。', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('709', '60', 'INHE-0535', '2019-07-29 10:48:24', '2019-07-29 11:00:41', 'khxx20190729873/MAHARASHTRA STATE ELECTRICITY DISTRIBUTION CO. LTD.', 'khxx20190729873', 'MAHARASHTRA STATE ELECTRICITY DISTRIBUTION CO. LTD.', 'MSEDCL', '亚洲', '印度', 'http://www.mahadiscom.in\r\n', 'Materials Management Cell,\r\nPlot No. G-9, “Prakashgad” First floor,\r\nProf. Anant Kanekar Marg,\r\nBandra (E), Mumbai – 400 051.\r\n', '马哈拉施特邦配电公司MSEDCL负责孟买东北部地区电力业务，用户基数达2480万。投入大量经历和资源实现“确保客户服务卓越”的使命。', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('710', '61', 'INHE-0885', '2019-07-30 11:38:28', '2019-07-30 13:25:25', 'khxx20190730874/FACTORFAST METERING (PTY) LTD\r\n', 'khxx20190730874', 'FACTORFAST METERING (PTY) LTD', '无', '非洲', '博茨瓦纳', '无', 'Unit 5,Plot 5640,Kubu Road,Broadhurst Industrial,Geborone Botswana', '主营电力设备相关业务,已经在BPC公布的项目上有过多次合作，该公司在电力公司有一定的客户关系。', '潘健康(Klein)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('711', '61', 'INHE-0885', '2019-08-01 11:08:06', '2019-08-01 11:33:46', 'khxx20190801875/Almaz (Pty)Ltd', 'khxx20190801875', 'Almaz (Pty)Ltd', 'Almaz', '非洲', '博茨瓦纳', '无', '		\rALMAZ Pty Ltd\r		\r\r\r\nP O Box 41034 Gaborone\r\r\r\r\r\r\n', '博茨瓦纳当地公司，主营业务为电子设备组装工厂，为博茨瓦纳当地政府提供笔记本电脑以及本地预付费电水表项目。具有一定的政府关系，在博茨瓦纳有一定的市场基础。\r\r\r\r\r\r\r\r\n						\r\r\r\r\r\n', '潘健康(Klein)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('712', '66', 'JXINHE-2559', '2019-08-02 11:48:38', '2019-08-02 13:24:54', 'khxx20190802876/ZOUBOULAKIS SA', 'khxx20190802876', 'ZOUBOULAKIS SA', 'ZOUBOULAKIS', '欧洲', '希腊', 'www.zouboulakis.gr', ' 39 Vas. Alexandrou Str. GR-121 31, Peristeri, Athens', '公司成立于1979年，希腊雅典，为政府部门如事工部门，军队，大学，公用企业，州政府，市政，安全部队，公立和私营学校和私立公司的供应商。客户超过1000家，经过40多年的运营，成为政府和私营企业业务的是大合同供应商，向HEDNO供应过非电表的非电力类项目。', '淦永妍', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('713', '60', 'INHE-0535', '2019-08-02 20:30:41', '2019-08-07 10:23:32', 'khxx20190802877/Salasar Techno Engineering Limited\r\n', 'khxx20190802877', 'Salasar Techno Engineering Limited', 'Salasar', '亚洲', '印度', 'www.salasartechno.com', 'E-20, South Extension-I, New Delhi-110049 / office at KL-46, Kavi Nagar, Ghaziabad-201002 (UP) India\r\n', 'Salasar是一家定制化钢材加工和基础设施解决方案供应商。致力于钢材建筑的定制化及先进技术化设计，生产和安装。涉足通信塔，输电塔，变电站建筑，光伏建筑，铁轨，火车车厢，农村电气化结构，电缆槽，镀锌非镀锌钢制造等，在全球30多个国家扩展业务。过去5年年平均营业额$58Million.', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('714', '66', 'INHE-0628', '2019-08-05 09:04:05', '2019-08-05 09:36:53', 'khxx20190805878/Polska Grupa Energetyczna', 'khxx20190805878', 'Polska Grupa Energetyczna', 'PGE', '欧洲', '波兰', 'https://www.gkpge.pl/', 'PGE Polska Grupa Energetyczna S.A.\r\n2 Mysia Street, 00-496 Warsaw,Poland', '业务简介\r\nPGE Capital Group是波兰最大的能源部门公司，涉及销售收入和净利润。由于自身燃料资源，发电和配电网络的结合，PGE为500多万个家庭，企业和机构提供安全可靠的电力供应。\r\n\r\n使命和愿景\r\nPGE的使命是确保基于供应可靠性，卓越技术，现代服务和合作伙伴关系的安全性和增长。PGE集团业务的总体目标是提高其股东价值以及确保波兰能源安全的关键作用。根据其长期增长愿景，PGE将成为：\r\n\r\n- 发电领导者，积极利用增长机会\r\n\r\n- 可靠，活跃的媒体和服务供应商\r\n\r\n- 波兰最高效，最灵活的能源集团 \r\n\r\n- 开发新业务模式和业务线的领导者\r\n\r\n保持在发电领域的领先地位将涉及在2020年以后在波兰的发电市场中实现至少40％的份额。', '刘元豪', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('715', '61', 'INHE-0865', '2019-08-08 09:13:20', '2019-08-08 10:24:58', 'khxx20190808880/Groupement des services Eau et électricité\r\n', 'khxx20190808880', 'Groupement des services Eau et électricité', 'GS2E', '非洲', '科特迪瓦', 'http://www.gs2e.ci/', '1 Avenue Christiani Treichville\r\n01 BP 8142  Abidjan 01', 'ERANOVE在科特迪瓦市场的子公司。主要服务于科特迪瓦的电力公司和水务公司的IT部门。', '蔡慧', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('716', '97', 'INHE-0051', '2019-08-08 17:51:38', '2019-08-08 17:55:31', 'khxx20190808881/珠海银河智能电网有限公司', 'khxx20190808881', '珠海银河智能电网有限公司', '银河电网', '亚洲', '中国', '', '', '', '盛燕', '企业管理与信息化部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('717', '61', 'INHE-0725', '2019-08-12 18:25:12', '2019-08-13 18:02:38', 'khxx20190812883/NG市场微网客户', 'khxx20190812883', 'ACOB Lighting Technology Ltd', 'MNP', '非洲', '尼日利亚', 'http://www.acoblighting.com/', 'Abuja, Nigeria', 'ACOB Lighting Technology Ltd是一家尼日利亚主做LED及发电业务的公司，为本地微型电网运营商之一，其公司老板Mr Alex同时也是本地微网项目运营联盟AMDA(African Minigrids Development Association)的CEO，此机构已受政府授权管理尼日利亚微网项目。与本地多家微网运营商关系密切，与政府部门关系较好，同时同美国公司有一定的关系，上个月刚刚获得10万美金投资。\r\r\nNG市场目前的微网项目正在兴起，目前业务正在联系的微网客户有ACOB Lighting Technology, Ureka Content Distribution Limited, 以及主要微网运营机构REA(Rural Electrification Agency), GIZ(Deutsche Internationale Zusammenarbeil)以及AMDA(African Minigrids Development Association)。这些机构在本地有较强的客户关系（尤其与本地政府），一定的经济实力及表计需求。目前尼日利亚仍有8000万人左右没有供电，微网市场前景广阔，国家政策扶持。\r\r\r\n因本地微网客户较多，业务计划针对所有本地微网项目单独立一个项目，便于节约工作流程，提高工作效率。', '赵政洁(Oscar)', '国际业务二部', null, null, 'E', 'INHE');
