INSERT INTO `inhe_customer_data` VALUES ('721', '61', 'INHE-0843', '2019-08-23 15:32:13', '2019-08-23 15:52:30', 'khxx20190823889/Protecsa Ingeniería S.A. de C.V.\r\n', 'khxx20190823889', 'Protecsa Ingeniería S.A. de C.V.', 'Protecsa', '北美洲', '墨西哥', 'http://www.protecsaing.mx', 'Parque Tecnológico Innovación Queretaro, Carretera Estatal Km 2+200 Int. 15, El Marques Querétro, 76246, México', 'Protecsa在墨西哥的主营业务是为电力行业提供智能电表、计量设备、AMI方案、TPCyM方案和智能电网解决方案，拥有20年的行业经验，本地有大型工厂生产自主品牌产品。', '刘畑杏(Laura)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('722', '61', 'INHE-0843', '2019-08-26 14:48:31', '2019-08-26 17:09:39', 'khxx20190826890/ALEMINSA S.A.\r\n', 'khxx20190826890', 'ALEMINSA S.A.', 'ALEMINSA', '南美洲', '厄瓜多尔', 'https://www.aleminsa.com\r\n', 'Alborada XI Etapa C.C.Albocentro 5B Bloque D2 Piso 2 Oficina 201\r\r\nGuayaquil - Ecuador\r\r\n', 'ALEMINSA是厄瓜多尔一家致力于高、中、低压电气材料和电气设备销售的私营公司，拥有超过20年的行业经验，业务遍布整个厄瓜多尔领土。客户与厄瓜多尔国电CNEL、首都电力局EEQ有多个项目合作；曾负责过厄瓜多尔10万台AMI圆表项目。\r\r\n', '刘畑杏(Laura)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('723', '61', 'INHE-0853', '2019-08-27 19:41:27', '2019-08-27 19:58:51', 'khxx20190827894/GUYANA POWER&LIGHT,INC. ', 'khxx20190827894', 'GUYANA POWER&LIGHT,INC.', 'GPL', '南美洲', '圭亚那', 'http://gplinc.net/', '40 Main street,Georgetown,Guyana  ', '圭亚那电力与照明公司(GPL)是南美洲圭亚那最大的电力供应商，其特许经营区域涵盖了所有三个县的Demerara, Berbice和Essequibo。GPL向其所有国内客户提供的电压范围从110伏到220伏，视地区而定。', '胡亚婵(Zoe)', '', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('724', '66', 'INHE-0579', '2019-09-03 09:13:29', '2019-09-03 09:22:10', 'khxx20190903903/ICE ENGINEERING', 'khxx20190903903', 'ICE ENGINEERING', 'ICE', '非洲', '突尼斯', 'www.ice-engineering.net\r\n', 'Avenue 5 Aout, rue Baghdad Immeuble Soprano app 3-2 SFAX 3000 - Tunisia \r\r\n', '1.成立于2016年，公司营业范围为电气产品、机械和液压设备等。\r\n2. 2015年-2018年均给电力公司STEG供过货（中标供货），合同有七十万人民币，九十万人民币，三百万，七百万的合同等。\r\n3. 在突尼斯电力公司内部有一定关系，帮助银河拿到新版技术以及商务草稿。\r\n4.公司所在地为突尼斯智能电表项目实施地sfax省。', '孙娜', '业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('725', '61', 'INHE-0876', '2019-09-04 15:02:31', '2019-09-04 15:58:05', 'khxx20190904905/Electricidade de Mocambique, E.P \r\n', 'khxx20190904905', 'Electricidade de Mocambique, E.P', '   EDM', '非洲', '莫桑比克', 'https://www.edm.co.mz/', 'Av. Filipe Samuel Magaia no 368, CP 2532, Maputo\r\r\r\n', '目前全国电网主要由两家公司运行，分别是EDM和HCB。其中EDM主要负责莫桑国内电力的购买、输送和配售。HCB主要负责其Cahora Bassa水电站向南非和津巴等输送电力。莫桑最大的电源点是HCB拥有的Cahora Bassa水电站，其余电站除少量EDM开发拥有的小型水电、燃气电站和燃油电站外，均为私人投资商开发。', '邓彧(Daniel)', '国际二', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('726', '61', 'INHE-0843', '2019-09-06 23:52:00', '2019-09-09 08:43:01', 'khxx20190823889/Powermex Energy S.A de C.V.', 'khxx20190823889', 'Powermex Energy S.A de C.V.', 'Powermex Energy', '北美洲', '墨西哥', 'http://www.protecsaing.mx', 'Av Candieles 92, Fracc los Robles, Zip 76900 Corregidora, Queretaro, Mexico', 'Powermex Energy S.A. de C.V.是Protecsa集团旗下的子公司，主要负责Protecsa的对外进出口贸易、物流运输等业务。', '刘畑杏(Laura)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('727', '61', 'INHE-0642', '2019-09-09 05:23:30', '2019-09-09 08:59:36', 'khxx20190909908/Metals and Engineering Corporation Hi-tech Engineering Industry', 'khxx20190909908', 'Metals and Engineering Corporation Hi-tech Engineering Industry', 'Hi-tech', '非洲', '埃塞俄比亚', '', '', '埃塞军企的下属企业，涉及业务面广且实力较强；提格雷人当政的时候十分强势，新总理上台后该企业高层全面洗牌，但公司由于业务面广，公司得以保留。', '潘正豪(James)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('728', '61', 'INHE-0899', '2019-09-09 09:55:33', '2019-09-09 13:25:51', 'khxx20190909909/APOLLO INTERNATIONAL LIMITED', 'khxx20190909909', 'APOLLO INTERNATIONAL LIMITED', 'APOLLO INTERNATIONAL LIMITED', '南美洲', '圭亚那', 'www.apolloindia.com \r\n', 'Apollo Towers, Plot No. 20, Sector 44\r\r\nGurugram 122002, Haryana India\r\r\n', '成立于1994年，是阿波罗集团的一部分，旨在探索新的商业领域，并利用后自由化时代印度经济提供的机遇。作为世界经济论坛(World Economic forum)公认的“全球成长型企业”，主营业务：综合物流，轮胎分销和营销(轮胎科技全球)，国际商业产品，IBD设备和项目，皮革服装和配件(Tag时装)。', '李梦君', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('729', '61', 'INHE-0721', '2019-09-16 18:16:46', '2019-09-16 18:32:16', 'khxx20190916910/Electrificadora del Caribe S.A. E.S.P.\r\n', 'khxx20190916910', 'Electrificadora del Caribe S.A. E.S.P.', 'ECA', '南美洲', '哥伦比亚', 'http://www.electricaribe.co/\r\n', 'Carrera 55 # 72 - 109 B/quilla - Colombia PBX.: 575 3611000\r\r\n', 'Electricaribe是一家哥伦比亚电力公司，成立于1998年，由该地区七个部门的7家现有公共电气化公司合并而成。共有270多万客户，约80多万用户，负责Atlántico ， Bolívar ， Sucre ， Córdoba ， Cesar ， Magdalena和La Guajira等省的电能分配和商业化。', '胡云义(Anita)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('730', '61', 'INHE-0500', '2019-09-18 02:22:33', '2019-09-18 08:39:41', 'khxx20190918911/City Power\r\nJohannesburg (SOC) Ltd\r\n', 'khxx20190918911', 'City PowerJohannesburg (SOC) Ltd', 'City Power', '非洲', '南非', 'www.citypower.co.za\r\n', '40 Heronmere Road P.O.Box 38766\r\r\r\nReuven Booysens\r\r\r\nJohannesburg 2016\r\r\r\n', '			\r\r\r1.招标方为南非市场8大大都市市政之一，用户数量约50万，普通居民用户数量约为45万个，工商业用户约为5万个；\r2.招标方市政公司普通居民用表主要为兰吉尔、海兴和Itron，工商业用户电表主要为兰吉尔、Itron和海兴，当前售电系统供应商为Ontect（Itron），AMR供应商为Itron和海兴分别供应；\r3.此次招标主要内容为后付费中小型商业、大型商业用户智能电表，三年期框架合同招标。	\r\r\r\r\n\r\r\r\n', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('731', '143', 'INHE-0773', '2019-09-18 11:50:10', '2019-09-18 13:28:38', 'khxx20190918912/HELIFLEX INVESTMENTS PRIVATE\r\n', 'khxx20190918912', 'HELIFLEX INVESTMENTS PRIVATE', 'HELIFLEX', '非洲', '津巴布韦', '无', '272 Samora Machel Ave, Harare, Zimbabwe\r\n', 'EOI项目已立项，项目为津巴布韦能源管理局ZERA代为国家电力公司ZETDC发布，在本地公司中进行预付费代码表经销意向招标，一共17家本地经销商合格中标可以从总共6家表厂（银河、海兴、EDMI、兰吉尔、Itron和Iscramaco）采购特定表型进行经销；2019年取消5家经销商资格，新增加12家经销商资格，目前共22个供应商。HELIFLEX INVESTMENTS PRIVATE为其中一家经销商', '林丹敏', '竞标组', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('732', '66', 'INHE-0774', '2019-09-19 10:00:50', '2019-09-19 10:20:02', 'khxx20190919916/MOSECO C Modern Scientific & Electronics Co.', 'khxx20190919916', 'MOSECO C Modern Scientific & Electronics Co.', 'MOSECO', '亚洲', '约旦', 'www.mosecogroup.com', ' 1914, Amman 11941, Jordan', 'MOSECO集团是一家领先的阿拉伯系统集成商，在IT电信市场拥有超过38年的经验。 MOSECO能够以全面且经济高效的方式独特地安装和支持电信基础设施解决方案及其互补的运营和业务支持解决方案。 Moseco集团总部位于约旦安曼，在沙特阿拉伯，卡塔尔，巴勒斯坦和伊拉克北部开展业务。 集团在阿拉伯地区雇用了超过600名专业人员，服务于阿拉伯地区的客户群。同时也是诺基亚在巴勒斯坦的分销商。', '何森华', '业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('733', '66', 'INHE-0774', '2019-09-19 10:33:14', '2019-09-19 10:45:14', 'khxx20190919918/Palestinian energy and Natural Resources Authority', 'khxx20190919918', 'Palestinian energy and Natural Resources Authority', 'PENRA', '亚洲', '巴勒斯坦', 'http://www.penra.gov.ps/', 'Al Ersal street', '巴勒斯坦能源和自然资源管理局（PENRA）成立于1994年，负责监督能源部门的发展。它负责能源部门的政策，协调和部门发展，并向巴勒斯坦总统汇报。它负责执行巴勒斯坦权力机构1997年部门政策函的规定，其中概述了西岸和加沙电力部门发展的未来体制框架。根据这项政策，它将向部门实体颁发许可证，并授权进出口电力。\r\nPENRA负责将西岸的供电和配电安排整合为五个配电公用事业，这是巴勒斯坦行业政策下的一项重大改革。它创建了五个公用事业：北方电力分配公司（NEDCO），希伯伦电力公司（HEPCO）和南方电力公司（SELCO）以及Tubas电力分配公司（TEDCO）。这些电力公司加入了为耶路撒冷中心区域周边服务的历史悠久的电力公司- 耶路撒冷地区电力公司（JDECO）。加沙电力分配公司（DISCO）负责加沙的输电和配电。', '何森华', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('734', '61', 'INHE-0843', '2019-09-19 11:25:56', '2019-09-19 11:32:05', 'khxx20190919919/Empresa Eléctrica Regional Centro Sur C.A.', 'khxx20190919919', 'Empresa Eléctrica Regional Centro Sur C.A.', 'CENTROSUR', '南美洲', '厄瓜多尔', 'www.centrosur.gob.ec', 'Av. Max Uhle y Pumapungo, sector Monay, Ciudad de Cuenca, Ecuador\r\r\n', '厄瓜多尔排名前五的电力公司，成立于1979年，主要负责厄瓜多尔中南部地区的电力供应。', '刘畑杏(Laura)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('735', '61', 'INHE-0721', '2019-09-19 16:02:46', '2019-09-19 17:06:17', 'khxx20190919920/Codensa S.A. ESP', 'khxx20190919920', 'Codensa S.A. ESP', 'Codensa', '南美洲', '哥伦比亚', 'https://www.enel.com.co/en/investors/codensa-electric-power.html\r\n', '14, Cra. 20 ##15, Bogotá, Cundinamarca, 哥伦比亚\r\r\n', 'CODENSA哥伦比亚电力公司，主管波哥大地区，被意大利电力公司ENEL收购，用户总数量约为350万，其中大用\r\r\n户为13000。\r\r\n', '胡云义(Anita)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('736', '75', 'INHE-0432', '2019-09-27 17:57:17', '2019-09-27 20:13:46', 'khxx20190927921/INHEMETER AFRICA COMPANY LIMITED', 'khxx20190927921', 'INHEMETER AFRICA COMPANY LIMITED', 'IAC', '非洲', '肯尼亚', '无', '肯尼亚内罗毕', '深圳银河海外子公司:IAC', '谭东羊(Timon)', 'INHEMETER AFRICA', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('737', '60', 'INHE-0560', '2019-10-08 14:53:28', '2019-10-08 15:43:13', 'khxx20191008922/ “Mon-Energy Consult” Co., Ltd', 'khxx20191008922', '“Mon-Energy Consult” Co., Ltd', 'Mon-energy', '亚洲', '蒙古', 'http://www.mon.energy.mn/index.php', 'Ulaanbaatar Shuudan, P.O.Box-10210030, Branch-102', '“ Mon-Energy Consult”有限公司成立于1994年，是一家咨询和工程公司，主要经营能源/电力，供热，能源效率，节能，电力，电力管理，市政，基础设施，已在咨询，工程，建筑设计，建筑工程，贸易，维修/大修以及电力设备采购和建筑业务方面实现多元化经营。已累计参与60多个项目，旨在改善蒙古主要城市， 小城市中心和农村地区的能源系统和电力管理。', '李美娇', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
