INSERT INTO `inhe_customer_data` VALUES ('739', '66', 'INHE-0634', '2019-10-15 17:37:38', '2019-10-15 17:50:05', 'khxx20191015924/Electricity Distribution and Supply Authority （EDSA）', 'khxx20191015924', 'Electricity Distribution and Supply Authority （EDSA）', 'EDSA', '非洲', '塞拉利昂', '\r\nhttp://www.edsa.sl \r\n', '\r\nFreetown, Western Area ', '塞拉利昂电力分配和供应局（EDSA）是在2014年底国家电力局（NPA）分拆后成立的.EDSA负责塞拉利昂的电力分配和供应，而其大部分业务集中在西部 EDSA努力扩展其网络以实现全国的电气化。\r\n', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
