INSERT INTO `inhe_customer_data` VALUES ('743', '60', 'INHE-0680', '2019-10-23 13:02:57', '2019-10-23 13:28:54', 'khxx20191023928/塔吉克水电安装', 'khxx20191023928', '塔吉克水电安装', '塔吉克水电', '亚洲', '塔吉克斯坦', 'https://tgem.tj/\r\n', '', 'TAK项目是中亚地区较大的项目,总承包商是当地比较有实力的公司，总承包商情况介绍：\r\n在年轻的塔吉克斯坦的能源发展历史中，占据了举足轻重的地位，因为在当时的塔吉克装配部门水电蒙太奇的工程师和工人的帮助下竖立了大型项目，现在已成为塔吉克市场能源设施建设的领先公司。 公司技术和人员的潜力不仅可以在能源领域，而且可以在其他行业中实施任何复杂的项目。\r\n\r\n', '陈嘉豪', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
