INSERT INTO `inhe_customer_data` VALUES ('747', '143', 'INHE-0773', '2019-11-11 09:20:02', '2019-11-28 11:04:18', 'khxx20191111937/PARAMOUNT CABLES PRIVATE LIMITED\r\n', 'khxx20191111937', 'PARAMOUNT CABLES PRIVATE LIMITED', 'PARAMOUNT CABLES PRIVATE LIMITED\r\n\r\n', '非洲', '津巴布韦', 'N/A', '89 Kelvin Road South \r\nGraniteside\r\nHarare, ZIMBABWE\r\n', '1.EOI项目已立项，项目为津巴布韦能源管理局ZERA代为国家电力公司ZETDC发布，在本地公司中进行预付费代码表经销意向招标，一共17家本地经销商合格中标可以从总共6家表厂（银河、海兴、EDMI、兰吉尔、Itron和Iscramaco）采购特定表型进行经销；2019年取消5家经销商资格，新增加12家经销商资格，目前共22个供应商。\r\r\r\r\r\r\n2. PARAMOUNT CABLES PRIVATE LIMITED是2018年旧经销商，是FINMARK HOLDINGS P/L （FHL）的子公司\r\r\r\r\r\r\n\r\r\r\r\r\r\n						\r\r\r\r\r\r\n', '林丹敏', '竞标组', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('748', '61', 'INHE-0578', '2019-11-11 17:21:32', '2019-11-28 11:03:57', 'khxx20191111938/Zimbabwe Electricity Transmission & Distribution Company (Private) Limited.', 'khxx20191111938', 'Zimbabwe Electricity Transmission & Distribution Company (Private) Limited.', 'ZETDC', '非洲', '津巴布韦', '', '25 Samora Machel Avenue, Harare, Zimbabwe.', '津巴布韦国家电力公司ZETDC。\r\n历史向该电力公司供货了ZEC项目（通过经销商供货），本次ZWS项目与电力公司ZETDC直接交易，因此补录可信息。', '覃湘君(June)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('749', '60', 'INHE-0881', '2019-11-13 09:49:11', '2019-11-13 10:02:59', 'khxx20191113939/Fuji Dharma Electric', 'khxx20191113939', 'Fuji Dharma Electric', 'FDE', '亚洲', '印尼', 'http://www.id.fujielectric.com/company/index.html						\r\n', 'Jl.Rawagelam I/10,Kawasam Industri Pulogadung-Jakarta 13930		\r\n', 'FDE(Fuji Dharma Electric) 是印尼大型控股集团CCM (CENTRAL CIPTA MURDAYA ) 旗下一家子公司。该控股公司旗下共有五十多家子公司，涉及电力，石油，房地产，会展，鞋加工厂等等行业。该集团公司和印尼国家电力公司PLN关系十分密切，其子公司产品覆盖电力公司发电，运输电和配电。FDE是和日本公司Fuji Electric在1983年合资成立，成为印尼当地最早的电表厂之一，后来FDE收购了Fuji Electric在印尼的百分百股权。', '王鹏钦', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('750', '60', 'INHE-0535', '2019-11-18 10:12:20', '2019-11-18 10:48:41', 'khxx20191118941/Genus Innovation Limited\r\n', 'khxx20191118941', 'Genus Innovation Limited', 'GENUS', '亚洲', '印度', 'https://www.genusinnovation.com \r\r\n', 'SPL 2B, RIICO Industrial Area, Sitapura, Tonk Road, Jaipur 302022, India\r\n', 'Genus Innovation成立于1998年，主要设计，开发和制造各种环境友好型太阳能产品如太阳能逆变器，太阳能电池板，太阳能调节装置，电池等，还为在电源备份领域寻求制造专业知识的公司提供OEM服务。\r\r\r\r\n\r\r\r\r\n母公司Genus Power Infrastructure Limited是印度最大的电表制造公司，已经在印度安装了数百万台电表。\r\r\r\r\n', '左亚楠', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('751', '66', 'INHE-0634', '2019-11-19 13:55:35', '2019-11-19 14:19:30', 'khxx20191119942/TECNERGA - TECHNICAL ELECTRICITY LDA\r\n', 'khxx20191119942', 'TECNERGA - TECHNICAL ELECTRICITY LDA', 'TECNERGA', '欧洲', '葡萄牙', 'www.tecnerga.pt\r\n', 'Av. Engo Arantes e Oliveira, No 1 SL-D\r\n1900-221 Lisboa / Portugal\r\n', '自1981年成立，尤其是近20年来，在航空、铁路和变电站建设等的物料和零配件设备供应领域活跃。2018年税后营业额约为430万欧元。项目业绩主要有如下：1 -直接与业主签订合同：\r\r\na)玻璃绝缘体(2 + 1 + 1年)，约为1.000.000', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
