INSERT INTO `inhe_customer_data` VALUES ('753', '61', 'INHE-0500', '2019-11-27 12:36:37', '2019-11-27 13:27:03', 'khxx20191127945/Nyamezela Metering (Pty) Ltd\r\n', 'khxx20191127945', 'Nyamezela Metering (Pty) Ltd', 'NYC', '非洲', '南非', 'www.nyamezela.co.za	\r\n', '270 Granville, Robertville Ext 10, Roodepoort, Gauteng \r\r\n			\r\r\n', '1.银河在南非的独家代理，本地黑人妇女控股企业，自2009年开始合作，已完成津巴布韦电力公司ZEC项目（25万台预付费智能电表）、南非电力公司ESKOM ESA项目（45台预付费代码表），在本地协助建立了N4工厂，具体较为完整的本地电表组装能力。2020年将会扩展工厂二期，届时将有SMT车间和DIP车间的完整本地生产产线；\r\n2.慧联在南非的电表项目将暂时由本地代理执行和直接交易，慧联和本地代理NML直接交易。						\r\n', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('754', '66', 'INHE-0634', '2019-11-29 10:12:41', '2019-11-29 10:52:29', 'khxx20191129947/MINISTERE, DE L’ECONOMIE, DES INVESTISSEMENTS ET DE L’ENERGIE ', 'khxx20191129947', 'MINISTERE, DE L’ECONOMIE, DES INVESTISSEMENTS ET DE L’ENERGIE', 'MEIE', '非洲', '科摩罗', '', '', '电网老化严重，据测算，约7兆瓦电力在输电过程中的损耗率高达40%，为此，亟待对电网进行改造。目前，Majoyezi-ya-Mbude、 Sambamadi、Sada、Nkurani、Mlimani和Dzahani-ya-Washi 等6个地区尚未被电网覆盖。', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('755', '61', 'INHE-0500', '2019-11-30 21:00:34', '2019-12-02 09:36:40', 'khxx20191130948/DELEGATE IBERICA LDA\r\n', 'khxx20191130948', 'DELEGATE IBERICA LDA', 'DELEGATE IBERICA LDA\r\r\n', '欧洲', '葡萄牙', 'N/A', 'R. QTA. CHARQUINHO, 25, R/C E,1500-530 LISBOA,PORTUGAL\r\r\n', 'EAB客户Baltazar Fernandes & Moreira, Lda的融资合作伙伴，负责EAB项目的直接付款。', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('756', '66', 'INHE-0774', '2019-12-02 09:14:29', '2019-12-02 09:36:08', 'khxx20191202949/Eneo', 'khxx20191202949', 'Eneo', 'Eneo', '非洲', '喀麦隆', 'https://www.eneocameroon.cm/index.php/en\r\n', 'Bonanjo Avenue Charles de Gaulle- B.P : 4077 Douala Cameroun', 'Eneo是喀麦隆历史悠久的主要电力公司。它是部分国有企业，由英联集团（Actis）持有51％的股本，Eneo员工持股5％，喀麦隆政府持股44％。\r\r\n\r\r\n在发电方面，Eneo的装机容量为968MW。其发电设施由39个发电厂组成，包括13个电网发电厂和26个远程火力发电厂。 Eneo发电的74％来自水力发电。\r\r\n\r\r\n传输网络包括24个变电站，其中包括1944.29公里的高压线路，15081.48公里的中压线路和15209.25公里的低压线路。\r\r\n\r\r\n配电网络包括5.5至33 KV的11 450公里线路和220至380 KV的11 158公里线路。 Eneo拥有超过973,250客户，其中约45％居住在在杜阿拉和雅温得。\r\r\n\r\r\nEneo拥有3765名固定员工。自2015年6月起，Eneo喀麦隆公司成为英国投资集团Actis的子公司。它的活动受喀麦隆政府与英联社之间签署的特许协议的约束。', '何森华', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('757', '66', 'INHE-0774', '2019-12-02 09:33:35', '2019-12-02 10:20:31', 'khxx20191202951/GUIGUI SARL ', 'khxx20191202951', 'GUIGUI SARL', 'GUIGUI SARL ', '非洲', '喀麦隆', 'www.consulting-gs.com', 'Seme Beach, Victoria (CMR)\r\n', 'GUIGUI Sarl是一家根据喀麦隆法律建立的会计和金融专业公司，旨在为经济参与者提供优质的服务，同时使他们能够在舒适的环境中工作。', '何森华', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('758', '61', 'INHE-0853', '2019-12-04 06:21:38', '2019-12-04 08:48:10', 'khxx20191204952/The energy of cameroon', 'khxx20191204952', 'ENEO CAMEROON S.A', 'ENEO', '非洲', '喀麦隆', 'https://www.eneocameroon.cm/index.php/en', 'Siège Social : Bonanjo Avenue Charles de Gaulle- B.P : 4077 Douala Cameroun', 'Eneo由英联集团（Actis）持有51％的股份，Eneo员工则为5％，喀麦隆国家控股44％。它的活动受喀麦隆政府与英联社之间签署的特许协议的约束。', '胡亚婵(Zoe)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('759', '61', 'INHE-0654', '2019-12-05 11:06:50', '2019-12-05 11:06:50', 'khxx20191205953/ EPEC Córdoba', 'khxx20191205953', 'EPEC Córdoba', 'EPEC ', '南美洲', '阿根廷', 'https://www.epec.com.ar/', 'La Tablada 350 - X5000FEJ - Córdoba - Argentina', 'EPEC是阿根廷科尔多万地区的电力公司，总用户数量约为100万。EPEC诞生于1953年，由两个公共机构合并而成，提供和管理电力服务：电力总局和科尔多瓦公共电力服务局（SPEC）。', '李明(Ming)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('760', '60', 'INHE-0881', '2019-12-09 15:01:54', '2019-12-09 16:28:41', 'khxx20191209957/Golden Man Saq Solidos Holdings Limited', 'khxx20191209957', 'Golden Man Saq Solidos Holdings Limited', 'GM', '亚洲', '哈萨克斯坦', '', 'No.145, building 55/18, Mangilik EI Avenue, Yesil district, Nur-Sultan city, Kazakhstan', '客户GM公司是根据哈萨克斯坦共和国法律成立的商业组织形式的法人企业，公司的主营业务包括信托，基金和其他金融投资业务。此外，客户涉及基建和矿收购等相关业务，跟能源部部长私交甚好，在哈萨克斯坦和中亚地区拥有丰富的人脉资源。', '王鹏钦', '国际业务一部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('761', '61', 'INHE-0381', '2019-12-16 14:44:13', '2019-12-16 14:53:04', 'khxx20191216964/Voltalia', 'khxx20191216964', 'Voltalia', 'Voltalia', '欧洲', '法国', 'www.voltalia.com', '84 Boulevard de Sebastopol\r\r\n75003 Paris, France\r\r\n', '成立于2005年的Voltalia是一家利用太阳能，风能，水能和生物质能（结合存储解决方案）生产可再生电力的电力生产商和服务提供商。\r\r作为一家综合性公司，Voltalia在整个可再生项目的价值链中拥有丰富的专业知识：项目开发，项目融资，EPC以及运营与维护。\r\r该集团活跃在20个国家/地区，能够为全球客户提供服务。\r\r', '张柳芳(Alexie)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
