INSERT INTO `inhe_customer_data` VALUES ('763', '61', 'INHE-0853', '2019-12-20 07:23:12', '2019-12-20 08:38:04', 'khxx20191220966/Electricity Development Corporation', 'khxx20191220966', 'Electricity Development Corporation', 'EDC ', '非洲', '喀麦隆', 'https://www.edc.cm/', 'Immeuble Hibiscus, B.P. 15111 Yaoundé,Cameroon\r\r\r\n', '喀麦隆电力发展公司（EDC），成立于2006年，由喀麦隆政府所有，主要负责喀麦隆电站的规划和建设，实施电力基础建设项目。', '胡亚婵(Zoe)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('764', '61', 'INHE-0853', '2019-12-20 08:03:43', '2019-12-20 08:49:12', 'khxx20191220967/REDONDO Y GARCIA, S.A.', 'khxx20191220967', 'REDONDO Y GARCIA, S.A.', '', '欧洲', '西班牙', 'http://www.redondoygarcia.com/en/', 'Serranía de Ronda, 16 Area Empresarial Andalucía - Sector 1 28320 Pinto - Madrid', '雷东多·加西亚集团（Redondo yGarcíaGroup）是一家成立于1944年的西班牙公司，工业供应领域的领导者，致力于满足工业，建筑业和公共部门专业人士的特定需求，并提供最广泛的国内外品牌。代理的产品涵盖与公司和政府机构工业供应相关的所有领域。', '胡亚婵(Zoe)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('765', '60', 'INHE-0868', '2019-12-30 09:05:11', '2019-12-30 09:29:30', 'khxx20191230972/Da Afghanistan Breshna Sherkat', 'khxx20191230972', 'Da Afghanistan Breshna Sherkat', 'DABS', '亚洲', '阿富汗', 'www.dabs.af\r\r\n', 'Da Afghanistan Breshna Sherkat (DABS)\r\nDehmazang, Kabul', 'DABS是一家由阿富汗政府（GoA）拥有所有股权的有限责任公司。 该公司成立于2008年5月4日（Saur 1387年5月15日），并取代了达富·布雷希纳·穆阿萨萨（DABM）作为国家电力公司。 DABS将在整个商业范围内运营和管理整个阿富汗的发电，进口，输电和配电。', '庄钦', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('766', '60', 'INHE-0868', '2019-12-30 17:16:25', '2019-12-30 17:50:35', 'khxx20191230973/CANUCK LOGISTICS & SUPPLY SERVICES CO', 'khxx20191230973', 'CANUCK LOGISTICS & SUPPLY SERVICES CO', 'CANUCK', '亚洲', '阿富汗', '-', 'Shahrak Aria，Kabul，Afghanistan', 'Canuck Logistics & Supply Services Co 位于喀布尔，电力建设项目的EPC承包商，例如配电网，变电站和输电线路。主要业务有专用变压器和电表，在电力公司有一定关系，以前是思达代理，有成功案例。', '庄钦', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
