INSERT INTO `inhe_customer_data` VALUES ('768', '61', 'INHE-0776', '2020-01-03 16:41:08', '2020-01-03 16:46:21', 'khxx20200103978/INTELMETER S.A.C', 'khxx20200103978', 'INTELMETER S.A.C', 'INTELMETER', '南美洲', '秘鲁', 'www.intelmeter.com', 'Pasaje Monte Azul N\'120,Oficina 206,\r\r\nUrbanización Chacarilla del Estanque,distrito de Santiago de Surco,provincia y departamento de Lima.\r\r\n', 'INTELMETER是一家从事能源行业的秘鲁公司，是重要亚洲公司的本地代理，已与欧洲，北美和国内供应商建立了合作关系。致力于高，中，低压电气系统，测量，医疗卫生，机械和液压，可再生能源的高质量产品创新，项目开发（EPC）以及工程实施和咨询，特别着重于电气，电子和节能基础设施项目开发，实施完整的解决方案，并将继续跟随保证前期，中期和后期的商业运营。', '李玟', '国际业务二部', null, null, 'E', 'INHE');
