INSERT INTO `inhe_customer_data` VALUES ('773', '61', 'INHE-0500', '2020-02-05 16:10:51', '2020-02-05 16:29:39', 'khxx20200205986/TelOne (Private) Limited\r\n', 'khxx20200205986', 'TelOne (Private) Limited', 'TelOne', '非洲', '津巴布韦', 'N/A', 'PMU, 8th Floor Runhare House,\r\r\n107 Kwame Nkrumah Avenue\r\r\nP. O Box CY 331\r\r\nCauseway\r\r\nHARARE\r\r\nZIMBABWE\r\r\n', '1.津巴布韦半国有企业，为津巴布韦第二大通讯运行商，主营业务涉及通讯基础建设、运营和服务以及相关通讯产品的供应。旗下2017年新成立一个制造工厂子公司，当前主要进行PC、个人电脑和相关ICT设备的本地SKD组装，其有意向增加电能表的SKD组装线，并于2019年10月到访了银河总部考察和关于新工厂建设的交流；\r\n2.其于2020年2月3日发布关于寻求厂商合作建设本地电能表组装厂的限制性招标，2月27日截标，待安排投标。', '李忠鹏(Evans)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
