INSERT INTO `inhe_customer_data` VALUES ('775', '61', 'INHE-0725', '2020-02-13 09:10:02', '2020-02-13 09:40:32', 'khxx20200213988/New Moon Nigeria Limited', 'khxx20200213988', 'New Moon Nigeria Limited', 'MNP02', '非洲', '尼日利亚', 'https://www.manpower.com.ng/company/69546/new-moon-nigeria-limited', '4 Adegbite Close Dopemu Agege Lagos', 'New Moon Nigeria Limited是尼日利亚一家从事电力行业实力较强经验丰富的公司，主要从事微型太阳能项目，变压器供应，路灯项目。目前作为微网项目运营商与我方洽谈合作。目前有2000台表计的项目，希望采购300台+售电软件先行试点，业务尝试扩大订单未果，可清EOI现有2100台表计库存，业务收到100%预付款后悔另起OA申请调用EOI库存。\r\r\n\r\nNew Moon Nigeria Limited属于微网客户，业务此前针对尼日利亚微网客户单独立项MNP，现补充客户档案。', '赵政洁(Oscar)', '国际业务二部', null, null, 'E', 'INHE');
