INSERT INTO `inhe_customer_data` VALUES ('814', '66', 'INHE-0634', '2020-04-27 09:02:23', '2020-04-27 09:10:20', 'khxx202004271041/The United Nations Development Programme', 'khxx202004271041', 'The United Nations Development Programme', 'UNDP', '北美洲', '美国', '\r\nhttp://www.undp.org/ ', '纽约', '联合国开发计划署是世界上最大的负责进行技术援助的多边机构。它是联合国的一个下属机构，总部位于纽约。其主要工作是为发展中国家提供技术上的建议、培训人才并提供设备，特别是为最不发达国家进行帮助。', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('815', '66', 'INHE-0634', '2020-05-07 15:32:12', '2020-05-07 15:36:05', 'khxx202005071042/Peace Myanmar Electric Holding Co.,Ltd', 'khxx202005071042', 'Peace Myanmar Electric Holding Co.,Ltd', 'PME', '亚洲', '缅甸', 'https://pmeholding.com', '137/139, Botahtaung Pagoda Road,Botahtaung Township,', '于1994年成立，在仰光有一个服务中心，在曼德勒和内比都分别有一个分公司，总员工人数超过1000人，还是三菱电机在缅甸长达25年的忠诚合作伙伴。PME的销售产品种类较多，主要有如下几个大类：空调、冰箱、工业通风设备、水泵、安保设备、电缆以及输配电设备（66 kV雷击避雷器、66kV气体绝缘金属封闭式开关设备、12 kV环网柜、66kV户外气体绝缘开关设备、66 kV户外气体断路器、66 kV电压互感器）。PME有推广过三菱的电表，但估计是价格因素，未在缅甸电表市场取得很好的成绩，希望与银河就智能电表开展长期合作关系。', '陈雁', '国际三部 INTL.Business Dept.3', null, null, 'E', 'INHE');
