INSERT INTO `inhe_customer_data` VALUES ('832', '153', 'INHE-0535', '2020-06-15 16:05:57', '2020-06-15 16:26:40', 'khxx202006151069/Meghalaya Power Distribution Corporation Limited \r\n', 'khxx202006151069', 'Meghalaya Power Distribution Corporation Limited', 'MePDCL\r\r\n', '亚洲', '印度', 'Website: www.meecl.co.in\r\n', 'Lumjingshai, Short Round Road, Shillong -793001, Meghalaya, India', 'MePDCL电力公司位于印度Meghalaya邦，旨在为Maghalaya邦的民众提供普遍、充足、负担得起、可靠和可持续的电力，并确保长期提供电力分配服务的可持续性和财务可行性。减少配电中的技术和商业损失。\r\r\r\n作为重要的项目干预措施之一，MePDCL计划通过将智能电表替换约45％的现有电表（主要是旧的机电式电表）来更新和现代化其现有的电表基础设施，以减少商业损失，提高账单效率和收款。', '左亚楠', '重大项目部', null, null, 'E', 'INHE');
