INSERT INTO `inhe_customer_data` VALUES ('840', '61', 'INHE-0725', '2020-06-18 09:14:32', '2020-06-18 09:39:02', 'khxx202006181084/Ampersand Logistics', 'khxx202006181084', 'Ampersand Logistics', 'ALL', '非洲', '尼日利亚', 'https://www.myxtate.ng/', ' G11 Unit 2 New Horizon 2 Estate,Meadow Hall Way Elegushi Beach,Lekki Lagos, Nigeria.', '该客户是尼日利亚本地一家软件公司，自有线上支付系统，和银行做了接口。去年开始从事表计行业微网项目，目前有意与我司合作，先采购系统，后采购电表拓展本地业务', '赵政洁(Oscar)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('841', '61', 'INHE-0725', '2020-06-18 09:33:03', '2020-06-18 10:00:57', 'khxx202006181085/Deutsche Gesellschaft Fur Internationle Zusammenarbeit', 'khxx202006181085', 'Deutsche Gesellschaft Fur Internationle Zusammenarbeit', 'GIZ', '非洲', '尼日利亚', 'https://www.giz.de/en/html/index.html', 'No.4, Julius Nyerere Crescent, Off Yakubu Gowon Crescent, Asokoro, Abuja, FCT, Nigeria', 'Deutsche Gesellschaft Fur Internationle Zusammenarbeit(GIZ)又称德国国际合作机构创建于1975年，总部在法兰克福附近的Eschborn，是德国政府所有的一家推动国际合作的服务型企业，主要接受德国经济合作与发展部（BMZ)等德国政府部门及别国政府委托，支持德国伙伴国的发展和改革。目前在世界各地同130多个国家以及世界银行、欧盟、联合国开发计划署、亚洲开发银行等国际组织和机构开展合作。\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\nGIZ在2018年与尼日利亚政府达成协议，受NERC（尼日利亚电力行业监管机构）指派负责本地微网项目招标（包含太阳能发电，输配电及计量设备及方案），享受尼政府优惠政策（免税），2018-2019年处于业务积累阶段，目前已完成微网市场布局，本地客户如GVE(GA），Nayo Tropical(AN)，ACOB Lighting(MNP)相继与GIZ展开合作，有整合尼日利亚微网市场的计划，能力和人脉。', '赵政洁(Oscar)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('842', '61', 'INHE-0434', '2020-06-18 16:34:36', '2020-06-18 17:14:51', 'khxx202006181086/Northern Electricity Distribution Company\r\n', 'khxx202006181086', 'Northern Electricity Distribution Company', 'NEDCO', '非洲', '加纳', 'http://www.nedcogh.com/profile.php\r\n', 'NORRIP Building, Bolga Road，P. O. Box TM77 Tamale, Ghana\r\r\r\n', '加纳北方配电电力公司，与ECG属同一性质。服务范围覆盖加纳64%区域，用户从1987年的2万至2015年增长至近70万。', '钟云林(Andy)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('843', '153', 'INHE-0535', '2020-06-19 09:23:17', '2020-06-19 09:40:41', 'khxx202006191087/Adani Electricity Mumbai Ltd', 'khxx202006191087', 'Adani Electricity Mumbai Ltd', 'AEML', '亚洲', '印度', 'www.adanielectricity.com\r\r\n', 'Devidas Lane, Off SVP Road Nr Devidas Ln Telephone Exch Mumbai, 400103 India\r\r\n', 'AEML是Adani输电公司收购Reliance基建有限公司的综合发电，输电和配电公用事业后成立的一个子公司，该公司为孟买市提供电力。其配电网络跨越400平方千米，服务超过290万客户的电力需求，范围包括孟买郊区地区从西侧的Bandra到Bhayander，从东侧的Sion到Mankhurd。', '左亚楠', '重大项目部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('844', '153', 'INHE-0922', '2020-06-23 15:24:27', '2020-06-23 15:36:02', 'khxx202006231088/Persia consortium of energy\r\n', 'khxx202006231088', 'Persia consortium of energy', 'Persia', '亚洲', '伊朗', 'http://www.parsmeter.com/\r\n', ' Office Unit, .No, Hekmat Alley , Noroozian Boulevard, Qazvin, Iran.\r\r\r\r\n', 'Sanjesh Energy Pars Alborz Company#FE54` SEP Alborz Co. has established with the convergence of experienced executives and experts in research and development, sales engineering, IT, commercial and manufacturing of electronic and smart meters and in order to meet the growing needs in relation to smart measurement and management of Energy.\r\nThe company intends to work with the managers and experts of energy sector with a triple tool of responsible attitude, orientation, and manner.\r\nTherefore, using its dynamic knowledge and experience, in addition to its ever-increasing efforts to provide optimal service to domestic industries and customers, it has always looked to other countries in the region to get closer to its long-term goals.\r\n', '石洋', '重大项目部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('845', '153', 'INHE-0922', '2020-06-23 16:36:57', '2020-06-23 17:13:54', 'khxx202006231089/PUBLIC ESTABLISHMENT FOR DISTRIBUTION \r\nOF ELECTRICAL ENERGY\r\n', 'khxx202006231089', 'PUBLIC ESTABLISHMENT FOR DISTRIBUTION OF ELECTRICAL ENERGY', 'PEDE\r\r\n', '亚洲', '叙利亚', 'http://pede.com.sy/\r\n', 'P.O Box 35199 Damascus - Syria\r\n		\r\n', '\r\r\nMinistry of Electricity does directly or by means of the institutions and\r\r\ncompanies related to it, or in cooperation with other institutions, does all\r\r\ntasks and functions related to the electricity sector, specially:\r\r\na – Preparing the required plans to fulfill the state needs of the electrical\r\r\nenergy and to carry out the current projects to attain this purpose.\r\r\nb - Producing, transmission, distribution and investment of the electrical\r\r\npower and saving it to suit the overall economic, industrial and\r\r\ncommercial development.\r\r\nc –Circulating the lighting all over the countryside of the country.\r\r\nd - Supervising the production of electricity in all the institutions,\r\r\ncompanies and public sector departments, which have major and auxiliary\r\r\ngenerating electricity, and issuing the particular instructions to operate and\r\r\ninvest it to suit the public interest.', '石洋', '重大项目部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('846', '60', 'INHE-0868', '2020-06-28 18:14:35', '2020-06-28 18:29:27', 'khxx202006281090/INTERLINK COMMINICATION PUBLIC COMPANY LIMITED\r\n', 'khxx202006281090', 'INTERLINK COMMINICATION PUBLIC COMPANY LIMITED', 'Interlink', '亚洲', '泰国', 'www.interlink.co.th', '48 INTERLINK Building, Soi Rung-rueng, Ratchadaphisek Road, Samsennok,?Huay Khwang, Bangkok 10310, Thailand\r\n', 'Ineterlink Communication Public Company Limited成立于1995年，2004年上市，是集团公司。其母公司为Interlink Holding Company Limited，又有子公司：Interlink Telecom Public Company Limited，Interlink Power and Energy Company Limited。主要业务分为三大板块：经销板块（电缆光纤类），电力工程板块（电力系统和通讯），电信板块。电力公司PEA和MEA在全国的光纤均由Interlink提供，国家铁路及MEA，PEA电线杆的电信网络也都是由Interlink安装运营。', '庄钦', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('847', '60', 'INHE-0868', '2020-06-28 18:19:47', '2020-06-28 18:29:11', 'khxx202006281091/Provincial Electricity Authority（PEA）', 'khxx202006281091', 'Provincial Electricity Authority（PEA）', 'PEA', '亚洲', '泰国', 'www.pea.co.th\r\r\n', '200 Ngamwongwan Road, Ladyao, Chatuchak Bangkok 10900\r\n', 'Provincial Electricity Authority,负责除大曼谷地区外的配电和售电业务。电表招标主要由PEA发标。', '庄钦', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('848', '61', 'INHE-0725', '2020-07-06 08:48:01', '2020-07-06 09:17:12', 'khxx202007061092/Power Factor Limited', 'khxx202007061092', 'Power Factor Limited', 'PF', '非洲', '加纳', 'www.powerfactorgh.com', 'P.O. Box BT 651 Tema -Ghana West Africa', 'Power Factor Limited是一家加纳EPC工程公司，在阿克拉郊区有办公室，主做变压器（和某中国厂商合作），在能源部及电力公司处有客情，公司有一万平米的地皮（便于后续建厂），也有运载货物用的大卡车（运货）；整体而言公司实力较强。本次有意与我方合作', '赵政洁(Oscar)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('849', '61', 'INHE-0876', '2020-07-10 20:23:16', '2020-07-13 08:36:08', 'khxx202007101095/SENELEC', 'khxx202007101095', 'SENELEC', 'SENELEC', '非洲', '塞内加尔', 'http://www.senelec.sn/\r\n', 'SENELEC , 28 Rue Vincens  \r\r\n', '塞国家电力公司由塞政府控股，目前几乎垄断了全国的电力生产、输配业务。2008年，塞全国生产电力（包括进口）近24亿度。塞电力公司销售约17.86亿度电；营业额：1805亿非郎，约合3.6亿美元；客户数量：71万户；员工人数：2492人。塞电力公司2007年并网发电共计14.92亿度电，比2006年增加了10.4%；独立用户发电为1.03亿度。塞国家电力公司从独立发电厂购买电量为70万度左右。', '邓彧(Daniel)', '国际业务二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('850', '66', 'INHE-0774', '2020-07-13 11:31:05', '2020-07-13 13:30:47', 'khxx202007131096/Qarnass Group\r\n', 'khxx202007131096', 'Qarnass Group', 'Qarnass Group', '亚洲', '伊拉克', ' https://www.qarnass.com\r\r\n', 'House. 37 / Street. 64 / Quarter 635 / Aljamaa District , Baghdad, Iraq', '位于伊拉克和约旦， 成立于2001年5月30日，主要从事一般贸易与承包公司，子公司Al-Rama在约旦注册，从事仓储和一般贸易。 AL-Qarnass集团拥有20多名工程师和10名专业管理人员。', '何森华', '业务三部', null, null, 'E', 'INHE');
