INSERT INTO `inhe_customer_data` VALUES ('856', '153', 'INHE-0015', '2020-08-05 15:28:21', '2020-08-05 15:36:27', 'khxx202008051107/SP Group', 'khxx202008051107', 'SP Group', 'SP', '亚洲', '新加坡', ' spgroup.com.sg ', 'SP Group 2 Kallang Sector \r\nSingapore 349277', 'SP Group is a leading energy utilities group in the Asia Pacific. It owns and operates electricity and gas transmission and distribution businesses in Singapore and Australia, and district cooling businesses in Singapore and China. SP Group is committed to providing customers with reliable and efficient energy utilities services. About 1.6 million industrial, commercial and residential customers in Singapore benefit from SP Group\'s world-class transmission, distribution and market support services. These networks are amongst the most reliable and cost-effective worldwide. SP Group also drives digital solutions to empower customers to manage their utilities, reduce consumption and save cost.', '王维', '重大项目部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('857', '153', 'INHE-0015', '2020-08-05 15:35:36', '2020-08-05 17:21:33', 'khxx202008051108/The Energy Market Authority ', 'khxx202008051108', 'The Energy Market Authority', 'EMA', '亚洲', '新加坡', ' www.ema.gov.sg ', '991G Alexandra Road #01-29\r\nSingapore 119975', 'The Energy Market Authority is a statutory board under the Ministry of Trade and Industry. Our main goals are to ensure a reliable and secure energy supply, promote effective competition in the energy market and develop a dynamic energy sector in Singapore. Through our work, the EMA seeks to forge a progressive energy landscape for sustained growth. ', '王维', '重大项目部', null, null, 'E', 'INHE');
