INSERT INTO `inhe_customer_data` VALUES ('860', '60', 'INHE-0680', '2020-08-11 10:09:07', '2020-08-11 10:34:19', 'khxx202008111113/CANUCK LOGISTICS & SUPPLY SERVICES CO1', 'khxx202008111113', 'CANUCK LOGISTICS & SUPPLY SERVICES CO1', 'CANUCK01\r\r\r\n', '亚洲', '阿富汗', '\r\r\n', '', 'Canuck Logistics & Supply Services Co 位于喀布尔，电力建设项目的EPC承包商，例如配电网，变电站和输电线路。主要业务有专用变压器和电表，在电力公司有一定关系，以前是思达代理，有成功案例。\r\n', '陈嘉豪', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('861', '60', 'INHE-0680', '2020-08-11 10:13:21', '2020-08-11 10:34:05', 'khxx202008111114/Da Afghanistan Breshna Sherkat01\r\n', 'khxx202008111114', 'Da Afghanistan Breshna Sherkat01', 'DABS01', '亚洲', '阿富汗', '', '', 'DABS是一家由阿富汗政府（GoA）拥有所有股权的有限责任公司。 该公司成立于2008年5月4日（Saur 1387年5月15日），并取代了达富·布雷希纳·穆阿萨萨（DABM）作为国家电力公司。 DABS将在整个商业范围内运营和管理整个阿富汗的发电，进口，输电和配电。\r\n', '陈嘉豪', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('862', '61', 'INHE-0434', '2020-08-12 15:01:56', '2020-08-12 15:09:10', 'khxx202008121115/Ontec Systems (Pty) Ltd', 'khxx202008121115', 'Ontec Systems (Pty) Ltd', 'ONTEC', '非洲', '南非', 'http://ontec.co.za/\r\n', 'Tygerberg House, 2nd Floor, 163 Tygerberg Office Park, Uys Krige Drive, Plattekloof, 7500, Cape Town, South Africa', 'ITRON(南非)于16年改组，ONTEC顺应成立。公司主营业务范围主要提供预付费售电系统及其相关业务，同时经营电表与水表相关业务\r\n', '钟云林(Andy)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('863', '61', 'INHE-0772', '2020-08-12 14:16:40', '2020-08-12 15:11:47', 'khxx202008121116/Fiduciary Agency for Project Implementation\r\n', 'khxx202008121116', 'Fiduciary Agency for Project Implementation', 'AFAP', '非洲', '圣多美和普林西比', 'www.afap.st', 'Address: Edifício do Afriland First Bank\r\r\r\r\r\n               Floor/ Room number:2 Andar\r\r\r\r\r\n              Avenida Kwame N\'Krumah,\r\r\r\r\r\nCity: Sao Tome\r\r\r\r\r\nZIP Code: CP 1029\r\r\r\r\r\nCountry: : Sao Tome and Príncipe\r\r\r\r\r\n		\r\r\n\r\r\r\n', '圣多美民主共和国政府已从欧洲投资银行获得了电力部门恢复项目的资金，并打算将部分收益用于根据计量解决方案的设备供应和安装合同进行的付款。AFAP是该国家贷款项目的主管单位。', '张子琦(Miranda)', '国际二部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('864', '93', 'INHEGRID-0048', '2020-08-14 08:45:40', '2020-08-14 09:11:31', 'khxx202008141119/CENTRO INDUSTRIAL ELETROMECANICO', 'khxx202008141119', 'CENTRO INDUSTRIAL ELETROMECANICO', 'CIEM', '非洲', '圣多美和普林西比', 'https://www.ciem.st/', 'Zona Industrial Bobo-Forro - C/P:137 - S?o Tomé e Príncipe', '圣普当地标书一般由当地信托管理机构AFAP发出，圣普当地电力公司为EMAE。CIEM业务涉及汽车经销，医疗设备，发电机安装。\r\nCIEM与AFAP和EMAE有着良好的客情关系，并且为AFAP合EMAE提供过发电机产品和安装服务。', '李林（Wilson Li)', '国际业务部(OBD)', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('865', '93', 'INHEGRID-0048', '2020-08-14 09:14:17', '2020-08-14 09:33:20', 'khxx202008141120/Agência Fiduciária de Administracao de Projectos ', 'khxx202008141120', 'Agência Fiduciária de Administracao de Projectos', 'AFAP', '非洲', '圣多美和普林西比', 'http://www.afap.st/index.php/sobre-nos', 'San Tome\r\r\nAvenida Kwame N\'krumah, Prédio do Afriland First Bank, 2o Andar, C.P. 1029', '圣多美和普林西比政府项目管理的信托机构。圣普当地的电力项目资金来源一般是由圣普政府向国际组织或者银行贷款，AFAP作为招标方。\r\r\n', '李林（Wilson Li)', '国际业务部(OBD)', null, null, 'E', 'INHE');
