INSERT INTO `inhe_customer_data` VALUES ('868', '61', 'INHE-0913', '2020-08-18 15:33:36', '2020-08-18 16:32:57', 'khxx202008181123/Société d`Energie et d`Eau du Gabon', 'khxx202008181123', 'Société d`Energie et d`Eau du Gabon', 'SEEG', '非洲', '加蓬', 'www.seeg-gabon.com', 'BP 2187 – Libreville, Gabon\r\r\n', '加蓬能源和水公司（SEEG）创建于1950，自1997年实现起私有化，由法国Veolia水务集团拥有51%的股份，加蓬政府、加蓬私人投资者和公司员工拥有49%的股份，垄断了加蓬的水电供应。', '魏紫薇(Valentine)', '国际二部 INTL.Business Dept.2', null, null, 'E', 'INHE');
