INSERT INTO `inhe_customer_data` VALUES ('872', '60', 'INHE-0680', '2020-09-01 09:27:00', '2020-09-01 09:38:36', 'khxx202009011132/Ets Abdou Hayek', 'khxx202009011132', 'Ets Abdou Hayek', 'EAH', '亚洲', '黎巴嫩', 'www.destination.com.lb', 'Jdeideh - Essayli street - Maksoud1 Bldg. - P.O.Box: 90-494\r\r\nTel: +961 1 902 973 - 902 974\r\r\nFax: +961 1 902 975\r\r\nBeirut - Lebanon', 'EAH是一家领先的公司，专门从事黎巴嫩和邻国中，低压线路以及变电站的建设。\r\r\r\nEts Abdou Hayek包含Simpass和Simek。\r\r\r\nSimpass专门从事与中高压线路，变电站和公共照明建设有关的产品和材料的贸易和供应的承包商。 Simek有两项业务，第一项专注于与电气工程和传输网络有关的产品和配件的制造和组装，第二项与“承包和交钥匙工程”。\r\r\r\n该集团成立于1950年，目前拥有约60名员工。\r\r\r\n该集团是黎巴嫩电力公司（Electricitédu Liban-EDL）的主要供应商和承包商。 该集团已经获得了许多投标和合同，可以保持其在其市场领域内的领先地位。', '陈嘉豪', '国际一部 INTL.Business Dept.1', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('873', '173', 'INHE-0500', '2020-09-04 13:57:48', '2020-09-04 14:35:31', 'khxx202009041134/Tsogatec (Pty) Ltd\r\n', 'khxx202009041134', 'Tsogatec (Pty) Ltd', 'TST', '非洲', '南非', 'www.tsogatec.co.za', 'Reg No: 2016/391185/07 \r\r\r\n17 Midaslaan, Olympus, Moreletapark, Pretoria East, 0081 RSA\r\r\r\n', '1.此公司为2016年新成立的第三方售电系统ICT类型公司，公司主营业务范围主要从事为南非市政公司提供涵盖新能源系统管理、新型第三方售电平台及相关软件系统业务，公司正式员工9名（4名管理人员，5名程序开发工程师），其独立开发的本地第三方售电平台在当地已和各大银行、Whatsup平台完成兼容交互；\r\r\n\r\r\n2.截止目前为主，该公司已中标如下第三方售电/售水授权合同：\r\r\n*** 大都市市政公司City of Ekurhuleni的第三方售电（4个第三方售电平台之一）\r\r\n*** Sekhukhune地区市政公司售水系统平台和水表项目（目前正在和其洽谈银河提供水表一体化方案）\r\n\r\r\n', '李忠鹏(Evans)', '南非区SADC', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('874', '173', 'INHE-0500', '2020-09-04 14:17:23', '2020-09-04 14:35:19', 'khxx202009041135/Buffalo City Metropolitan Municipality\r\n', 'khxx202009041135', 'Buffalo City Metropolitan Municipality', 'BCMM', '非洲', '南非', 'www.buffalocity.gov.za\r\r\n', '80 Phillip Frame Road，Chiselhurst,East London，Eastern Cape Province RSA', '南非市场8大大都市市政之一，位于东开普省East London，为东开普省两个大都市市政公司之一，电表用户基数约为40万户，其中90%为普通低压单相居民用电。\r\n\r\n\r\n此次为银河第一次联合代理投标该市政项目。', '李忠鹏(Evans)', '南非区SADC', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('875', '172', 'INHE-0913', '2020-09-09 14:39:19', '2020-09-09 14:56:13', 'khxx202009091139/特变电工股份有限公司', 'khxx202009091139', '特变电工股份有限公司', '特变电工', '亚洲', '中国', 'www.tbea.com', '中国新疆昌吉市北京南路189号', '特变电工是全球能源事业提供系统解决方案服务商，主营业务为输变电产业、新材料产业以及新能源产业。', '魏紫薇(Valentine)', '中非区CAC', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('876', '172', 'INHE-0913', '2020-09-09 15:08:49', '2020-09-23 11:10:07', 'khxx202009091140/National Water and Electricity Company Limited', 'khxx202009091140', 'National Water and Electricity Company Limited', 'NAWEC\r\n', '非洲', '冈比亚', 'www.nawec.gm', '53, Mamady Maniyang Highway, P.O. Box 609, Banjul The Gambia\r\n		\r\n', 'NAWEC，成立于1966年，是一家公共有限责任公司。NAWEC从事为家庭、公共和工业用途生产和提供电力、供水和污水处理服务。电力、供水和排污资产归政府所有，但由NAWEC管理和运营。', '魏紫薇(Valentine)', '中非区CAC', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('877', '169', 'INHE-0578', '2020-09-14 14:48:36', '2020-09-14 14:53:40', 'khxx202009141144/Conduit Electrical Pvt Ltd', 'khxx202009141144', 'Conduit Electrical Pvt Ltd', 'Conduit', '非洲', '南非', '', '', '此公司为FINMARK 法人在南非的公司，相关联系人、负责人同FINMARK。', '覃湘君(June)', '总监助理', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('878', '66', 'INHE-0901', '2020-09-23 09:50:12', '2020-09-23 10:43:33', 'khxx202009231147/Protasis SA', 'khxx202009231147', 'Protasis SA', '', '欧洲', '希腊', 'https://www.protasis.net.gr/\r\n', '59B Apostolopoulou st.15231 Chalandri, Athens, Greece', '此公司是一家电力系统工程和咨询公司，为希腊电力局HEDNO的AMR/MDM System提供维护服务，协助HEDNO进行样机测试等，故Protasis了解HEDNO如何操作。公司联系人Sotiris在兰吉尔工作15年、ABB工作10年，其对技术方面非常熟悉，但非常固执，对我司过去给希腊SFALCO发过样机一事耿耿于怀，且关于合作费用细节都需我司提供信息参考。此公司成立于2002年，公司人员少于20人，查询营业额为每年437万美元。Protasis SA与2011年与华立有合作，但之后华立脱离Protasis并在希腊设立办事处，华立自己主投并屡次中标，这种脱离做法与Protasis想当甩手掌柜的做事方式有关。公司财务实力不够，只有我司提供很好的价格才有合作的机会。', '徐周泽弈', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('879', '66', 'INHE-0901', '2020-09-23 10:41:22', '2020-09-23 11:12:37', 'khxx202009231148/HEDNO', 'khxx202009231148', 'Hellenic Electricity Distribution Network Operator SA', 'HEDNO', '欧洲', '希腊', 'www.deddie.gr\r\r\n', '20 Perraivou & 5 Kallirrois str.117 43 Athens\r\r\r\n', 'HEDNO为希腊电力局，HEDNO在PPC SA的分销部门分拆后于2012年成立，它是PPC SA（希腊国家能源集团）的100％子公司，但在组织和功能上均是独立的公司。HEDNO为749万希腊用户供电。HEDNO网络线路总长度为240,000公里，HEDNO雇用大约7,000名员工。HEDNO为上市公司，截止2019年12月31日，总资产为9.09417亿欧元，2019年营业额为1.62465亿欧元，全年税后总收入为1495.7万欧元。每年发2-3次电表招标，近两年招标电表为含通信模块的单三相智能电表，电表需连接到其电表系统ZFA-F，华立中标电表居多。', '徐周泽弈', '国际业务三部', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('880', '174', 'INHE-0434', '2020-09-25 10:14:02', '2020-09-25 10:32:26', 'khxx202009251150/Afrika Smart Utilities (Pty) Ltd\r\n', 'khxx202009251150', 'Afrika Smart Utilities (Pty) Ltd', 'ASU', '非洲', '南非', 'sales@afrikasmart.co.za\r\n', '85 EDISON STREET WENDYWOOD SANDTON GAUTENG 2090\r\r\n, South Africa', '林洋代理，同时也代理海兴、威盛产品。公司主营业务范围主要提供预付费电表、水表及其相关业务，也较活跃于市政项目\r\n', '钟云林(Andy)', '东北非NEAC', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('881', '176', 'INHE-0934', '2020-09-25 14:37:53', '2020-09-25 16:08:36', 'khxx202009251152/Daxcomm Limited', 'khxx202009251152', 'Daxcomm Limited', 'Daxcomm\r\n', '非洲', '尼日利亚', 'http://daxcomm.com', 'God’s Grace Plaza Penthouse Floor 65 Allen Avenue Ikeja, Lagos\r\n', 'DAXCOMM成立于1992年，致力于制造，分销和供应计算机以及满足小型企业电子需求的公司，\r\r\n\r\r\n在电信，网络和防火墙，视频和电子监视系统，访问控制系统，办公和家庭自动化领域拥有专业知识。', '范凯悦(Blanca)', '中北美区NC America', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('882', '171', 'INHE-0772', '2020-09-29 09:24:34', '2020-09-29 09:54:39', 'khxx202009291153/特变电工国际工程有限公司', 'khxx202009291153', '特变电工国际工程有限公司', 'TBEA', '亚洲', '中国', 'www.tbea.com', '中国新疆昌吉市北京南路189号', '世界500强， 国际总承包商全球排名 80 位', '张子琦(Miranda)', '西非区WAC', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('883', '175', 'INHE-0932', '2020-09-30 13:33:29', '2020-09-30 14:32:37', 'khxx202009301154/Hamad Alfahad', 'khxx202009301154', 'Hamad Alfahad', '', '亚洲', '巴林', 'http://www.ascentech.net/contact-us', '', '公司业务：Ascentech集团目前由IT和工业服务，贸易和电信组成。提供互联网和互联网协议语音服务；提供虚拟主机解决方案；发展电信基础设施；转售移动电信服务；分发安全和保安设备，包括闭路电视和门禁系统。\nAscentech group:\n● Ascentech Telecom Bahrain（巴林）：主营低成本电信设备和服务等业务\n● Ascentech Services Bahrain（巴林）：成立于2009年，是集团的服务公司。专门从事特殊项目，培训计划以及外包和内包项目。\n● Ascentech Telecom Thiruvananthapuram（印度）：成立于2010年，管理公司各种电信品牌，并为公司现有的电信客户提供IT和技术支持。它也可以作为小组的支持呼叫中心和外包BPO中心。\n● Ascentech General Trading Dubai, UAE（迪拜）：成立于2011年，将公司的IT产品带入阿联酋市场。唯一拥有24/7全天候远程支持的系统集成商。', '符琳(Gisele)', '南美区S. America', null, null, 'E', 'INHE');
INSERT INTO `inhe_customer_data` VALUES ('884', '175', 'INHE-0932', '2020-09-30 15:02:49', '2020-09-30 16:03:26', 'khxx202009301155/Electricity Distribution Directorate, \r\nElectricity and Water Authority, Kingdom of Bahrain', 'khxx202009301155', 'Electricity Distribution Directorate, Electricity and Water Authority, Kingdom of Bahrain', 'EDD', '亚洲', '巴林', 'http://www.ewa.bh/en\r\n', '', '为巴林王国的可持续发展提供可靠和优质的水电供应。\r\r\r\n', '符琳(Gisele)', '南美区S. America', null, null, 'E', 'INHE');
